INSERT INTO "Card" VALUES('base1-26','Dratini','Pokémon','26','Uncommon','Ken Sugimori','Long considered a mythical Pokémon until recently, when a small colony was found living underwater.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/26.png","large":"https://images.pokemontcg.io/base1/26_hires.png"}',NULL,'40','10','["Basic"]','["Colorless"]',NULL,'["Dragonair"]',NULL,'[{"name":"Pound","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]',NULL,'[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[147]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-27','Farfetch''d','Pokémon','27','Uncommon','Ken Sugimori','The sprig of green onions it holds is its weapon. This sprig is used much like a metal sword.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/27.png","large":"https://images.pokemontcg.io/base1/27_hires.png"}',NULL,'50','20','["Basic"]','["Colorless"]',NULL,'["Sirfetch''d"]',NULL,'[{"name":"Leek Slap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"Flip a coin. If tails, this attack does nothing. Either way, you can''t use this attack again as long as Farfetch''d stays in play (even putting Farfetch''d on the Bench won''t let you use it again)."},{"name":"Pot Smash","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[83]',NULL,NULL,'base1');
