INSERT INTO "Card" VALUES('base1-59','Poliwag','Pokémon','59','Common','Ken Sugimori','Its newly grown legs prevent it from running. It appears to prefer swimming over trying to stand.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/59.png","large":"https://images.pokemontcg.io/base1/59_hires.png"}',NULL,'40','13','["Basic"]','["Water"]',NULL,'["Poliwhirl"]',NULL,'[{"name":"Water Gun","cost":["Water"],"convertedEnergyCost":1,"damage":"10+","text":"Does 10 damage plus 10 more damage for each Water Energy attached to Poliwag but not used to pay for this attack''s Energy cost. Extra Water Energy after the 2nd don''t count."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[60]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-60','Ponyta','Pokémon','60','Common','Ken Sugimori','Its hooves are 10 times harder than diamonds. It can trample anything flat in moments.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/60.png","large":"https://images.pokemontcg.io/base1/60_hires.png"}',NULL,'40','10','["Basic"]','["Fire"]',NULL,'["Rapidash"]',NULL,'[{"name":"Smash Kick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""},{"name":"Flame Tail","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[77]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-61','Rattata','Pokémon','61','Common','Mitsuhiro Arita','Bites anything when it attacks. Small and very quick, it is a common sight in many places.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/61.png","large":"https://images.pokemontcg.io/base1/61_hires.png"}',NULL,'30','9','["Basic"]','["Colorless"]',NULL,'["Raticate"]',NULL,'[{"name":"Bite","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]',NULL,NULL,'[19]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-62','Sandshrew','Pokémon','62','Common','Ken Sugimori','Burrows deep underground in arid locations far from water. It only emerges to hunt for food.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/62.png","large":"https://images.pokemontcg.io/base1/62_hires.png"}',NULL,'40','12','["Basic"]','["Fighting"]',NULL,'["Sandslash"]',NULL,'[{"name":"Sand-attack","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":"If the Defending Pokémon tries to attack during your opponent''s next turn, your opponent flips a coin. If tails, that attack does nothing."}]','[{"type":"Grass","value":"×2"}]','[{"type":"Lightning","value":"-30"}]','["Colorless"]',1,'[27]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-63','Squirtle','Pokémon','63','Common','Mitsuhiro Arita','After birth, its back swells and hardens into a shell. It powerfully sprays foam from its mouth.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/63.png","large":"https://images.pokemontcg.io/base1/63_hires.png"}',NULL,'40','8','["Basic"]','["Water"]',NULL,'["Wartortle"]',NULL,'[{"name":"Bubble","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Withdraw","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, prevent all damage done to Squirtle during your opponent''s next turn. (Any other effects of attacks still happen.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[7]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-64','Starmie','Pokémon','64','Common','Keiji Kinebuchi','Its central core glows with the seven colors of the rainbow. Some people value this core as a gem.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/64.png","large":"https://images.pokemontcg.io/base1/64_hires.png"}',NULL,'60','28','["Stage 1"]','["Water"]','Staryu',NULL,NULL,'[{"name":"Recover","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"","text":"Discard 1 Water Energy card attached to Starmie in order to use this attack. Remove all damage counters from Starmie."},{"name":"Star Freeze","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[121]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-65','Staryu','Pokémon','65','Common','Keiji Kinebuchi','An enigmatic Pokémon that can effortlessly regenerate any appendage it loses in battle.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/65.png","large":"https://images.pokemontcg.io/base1/65_hires.png"}',NULL,'40','15','["Basic"]','["Water"]',NULL,'["Starmie"]',NULL,'[{"name":"Slap","cost":["Water"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[120]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-66','Tangela','Pokémon','66','Common','Mitsuhiro Arita','Its whole body is swathed with wide vines that are similar to seaweed. These vines shake as it walks.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/66.png","large":"https://images.pokemontcg.io/base1/66_hires.png"}',NULL,'50','8','["Basic"]','["Grass"]',NULL,'["Tangrowth"]',NULL,'[{"name":"Bind","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Poisonpowder","cost":["Grass","Grass","Grass"],"convertedEnergyCost":3,"damage":"20","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[114]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-67','Voltorb','Pokémon','67','Common','Keiji Kinebuchi','Usually found in power plants. Easily mistaken for a Monster Ball, it has zapped many people.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/67.png","large":"https://images.pokemontcg.io/base1/67_hires.png"}',NULL,'40','10','["Basic"]','["Lightning"]',NULL,'["Electrode"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[100]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-68','Vulpix','Pokémon','68','Common','Ken Sugimori','At the time of birth, it has just one tail. Its tail splits from the tip as it grows older.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/68.png","large":"https://images.pokemontcg.io/base1/68_hires.png"}',NULL,'50','11','["Basic"]','["Fire"]',NULL,'["Ninetales"]',NULL,'[{"name":"Confuse Ray","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[37]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-69','Weedle','Pokémon','69','Common','Mitsuhiro Arita','Often found in forests, eating leaves. It has a sharp, venomous stinger on its head.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/69.png","large":"https://images.pokemontcg.io/base1/69_hires.png"}',NULL,'40','12','["Basic"]','["Grass"]',NULL,'["Kakuna"]',NULL,'[{"name":"Poison Sting","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[13]',NULL,NULL,'base1');
INSERT INTO "Card" VALUES('base1-70','Clefairy Doll','Trainer','70','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/70.png","large":"https://images.pokemontcg.io/base1/70_hires.png"}',NULL,'10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Clefairy Doll as if it were a Basic Pokémon. While in play, Clefairy Doll counts as a Pokémon (instead of a Trainer card). Clefairy Doll has no attacks, can''t retreat, and can''t be Asleep, Confused, Paralyzed, or Poisoned. If Clefairy Doll is Knocked Out, it doesn''t count as a Knocked Out Pokémon. At any time during your turn before your attack, you may discard Clefairy Doll."]','base1');
INSERT INTO "Card" VALUES('base1-71','Computer Search','Trainer','71','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/71.png","large":"https://images.pokemontcg.io/base1/71_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 of the other cards from your hand in order to search your deck for any card and put it into your hand. Shuffle your deck afterward."]','base1');
INSERT INTO "Card" VALUES('base1-72','Devolution Spray','Trainer','72','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/72.png","large":"https://images.pokemontcg.io/base1/72_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your own Pokémon in play and a Stage of Evolution. Discard all Evolution cards of that Stage or higher attached to that Pokémon. That Pokémon is no longer Asleep, Confused, Paralyzed, Poisoned, or anything else that might be the result of an attack (just as if you had evolved it)."]','base1');
INSERT INTO "Card" VALUES('base1-73','Impostor Professor Oak','Trainer','73','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/73.png","large":"https://images.pokemontcg.io/base1/73_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent shuffles his or her hand into his or her deck, then draws 7 cards."]','base1');
INSERT INTO "Card" VALUES('base1-74','Item Finder','Trainer','74','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/74.png","large":"https://images.pokemontcg.io/base1/74_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 of the other cards from your hand in order to put a Trainer card from your discard pile into your hand."]','base1');
INSERT INTO "Card" VALUES('base1-75','Lass','Trainer','75','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/75.png","large":"https://images.pokemontcg.io/base1/75_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You and your opponent show each other your hands, then shuffle all the Trainer cards from your hands into your decks."]','base1');
INSERT INTO "Card" VALUES('base1-76','Pokémon Breeder','Trainer','76','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/76.png","large":"https://images.pokemontcg.io/base1/76_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Stage 2 Evolution card from your hand on the matching Basic Pokémon. You can only play this card when you would be allowed to evolve that Pokémon anyway."]','base1');
INSERT INTO "Card" VALUES('base1-77','Pokémon Trader','Trainer','77','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/77.png","large":"https://images.pokemontcg.io/base1/77_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Trade 1 of the Basic Pokémon or Evolution cards in your hand for 1 of the Basic Pokémon or Evolution cards from your deck. Show both cards to your opponent. Shuffle your deck afterward."]','base1');
INSERT INTO "Card" VALUES('base1-78','Scoop Up','Trainer','78','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/78.png","large":"https://images.pokemontcg.io/base1/78_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon in play and return its Basic Pokémon card to your hand. (Discard all cards attached to that card.)"]','base1');
INSERT INTO "Card" VALUES('base1-79','Super Energy Removal','Trainer','79','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/79.png","large":"https://images.pokemontcg.io/base1/79_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 1 Energy card attached to 1 of your Pokémon in order to choose 1 of your opponent''s Pokémon and up to 2 Energy cards attached to it. Discard those Energy cards."]','base1');
INSERT INTO "Card" VALUES('base1-80','Defender','Trainer','80','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/80.png","large":"https://images.pokemontcg.io/base1/80_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Defender to 1 of your Pokémon. At the end of your opponent''s next turn, discard Defender. Damage done to that Pokémon by attacks is reduced by 20 (after applying Weakness and Resistance)."]','base1');
INSERT INTO "Card" VALUES('base1-81','Energy Retrieval','Trainer','81','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/81.png","large":"https://images.pokemontcg.io/base1/81_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Trade 1 of the other cards in your hand for up to 2 basic Energy cards from your discard pile."]','base1');
INSERT INTO "Card" VALUES('base1-82','Full Heal','Trainer','82','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/82.png","large":"https://images.pokemontcg.io/base1/82_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your Active Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned."]','base1');
INSERT INTO "Card" VALUES('base1-83','Maintenance','Trainer','83','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/83.png","large":"https://images.pokemontcg.io/base1/83_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Shuffle 2 of the other cards from your hand into your deck in order to draw a card."]','base1');
INSERT INTO "Card" VALUES('base1-84','PlusPower','Trainer','84','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/84.png","large":"https://images.pokemontcg.io/base1/84_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach PlusPower to your Active Pokémon. At the end of your turn, discard PlusPower. If this Pokémon''s attack does damage to the Defending Pokémon (after applying Weakness and Resistance), the attack does 10 more damage to the Defending Pokémon."]','base1');
INSERT INTO "Card" VALUES('base1-85','Pokémon Center','Trainer','85','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/85.png","large":"https://images.pokemontcg.io/base1/85_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all damage counters from all of your own Pokémon with damage counters on them, then discard all Energy cards attached to those Pokémon."]','base1');
INSERT INTO "Card" VALUES('base1-86','Pokémon Flute','Trainer','86','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/86.png","large":"https://images.pokemontcg.io/base1/86_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 Basic Pokémon card from your opponent''s discard pile and put it onto his or her Bench. (You can''t play Pokémon Flute if your opponent''s Bench is full.)"]','base1');
INSERT INTO "Card" VALUES('base1-87','Pokédex','Trainer','87','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/87.png","large":"https://images.pokemontcg.io/base1/87_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at up to 5 cards from the top of your deck and rearrange them as you like."]','base1');
INSERT INTO "Card" VALUES('base1-88','Professor Oak','Trainer','88','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/88.png","large":"https://images.pokemontcg.io/base1/88_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard your hand, then draw 7 cards."]','base1');
INSERT INTO "Card" VALUES('base1-89','Revive','Trainer','89','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base1/89.png","large":"https://images.pokemontcg.io/base1/89_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 1 Basic Pokémon card from your discard pile onto your Bench. Put damage counters on that Pokémon equal to half its HP (rounded down to the nearest 10). (You can''t play Revive if your Bench is full.)"]','base1');
