INSERT INTO "Card" VALUES('base1-95','Switch','Trainer','95','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base1/95.png","large":"https://images.pokemontcg.io/base1/95_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch 1 of your own Benched Pokémon with your Active Pokémon."]','base1');
