INSERT INTO "Card" VALUES('base2-42','Persian','Pokémon','42','Uncommon','Kagemaru Himeno','Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base2/42.png","large":"https://images.pokemontcg.io/base2/42_hires.png"}',NULL,'70','25','["Stage 1"]','["Colorless"]','Meowth',NULL,NULL,'[{"name":"Scratch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""},{"name":"Pounce","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"If the Defending Pokémon attacks Persian during your next turn, any damage done by the attack is reduced by 10 (after applying Weakness and Resistance). (Benching either Pokémon ends this effect.)"}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]',NULL,NULL,'[53]',NULL,NULL,'base2');
