INSERT INTO "Card" VALUES('base2-49','Bellsprout','Pokémon','49','Common','Kagemaru Himeno','A carnivorous Pokémon that traps and eats bugs. It uses its root feet to soak up needed moisture.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base2/49.png","large":"https://images.pokemontcg.io/base2/49_hires.png"}',NULL,'40','11','["Basic"]','["Grass"]',NULL,'["Weepinbell"]',NULL,'[{"name":"Vine Whip","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Call for Family","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon named Bellsprout and put it onto your Bench. Shuffle your deck afterward. (You can''t use this attack if your Bench is full.)"}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[69]',NULL,NULL,'base2');
INSERT INTO "Card" VALUES('base2-50','Cubone','Pokémon','50','Common','Mitsuhiro Arita','Because it never removes its skull helmet, no one has ever seen this Pokémon''s real face.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base2/50.png","large":"https://images.pokemontcg.io/base2/50_hires.png"}',NULL,'40','13','["Basic"]','["Fighting"]',NULL,'["Marowak"]',NULL,'[{"name":"Snivel","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If the Defending Pokémon attacks Cubone during your opponent''s next turn, any damage done by the attack is reduced by 20 (after applying Weakness and Resistance). (Benching either Pokémon ends this effect.)"},{"name":"Rage","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"10+","text":"Does 10 damage plus 10 more damage for each damage counter on Cubone."}]','[{"type":"Grass","value":"×2"}]','[{"type":"Lightning","value":"-30"}]','["Colorless"]',1,'[104]',NULL,NULL,'base2');
INSERT INTO "Card" VALUES('base2-51','Eevee','Pokémon','51','Common','Kagemaru Himeno','Its genetic code is irregular. It may mutate if it is exposed to radiation from elemental stones.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base2/51.png","large":"https://images.pokemontcg.io/base2/51_hires.png"}',NULL,'50','12','["Basic"]','["Colorless"]',NULL,'["Vaporeon","Jolteon","Flareon","Sylveon","Espeon","Umbreon","Leafeon","Glaceon"]',NULL,'[{"name":"Tail Wag","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon can''t attack Eevee during your opponent''s next turn. (Benching either Pokémon ends this effect.)"},{"name":"Quick Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[133]',NULL,NULL,'base2');
