INSERT INTO "Card" VALUES('base4-79','Magnemite','Pokémon','79','Common','Keiji Kinebuchi','Uses anti-gravity to stay suspended. Appears without warning and uses attacks like Thunder Wave.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base4/79.png","large":"https://images.pokemontcg.io/base4/79_hires.png"}',NULL,'40','13','["Basic"]','["Lightning"]',NULL,'["Magneton"]',NULL,'[{"name":"Thunder Wave","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Selfdestruct","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Does 10 damage to each Pokémon on each player''s Bench. (Don''t apply Weakness and Resistance for Benched Pokémon.) Magnemite does 40 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[81]',NULL,NULL,'base4');
