INSERT INTO "Card" VALUES('base4-100','Weedle','Pokémon','100','Common','Mitsuhiro Arita','Often found in forests, eating leaves. It has a sharp, venomous stinger on its head.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base4/100.png","large":"https://images.pokemontcg.io/base4/100_hires.png"}',NULL,'40','12','["Basic"]','["Grass"]',NULL,'["Kakuna"]',NULL,'[{"name":"Poison Sting","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[13]',NULL,NULL,'base4');
INSERT INTO "Card" VALUES('base4-101','Computer Search','Trainer','101','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base4/101.png","large":"https://images.pokemontcg.io/base4/101_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 of the other cards from your hand in order to search your deck for any card and put it into your hand. Shuffle your deck afterward."]','base4');
