INSERT INTO "Card" VALUES('base4-107','Scoop Up','Trainer','107','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base4/107.png","large":"https://images.pokemontcg.io/base4/107_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon in play and return its Basic Pokémon card to your hand. (Discard all cards attached to that card.)"]','base4');
