INSERT INTO "Card" VALUES('base5-46','Dark Wartortle','Pokémon','46','Uncommon','Kagemaru Himeno','A Pokémon with a negative attitude, it hides in its shell whenever it''s in a bad mood—which is often.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/46.png","large":"https://images.pokemontcg.io/base5/46_hires.png"}',NULL,'60','21','["Stage 1"]','["Water"]','Squirtle','["Blastoise"]',NULL,'[{"name":"Doubleslap","cost":["Water"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."},{"name":"Mirror Shell","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"","text":"If an attack does damage to Dark Wartortle during your opponent''s next turn (even if Dark Wartortle is Knocked Out), Dark Wartortle attacks the Defending Pokémon for an equal amount of damage."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[8]',NULL,NULL,'base5');
