INSERT INTO "Card" VALUES('base5-71','Here Comes Team Rocket!','Trainer','71','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/71.png","large":"https://images.pokemontcg.io/base5/71_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player plays with his or her Prize cards face up for the rest of the game."]','base5');
INSERT INTO "Card" VALUES('base5-72','Rocket''s Sneak Attack','Trainer','72','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/72.png","large":"https://images.pokemontcg.io/base5/72_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your opponent''s hand. If he or she has any Trainer cards, choose 1 of them. Your opponent shuffles that card into his or her deck."]','base5');
