INSERT INTO "Card" VALUES('base5-74','Challenge!','Trainer','74','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/74.png","large":"https://images.pokemontcg.io/base5/74_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Ask your opponent if he or she accepts your challenge. If your opponent declines (or if both Benches are full), draw 2 cards. If your opponent accepts, each of you searches your decks for any number of Basic Pokémon cards and puts them face down onto your Benches. (A player can''t do this if his or her Bench is full.) When you both have finished, shuffle your decks and turn those cards face up."]','base5');
INSERT INTO "Card" VALUES('base5-75','Digger','Trainer','75','Uncommon','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/75.png","large":"https://images.pokemontcg.io/base5/75_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If tails, do 10 damage to your Active Pokémon. If heads, your opponent flips a coin. If tails, your opponent does 10 damage to his or her Active Pokémon. If heads, you flip a coin. Keep doing this until a player gets tails."]','base5');
INSERT INTO "Card" VALUES('base5-76','Imposter Oak''s Revenge','Trainer','76','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/76.png","large":"https://images.pokemontcg.io/base5/76_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand in order to play this card. Your opponent shuffles his or her hand into his or her deck, then draws 4 cards."]','base5');
