INSERT INTO "Card" VALUES('base5-80','Rainbow Energy','Energy','80','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/80.png","large":"https://images.pokemontcg.io/base5/80_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Rainbow Energy to 1 of your Pokémon. While in play, Rainbow Energy counts as every type of basic Energy but only provides 1 Energy at a time. (Doesn''t count as a basic Energy card when not in play.) When you attach this card from your hand to 1 of your Pokémon, it does 10 damage to that Pokémon. (Don''t apply Weakness and Resistance.)"]','base5');
INSERT INTO "Card" VALUES('base5-81','Full Heal Energy','Energy','81','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base5/81.png","large":"https://images.pokemontcg.io/base5/81_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If you play this card from your hand, the Pokémon you attach it to is no longer Asleep, Confused, Paralyzed, or Poisoned.","Full Heal Energy provides Colorless energy. (Doesn''t count as a basic Energy card.)"]','base5');
