INSERT INTO "Card" VALUES('base6-71','Doduo','Pokémon','71','Common','Mitsuhiro Arita','A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/71.png","large":"https://images.pokemontcg.io/base6/71_hires.png"}',NULL,'50','10','["Basic"]','["Colorless"]',NULL,'["Dodrio"]',NULL,'[{"name":"Fury Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[84]',NULL,NULL,'base6');
