INSERT INTO "Card" VALUES('base6-81','Mankey','Pokémon','81','Common','Sumiyoshi Kizuki','Normally friendly, it quickly becomes angry if it doesn''t get what it wants.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/81.png","large":"https://images.pokemontcg.io/base6/81_hires.png"}',NULL,'40','14','["Basic"]','["Fighting"]',NULL,'["Primeape"]',NULL,'[{"name":"Mischief","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Shuffle your opponent''s deck."},{"name":"Anger","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 20 more damage; if tails, this attack does 20 damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,NULL,NULL,'[56]',NULL,NULL,'base6');
