INSERT INTO "Card" VALUES('base6-93','Slowpoke','Pokémon','93','Common','Miki Tanaka','Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/93.png","large":"https://images.pokemontcg.io/base6/93_hires.png"}',NULL,'50','18','["Basic"]','["Psychic"]',NULL,'["Slowbro","Slowking"]',NULL,'[{"name":"Spacing Out","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, remove a damage counter from Slowpoke. This attack can''t be used if Slowpoke has no damage counters on it."},{"name":"Scavenge","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"","text":"Discard 1 Psychic Energy card attached to Slowpoke in order to use this attack. Put a Trainer card from your discard pile into your hand."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[79]',NULL,NULL,'base6');
