INSERT INTO "Card" VALUES('base6-97','Voltorb','Pokémon','97','Common','Keiji Kinebuchi','Usually found in power plants. Easily mistaken for a Poké Ball, it has zapped many people.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/97.png","large":"https://images.pokemontcg.io/base6/97_hires.png"}',NULL,'40','10','["Basic"]','["Lightning"]',NULL,'["Electrode"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[100]',NULL,NULL,'base6');
INSERT INTO "Card" VALUES('base6-98','Vulpix','Pokémon','98','Common','Ken Sugimori','At the time of birth, it has just one tail. Its tail splits from the tip as it grows older.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/98.png","large":"https://images.pokemontcg.io/base6/98_hires.png"}',NULL,'50','11','["Basic"]','["Fire"]',NULL,'["Ninetales"]',NULL,'[{"name":"Confuse Ray","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[37]',NULL,NULL,'base6');
INSERT INTO "Card" VALUES('base6-99','Weedle','Pokémon','99','Common','Mitsuhiro Arita','Often found in forests, eating leaves. It has a sharp, venomous stinger on its head.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base6/99.png","large":"https://images.pokemontcg.io/base6/99_hires.png"}',NULL,'40','12','["Basic"]','["Grass"]',NULL,'["Kakuna"]',NULL,'[{"name":"Poison Sting","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[13]',NULL,NULL,'base6');
INSERT INTO "Card" VALUES('base6-100','Full Heal Energy','Energy','100','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/100.png","large":"https://images.pokemontcg.io/base6/100_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If you play this card from your hand, the Pokémon you attach it to is no longer affected by a Special Condition. Full Heal Energy provides Colorless energy. (Doesn''t count as a basic Energy card.)"]','base6');
INSERT INTO "Card" VALUES('base6-101','Potion Energy','Energy','101','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/101.png","large":"https://images.pokemontcg.io/base6/101_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If you play this card from your hand, remove 1 damage counter from the Pokémon you attach it to, if it has any. Potion Energy provides Colorless energy. (Doesn''t count as a basic Energy card.)"]','base6');
INSERT INTO "Card" VALUES('base6-102','Pokémon Breeder','Trainer','102','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/102.png","large":"https://images.pokemontcg.io/base6/102_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Stage 2 Evolution card from your hand on the matching Basic Pokémon. You can play this card only when you would be allowed to evolve that Pokémon anyway."]','base6');
INSERT INTO "Card" VALUES('base6-103','Pokémon Trader','Trainer','103','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/103.png","large":"https://images.pokemontcg.io/base6/103_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Trade 1 of the Basic Pokémon or Evolution cards in your hand for 1 of the Basic Pokémon or Evolution cards from your deck. Show both cards to your opponent. Shuffle your deck afterward."]','base6');
INSERT INTO "Card" VALUES('base6-104','Scoop Up','Trainer','104','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/104.png","large":"https://images.pokemontcg.io/base6/104_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon in play and return its Basic Pokémon card to your hand. (Discard all cards attached to that card.)"]','base6');
INSERT INTO "Card" VALUES('base6-105','The Boss''s Way','Trainer','105','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/105.png","large":"https://images.pokemontcg.io/base6/105_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for an Evolution card with Dark in its name. Show it to your opponent and put it into your hand. Shuffle your deck afterward."]','base6');
INSERT INTO "Card" VALUES('base6-106','Challenge!','Trainer','106','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/106.png","large":"https://images.pokemontcg.io/base6/106_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Ask your opponent if he or she accepts your challenge. If your opponent declines (or if both Benches are full), draw 2 cards. If your opponent accepts, each of you searches your decks for any number of Basic Pokémon cards and puts them face down onto your Benches. (A player can''t do this if his or her Bench is full.) When you both have finished, shuffle your decks and turn those cards face up."]','base6');
INSERT INTO "Card" VALUES('base6-107','Energy Retrieval','Trainer','107','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base6/107.png","large":"https://images.pokemontcg.io/base6/107_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Trade 1 of the other cards in your hand for up to 2 basic Energy cards from your discard pile."]','base6');
INSERT INTO "Card" VALUES('base6-108','Bill','Trainer','108','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/108.png","large":"https://images.pokemontcg.io/base6/108_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 2 cards."]','base6');
INSERT INTO "Card" VALUES('base6-109','Mysterious Fossil','Trainer','109','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/base6/109.png","large":"https://images.pokemontcg.io/base6/109_hires.png"}',NULL,'10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Pokémon (instead of a Trainer card). Mysterious Fossil has no attacks, can''t retreat, and can''t be affected by Special Conditions. If Mysterious Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play. You can put Pokémon that evolve from Mysterious Fossil on this card."]','base6');
INSERT INTO "Card" VALUES('base6-110','Potion','Trainer','110','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/base6/110.png","large":"https://images.pokemontcg.io/base6/110_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove up to 2 damage counters from 1 of your Pokémon."]','base6');
INSERT INTO "Card" VALUES('basep-1','Pikachu','Pokémon','1','Promo','Keiji Kinebuchi','When several of these Pokémon gather, their electricity could build and cause lightning storms.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/1.png","large":"https://images.pokemontcg.io/basep/1_hires.png"}',NULL,'60','16','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Growl","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If the Defending Pokémon attacks Pikachu during your opponent''s next turn, any damage done by the attack is reduced by 10 (after applying Weakness and Resistance). (Benching either Pokémon ends this effect.)"},{"name":"Thundershock","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-2','Electabuzz','Pokémon','2','Promo','Ken Sugimori','A wild Pokémon with a short temper. It is able to distinguish colors, and likes the color red.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/2.png","large":"https://images.pokemontcg.io/basep/2_hires.png"}',NULL,'60','20','["Basic"]','["Lightning"]',NULL,'["Electivire"]',NULL,'[{"name":"Light Screen","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Whenever an attack does damage to Electabuzz (after applying Weakness and Resistance) during your opponent''s next turn, that attack only does half the damage to Electabuzz (rounded down to the nearest 10). (Any other effects of attacks still happen.)"},{"name":"Quick Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[125]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-3','Mewtwo','Pokémon','3','Promo','Ken Sugimori','Years of genetic experiments resulted in the creation of this never-before-seen violent Pokémon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/3.png","large":"https://images.pokemontcg.io/basep/3_hires.png"}',NULL,'70','60','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Energy Absorption","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Choose up to 2 Energy cards from your discard pile and attach them to Mewtwo."},{"name":"Psyburn","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-4','Pikachu','Pokémon','4','Promo','Ken Sugimori','When several of these Pokémon gather, they attract so much electricity that they can cause lightning to strike.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/4.png","large":"https://images.pokemontcg.io/basep/4_hires.png"}',NULL,'50','13','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Recharge","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Lightning Energy card and attach it to Pikachu. Shuffle your deck afterward."},{"name":"Thunderbolt","cost":["Lightning","Lightning","Lightning"],"convertedEnergyCost":3,"damage":"50","text":"Discard all Energy cards attached to Pikachu in order to use this attack."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-5','Dragonite','Pokémon','5','Promo','Toshinao Aoki','This Pokémon can fly is spite of its large bulk. It is said to be able to circumnavigate the earth in just 16 hours.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/5.png","large":"https://images.pokemontcg.io/basep/5_hires.png"}',NULL,'90','43','["Stage 2"]','["Colorless"]','Dragonair',NULL,'[{"name":"Special Delivery","text":"Once during your turn (before your attack), you may draw a card. If you do, choose a card from your hand and put it on top of your deck. This power can''t be used if Dragonite is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Supersonic Flight","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Flip a coin. If tails, this attack does nothing."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[149]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-6','Arcanine','Pokémon','6','Promo','Ken Sugimori','A legendary Pokémon famous for its beauty. It looks almost as if it flies when it runs.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/6.png","large":"https://images.pokemontcg.io/basep/6_hires.png"}',NULL,'70','34','["Stage 1"]','["Fire"]','Growlithe',NULL,NULL,'[{"name":"Quick Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage."},{"name":"Flames of Rage","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"40+","text":"Discard 2 Fire Energy cards attached to Arcanine in order to use this attack. This attack does 40 damage plus 10 more damage for each damage counter on Arcanine."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[59]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-7','Jigglypuff','Pokémon','7','Promo','Keiji Kinebuchi','When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/7.png","large":"https://images.pokemontcg.io/basep/7_hires.png"}',NULL,'50','12','["Basic"]','["Colorless"]',NULL,'["Wigglytuff"]',NULL,'[{"name":"First Aid","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Remove 1 damage counter from Jigglypuff."},{"name":"Double-edge","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Jigglypuff does 20 damage to itself."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[39]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-8','Mew','Pokémon','8','Promo','Ken Sugimori','So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/8.png","large":"https://images.pokemontcg.io/basep/8_hires.png"}',NULL,'50','23','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Psywave","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10×","text":"Does 10 damage times the number of Energy cards attached to the Defending Pokémon."},{"name":"Devolution Beam","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"","text":"Choose an evolved Pokémon (your own or your opponent''s). Return the highest Stage Evolution card on that Pokémon to its player''s hand. That Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned, or anything else that might be the result of an attack (just as if you had evolved it)."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-9','Mew','Pokémon','9','Promo','Ken Sugimori','So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/9.png","large":"https://images.pokemontcg.io/basep/9_hires.png"}',NULL,'50','51','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Psywave","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10×","text":"Does 10 damage times the number of Energy cards attached to the Defending Pokémon."},{"name":"Devolution Beam","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"","text":"Choose an evolved Pokémon (your own or your opponent''s). Return the highest Stage Evolution card on that Pokémon to its player''s hand. That Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned, or anything else that might be the result of an attack (just as if you had evolved it)."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-10','Meowth','Pokémon','10','Promo','Kagemaru Himeno','Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/10.png","large":"https://images.pokemontcg.io/basep/10_hires.png"}',NULL,'50','13','["Basic"]','["Colorless"]',NULL,'["Persian"]',NULL,'[{"name":"Cat Punch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, this attack does 20 damage. If tails and if your opponent has any Benched Pokémon, he or she chooses 1 of them and this attack does 20 damage to it. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[52]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-11','Eevee','Pokémon','11','Promo','Kagemaru Himeno','Its genetic code is irregular. It may mutate if it is exposed to radiation from elemental stones.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/11.png","large":"https://images.pokemontcg.io/basep/11_hires.png"}',NULL,'30','7','["Basic"]','["Colorless"]',NULL,'["Vaporeon","Jolteon","Flareon","Sylveon","Espeon","Umbreon","Leafeon","Glaceon"]','[{"name":"Chain Reaction","text":"This power can only be used when a Pokémon evolves. Search your deck for a card that evolves from Eevee and attach it to Eevee. This counts as evolving Eevee. Shuffle your deck afterward. This power can''t be used if Eevee is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Bite","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]',NULL,NULL,'[133]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-12','Mewtwo','Pokémon','12','Promo','Christopher Rush','A scientist created this Pokémon after years of horrific gene-splicing and DNA engineering experiments.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/12.png","large":"https://images.pokemontcg.io/basep/12_hires.png"}',NULL,'60','13','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Energy Control","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose a basic Energy card attached to 1 of your opponent''s Pokémon and attach it to another of your opponent''s Pokémon of your choice."},{"name":"Telekinesis","cost":["Psychic","Psychic","Psychic"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 30 damage to that Pokémon. Don''t apply Weakness and Resistance for this attack. (Any other effects that would happen after applying Weakness and Resistance still happen.)"}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-13','Venusaur','Pokémon','13','Promo','Ken Sugimori','This plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/13.png","large":"https://images.pokemontcg.io/basep/13_hires.png"}',NULL,'100','16','["Stage 2"]','["Grass"]','Ivysaur',NULL,'[{"name":"Solar Power","text":"Once during your turn (before your attack), you may use this power. Your Active Pokémon and the Defending Pokémon are no longer Asleep, Confused, Paralyzed, or Poisoned. This power can''t be used if Venusaur is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Mega Drain","cost":["Grass","Grass","Grass","Grass"],"convertedEnergyCost":4,"damage":"40","text":"Remove a number of damage counters from Venusaur equal to half the damage done to the Defending Pokémon (after applying Weakness and Resistance) (rounded up to the nearest 10). If Venusaur has fewer damage counters than that, remove all of them."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[3]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-14','Mewtwo','Pokémon','14','Promo','Benimaru Itoh','Years of genetic experiments resulted in the creation of this never-before-seen violent Pokémon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/14.png","large":"https://images.pokemontcg.io/basep/14_hires.png"}',NULL,'70','60','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Energy Absorption","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Choose up to 2 Energy cards from your discard pile and attach them to Mewtwo."},{"name":"Psyburn","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-15','Cool Porygon','Pokémon','15','Promo','Hiromichi Sugiyama','A Pokémon that consists entirely of programming code. Capable of moving freely in cyberspace.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/15.png","large":"https://images.pokemontcg.io/basep/15_hires.png"}',NULL,'50','15','["Basic"]','["Colorless"]',NULL,'["Porygon2"]',NULL,'[{"name":"Texture Magic","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"You may change Cool Porygon''s Resistance to a type of your choice other than Colorless. If the Defending Pokémon has a Weakness, you may change it to a type of your choice other than Colorless. (Benching either Pokémon ends the effect on that Pokémon.)"},{"name":"3-D Attack","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20×","text":"Flip 3 coins. This attack does 20 damage times the number of heads."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[137]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-16','Computer Error','Trainer','16','Promo','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/16.png","large":"https://images.pokemontcg.io/basep/16_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may draw up to 5 cards, then your opponent may draw up to 5 cards. Your turn is over now (you don''t get to attack)."]','basep');
INSERT INTO "Card" VALUES('basep-17','Dark Persian','Pokémon','17','Promo','Ken Sugimori','Popular with women because of its beautiful fur. The leader of the Rockets keeps one as a pet.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/17.png","large":"https://images.pokemontcg.io/basep/17_hires.png"}',NULL,'60','28','["Stage 1"]','["Colorless"]','Meowth',NULL,NULL,'[{"name":"Tempt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has any Benched Pokémon, flip a coin. If heads, choose 1 of your opponent''s Benched Pokémon and switch it with the Defending Pokémon."},{"name":"Poison Claws","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. if heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]',NULL,NULL,'[53]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-18','Team Rocket''s Meowth','Pokémon','18','Promo','Kunihiko Yuyama','This Pokémon is more active at night. It likes bright, shiny things and cannot resist taking them and adding them to its collection.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/18.png","large":"https://images.pokemontcg.io/basep/18_hires.png"}',NULL,'40','30','["Basic"]','["Colorless"]',NULL,'["Persian"]',NULL,'[{"name":"Miraculous Comeback","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a number of coins equal to the number of Pokémon in play. This attack does 10 damage times the number of heads. Then Team Rocket''s Meowth does 10 damage times the number of tails to itself."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[52]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-19','Sabrina''s Abra','Pokémon','19','Promo','Atsuko Nishida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/19.png","large":"https://images.pokemontcg.io/basep/19_hires.png"}',NULL,'40','15','["Basic"]','["Psychic"]',NULL,'["Kadabra"]',NULL,'[{"name":"Pound","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Synchronize","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"This attack can''t be used unless Sabrina''s Abra and the Defending Pokémon have the same number of Energy cards attached to them."}]','[{"type":"Psychic","value":"×2"}]',NULL,NULL,NULL,'[63]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-20','Psyduck','Pokémon','20','Promo','Kagemaru Himeno','While lulling its enemies with its vacant look, this wily Pokémon will use psychokinetic powers.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/20.png","large":"https://images.pokemontcg.io/basep/20_hires.png"}',NULL,'50','15','["Basic"]','["Water"]',NULL,'["Golduck"]',NULL,'[{"name":"Headache","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Your opponent can''t play Trainer cards during his or her next turn."},{"name":"Fury Swipes","cost":["Water"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 3 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[54]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-21','Moltres','Pokémon','21','Promo','Toshinao Aoki','The flames on this legendary Pokémon''s wings burn so brightly that they can make night seem like day.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/21.png","large":"https://images.pokemontcg.io/basep/21_hires.png"}',NULL,'70','33','["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Hyper Flame","cost":["Fire","Fire","Fire"],"convertedEnergyCost":3,"damage":"60","text":"Flip a coin. If heads, discard 1 Fire Energy card attached to Moltres. If tails, discard all Energy cards attached to Moltres. If you can''t discard Energy cards, this attack does nothing."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[146]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-22','Articuno','Pokémon','22','Promo','Toshinao Aoki','This legendary Pokémon is said to freeze the water in the air during winter, causing snow.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/22.png","large":"https://images.pokemontcg.io/basep/22_hires.png"}',NULL,'70','34','["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Diamond Dust","cost":["Water","Water","Water"],"convertedEnergyCost":3,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed and this attack does 10 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[144]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-23','Zapdos','Pokémon','23','Promo','Toshinao Aoki','This legendary Pokémon is said to be present wherever there is a lightning storm.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/23.png","large":"https://images.pokemontcg.io/basep/23_hires.png"}',NULL,'70','30','["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Lightning Burn","cost":["Lightning","Lightning","Lightning"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, and if your opponent has any Benched Pokémon, choose 1 of them. This attack does 30 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) If tails, Zapdos does 30 damage to itself."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[145]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-24','_____''s Pikachu','Pokémon','24','Promo','Kagemaru Himeno','Your Birthdate: ______________________________','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/24.png","large":"https://images.pokemontcg.io/basep/24_hires.png"}',NULL,'50','17','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Birthday Surprise","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"30+","text":"If it''s not your birthday, this attack does 30 damage. If it is your birthday, flip a coin. If heads, this attack does 30 damage plus 50 more damage; if tails, this attack does 30 damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-25','Flying Pikachu','Pokémon','25','Promo','Toshinao Aoki','By learning how to fly, Pikachu overcame its weakness to Fighting Pokémon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/25.png","large":"https://images.pokemontcg.io/basep/25_hires.png"}',NULL,'40','12','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Thundershock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Fly","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all effects of attacks, including damage, done to Flying Pikachu; if tails, this attack does nothing (not even damage)."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-26','Pikachu','Pokémon','26','Promo','Gakuji Nomoto','It uses its sensitive tail to sense its environment and has been known to react violently if its tail is grabbed.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/26.png","large":"https://images.pokemontcg.io/basep/26_hires.png"}',NULL,'40','9','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Thunderbolt","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"40","text":"Discard all Energy cards attached to Pikachu."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-27','Pikachu','Pokémon','27','Promo','Atsuko Nishida','When several of these Pokémon gather, their electricity can cause lightning storms.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/27.png","large":"https://images.pokemontcg.io/basep/27_hires.png"}',NULL,'30','5','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Thundershock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Agility","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all effects of attacks, including damage, done to Pikachu."}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-28','Surfing Pikachu','Pokémon','28','Promo','Toshinao Aoki','One summer, a group of Pikachus was found riding the waves at the local beach.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/basep/28.png","large":"https://images.pokemontcg.io/basep/28_hires.png"}',NULL,'50','32','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Surf","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-29','Marill','Pokémon','29','Promo','Ken Sugimori','The tip of its tail, which contains oil that is lighter than water, lets it swim without drowning.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/29.png","large":"https://images.pokemontcg.io/basep/29_hires.png"}',NULL,'50','64','["Basic"]','["Water"]',NULL,'["Azumarill"]',NULL,'[{"name":"Water Gun","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"20+","text":"Does 20 damage plus 10 more damage for each Energy attached to Marill but not used to pay for this attack''s Energy cost. You can''t add more than 20 damage in this way."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[183]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-30','Togepi','Pokémon','30','Promo','Ken Sugimori','Still only a hatchling, it uses poison to chase off its enemies when threatened.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/30.png","large":"https://images.pokemontcg.io/basep/30_hires.png"}',NULL,'30','8','["Basic"]','["Colorless"]',NULL,'["Togetic"]',NULL,'[{"name":"Snivel","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If the Defending Pokémon attacks Togepi during your opponent''s next turn, any damage done to Togepi is reduced by 20 (before applying Weakness and Resistance). (Benching either Pokémon ends this effect.)"},{"name":"Mini-Metronome","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, choose 1 of the Defending Pokémon''s attacks. Mini-Metronome copies that attack except for its Energy cost. (You must still do anything else in order to use that attack.) (No matter what type the Defending Pokémon is, Togepi''s type is still Colorless.) Togepi performs that attack."}]',NULL,'[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[175]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-31','Cleffa','Pokémon','31','Promo','Ken Sugimori','Because of its unusual, star-like silhouette, people believe that it came here on a meteor.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/31.png","large":"https://images.pokemontcg.io/basep/31_hires.png"}',NULL,'30','5','["Baby"]','["Colorless"]',NULL,'["Clefairy"]',NULL,'[{"name":"Eek","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw 2 cards."}]',NULL,NULL,NULL,NULL,'[173]',NULL,'["If this Baby Pokémon is your Active Pokémon and your opponent announces an attack, your opponent flips a coin (before doing anything else). If tails, your opponent''s turn ends."]','basep');
INSERT INTO "Card" VALUES('basep-32','Smeargle','Pokémon','32','Promo','Tomokazu Komiya','Once it becomes an adult, it has a tendency to let its comrades plant footprints on its back.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/32.png","large":"https://images.pokemontcg.io/basep/32_hires.png"}',NULL,'40','21','["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Paint","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose a type (other than Colorless) and put a Coloring counter on the Defending Pokémon. That Pokémon is now the type you chose. If it already had a Coloring counter, remove the old one. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[235]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-33','Scizor','Pokémon','33','Promo','Hironobu Yoshida','Its wings are not used for flying. They are flapped at high speed to adjust its body temperature.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/33.png","large":"https://images.pokemontcg.io/basep/33_hires.png"}',NULL,'70','36','["Stage 1"]','["Metal"]','Scyther',NULL,NULL,'[{"name":"Leer","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon can''t attack Scizor during your opponent''s next turn. (Benching either Pokémon ends this effect.)"},{"name":"Metal Pincer","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"Flip a coin until you get tails. This attack does 30 damage plus 10 more damage for each heads."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless"]',2,'[212]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-34','Entei','Pokémon','34','Promo','Ken Sugimori','Volcanoes erupt when it barks. Unable to restrain its extreme power, it races headlong around the land.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/34.png","large":"https://images.pokemontcg.io/basep/34_hires.png"}',NULL,'80','37','["Basic"]','["Fire"]',NULL,NULL,'[{"name":"Bolt","text":"Whenever your opponent''s attack damages Entei, unless that attack Knocks Out Entei, flip a coin. If heads, shuffle Entei and all cards attached to it into your deck. This power can''t be used if Entei is already Asleep, Confused, or Paralyzed when it is damaged.","type":"Pokémon Power"}]','[{"name":"Protective Flame","cost":["Fire","Fire","Fire"],"convertedEnergyCost":3,"damage":"50","text":"During your opponent''s next turn, prevent all effects of attacks, including damage, done to your Benched Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[244]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-35','Pichu','Pokémon','35','Promo','Ken Sugimori','It is not yet skilled at storing electricity. It may send out a jolt if amused or startled.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/35.png","large":"https://images.pokemontcg.io/basep/35_hires.png"}',NULL,'30','4','["Baby"]','["Lightning"]',NULL,'["Pikachu"]',NULL,'[{"name":"Let''s Play!","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Baby Pokémon card and put it onto your Bench. Shuffle your deck afterward. (You can''t use this attack if your Bench is full.)"}]',NULL,NULL,NULL,NULL,'[172]',NULL,'["If this Baby Pokémon is your Active Pokémon and your opponent announces an attack, your opponent flips a coin (before doing anything else). If tails, your opponent''s turn ends."]','basep');
INSERT INTO "Card" VALUES('basep-36','Igglybuff','Pokémon','36','Promo','Kagemaru Himeno','Its extremely flexible and elastic body makes it bounce continuously—anytime, anywhere.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/36.png","large":"https://images.pokemontcg.io/basep/36_hires.png"}',NULL,'30','5','["Baby"]','["Colorless"]',NULL,'["Jigglypuff"]',NULL,'[{"name":"Good Night Song","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."}]',NULL,NULL,NULL,NULL,'[174]',NULL,'["If this Baby Pokémon is your Active Pokémon and your opponent announces an attack, your opponent flips a coin (before doing anything else). If tails, your opponent''s turn ends."]','basep');
INSERT INTO "Card" VALUES('basep-37','Hitmontop','Pokémon','37','Promo','Atsuko Nishida','It launches kicks while spinning. If it spins at high speed, it may bore its way into the ground.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/37.png","large":"https://images.pokemontcg.io/basep/37_hires.png"}',NULL,'60','29','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Repeating Kick","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"20×","text":"Flip a coin until you get tails. This attack does 20 damage times the number of heads."},{"name":"Rapid Spin","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with his or her Active Pokémon, then, if you have any Benched Pokémon, you switch 1 of them with your Active Pokémon. (Do the damage before switching the Pokémon.)"}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[237]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-38','Unown [J]','Pokémon','38','Promo','Hideki Kazama','Their shapes look like hieroglyphs on ancient tablets. It is said that the two are somehow related.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/38.png","large":"https://images.pokemontcg.io/basep/38_hires.png"}',NULL,'40','17','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"[Join]","text":"Once during your turn (before your attack), if you have Unown [J], Unown [O], Unown [I], and Unown Dragon on your Bench, you may search your deck for a Basic Pokémon or Evolution card. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward.","type":"Pokémon Power"}]','[{"name":"Hidden Power","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[201]',NULL,'["You may have up to 4 Basic Pokémon cards in your deck with Unown in their names."]','basep');
INSERT INTO "Card" VALUES('basep-39','Misdreavus','Pokémon','39','Promo','Shin-ichi Yoshida','It loves to bite and yank people''s hair from behind without warning, just to see their shocked reactions.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/39.png","large":"https://images.pokemontcg.io/basep/39_hires.png"}',NULL,'50','23','["Basic"]','["Psychic"]',NULL,'["Mismagius"]',NULL,'[{"name":"Pain Split","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Put 1 damage counter on the Defending Pokémon for each damage counter on Misdreavus."},{"name":"Confuse Ray","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[200]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-40','Pokémon Center','Trainer','40','Promo','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/40.png","large":"https://images.pokemontcg.io/basep/40_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all damage counters from all of your own Pokémon with damage counters on them, then discard all Energy cards attached to those Pokémon."]','basep');
INSERT INTO "Card" VALUES('basep-41','Lucky Stadium','Trainer','41','Promo','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/41.png","large":"https://images.pokemontcg.io/basep/41_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may flip a coin. If heads, that player draws a card."]','basep');
INSERT INTO "Card" VALUES('basep-42','Pokémon Tower','Trainer','42','Promo','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/42.png","large":"https://images.pokemontcg.io/basep/42_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","If the effect of a Pokémon Power, attack, Energy card, or Trainer card would put a card in a discard pile into its owner''s hand, that card stays in that discard pile instead."]','basep');
INSERT INTO "Card" VALUES('basep-43','Machamp','Pokémon','43','Promo','Tomokazu Komiya','Using its amazing muscles, it throws powerful punches that can knock its victim clear over the horizon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/43.png","large":"https://images.pokemontcg.io/basep/43_hires.png"}',NULL,'90','54','["Stage 2"]','["Fighting"]','Machoke',NULL,NULL,'[{"name":"Seething Anger","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a number of coins equal to the number of damage counters on Machamp. This attack does 20 damage plus 10 more damage for each heads."},{"name":"Fling","cost":["Fighting","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"50","text":"If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with the Defending Pokémon. (Do the damage before switching the Pokémon.)"}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[68]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-44','Magmar','Pokémon','44','Promo','Atsuko Nishida','Its body always burns with an orange glow that enables it to hide perfectly among flames.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/44.png","large":"https://images.pokemontcg.io/basep/44_hires.png"}',NULL,'60','27','["Basic"]','["Fire"]',NULL,'["Magmortar"]',NULL,'[{"name":"Burning Fire","cost":["Fire"],"convertedEnergyCost":1,"damage":"10+","text":"When you use this attack, you may discard any number of Fire Energy cards attached to your Pokémon in play. This attack does 10 damage plus 10 more damage for each Fire Energy card you discarded in this way."},{"name":"Magma Punch","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[126]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-45','Scyther','Pokémon','45','Promo','Hironobu Yoshida','With ninja-like agility and speed, it can create the illusion that there is more than one.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/45.png","large":"https://images.pokemontcg.io/basep/45_hires.png"}',NULL,'60','23','["Basic"]','["Grass"]',NULL,'["Scizor"]',NULL,'[{"name":"Slashing Strike","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"40","text":"Scyther can''t use this attack during your next turn. (Benching or evolving Scyther ends this effect.)"}]','[{"type":"Fire","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[123]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-46','Electabuzz','Pokémon','46','Promo','Miki Tanaka','Normally found near power plants, it can wander away and cause major blackouts in cities.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/46.png","large":"https://images.pokemontcg.io/basep/46_hires.png"}',NULL,'60','22','["Basic"]','["Lightning"]',NULL,'["Electivire"]',NULL,'[{"name":"Lightning Rod","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon and put a Lightning Rod marker on it. (A Pokémon can have only 1 Lightning Rod marker on it at a time.)"},{"name":"Lightning Bolt","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"10","text":"This attack does 20 damage to any Pokémon with a Lightning Rod marker on it. Apply Weakness and Resistance."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[125]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-47','Mew','Pokémon','47','Promo','Ken Sugimori','So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/47.png","large":"https://images.pokemontcg.io/basep/47_hires.png"}',NULL,'40','8','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Neutral Shield","text":"Prevent all effects of attacks, including damage, done to Mew by Evolved Pokémon. You can''t use this power if Mew is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Psyshock","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-48','Articuno','Pokémon','48','Promo','Atsuko Nishida','A legendary bird Pokémon that is said to appear to doomed people who are lost in icy mountains.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/48.png","large":"https://images.pokemontcg.io/basep/48_hires.png"}',NULL,'80','34','["Basic"]','["Water"]',NULL,NULL,'[{"name":"Aurora Veil","text":"As long as Articuno is your Active Pokémon, your Benched Pokémon do not take damage from and are not affected by attacks. This power cannot be used if Articuno is affected by a Special Condition.","type":"Pokémon Power"}]','[{"name":"Ice Beam","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[144]',NULL,NULL,'basep');
INSERT INTO "Card" VALUES('basep-49','Snorlax','Pokémon','49','Promo','Craig Turvey','Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/basep/49.png","large":"https://images.pokemontcg.io/basep/49_hires.png"}',NULL,'90','35','["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Guard","text":"As long as Snorlax is your Active Pokémon, the Defending Pokémon can''t Retreat. This power stops working when Snorlax is affected by a Special Condition.","type":"Pokémon Power"}]','[{"name":"Roll Over","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"30","text":"Snorlax is now Asleep. Flip a coin. If heads, the Defending Pokémon is now Asleep."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[143]',NULL,NULL,'basep');
