INSERT INTO "Card" VALUES('bp-1','Electabuzz','Pokémon','1','Promo','Ken Sugimori','Normally found near power plants, it can wander away and cause major blackouts in cities.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/1.png","large":"https://images.pokemontcg.io/bp/1_hires.png"}',NULL,'70','35','["Basic"]','["Lightning"]',NULL,'["Electivire"]',NULL,'[{"name":"Thundershock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Thunderpunch","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 10 more damage; if tails, this attack does 30 damage plus Electabuzz does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[125]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-2','Hitmonchan','Pokémon','2','Promo','Ken Sugimori','While seeming to do nothing, it fires punches in lightning-fast volleys that are impossible to see.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/2.png","large":"https://images.pokemontcg.io/bp/2_hires.png"}',NULL,'60','33','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Jab","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Special Punch","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[107]',NULL,NULL,'bp');
