INSERT INTO "Card" VALUES('bp-4','Rocket''s Scizor','Pokémon','4','Promo','K Hoshiba',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/4.png","large":"https://images.pokemontcg.io/bp/4_hires.png"}',NULL,'60',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Focus","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your next turn, Rocket''s Scizor''s Agility attack''s damage is doubled."},{"name":"Agility","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all effects of attacks, including damage, done to Rocket''s Scizor."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless"]',2,'[212]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-5','Rocket''s Sneasel','Pokémon','5','Promo','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/5.png","large":"https://images.pokemontcg.io/bp/5_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"name":"Entrap","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."},{"name":"Continuous Scratch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10×","text":"Flip 4 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[215]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-6','Dark Ivysaur','Pokémon','6','Promo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/6.png","large":"https://images.pokemontcg.io/bp/6_hires.png"}',NULL,'50',NULL,'["Stage 1"]','["Grass"]','Bulbasaur','["Dark Venusaur"]','[{"name":"Vine Pull","text":"Once during your turn when Dark Ivysaur retreats, choose 1 of your opponent''s Benched Pokémon and switch it with his or her Active Pokémon.","type":"Poké-Body"}]','[{"name":"Fury Strikes","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"","text":"Your opponent puts 3 markers onto his or her Pokémon (divided as he or she chooses). (More than 1 marker can be put on the same Pokémon.) Then, this attack does 10 damage to each Pokémon for each marker on it. Don''t apply Weakness and Resistance. Remove the markers at the end of the turn."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[2]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-7','Dark Venusaur','Pokémon','7','Promo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/7.png","large":"https://images.pokemontcg.io/bp/7_hires.png"}',NULL,'70',NULL,'["Stage 2"]','["Grass"]','Dark Ivysaur',NULL,NULL,'[{"name":"Horrid Pollen","cost":["Grass","Grass","Grass"],"convertedEnergyCost":3,"damage":"30","text":"Flip 2 coins. If 1 is heads, the Defending Pokémon is now Asleep and Poisoned. If both are heads, the Defending Pokémon is now Confused and Poisoned. If both are tails, the Defending Pokémon is now Paralyzed and Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[3]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-8','Rocket''s Mewtwo','Pokémon','8','Promo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/8.png","large":"https://images.pokemontcg.io/bp/8_hires.png"}',NULL,'70','35','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Juxtapose","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, switch the number of damage counters on Rocket''s Mewtwo with the number of damage counters on the Defending Pokémon (even if it would Knock Out either Pokémon). (It''s okay if 1 of the Pokémon has no damage counters on it.)"},{"name":"Hypnoblast","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Asleep."},{"name":"Psyburn","cost":["Psychic","Psychic","Psychic","Colorless"],"convertedEnergyCost":4,"damage":"60","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'bp');
INSERT INTO "Card" VALUES('bp-9','Rocket''s Hitmonchan','Pokémon','9','Promo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/bp/9.png","large":"https://images.pokemontcg.io/bp/9_hires.png"}',NULL,'60','29','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Crosscounter","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"If an attack does damage to Rocket''s Hitmonchan during your opponent''s next turn (even if Rocket''s Hitmonchan is Knocked Out), flip a coin. If heads, Rocket''s Hitmonchan attacks your opponent''s Active Pokémon for double that amount of damage. (If Rocket''s Hitmonchan takes 20 damage, it does 40 damage to that Pokémon.)"},{"name":"Magnum Punch","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[107]',NULL,NULL,'bp');
