INSERT INTO "Card" VALUES('bw1-3','Servine','Pokémon','3','Uncommon','Kagemaru Himeno','They avoid attacks by sinking into the shadows of thick foliage. They retaliate with masterful whipping techniques.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw1/3.png","large":"https://images.pokemontcg.io/bw1/3_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Grass"]','Snivy','["Serperior"]',NULL,'[{"name":"Wrap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Tackle","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[496]',NULL,NULL,'bw1');
