INSERT INTO "Card" VALUES('bw1-54','Scolipede','Pokémon','54','Rare','Masakazu Fukuda','Highly aggressive, it uses the claws near its neck to dig into its opponent and poison them.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw1/54.png","large":"https://images.pokemontcg.io/bw1/54_hires.png"}',NULL,'150',NULL,'["Stage 2"]','["Psychic"]','Whirlipede',NULL,NULL,'[{"name":"Steamroller","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"This attack''s damage isn''t affected by Resistance."},{"name":"Poison Claws","cost":["Psychic","Psychic","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[545]',NULL,NULL,'bw1');
