INSERT INTO "Card" VALUES('bw1-60','Gurdurr','Pokémon','60','Uncommon','Naoki Saito','They strengthen their bodies by carrying steel beams. They show off their big muscles to their friends.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw1/60.png","large":"https://images.pokemontcg.io/bw1/60_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fighting"]','Timburr','["Conkeldurr"]',NULL,'[{"name":"Bulk Up","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"During your next turn, each of this Pokémon''s attacks does 20 more damage (before applying Weakness and Resistance)."},{"name":"Pound","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[533]',NULL,NULL,'bw1');
