INSERT INTO "Card" VALUES('bw1-68','Scraggy','Pokémon','68','Common','Masakazu Fukuda','Its skin has a rubbery elasticity, so it can reduce damage by defensively pulling its skin up to its neck.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw1/68.png","large":"https://images.pokemontcg.io/bw1/68_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Scrafty"]',NULL,'[{"name":"Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[559]',NULL,NULL,'bw1');
