INSERT INTO "Card" VALUES('bw10-3','Lileep','Pokémon','3','Uncommon','Suwama Chiaki','It lived on the seafloor 100 million years ago and was reanimated scientifically.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw10/3.png","large":"https://images.pokemontcg.io/bw10/3_hires.png"}',NULL,'80',NULL,'["Restored"]','["Grass"]','Root Fossil Lileep','["Cradily"]','[{"name":"Prehistoric Call","text":"Once during your turn (before your attack), if this Pokémon is in your discard pile, you may put this Pokémon on the bottom of your deck.","type":"Ability"}]','[{"name":"Spiral Drain","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Heal 10 damage from this Pokémon."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[345]',NULL,'["Put this card onto your Bench only with the effect of Root Fossil Lileep"]','bw10');
INSERT INTO "Card" VALUES('bw10-4','Cradily','Pokémon','4','Rare','kawayoo','It lives in the shallows of warm seas. When the tide goes out, it digs up prey from beaches.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw10/4.png","large":"https://images.pokemontcg.io/bw10/4_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Grass"]','Lileep',NULL,NULL,'[{"name":"Lifesplosion","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"For each Energy attached to this Pokémon, search your deck for a Stage 2 Pokémon and put it onto your Bench. Shuffle your deck afterward."},{"name":"Spiral Drain","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Heal 20 damage from this Pokémon."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[346]',NULL,NULL,'bw10');
