INSERT INTO "Card" VALUES('bw11-76','Reuniclus','Pokémon','76','Rare','Kyoko Umemoto','When Reuniclus shake hands, a network forms between their brains, increasing their psychic power.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw11/76.png","large":"https://images.pokemontcg.io/bw11/76_hires.png"}',NULL,'90',NULL,'["Stage 2"]','["Psychic"]','Duosion',NULL,NULL,'[{"name":"Future Sight","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 5 cards of your deck and put them back on top of your deck in any order."},{"name":"Net Force","cost":["Psychic"],"convertedEnergyCost":1,"damage":"40×","text":"Does 40 damage times the number of Reuniclus you have in play."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[579]',NULL,NULL,'bw11');
