INSERT INTO "Card" VALUES('bw11-107','Bouffalant','Pokémon','107','Uncommon','Sanosuke Sakuma','Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw11/107.png","large":"https://images.pokemontcg.io/bw11/107_hires.png"}',NULL,'100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Revenge","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"If any of your Pokémon were Knocked Out by damage from an opponent''s attack during his or her last turn, this attack does 70 more damage."},{"name":"Head Charge","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"Flip a coin. If tails, this Pokémon does 20 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[626]',NULL,NULL,'bw11');
