INSERT INTO "Card" VALUES('bw11-RC23','Emolga','Pokémon','RC23','Rare Ultra','Atsuko Nishida','It glides on its outstretched membrane while shocking foes with the electricity stored in the pouches on its cheeks.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw11/RC23.png","large":"https://images.pokemontcg.io/bw11/RC23_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for 2 Basic Pokémon and put them onto your Bench. Shuffle your deck afterward."},{"name":"Static Shock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[587]',NULL,NULL,'bw11');
