INSERT INTO "Card" VALUES('bw3-71','Golett','Pokémon','71','Common','Masakazu Fukuda','These Pokémon are thought to have been created by the science of an ancient and mysterious civilization.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw3/71.png","large":"https://images.pokemontcg.io/bw3/71_hires.png"}',NULL,'80',NULL,'["Basic"]','["Fighting"]',NULL,'["Golurk"]',NULL,'[{"name":"Dynamic Punch","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, this attack does 20 more damage and the Defending Pokémon is now Confused."}]','[{"type":"Water","value":"×2"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[622]',NULL,NULL,'bw3');
