INSERT INTO "Card" VALUES('bw3-79','Hydreigon','Pokémon','79','Rare Holo','5ban Graphics','The heads on their arms do not have brains. They use all three heads to consume and destroy everything.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw3/79.png","large":"https://images.pokemontcg.io/bw3/79_hires.png"}',NULL,'150',NULL,'["Stage 2"]','["Darkness"]','Zweilous',NULL,'[{"name":"Dark Aura","text":"All Energy attached to this Pokémon are Darkness Energy instead of their usual type.","type":"Ability"}]','[{"name":"Berserker Blade","cost":["Darkness","Darkness","Darkness","Darkness"],"convertedEnergyCost":4,"damage":"60","text":"Does 40 damage to 2 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[635]',NULL,NULL,'bw3');
