INSERT INTO "Card" VALUES('bw3-89','Druddigon','Pokémon','89','Rare','Masakazu Fukuda','It races through narrow caves, using its sharp claws to catch prey. The skin on its face is harder than a rock.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw3/89.png","large":"https://images.pokemontcg.io/bw3/89_hires.png"}',NULL,'100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Rough Skin","text":"If this Pokémon is your Active Pokémon and is damaged by an opponent''s attack (even if this Pokémon is Knocked Out), put 2 damage counters on the Attacking Pokémon.","type":"Ability"}]','[{"name":"Clutch","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]',NULL,NULL,'["Colorless","Colorless"]',2,'[621]',NULL,NULL,'bw3');
INSERT INTO "Card" VALUES('bw3-90','Cover Fossil','Trainer','90','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw3/90.png","large":"https://images.pokemontcg.io/bw3/90_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the bottom 7 cards of your deck. You may reveal a Tirtouga you find there and put it onto your Bench. Shuffle the other cards back into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','bw3');
