INSERT INTO "Card" VALUES('bw4-69','Sneasel','Pokémon','69','Common','Masakazu Fukuda','A smart and sneaky Pokémon. A pair may work together to steal eggs by having one lure the parents away.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw4/69.png","large":"https://images.pokemontcg.io/bw4/69_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Weavile"]',NULL,'[{"name":"Corner","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."},{"name":"Scratch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[215]',NULL,NULL,'bw4');
