INSERT INTO "Card" VALUES('bw4-84','Minccino','Pokémon','84','Uncommon','Tomohiro Kitakaze','These Pokémon prefer a tidy habitat. They are always sweeping and dusting, using their tails as brooms.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw4/84.png","large":"https://images.pokemontcg.io/bw4/84_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Cinccino"]',NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward."},{"name":"Tail Smack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[572]',NULL,NULL,'bw4');
