INSERT INTO "Card" VALUES('bw6-24','Gyarados','Pokémon','24','Rare','Mizue','Once it begins to rampage, a Gyarados will burn everything down, even in a harsh storm.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/24.png","large":"https://images.pokemontcg.io/bw6/24_hires.png"}',NULL,'130',NULL,'["Stage 1"]','["Water"]','Magikarp',NULL,NULL,'[{"name":"Sharp Fang","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""},{"name":"Swing Around","cost":["Water","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60+","text":"Flip 2 coins. This attack does 30 more damage for each heads."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[130]',NULL,NULL,'bw6');
INSERT INTO "Card" VALUES('bw6-25','Wailmer','Pokémon','25','Uncommon','Atsuko Nishida','On sunny days, it lands on beaches to bounce like a ball and play. It spouts water from its nose.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/25.png","large":"https://images.pokemontcg.io/bw6/25_hires.png"}',NULL,'100',NULL,'["Basic"]','["Water"]',NULL,'["Wailord"]',NULL,'[{"name":"Lullaby","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Asleep."},{"name":"Water Gun","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[320]',NULL,NULL,'bw6');
INSERT INTO "Card" VALUES('bw6-26','Wailord','Pokémon','26','Rare Holo','match','The biggest of all Pokémon. It can dive to a depth of almost 10,000 feet on only one breath.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/26.png","large":"https://images.pokemontcg.io/bw6/26_hires.png"}',NULL,'200',NULL,'["Stage 1"]','["Water"]','Wailmer',NULL,NULL,'[{"name":"Water Cannon","cost":["Water"],"convertedEnergyCost":1,"damage":"30×","text":"Flip a coin. If heads, this attack does 30 damage times the amount of Water Energy attached to this Pokémon."},{"name":"Giant Wave","cost":["Water","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"This Pokémon can''t use Giant Wave during your next turn."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[321]',NULL,NULL,'bw6');
INSERT INTO "Card" VALUES('bw6-27','Feebas','Pokémon','27','Common','Kouki Saitou','It is a shabby and ugly Pokémon. However, it is very hardy and can survive on little water.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/27.png","large":"https://images.pokemontcg.io/bw6/27_hires.png"}',NULL,'30',NULL,'["Basic"]','["Water"]',NULL,'["Milotic"]',NULL,'[{"name":"Add-a-Dash","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Flip 2 coins. For each heads, draw a card."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[349]',NULL,NULL,'bw6');
