INSERT INTO "Card" VALUES('bw6-45','Emolga','Pokémon','45','Uncommon','Kanako Eo','They live on treetops and glide using the inside of a cape-like membrane while discharging electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/45.png","large":"https://images.pokemontcg.io/bw6/45_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for 2 Basic Pokémon and put them onto your Bench. Shuffle your deck afterward."},{"name":"Static Shock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[587]',NULL,NULL,'bw6');
