INSERT INTO "Card" VALUES('bw6-48','Shedinja','Pokémon','48','Rare','Masakazu Fukuda','A discarded bug shell that came to life. Peering into the crack on its back is said to steal one''s spirit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/48.png","large":"https://images.pokemontcg.io/bw6/48_hires.png"}',NULL,'60',NULL,'["Stage 1"]','["Psychic"]','Nincada',NULL,'[{"name":"Empty Shell","text":"If this Pokémon is Knocked Out, your opponent can''t take any Prize cards for it.","type":"Ability"}]','[{"name":"Cursed Drop","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Put 3 damage counters on your opponent''s Pokémon in any way you like."}]',NULL,NULL,NULL,NULL,'[292]',NULL,NULL,'bw6');
