INSERT INTO "Card" VALUES('bw6-53','Trubbish','Pokémon','53','Common','Tomokazu Komiya','Inhaling the gas they belch will make you sleep for a week. They prefer unsanitary places.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/53.png","large":"https://images.pokemontcg.io/bw6/53_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,'["Garbodor"]',NULL,'[{"name":"Pound","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""},{"name":"Poison Gas","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[568]',NULL,NULL,'bw6');
