INSERT INTO "Card" VALUES('bw6-55','Gothita','Pokémon','55','Common','Aya Kusube','They intently observe both Trainers and Pokémon. Apparently, they are looking at something that only Gothita can see.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/55.png","large":"https://images.pokemontcg.io/bw6/55_hires.png"}',NULL,'50',NULL,'["Basic"]','["Psychic"]',NULL,'["Gothorita"]',NULL,'[{"name":"Future Sight","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 5 cards of your deck and put them back on top of your deck in any order."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[574]',NULL,NULL,'bw6');
