INSERT INTO "Card" VALUES('bw6-62','Nosepass','Pokémon','62','Common','Shin Nagasawa','When endangered, it may protect itself by raising its magnetism and drawing iron objects to its body.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/62.png","large":"https://images.pokemontcg.io/bw6/62_hires.png"}',NULL,'80',NULL,'["Basic"]','["Fighting"]',NULL,'["Probopass"]',NULL,'[{"name":"Rock Throw","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[299]',NULL,NULL,'bw6');
