INSERT INTO "Card" VALUES('bw6-64','Claydol','Pokémon','64','Rare','Shin Nagasawa','An ancient clay figurine that came to life as a Pokémon from exposure to a mysterious ray of light.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/64.png","large":"https://images.pokemontcg.io/bw6/64_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fighting"]','Baltoy',NULL,NULL,'[{"name":"Rapid Spin","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Switch this Pokémon with 1 of your Benched Pokémon. Then, your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Rock Smash","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Flip a coin. If heads, this attack does 30 more damage."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[344]',NULL,NULL,'bw6');
