INSERT INTO "Card" VALUES('bw6-69','Sawk','Pokémon','69','Uncommon','Masakazu Fukuda','Tying their belts gets them pumped and makes their punches more destructive. Disturbing their training angers them.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw6/69.png","large":"https://images.pokemontcg.io/bw6/69_hires.png"}',NULL,'90',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Defensive Stance","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Heal 30 damage from this Pokémon. Switch this Pokémon with 1 of your Benched Pokémon."},{"name":"Karate Chop","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70-","text":"Does 70 damage minus 10 damage for each damage counter on this Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[539]',NULL,NULL,'bw6');
