INSERT INTO "Card" VALUES('bw7-18','Charmander','Pokémon','18','Common','Akira Komayama','The fire on the tip of its tail is a measure of its life. If healthy, its tail burns intensely.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/18.png","large":"https://images.pokemontcg.io/bw7/18_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fire"]',NULL,'["Charmeleon"]',NULL,'[{"name":"Draw In","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Attach 2 Fire Energy cards from your discard pile to this Pokémon."},{"name":"Flare","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[4]',NULL,NULL,'bw7');
