INSERT INTO "Card" VALUES('bw7-24','Tepig','Pokémon','24','Common','Shin Nagasawa','It blows fire through its nose. When it catches a cold, the fire becomes pitch-black smoke instead.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/24.png","large":"https://images.pokemontcg.io/bw7/24_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Pignite"]',NULL,'[{"name":"Flare","cost":["Fire"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Rollout","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[498]',NULL,NULL,'bw7');
