INSERT INTO "Card" VALUES('bw7-31','Blastoise','Pokémon','31','Rare Holo','Satoshi Shirai','The jets of water it spouts from the rocket cannons on its shell can punch through thick steel.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/31.png","large":"https://images.pokemontcg.io/bw7/31_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Water"]','Wartortle',NULL,'[{"name":"Deluge","text":"As often as you like during your turn (before your attack), you may attach a Water Energy card from your hand to 1 of your Pokémon.","type":"Ability"}]','[{"name":"Hydro Pump","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60+","text":"Does 10 more damage for each Water Energy attached to this Pokémon."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[9]',NULL,NULL,'bw7');
