INSERT INTO "Card" VALUES('bw7-37','Azumarill','Pokémon','37','Uncommon','Masakazu Fukuda','Its long ears are superb sensors. It can distinguish the movements of things in water and tell what they are.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/37.png","large":"https://images.pokemontcg.io/bw7/37_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Water"]','Marill',NULL,NULL,'[{"name":"Deep Dive","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip 2 coins. For each heads, heal 40 damage from this Pokémon."},{"name":"Aqua Sonic","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"This attack''s damage isn''t affected by Resistance."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[184]',NULL,NULL,'bw7');
