INSERT INTO "Card" VALUES('bw7-73','Whirlipede','Pokémon','73','Uncommon','match','Storing energy for evolution, it sits. But, when predators approach, it moves to stab them with poison spikes.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/73.png","large":"https://images.pokemontcg.io/bw7/73_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Psychic"]','Venipede','["Scolipede"]','[{"name":"Poison Point","text":"If this Pokémon is your Active Pokémon and is damaged by an opponent''s attack (even if this Pokémon is Knocked Out), this Attacking Pokémon is now Poisoned.","type":"Ability"}]','[{"name":"Spinning Attack","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[544]',NULL,NULL,'bw7');
