INSERT INTO "Card" VALUES('bw7-105','Raticate','Pokémon','105','Uncommon','Naoki Saito','With its long fangs, this surprisingly violent Pokémon can gnaw away even thick concrete with ease.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/105.png","large":"https://images.pokemontcg.io/bw7/105_hires.png"}',NULL,'60',NULL,'["Stage 1"]','["Colorless"]','Rattata',NULL,NULL,'[{"name":"Gnaw Through","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Discard a Pokémon Tool card attached to the Defending Pokémon."},{"name":"Super Fang","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Put damage counters on the Defending Pokémon until its remaining HP is 10."}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[20]',NULL,NULL,'bw7');
