INSERT INTO "Card" VALUES('bw7-114','Delcatty','Pokémon','114','Uncommon','Shin Nagasawa','The reason it does not have a nest is that it simply searches for a clean, comfortable place then sleeps there.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/114.png","large":"https://images.pokemontcg.io/bw7/114_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Colorless"]','Skitty',NULL,NULL,'[{"name":"Gather Energy","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"Search your deck for a basic Energy card and attach it to 1 of your Pokémon. Shuffle your deck afterward."},{"name":"Double Slap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30×","text":"Flip 2 coins. This attack does 30 damage times the number of heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[301]',NULL,NULL,'bw7');
