INSERT INTO "Card" VALUES('bw7-123','Pidove','Pokémon','123','Common','Tomokazu Komiya','This very forgetful Pokémon will wait for a new order from its Trainer even though it already has one.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw7/123.png","large":"https://images.pokemontcg.io/bw7/123_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Tranquill"]',NULL,'[{"name":"Razor Wind","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[519]',NULL,NULL,'bw7');
