INSERT INTO "Card" VALUES('bw8-1','Turtwig','Pokémon','1','Common','Kouki Saitou','The shell on its back is made of soil. On a very healthy Turtwig, the shell should feel moist.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw8/1.png","large":"https://images.pokemontcg.io/bw8/1_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,'["Grotle"]',NULL,'[{"name":"Nap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Heal 20 damage from this Pokémon."},{"name":"Razor Leaf","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[387]',NULL,NULL,'bw8');
