INSERT INTO "Card" VALUES('bw8-9','Swadloon','Pokémon','9','Uncommon','Kyoko Umemoto','Preferring dark, damp places, it spends the entire day eating fallen leaves that lie around it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw8/9.png","large":"https://images.pokemontcg.io/bw8/9_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Grass"]','Sewaddle','["Leavanny"]',NULL,'[{"name":"Swaddle Guard","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, any damage done to this Pokémon by attacks is reduced by 40 (after applying Weakness and Resistance)."},{"name":"Surprise Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[541]',NULL,NULL,'bw8');
