INSERT INTO "Card" VALUES('bw8-110','Patrat','Pokémon','110','Common','Kouki Saitou','Extremely cautious, one of them will always be on the lookout, but it won''t notice a foe coming from behind.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw8/110.png","large":"https://images.pokemontcg.io/bw8/110_hires.png"}',NULL,'50',NULL,'["Basic"]','["Colorless"]',NULL,'["Watchog"]',NULL,'[{"name":"Reckless Charge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[504]',NULL,NULL,'bw8');
