INSERT INTO "Card" VALUES('bw9-80','Mawile','Pokémon','80','Uncommon','Mitsuhiro Arita','Attached to its head is a huge set of jaws formed by horns. It can chew through iron beams.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/80.png","large":"https://images.pokemontcg.io/bw9/80_hires.png"}',NULL,'70',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Astonish","cost":["Metal"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose a random card from your opponent''s hand. Your opponent reveals that card and shuffles it into his or her deck."},{"name":"Big Ol'' Bite","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Heal 30 damage from this Pokémon. The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[303]',NULL,NULL,'bw9');
