INSERT INTO "Card" VALUES('bw9-84','Kingdra','Pokémon','84','Rare Holo','Naoyo Kimura','It lives in caves on the seafloor and creates giant whirlpools every time it moves.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/84.png","large":"https://images.pokemontcg.io/bw9/84_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Dragon"]','Seadra',NULL,NULL,'[{"name":"Dragon Vortex","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20×","text":"Does 20 damage times the number of Water Energy cards and Lightning Energy cards in your discard pile. Then, shuffle all of those cards back into your deck."},{"name":"Tri Bullet","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"This attack does 30 damage to 3 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Dragon","value":"×2"}]',NULL,'["Colorless"]',1,'[230]',NULL,NULL,'bw9');
