INSERT INTO "Card" VALUES('bw9-89','Eevee','Pokémon','89','Common','Naoki Saito','Thanks to its unstable genetic makeup, this special Pokémon conceals many different possible evolutions.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/89.png","large":"https://images.pokemontcg.io/bw9/89_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Vaporeon","Jolteon","Flareon","Sylveon","Espeon","Umbreon","Leafeon","Glaceon"]',NULL,'[{"name":"Growl","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, any damage done by attacks from the Defending Pokémon is reduced by 20 (before applying Weakness and Resistance)."},{"name":"Quick Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[133]',NULL,NULL,'bw9');
