INSERT INTO "Card" VALUES('bw9-91','Hoothoot','Pokémon','91','Common','match','It marks time precisely. Some countries consider it to be a wise friend, versed in the world''s ways.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/91.png","large":"https://images.pokemontcg.io/bw9/91_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Noctowl"]',NULL,'[{"name":"Dual Draw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Each player draws 2 cards."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[163]',NULL,NULL,'bw9');
