INSERT INTO "Card" VALUES('bw9-95','Starly','Pokémon','95','Common','Kouki Saitou','Because they are weak individually, they form groups. However, they bicker if the group grows too big.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/95.png","large":"https://images.pokemontcg.io/bw9/95_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Staravia"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[396]',NULL,NULL,'bw9');
