INSERT INTO "Card" VALUES('bw9-103','Superior Energy Retrieval','Trainer','103','Uncommon','5ban Graphics',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/103.png","large":"https://images.pokemontcg.io/bw9/103_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 cards from your hand. (If you can''t discard 2 cards, you can''t play this card.) Put 4 basic Energy cards from your discard pile into your hand. (You can''t choose a card you discarded with the effect of this card.)","You may play as many Item cards as you like during your turn (before your attack)."]','bw9');
