INSERT INTO "Card" VALUES('bw9-107','Life Dew','Trainer','107','Rare ACE','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/bw9/107.png","large":"https://images.pokemontcg.io/bw9/107_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If the Pokémon this card is attached to is Knocked Out, your opponent takes 1 fewer Prize card.","You may play as many Item cards as you like during your turn (before your attack).","You can''t have more than 1 ACE SPEC card in your deck."]','bw9');
