INSERT INTO "Card" VALUES('cel25-3','Kyogre','Pokémon','3','Rare','Ryuta Fuse','It is said to have widened the seas by causing downpours. It had been asleep in a marine trench.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/cel25/3.png","large":"https://images.pokemontcg.io/cel25/3_hires.png"}','E','130',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"cost":["Water","Water","Colorless"],"name":"Aqua Storm","damage":"","text":"Discard the top 5 cards of your deck, and then choose 2 of your opponent''s Benched Pokémon. This attack does 50 damage for each Energy card you discarded in this way to each of those Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)","convertedEnergyCost":3},{"cost":["Water","Water","Colorless","Colorless"],"name":"Surf","damage":"120","text":"","convertedEnergyCost":4}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[382]',NULL,NULL,'cel25');
INSERT INTO "Card" VALUES('cel25-4','Palkia','Pokémon','4','Rare','5ban Graphics','It has the ability to distort space. It is described as a deity in Sinnoh-region mythology.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/cel25/4.png","large":"https://images.pokemontcg.io/cel25/4_hires.png"}','E','130',NULL,'["Basic"]','["Water"]',NULL,NULL,'[{"type":"Ability","name":"Absolute Space","text":"As long as this Pokémon is in the Active Spot, your opponent can''t play any Stadium cards from their hand."}]','[{"cost":["Water","Colorless","Colorless"],"name":"Overdrive Smash","damage":"80+","text":"During your next turn, this Pokémon''s Overdrive Smash attack does 80 more damage (before applying Weakness and Resistance).","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[484]',NULL,NULL,'cel25');
