INSERT INTO "Card" VALUES('cel25c-2_A','Blastoise','Pokémon','2','Classic Collection','Ken Sugimori','A brutal Pokémon with pressurized water jets on its shell. They are used for high-speed tackles.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/2_A.png","large":"https://images.pokemontcg.io/cel25c/2_A_hires.png"}',NULL,'100','52','["Stage 2"]','["Water"]','Wartortle',NULL,'[{"name":"Rain Dance","text":"As often as you like during your turn (before your attack), you may attach 1 Water Energy card to 1 of your Water Pokémon. (This doesn''t use up your 1 Energy card attachment for the turn.) This power can''t be used if Blastoise is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"cost":["Water","Water","Water"],"name":"Hydro Pump","damage":"40+","text":"Does 40 damage plus 10 more damage for each Water Energy attached to Blastoise but not used to pay for this attack''s Energy cost. Extra Water Energy after the 2nd doesn''t count.","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[9]',NULL,NULL,'cel25c');
INSERT INTO "Card" VALUES('cel25c-4_A','Charizard','Pokémon','4','Classic Collection','Mitsuhiro Arita','Spits fire that is hot enough to melt boulders. Known to unintentionally cause forest fires.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/4_A.png","large":"https://images.pokemontcg.io/cel25c/4_A_hires.png"}',NULL,'120','76','["Stage 2"]','["Fire"]','Charmeleon',NULL,'[{"name":"Energy Burn","text":"As often as you like during your turn (before your attack), you may turn all Energy attached to Charizard into Fire Energy for the rest of the turn. This power can''t be used if Charizard is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"cost":["Fire","Fire","Fire","Fire"],"name":"Fire Spin","damage":"100","text":"Discard 2 Energy cards attached to Charizard in order to use this attack.","convertedEnergyCost":4}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[6]',NULL,NULL,'cel25c');
