INSERT INTO "Card" VALUES('cel25c-15_A4','Claydol','Pokémon','15','Classic Collection','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/15_D.png","large":"https://images.pokemontcg.io/cel25c/15_D_hires.png"}',NULL,'80','45','["Stage 1"]','["Fighting"]','Baltoy',NULL,'[{"type":"Poké-Power","name":"Cosmic Power","text":"Once during your turn (before your attack), you may choose up to 2 cards from your hand and put them on the bottom of your deck in any order. If you do, draw cards until you have 6 cards in your hand. This power can''t be used if Claydol is affected by a Special Condition."}]','[{"cost":["Fighting","Colorless"],"name":"Spinning Attack","damage":"40","text":"","convertedEnergyCost":2}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[344]',NULL,NULL,'cel25c');
