INSERT INTO "Card" VALUES('cel25c-86_A','Rocket''s Admin.','Trainer','86','Classic Collection','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/86_A.png","large":"https://images.pokemontcg.io/cel25c/86_A_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Each player shuffles his or her hand into his or her deck. Then, each player counts his or her Prize cards left and draws up to that many cards. (You draw your cards first.)"]','cel25c');
INSERT INTO "Card" VALUES('cel25c-88_A','Mew ex','Pokémon','88','Classic Collection','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/88_A.png","large":"https://images.pokemontcg.io/cel25c/88_A_hires.png"}',NULL,'90',NULL,'["Basic","ex"]','["Psychic"]',NULL,NULL,'[{"type":"Poké-Body","name":"Versatile","text":"Mew ex can use the attacks of all Pokémon in play as its own. (You still need the necessary Energy to use each attack.)"}]','[{"cost":["Psychic","Colorless"],"name":"Power Move","damage":"","text":"Search your deck for an Energy card and attach it to Mew ex. Shuffle your deck afterward. Then, you may switch Mew ex with 1 of your Benched Pokémon.","convertedEnergyCost":2}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,'["When Pokémon-ex has been knocked out, your opponent takes 2 Prize cards."]','cel25c');
INSERT INTO "Card" VALUES('cel25c-93_A','Gardevoir ex δ','Pokémon','93','Classic Collection','Masahiko Ishii',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/93_A.png","large":"https://images.pokemontcg.io/cel25c/93_A_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Fire"]','Kirlia',NULL,'[{"type":"Poké-Power","name":"Imprison","text":"Once during your turn (before your attack), if Gardevoir ex is your Active Pokémon, you may put an Imprison marker on 1 of your opponent''s Pokémon. Any Pokémon that has any Imprison markers on it can''t use any Poké-Powers or Poké-Bodies. This power can''t be used if Gardevoir ex is affected by a Special Condition."}]','[{"cost":["Fire","Colorless","Colorless"],"name":"Flame Ball","damage":"80","text":"You may move a Fire Energy card attached to Gardevoir ex to 1 of your Benched Pokémon.","convertedEnergyCost":3}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[282]',NULL,'["When Pokémon-ex has been knocked out, your opponent takes 2 Prize cards."]','cel25c');
