INSERT INTO "Card" VALUES('cel25c-109_A','Luxray GL LV.X','Pokémon','109','Classic Collection','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/cel25c/109_A.png","large":"https://images.pokemontcg.io/cel25c/109_A_hires.png"}',NULL,'110','X','["Level-Up","SP"]','["Lightning"]','Luxray GL',NULL,'[{"type":"Poké-Power","name":"Bright Look","text":"Once during your turn (before your attack), when you put Luxray GL LV.X from your hand onto your Active Luxray GL, you may switch the Defending Pokémon with 1 of your opponent''s Benched Pokémon."}]','[{"cost":["Lightning","Colorless"],"name":"Flash Impact","damage":"60","text":"Does 30 damage to 1 of your Pokémon, and don''t apply Weakness and Resistance to this damage.","convertedEnergyCost":2}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]',NULL,NULL,'[405]',NULL,'["Put this card onto your Active Luxray GL. Luxray GL LV. X can use any attack, Poké-Power, or Poké-Body from its previous Level."]','cel25c');
