INSERT INTO "Card" VALUES('col1-SL1','Deoxys','Pokémon','SL1','Rare Holo','Noriko Hotta','DNA from a space virus mutated and became a Pokémon. It appears where auroras are seen.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL1.png","large":"https://images.pokemontcg.io/col1/SL1_hires.png"}',NULL,'80',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Cell Storm","cost":["Psychic","Psychic","Psychic"],"convertedEnergyCost":3,"damage":"60","text":"Discard 2 Psychic Energy attached to Deoxys and remove 6 damage counters from Deoxys."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[386]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL2','Dialga','Pokémon','SL2','Rare Holo','Ayaka Yoshida','This Pokémon completely controls the flow of time. It uses its power to travel at will through the past and future.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL2.png","large":"https://images.pokemontcg.io/col1/SL2_hires.png"}',NULL,'100',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Time Rewind","cost":["Metal","Metal","Metal","Metal"],"convertedEnergyCost":4,"damage":"70","text":"Shuffle your hand into your deck."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[483]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL3','Entei','Pokémon','SL3','Rare Holo','Yuri Umemura','A Pokémon that races across the land. It is said that one is born every time a new volcano appears.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL3.png","large":"https://images.pokemontcg.io/col1/SL3_hires.png"}',NULL,'90',NULL,'["Basic"]','["Fire"]',NULL,NULL,'[{"name":"Extreme Speed","text":"Entei''s Retreat Cost is Colorless Energy less for each Fire Energy attached to Entei.","type":"Poké-Body"}]','[{"name":"Wild Blaze","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Discard the top 3 cards of your deck."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[244]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL4','Groudon','Pokémon','SL4','Rare Holo','Yuri Umemura','Said to have expanded the lands by evaporating water with raging heat. It battled titanically with Kyogre.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL4.png","large":"https://images.pokemontcg.io/col1/SL4_hires.png"}',NULL,'100',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Volcano Stomp","cost":["Fighting","Fighting","Fighting","Fighting"],"convertedEnergyCost":4,"damage":"80","text":"Flip a coin. If heads, discard the top 4 cards of your opponent''s deck. If tails, discard the top 4 cards of your deck."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[383]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL5','Ho-Oh','Pokémon','SL5','Rare Holo','Hideaki Hakozaki','Legends claim this Pokémon flies the world''s skies continuously on its magnificent seven-colored wings.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL5.png","large":"https://images.pokemontcg.io/col1/SL5_hires.png"}',NULL,'100',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Combustion","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""},{"name":"Scorching Wing","cost":["Fire","Fire","Fire","Colorless","Colorless"],"convertedEnergyCost":5,"damage":"100","text":"Flip a coin. If tails, discard all Fire Energy attached to Ho-Oh."}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[250]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL6','Kyogre','Pokémon','SL6','Rare Holo','Yuri Umemura','A mythical Pokémon said to have swelled the seas with rain and tidal waves. It battled with Groudon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL6.png","large":"https://images.pokemontcg.io/col1/SL6_hires.png"}',NULL,'100',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Destructive Tsunami","cost":["Water","Water","Water","Water"],"convertedEnergyCost":4,"damage":"","text":"Flip a coin. If heads, this attack does 40 damage to each of your opponent''s Pokémon. If tails, this attack does 40 damage to each of your Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[382]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL7','Lugia','Pokémon','SL7','Rare Holo','Hideaki Hakozaki','It is said to be the guardian of the seas. It is rumored to have been seen on the night of a storm.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL7.png","large":"https://images.pokemontcg.io/col1/SL7_hires.png"}',NULL,'100',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Linear Attack","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 30 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Hydro Splash","cost":["Water","Water","Water","Colorless","Colorless"],"convertedEnergyCost":5,"damage":"80","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[249]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL8','Palkia','Pokémon','SL8','Rare Holo','Ayaka Yoshida','Its total control over the boundaries of space enable it to transport itself to faraway places or even other dimensions.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL8.png","large":"https://images.pokemontcg.io/col1/SL8_hires.png"}',NULL,'100',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Wormhole","cost":["Water","Water","Water","Water"],"convertedEnergyCost":4,"damage":"60","text":"Switch Palkia with 1 of your Benched Pokémon. Then, your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[484]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL9','Raikou','Pokémon','SL9','Rare Holo','Noriko Hotta','A Pokémon that races across the land while barking a cry that sounds like crashing thunder.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL9.png","large":"https://images.pokemontcg.io/col1/SL9_hires.png"}',NULL,'90',NULL,'["Basic"]','["Lightning"]',NULL,NULL,'[{"name":"Extreme Speed","text":"Raikou''s Retreat Cost is Colorless less for each Lightning Energy attached to Raikou.","type":"Poké-Body"}]','[{"name":"Raging Thunder","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Does 20 damage to 1 of your Pokémon and don''t apply Weakness and Resistance to this damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[243]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL10','Rayquaza','Pokémon','SL10','Rare Holo','Noriko Hotta','It flies in the ozone layer, way up high in the sky. Until recently, no one had ever seen it.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL10.png","large":"https://images.pokemontcg.io/col1/SL10_hires.png"}',NULL,'100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Inferno Spear","cost":["Fire","Fire","Lightning","Lightning"],"convertedEnergyCost":4,"damage":"100","text":"Discard a Fire Energy and a Lightning Energy attached to Rayquaza."}]','[{"type":"Colorless","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[384]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('col1-SL11','Suicune','Pokémon','SL11','Rare Holo','Ayaka Yoshida','This Pokémon races across the land. It is said that north winds will somehow blow whenever it appears.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/col1/SL11.png","large":"https://images.pokemontcg.io/col1/SL11_hires.png"}',NULL,'90',NULL,'["Basic"]','["Water"]',NULL,NULL,'[{"name":"Extreme Speed","text":"Suicune''s Retreat Cost is Colorless less for each Water Energy attached to Suicune.","type":"Poké-Body"}]','[{"name":"Tsunami","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"","text":"This attack does 20 damage to each of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[245]',NULL,NULL,'col1');
INSERT INTO "Card" VALUES('dc1-1','Team Magma''s Numel','Pokémon','1','Common','Akira Komayama','No matter how heavy the cargo, we can transport it to our destination with ease, thanks to Numel.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/1.png","large":"https://images.pokemontcg.io/dc1/1_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fire"]',NULL,'["Camerupt"]',NULL,'[{"name":"Ember","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Discard an Energy attached to this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[322]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-2','Team Magma''s Camerupt','Pokémon','2','Rare Holo','Shin Nagasawa','Camerupt, with its strength against fire, played a big role in rescuing team members.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/2.png","large":"https://images.pokemontcg.io/dc1/2_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Fire"]','Team Magma''s Numel',NULL,'[{"name":"Burning Draft","text":"Once during your turn (before your attack), you may attach a Fighting or Fire Energy card from your discard pile to this Pokémon.","type":"Ability"}]','[{"name":"Flame Ball","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Move a basic Energy from this Pokémon to 1 of your Benched Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[323]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-3','Team Aqua''s Spheal','Pokémon','3','Common','Sanosuke Sakuma','Spheal''s Water Gun can put out any fire. Flames used by opponents have no effect!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/3.png","large":"https://images.pokemontcg.io/dc1/3_hires.png"}',NULL,'60',NULL,'["Basic"]','["Water"]',NULL,'["Sealeo"]',NULL,'[{"name":"Water Gun","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[363]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-4','Team Aqua''s Sealeo','Pokémon','4','Common','Naoki Saito','It provides support by making paths of ice. It can win any battle as long as it''s on ice.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/4.png","large":"https://images.pokemontcg.io/dc1/4_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Water"]','Team Aqua''s Spheal','["Walrein"]',NULL,'[{"name":"Splatter","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Hail Storm","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"If your opponent''s Active Pokémon is a Team Magma Pokémon, this attack does 60 more damage."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[364]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-5','Team Aqua''s Walrein','Pokémon','5','Rare Holo','Hitoshi Ariga','It''s good at attacks that freeze opponents with a powerful cold snap. Then, it pulverizes a frozen foe with its sharp tusks!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/5.png","large":"https://images.pokemontcg.io/dc1/5_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Water"]','Team Aqua''s Sealeo',NULL,NULL,'[{"name":"Power Blow","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30×","text":"This attack does 30 damage times the amount of Energy attached to this Pokémon."},{"name":"Dual Blizzard","cost":["Water","Water","Water","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Discard 2 Water Energy attached to this Pokémon. This attack does 80 damage to 2 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[365]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-6','Team Aqua''s Kyogre-EX','Pokémon','6','Rare Ultra','nagimiso',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/6.png","large":"https://images.pokemontcg.io/dc1/6_hires.png"}',NULL,'190',NULL,'["Basic","EX"]','["Water"]',NULL,NULL,'[{"name":"Power Saver","text":"If there are 4 or fewer Team Aqua Pokémon in play, this Pokémon can''t attack.","type":"Ability"}]','[{"name":"Aqua Impact","cost":["Water","Water","Water","Colorless"],"convertedEnergyCost":4,"damage":"80+","text":"This attack does 20 more damage for each Colorless in your opponent''s Active Pokémon''s Retreat Cost."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[382]',NULL,'["Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards."]','dc1');
INSERT INTO "Card" VALUES('dc1-7','Team Aqua''s Grimer','Pokémon','7','Common','kawayoo','Its flexible body, which allows it to squeeze into any cracks, comes in handy when invading enemy hideouts.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/7.png","large":"https://images.pokemontcg.io/dc1/7_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,'["Muk"]',NULL,'[{"name":"Pound","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Mud-Slap","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[88]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-8','Team Aqua''s Muk','Pokémon','8','Rare Holo','Kouki Saitou','It immobilizes its opponents by wrapping them in its huge, poisonous body. It''ll smoosh you, too!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/8.png","large":"https://images.pokemontcg.io/dc1/8_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Psychic"]','Team Aqua''s Grimer',NULL,'[{"name":"Sludge Festival","text":"The Retreat Cost of each Pokémon in play (except for Team Aqua Pokémon) is Colorless more.","type":"Ability"}]','[{"name":"Pester","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"If your opponent''s Active Pokémon is affected by a Special Condition, this attack does 60 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[89]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-9','Team Aqua''s Seviper','Pokémon','9','Common','Naoki Saito','Seviper''s tail is a sharp blade. It can even poison you!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/9.png","large":"https://images.pokemontcg.io/dc1/9_hires.png"}',NULL,'90',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Venomous Fang","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Poisoned."},{"name":"Venom Tail","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"If your opponent''s Active Pokémon is affected by a Special Condition, discard an Energy attached to that Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[336]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-10','Team Magma''s Baltoy','Pokémon','10','Common','Mitsuhiro Arita','They all cry out at once to let us know when they spot an enemy. It really helps out!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/10.png","large":"https://images.pokemontcg.io/dc1/10_hires.png"}',NULL,'50',NULL,'["Basic"]','["Psychic"]',NULL,'["Claydol"]',NULL,'[{"name":"Telekinesis","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon. This attack''s damage isn''t affected by Weakness or Resistance."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[343]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-11','Team Magma''s Claydol','Pokémon','11','Rare Holo','Masakazu Fukuda','Claydol''s beam can seize opponents and keep them from moving. Long-range attacks are its specialty!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/11.png","large":"https://images.pokemontcg.io/dc1/11_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Psychic"]','Team Magma''s Baltoy',NULL,'[{"name":"Magma Switch","text":"Once during your turn (before your attack), you may move a basic Energy from 1 of your Pokémon to 1 of your Team Magma Pokémon.","type":"Ability"}]','[{"name":"Power Beam","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[344]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-12','Team Magma''s Aron','Pokémon','12','Common','Akira Komayama','Aron, which even devour metal, can eat and destroy enemy ships in an instant.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/12.png","large":"https://images.pokemontcg.io/dc1/12_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Lairon"]',NULL,'[{"name":"Gnaw","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[304]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-13','Team Magma''s Lairon','Pokémon','13','Common','Masakazu Fukuda','When Lairon uses Take Down, the impact from its solid body is enough to destroy concrete!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/13.png","large":"https://images.pokemontcg.io/dc1/13_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fighting"]','Team Magma''s Aron','["Aggron"]',NULL,'[{"name":"Gnaw","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Take Down","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[305]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-14','Team Magma''s Aggron','Pokémon','14','Rare Holo','TOKIYA','Aggron''s metal horns can smash through any defenses, no matter how strong!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/14.png","large":"https://images.pokemontcg.io/dc1/14_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Fighting"]','Team Magma''s Lairon',NULL,NULL,'[{"name":"Rock Stomp","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40×","text":"Discard as many Fighting Energy attached to your Pokémon as you like. This attack does 40 damage times the amount of Fighting Energy you discarded."},{"name":"Boulder Storm","cost":["Fighting","Fighting","Fighting","Colorless"],"convertedEnergyCost":4,"damage":"120","text":"This attack does 20 damage to each of your opponent''s Benched Pokémon that has any damage counters on it. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[306]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-15','Team Magma''s Groudon-EX','Pokémon','15','Rare Ultra','nagimiso',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/15.png","large":"https://images.pokemontcg.io/dc1/15_hires.png"}',NULL,'190',NULL,'["Basic","EX"]','["Fighting"]',NULL,NULL,'[{"name":"Power Saver","text":"If there are 4 or fewer Team Magma Pokémon in play, this Pokémon can''t attack.","type":"Ability"}]','[{"name":"Magma Quake","cost":["Fighting","Fighting","Fighting","Colorless"],"convertedEnergyCost":4,"damage":"80+","text":"If your opponent''s Active Pokémon already has any damage counters on it, this attack does 80 more damage."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[383]',NULL,'["Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards."]','dc1');
INSERT INTO "Card" VALUES('dc1-16','Team Aqua''s Poochyena','Pokémon','16','Common','Kouki Saitou','Poochyena can easily detect invading foes with its acute sense of smell. It''s an excellent lookout!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/16.png","large":"https://images.pokemontcg.io/dc1/16_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Mightyena"]',NULL,'[{"name":"Roar","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon."},{"name":"Bite","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[261]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-17','Team Magma''s Poochyena','Pokémon','17','Common','TOKIYA','Poochyena''s nose can identify any scent. It''s very useful for reconnaissance.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/17.png","large":"https://images.pokemontcg.io/dc1/17_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Mightyena"]',NULL,'[{"name":"Infiltrate","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Your opponent reveals his or her hand."},{"name":"Bite","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[261]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-18','Team Aqua''s Mightyena','Pokémon','18','Common','Mitsuhiro Arita','Thanks to Mightyena''s outstanding leadership, it''s very good at combination attacks that can leave a foe helpless.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/18.png","large":"https://images.pokemontcg.io/dc1/18_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Darkness"]','Team Aqua''s Poochyena',NULL,NULL,'[{"name":"Teampact","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30×","text":"Flip a coin for each Team Aqua Pokémon you have in play. This attack does 30 damage times the number of heads."},{"name":"Crunch","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Flip a coin. If heads, discard an Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[262]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-19','Team Magma''s Mightyena','Pokémon','19','Common','Hitoshi Ariga','This Pokémon is loyal to its master. It will protect its partner to the end, no matter what.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/19.png","large":"https://images.pokemontcg.io/dc1/19_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Darkness"]','Team Magma''s Poochyena',NULL,NULL,'[{"name":"Bite","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Hostile Fang","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"If your opponent''s Active Pokémon is a Team Aqua Pokémon, this attack does 40 more damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[262]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-20','Team Aqua''s Carvanha','Pokémon','20','Common','Sanosuke Sakuma','You can''t keep up with its movements underwater, can you? If you get caught in this whirlpool, there''ll be no escape.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/20.png","large":"https://images.pokemontcg.io/dc1/20_hires.png"}',NULL,'50',NULL,'["Basic"]','["Darkness"]',NULL,'["Sharpedo"]',NULL,'[{"name":"Fin Smack","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[318]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-21','Team Aqua''s Sharpedo','Pokémon','21','Rare Holo','kawayoo','It boasts fangs so powerful that they knock opponents out in one shot! Enemies that slip up will be taken down without fail!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/21.png","large":"https://images.pokemontcg.io/dc1/21_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Darkness"]','Team Aqua''s Carvanha',NULL,'[{"name":"Aqua Search","text":"Once during your turn (before your attack), you may search your deck for a Team Aqua Pokémon, reveal it, and put it into your hand. Shuffle your deck afterward.","type":"Ability"}]','[{"name":"Sharp Fang","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,NULL,NULL,'[319]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-22','Team Magma''s Zangoose','Pokémon','22','Common','Shin Nagasawa','Can you handle the formation attack of the fearless Zangoose?','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/22.png","large":"https://images.pokemontcg.io/dc1/22_hires.png"}',NULL,'90',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Basic Team Magma Pokémon and put them onto your Bench. Shuffle your deck afterward."},{"name":"Team Play","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20×","text":"This attack does 20 damage times the number of Team Magma Pokémon on your Bench."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[335]',NULL,NULL,'dc1');
INSERT INTO "Card" VALUES('dc1-23','Aqua Diffuser','Trainer','23','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/23.png","large":"https://images.pokemontcg.io/dc1/23_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,'[{"name":"Aqua Diffuser","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Confused and Poisoned."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Team Aqua Pokémon this card is attached to can also use the attack on this card. (You still need the necessary Energy to use this attack.)","You may play as many Item cards as you like during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-24','Magma Pointer','Trainer','24','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/24.png","large":"https://images.pokemontcg.io/dc1/24_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,'[{"name":"Magma Pointer","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Team Magma Pokémon this card is attached to can also use the attack on this card. (You still need the necessary Energy to use this attack.)","You may play as many Item cards as you like during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-25','Team Aqua Admin','Trainer','25','Uncommon','GAME FREAK inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/25.png","large":"https://images.pokemontcg.io/dc1/25_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a basic Energy card from your discard pile to your Active Team Aqua Pokémon.","You may play only 1 Supporter card during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-26','Team Aqua Grunt','Trainer','26','Uncommon','GAME FREAK inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/26.png","large":"https://images.pokemontcg.io/dc1/26_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand. (If you can''t discard a card, you can''t play this card.) Draw 3 cards. If you discarded a Team Aqua Pokémon, draw 1 more card.","You may play only 1 Supporter card during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-27','Team Aqua''s Great Ball','Trainer','27','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/27.png","large":"https://images.pokemontcg.io/dc1/27_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Team Aqua Pokémon and a basic Water Energy card, reveal them, and put them into your hand. Shuffle your deck afterward.","You may play as many Item cards as you like during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-28','Team Aqua''s Secret Base','Trainer','28','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/28.png","large":"https://images.pokemontcg.io/dc1/28_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The Retreat Cost of each Pokémon in play (except for Team Aqua Pokémon) is Colorless more.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','dc1');
INSERT INTO "Card" VALUES('dc1-29','Team Magma Admin','Trainer','29','Uncommon','GAME FREAK inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/29.png","large":"https://images.pokemontcg.io/dc1/29_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put up to 3 Team Magma Pokémon from your discard pile into your hand.","You may play only 1 Supporter card during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-30','Team Magma Grunt','Trainer','30','Uncommon','GAME FREAK inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/30.png","large":"https://images.pokemontcg.io/dc1/30_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand. (If you can''t discard a card, you can''t play this card.) Draw 3 cards. If you discarded a Team Magma Pokémon, draw 1 more card.","You may play only 1 Supporter card during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-31','Team Magma''s Great Ball','Trainer','31','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/31.png","large":"https://images.pokemontcg.io/dc1/31_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Team Magma Pokémon and a basic Fighting Energy card, reveal them, and put them into your hand. Shuffle your deck afterward.","You may play as many Item cards as you like during your turn (before your attack)."]','dc1');
INSERT INTO "Card" VALUES('dc1-32','Team Magma''s Secret Base','Trainer','32','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/32.png","large":"https://images.pokemontcg.io/dc1/32_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Whenever any player puts a Basic Pokémon (except for Team Magma Pokémon) from his or her hand onto his or her Bench, put 2 damage counters on that Pokémon.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','dc1');
INSERT INTO "Card" VALUES('dc1-33','Double Aqua Energy','Energy','33','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/33.png","large":"https://images.pokemontcg.io/dc1/33_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card can only be attached to Team Aqua Pokémon. Discard this card at the end of the turn you attached it.","This card provides WaterWater Energy only while it is attached to a Team Aqua Pokémon.","(If this card is attached to anything other than a Team Aqua Pokémon, discard this card.)"]','dc1');
INSERT INTO "Card" VALUES('dc1-34','Double Magma Energy','Energy','34','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dc1/34.png","large":"https://images.pokemontcg.io/dc1/34_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card can only be attached to Team Magma Pokémon. Discard this card at the end of the turn you attached it.","This card provides FightingFighting Energy only while it is attached to a Team Magma Pokémon.","(If this card is attached to anything other than a Team Magma Pokémon, discard this card.)"]','dc1');
INSERT INTO "Card" VALUES('det1-1','Bulbasaur','Pokémon','1','Common','MPC Film','A strange seed was planted on its back at birth. The plant sprouts and grows with this Pokémon.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/1.png","large":"https://images.pokemontcg.io/det1/1_hires.png"}',NULL,'60',NULL,'["Basic"]','["Grass"]',NULL,'["Ivysaur"]',NULL,'[{"name":"Find a Friend","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Grass Pokémon, reveal it, and put it into your hand. Then, shuffle your deck."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[1]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-2','Ludicolo','Pokémon','2','Rare','Framestore','If it hears festive music, all its muscles fill with energy. It can''t help breaking out into a dance.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/2.png","large":"https://images.pokemontcg.io/det1/2_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Grass"]','Lombre',NULL,'[{"name":"Table Service","text":"Once during your turn (before your attack), you may heal 30 damage from 1 of your Pokémon.","type":"Ability"}]','[{"name":"Punch and Run","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Switch this Pokémon with 1 of your Benched Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[272]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-3','Morelull','Pokémon','3','Common','MPC Film','It scatters its shining spores around itself. Even though they''re dangerous, nighttime tours of forests where Morelull live are popular.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/3.png","large":"https://images.pokemontcg.io/det1/3_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Shiinotic"]',NULL,'[{"name":"Sleep Spore","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Your opponent''s Active Pokémon is now Asleep."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[755]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-4','Charmander','Pokémon','4','Common','MPC Film','The flame on its tail indicates Charmander''s life force. If it is healthy, the flame burns brightly.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/4.png","large":"https://images.pokemontcg.io/det1/4_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Charmeleon"]',NULL,'[{"name":"Reckless Charge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[4]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-5','Charizard','Pokémon','5','Rare Ultra','Framestore','When expelling a blast of superhot fire, the red flame at the tip of its tail burns more intensely.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/5.png","large":"https://images.pokemontcg.io/det1/5_hires.png"}',NULL,'180',NULL,'["Stage 2"]','["Fire"]','Charmeleon',NULL,NULL,'[{"name":"Slash","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""},{"name":"Wild Tackle","cost":["Fire","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"180","text":"This Pokémon does 50 damage to itself."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[6]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-6','Arcanine','Pokémon','6','Rare','MPC Film','Legends tell of its fighting alongside a general and conquering a whole country.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/6.png","large":"https://images.pokemontcg.io/det1/6_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Fire"]','Growlithe',NULL,'[{"name":"Security Guard","text":"As long as this Pokémon is your Active Pokémon, all of your Pokémon take 30 less damage from your opponent''s attacks (after applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Sharp Fang","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[59]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-7','Psyduck','Pokémon','7','Common','Framestore','Using psychokinesis gives it a headache, so it normally passes the time spacing out and doing as little as possible.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/7.png","large":"https://images.pokemontcg.io/det1/7_hires.png"}',NULL,'80',NULL,'["Basic"]','["Water"]',NULL,'["Golduck"]',NULL,'[{"name":"Panic","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"This Pokémon is now Confused."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[54]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-8','Magikarp','Pokémon','8','Common','Framestore','In the distant past, they were fairly strong, but they have become gradually weaker over time.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/8.png","large":"https://images.pokemontcg.io/det1/8_hires.png"}',NULL,'30',NULL,'["Basic"]','["Water"]',NULL,'["Gyarados"]',NULL,'[{"name":"Hold Still","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Heal 10 damage from this Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[129]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-9','Greninja','Pokémon','9','Rare Ultra','MPC Film','It creates throwing stars out of compressed water. When it spins them and throws them at high speed, these stars can split metal in two.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/9.png","large":"https://images.pokemontcg.io/det1/9_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Water"]','Frogadier',NULL,'[{"name":"Evasion Jutsu","text":"If any damage is done to this Pokémon by attacks, flip a coin. If heads, prevent that damage.","type":"Ability"}]','[{"name":"Furious Shurikens","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"","text":"This attack does 50 damage to 2 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[658]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-10','Detective Pikachu','Pokémon','10','Rare','MPC Film','He loves to show off his vast knowledge. This expressive Pikachu is like a middle-aged man.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/10.png","large":"https://images.pokemontcg.io/det1/10_hires.png"}',NULL,'90',NULL,'["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Scout","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Your opponent reveals their hand."},{"name":"Surprise Attack","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[25]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-11','Mr. Mime','Pokémon','11','Rare','MPC Film','Its pantomime skills are wonderful. You may become enraptured while watching it, but next thing you know, Mr. Mime has made a real wall.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/11.png","large":"https://images.pokemontcg.io/det1/11_hires.png"}',NULL,'80',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Pantomime","text":"When you play this Pokémon from your hand onto your Bench during your turn, you may switch 1 of your face-down Prize cards with the top card of your deck.","type":"Ability"}]','[{"name":"Juggling","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 4 coins. This attack does 20 damage for each heads."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[122]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-12','Mewtwo','Pokémon','12','Rare Ultra','MPC Film','This Pokémon was created by years of horrific gene splicing and DNA engineering experiments.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/12.png","large":"https://images.pokemontcg.io/det1/12_hires.png"}',NULL,'130',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Psyjack","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Choose 1 of your opponent''s Active Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."},{"name":"Break Burn","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"130","text":"Discard 2 Psychic Energy from this Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-13','Machamp','Pokémon','13','Rare','MPC Film','It grasps its opponents with its four arms and twists them up in an intricate hold. People call it "the Machamp special."','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/13.png","large":"https://images.pokemontcg.io/det1/13_hires.png"}',NULL,'160',NULL,'["Stage 2"]','["Fighting"]','Machoke',NULL,NULL,'[{"name":"Directing Traffic","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 5 cards of your deck and put them back in any order."},{"name":"Cross Chop","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"80+","text":"Flip a coin. If heads, this attack does 60 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[68]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-14','Jigglypuff','Pokémon','14','Common','Framestore','Recordings of Jigglypuff''s strange lullabies can be purchased from department stores. These CDs can be found near the bedding area.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/14.png","large":"https://images.pokemontcg.io/det1/14_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fairy"]',NULL,'["Wigglytuff"]',NULL,'[{"name":"Healing Melody","cost":["Fairy"],"convertedEnergyCost":1,"damage":"","text":"Heal 10 damage from each of your Pokémon."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[39]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-15','Snubbull','Pokémon','15','Common','Framestore','It grows close to others easily and is also easily spoiled. The disparity between its face and its actions makes many young people wild about it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/15.png","large":"https://images.pokemontcg.io/det1/15_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fairy"]',NULL,'["Granbull"]',NULL,'[{"name":"Play Rough","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 30 more damage."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless","Colorless"]',2,'[209]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-16','Lickitung','Pokémon','16','Common','MPC Film','It checks out whatever''s around it by licking everything. If you don''t clean off a spot where it''s licked you, you''ll break out in a rash!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/16.png","large":"https://images.pokemontcg.io/det1/16_hires.png"}',NULL,'100',NULL,'["Basic"]','["Colorless"]',NULL,'["Lickilicky"]',NULL,'[{"name":"Continuous Lick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip a coin until you get tails. This attack does 20 damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[108]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-17','Ditto','Pokémon','17','Rare Ultra','MPC Film','While it can transform into anything, each Ditto apparently has its own strengths and weaknesses when it comes to transformations.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/17.png","large":"https://images.pokemontcg.io/det1/17_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Copy Anything","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon''s attacks and use it as this attack. If this Pokémon doesn''t have the necessary Energy to use that attack, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[132]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('det1-18','Slaking','Pokémon','18','Rare','Framestore','The world''s laziest Pokémon. It moves to another spot when there''s no food left within its reach.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/det1/18.png","large":"https://images.pokemontcg.io/det1/18_hires.png"}',NULL,'180',NULL,'["Stage 2"]','["Colorless"]','Vigoroth',NULL,NULL,'[{"name":"Pitch","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"150","text":"Your opponent switches their Active Pokémon with 1 of their Benched Pokémon."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[289]',NULL,NULL,'det1');
INSERT INTO "Card" VALUES('dp1-1','Dialga','Pokémon','1','Rare Holo','Nakaoka','It has the power to control time. It appears in Sinnoh-region myths as an ancient deity.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/1.png","large":"https://images.pokemontcg.io/dp1/1_hires.png"}',NULL,'90','68','["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Time Bellow","cost":["Metal"],"convertedEnergyCost":1,"damage":"10","text":"Draw a card."},{"name":"Flash Cannon","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"You may return all Energy cards attached to Dialga to your hand. If you do, remove the highest Stage Evolution card from the Defending Pokémon and shuffle that card into your opponent''s deck."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[483]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-2','Dusknoir','Pokémon','2','Rare Holo','Takabon','The antenna on its head captures radio waves from the world of spirits that command it to take people there.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/2.png","large":"https://images.pokemontcg.io/dp1/2_hires.png"}',NULL,'120','42','["Stage 2"]','["Psychic"]','Dusclops',NULL,'[{"name":"Dark Palm","text":"Once during your turn (before your attack), if your opponent has 4 or more Benched Pokémon, you may choose 1 of them and shuffle that Pokémon and all cards attached to it into his or her deck. This power can''t be used if Dusknoir if affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Hard Feelings","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Put 5 damage counters on the Defending Pokémon. Then, count the number of Prize cards your opponent has taken and put that many damage counters on the Defending Pokémon."}]','[{"type":"Darkness","value":"+30"}]','[{"type":"Colorless","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[477]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-3','Electivire','Pokémon','3','Rare Holo','Nakaoka','It pushes the tips of its two tails against the foe, then lets loose with over 20,000 volts of power.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/3.png","large":"https://images.pokemontcg.io/dp1/3_hires.png"}',NULL,'100','46','["Stage 1"]','["Lightning"]','Electabuzz',NULL,'[{"name":"Intense Voltage","text":"As often as you like during your turn (before your attack), if Elekid is anywhere under Electivire, you may move a Lightning Energy attached to your Pokémon to Electivire. This power can''t be used if Electivire is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Giga Impact","cost":["Lightning","Lightning","Lightning","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"You may discard all Lightning Energy attached to Electivire. If you do, this attack''s base damage is 120 instead of 60."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[466]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-4','Empoleon','Pokémon','4','Rare Holo','Nakaoka','The three horns that extend from its beak attest to its power. The leader has the biggest horns.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/4.png","large":"https://images.pokemontcg.io/dp1/4_hires.png"}',NULL,'130','42','["Stage 2"]','["Water"]','Prinplup',NULL,NULL,'[{"name":"Ice Blade","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 40 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Aqua Jet","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Flip a coin. If heads, this attack does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"+30"}]',NULL,'["Colorless","Colorless"]',2,'[395]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-5','Infernape','Pokémon','5','Rare Holo','Nakaoka','It uses a special kind of martial arts involving all its limbs. Its fire never goes out.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/5.png","large":"https://images.pokemontcg.io/dp1/5_hires.png"}',NULL,'100','40','["Stage 2"]','["Fire"]','Monferno',NULL,NULL,'[{"name":"Meteor Punch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30×","text":"Flip a coin until you get tails. This attack does 30 damage times the number of heads."},{"name":"Flare Blitz","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"90","text":"Discard all Fire Energy attached to Infernape."}]','[{"type":"Water","value":"+30"}]',NULL,NULL,NULL,'[392]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-6','Lucario','Pokémon','6','Rare Holo','Ken Sugimori','It has the ability to sense the auras of all things. It understands human speech.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/6.png","large":"https://images.pokemontcg.io/dp1/6_hires.png"}',NULL,'90','30','["Stage 1"]','["Fighting"]','Riolu',NULL,NULL,'[{"name":"Feint","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"This attack''s damage isn''t affected by Resistance."},{"name":"Aura Sphere","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"40","text":"Does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless"]',1,'[448]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-7','Luxray','Pokémon','7','Rare Holo','Mikiko Takeda','It has eyes that can see through anything. It spots and captures prey hiding behind objects.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/7.png","large":"https://images.pokemontcg.io/dp1/7_hires.png"}',NULL,'120','48','["Stage 2"]','["Lightning"]','Luxio',NULL,'[{"name":"Gleam Eyes","text":"Once during your turn, when you play Luxray from your hand to evolve 1 of your Pokémon, you may look at your opponent''s hand. If your opponent''s Bench isn''t full, choose 1 Basic Pokémon from your opponent''s hand, and put it onto his or her Bench. Then, switch it with the Defending Pokémon.","type":"Poké-Power"}]','[{"name":"Lightning Star","cost":["Lightning","Lightning","Lightning","Lightning"],"convertedEnergyCost":4,"damage":"80","text":"Move all Lightning Energy attached to Luxray to 1 of your Benched Pokémon. (Ignore this effect if you don''t have any Benched Pokémon.)"}]','[{"type":"Fighting","value":"+30"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[405]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-8','Magnezone','Pokémon','8','Rare Holo','Nakaoka','It evolved from exposure to a special magnetic field. Three units generate magnetism.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/8.png","large":"https://images.pokemontcg.io/dp1/8_hires.png"}',NULL,'120','48','["Stage 2"]','["Metal"]','Magneton',NULL,'[{"name":"Magnetize","text":"If you have any Metal Energy attached to your Active Pokémon, the Retreat Cost for that Pokémon is 0.","type":"Poké-Body"}]','[{"name":"Metal Blast","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"Does 50 damage plus 10 more damage for each Metal Energy attached to Magnezone."}]','[{"type":"Fire","value":"+30"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[462]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-9','Manaphy','Pokémon','9','Rare Holo','Nakaoka','Born on a cold seafloor, it will swim great distances to return to its birthplace.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/9.png","large":"https://images.pokemontcg.io/dp1/9_hires.png"}',NULL,'70','20','["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward."},{"name":"Aqua Ring","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"30","text":"Switch Manaphy with 1 of your Benched Pokémon."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[490]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-10','Mismagius','Pokémon','10','Rare Holo','Mikiko Takeda','Its cries sound like incantations. Those hearing it are tormented by headaches and hallucinations.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/10.png","large":"https://images.pokemontcg.io/dp1/10_hires.png"}',NULL,'90','37','["Stage 1"]','["Psychic"]','Misdreavus',NULL,NULL,'[{"name":"Avenge","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Count the number of your Pokémon that have any damage counters on them. Put that many damage counters on the Defending Pokémon."},{"name":"Psywave","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"Does 30 damage plus 20 more damage for each Energy attached to the Defending Pokémon."}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[429]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-11','Palkia','Pokémon','11','Rare Holo','Nakaoka','It has the ability to distort space. It is described as a deity in Sinnoh-region mythology.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/11.png","large":"https://images.pokemontcg.io/dp1/11_hires.png"}',NULL,'90','67','["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Spacial Rend","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Search your deck for a Stadium card, show it to your opponent, and put it into your hand. Shuffle your deck afterward. If there is any Stadium card in play, discard it."},{"name":"Transback","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"You may flip a coin. If heads, discard all Energy attached to Palkia and put the Defending Pokémon and all cards attached to it on top of your opponent''s deck. Your opponent shuffles his or her deck afterward."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[484]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-12','Rhyperior','Pokémon','12','Rare Holo','Nakaoka','It puts rocks in holes in its palms and uses its muscles to shoot them. Geodude are shot at rare times.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/12.png","large":"https://images.pokemontcg.io/dp1/12_hires.png"}',NULL,'140','61','["Stage 2"]','["Fighting"]','Rhydon',NULL,'[{"name":"Earth Fissure","text":"Once during your turn, when you play Rhyperior from your hand to evolve 1 of your Pokémon, you may discard the top 3 cards from your opponent''s deck.","type":"Poké-Power"}]','[{"name":"Rock Wrecker","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"This attack''s damage isn''t affected by Weakness or Resistance. Rhyperior can''t attack during your next turn."}]','[{"type":"Water","value":"+30"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[464]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-13','Roserade','Pokémon','13','Rare Holo','Nakaoka','It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/13.png","large":"https://images.pokemontcg.io/dp1/13_hires.png"}',NULL,'90','33','["Stage 1"]','["Grass"]','Roselia',NULL,NULL,'[{"name":"Poison Sting","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"30","text":"The Defending Pokémon is now Poisoned."},{"name":"Spike Whip","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"If Budew is anywhere under Roserade, choose 1 of your opponent''s Benched Pokémon. This attack does 30 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless"]',1,'[407]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-14','Shiftry','Pokémon','14','Rare Holo','Masakazu Fukuda','By flapping its leafy fan, it can whip up gusts of 100 ft/second that can level houses.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/14.png","large":"https://images.pokemontcg.io/dp1/14_hires.png"}',NULL,'120','48','["Stage 2"]','["Darkness"]','Nuzleaf',NULL,'[{"name":"Darkness Fan","text":"Once during your turn (before your attack), if Shiftry is your Active Pokémon, you may flip a coin. If heads, choose 1 Evolved Pokémon on your opponent''s Bench, remove the highest Stage Evolution card from that Pokémon, and put it back into his or her hand. This power can''t be used if Shiftry is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Spirit Dance","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"Flip 2 coins. This attack does 50 damage plus 20 more damage for each heads."}]','[{"type":"Fighting","value":"+30"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[275]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-15','Skuntank','Pokémon','15','Rare Holo','Hiroaki Ito','It sprays a vile-smelling fluid from the tip of its tail to attack. Its range is over 160 feet.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/15.png","large":"https://images.pokemontcg.io/dp1/15_hires.png"}',NULL,'90','36','["Stage 1"]','["Darkness"]','Stunky',NULL,NULL,'[{"name":"Frustration","cost":["Darkness","Darkness"],"convertedEnergyCost":2,"damage":"","text":"Choose 1 of your opponent''s Pokémon that doesn''t have any damage counters on it. This attack does 30 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Toxic Cloud","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned. Put 2 damage counters instead of 1 on the Defending Pokémon between turns."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[435]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-16','Staraptor','Pokémon','16','Rare Holo','Masahiko Ishii','It has a savage nature. It will courageously challenge foes that are much larger.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/16.png","large":"https://images.pokemontcg.io/dp1/16_hires.png"}',NULL,'100','54','["Stage 2"]','["Colorless"]','Staravia',NULL,NULL,'[{"name":"Accelerative Dive","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"Flip a coin. If tails, this attack does nothing. If heads, prevent all damage done to Staraptor by attacks (both yours and your opponent''s) until the end of your next turn."},{"name":"Brave Heart","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Flip a coin. If tails, Staraptor does 100 damage to itself."}]','[{"type":"Lightning","value":"+30"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[398]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-17','Torterra','Pokémon','17','Rare Holo','Masahiko Ishii','Small Pokémon occasionally gather on its unmoving back to begin building their nests.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/17.png","large":"https://images.pokemontcg.io/dp1/17_hires.png"}',NULL,'140','45','["Stage 2"]','["Grass"]','Grotle',NULL,NULL,'[{"name":"Body Slam","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Leaf Storm","cost":["Grass","Grass","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"Remove 2 damage counters from each of your Grass Pokémon."}]','[{"type":"Fire","value":"+30"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[389]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-18','Azumarill','Pokémon','18','Rare','Naoyo Kimura','It lives in rivers and lakes. In water, its coloring and patterns trick the vision of foes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/18.png","large":"https://images.pokemontcg.io/dp1/18_hires.png"}',NULL,'80','35','["Stage 1"]','["Water"]','Marill',NULL,NULL,'[{"name":"Defense Curl","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, prevent all damage done to Azumarill during your opponent''s next turn."},{"name":"Bubble Pump","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"40+","text":"If Azumarill has 3 or more Energy attached to it, this attack does 40 damage plus 20 more damage. If Azurill is anywhere under Azumarill, flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[184]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-19','Beautifly','Pokémon','19','Rare','Atsuko Nishida','It has an aggressive nature. It stabs prey with its long, narrow mouth to drain the prey''s fluids.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/19.png","large":"https://images.pokemontcg.io/dp1/19_hires.png"}',NULL,'100','29','["Stage 2"]','["Grass"]','Silcoon',NULL,NULL,'[{"name":"Whirlwind","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Giga Drain","cost":["Grass","Grass","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"50","text":"After your attack, remove from Beautifly the number of damage counters equal to the damage you did to the Defending Pokémon."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[267]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-20','Bibarel','Pokémon','20','Rare','Ken Sugimori','It makes its nest by damming streams with bark and mud. It is known as an industrious worker.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/20.png","large":"https://images.pokemontcg.io/dp1/20_hires.png"}',NULL,'100','26','["Stage 1"]','["Colorless"]','Bidoof',NULL,NULL,'[{"name":"Rest","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Remove all Special Conditions and 4 damage counters from Bibarel. Bibarel is now Asleep."},{"name":"Take Down","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Bibarel does 10 damage to itself."}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[400]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-21','Carnivine','Pokémon','21','Rare','Kouki Saitou','It attracts prey with its sweet-smelling saliva, then chomps down. It takes a whole day to eat prey.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/21.png","large":"https://images.pokemontcg.io/dp1/21_hires.png"}',NULL,'70','32','["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Swallow Up","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Before doing damage, count the remaining HP of the Defending Pokémon and Carnivine. If the Defending Pokémon has fewer remaining HP than Carnivine''s, this attack does 60 damage instead."},{"name":"Wring Out","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed and discard an Energy card attached to the Defending Pokémon."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[455]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-22','Clefable','Pokémon','22','Rare','Ken Sugimori','Rarely seen by people, it is said to be drawn by the full moon to play at deserted lakes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/22.png","large":"https://images.pokemontcg.io/dp1/22_hires.png"}',NULL,'90','37','["Stage 1"]','["Colorless"]','Clefairy',NULL,NULL,'[{"name":"Double Slap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30×","text":"Flip 2 coins. This attack does 30 damage times the number of heads."},{"name":"Metronome","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of the Defending Pokémon''s attacks. Metronome copies that attack except for its Energy cost. (You must still do anything else in order to use that attack.) Clefable performs that attack."}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[36]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-23','Drapion','Pokémon','23','Rare','Kouki Saitou','It has the power in its clawed arms to make scrap of a car. The tips of its claws release poison.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/23.png","large":"https://images.pokemontcg.io/dp1/23_hires.png"}',NULL,'100','41','["Stage 1"]','["Psychic"]','Skorupi',NULL,NULL,'[{"name":"Stomp","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 20 more damage."},{"name":"Poison Claws","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[452]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-24','Drifblim','Pokémon','24','Rare','Mitsuhiro Arita','It''s drowzy in daytime, but flies off in the evening in big groups. No one knows where they go.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/24.png","large":"https://images.pokemontcg.io/dp1/24_hires.png"}',NULL,'80','40','["Stage 1"]','["Psychic"]','Drifloon',NULL,NULL,'[{"name":"Wind Wave","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your discard pile for up to 5 in any combination of Pokémon and Supporter cards. Show them to your opponent and shuffle them into your deck."},{"name":"Explosive Smoke","cost":["Psychic","Psychic","Psychic"],"convertedEnergyCost":3,"damage":"60","text":"Does 10 damage to each Benched Pokémon (both yours and your opponent''s). (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]',NULL,NULL,'[426]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-25','Dustox','Pokémon','25','Rare','Kouki Saitou','A nocturnal Pokémon. Drawn by streetlights, they messily eat the leaves of trees lining boulevards.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/25.png","large":"https://images.pokemontcg.io/dp1/25_hires.png"}',NULL,'120','34','["Stage 2"]','["Grass"]','Cascoon',NULL,NULL,'[{"name":"Stun Spore","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Toxic Dust","cost":["Grass","Grass","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"50","text":"The Defending Pokémon is now Poisoned. Put 2 damage counters instead of 1 on the Defending Pokémon between turns."}]','[{"type":"Fire","value":"+30"}]',NULL,'["Colorless","Colorless"]',2,'[269]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-26','Floatzel','Pokémon','26','Rare','Masahiko Ishii','It floats using its well-developed floatation sac. It assists in the rescues of drowning people.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/26.png","large":"https://images.pokemontcg.io/dp1/26_hires.png"}',NULL,'90','29','["Stage 1"]','["Water"]','Buizel',NULL,NULL,'[{"name":"Screw Tail","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If heads, discard an Energy attached to the Defending Pokémon."},{"name":"Water Gun","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"40+","text":"Does 40 damage plus 20 more damage for each Water Energy attached to Floatzel but not used to pay for this attack''s Energy cost. You can''t add more than 40 damage in this way."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[419]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-27','Gengar','Pokémon','27','Rare','Kagemaru Himeno','It hides in shadows. It is said that if Gengar is hiding, it cools that area by nearly 10 degrees F.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/27.png","large":"https://images.pokemontcg.io/dp1/27_hires.png"}',NULL,'110','39','["Stage 2"]','["Psychic"]','Haunter',NULL,NULL,'[{"name":"Life Drain","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, put damage counters on the Defending Pokémon until it is 10 HP away from being Knocked Out."},{"name":"Shadow Dance","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Put 4 damage counters on your opponent''s Pokémon in any way you like. Then, switch Gengar with 1 of your Benched Pokémon."}]','[{"type":"Darkness","value":"+30"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[94]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-28','Heracross','Pokémon','28','Rare','Ken Sugimori','It gathers in forests to search for tree sap, its favorite food. It''s strong enough to hurl foes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/28.png","large":"https://images.pokemontcg.io/dp1/28_hires.png"}',NULL,'80','29','["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Pitch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Horn Slash","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 30 more damage."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[214]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-29','Hippowdon','Pokémon','29','Rare','Kouki Saitou','It blasts internally stored sand from ports on its body to create a towering twister for attack.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/29.png","large":"https://images.pokemontcg.io/dp1/29_hires.png"}',NULL,'110','45','["Stage 1"]','["Fighting"]','Hippopotas',NULL,NULL,'[{"name":"Vacuum Up","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."},{"name":"Sand Eject","cost":["Fighting","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"During your next turn, if an attack does damage to the Defending Pokémon (after applying Weakness and Resistance), that attack does 40 more damage."}]','[{"type":"Water","value":"+20"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[450]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-30','Lopunny','Pokémon','30','Rare','Kagemaru Himeno','An extremely cautious Pokémon. It cloaks its body with its fluffy ear fur when it senses danger.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/30.png","large":"https://images.pokemontcg.io/dp1/30_hires.png"}',NULL,'80','33','["Stage 1"]','["Colorless"]','Buneary',NULL,NULL,'[{"name":"Healing Wish","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin until you get tails. Remove a number of damage counters equal to the number of heads from 1 of your Pokémon."},{"name":"Flop","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) You may switch Lopunny with 1 of your Benched Pokémon."}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless"]',1,'[428]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-31','Machamp','Pokémon','31','Rare','Kagemaru Himeno','It punches with its four arms at blinding speed. It can launch 1,000 punches in two seconds.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/31.png","large":"https://images.pokemontcg.io/dp1/31_hires.png"}',NULL,'130','59','["Stage 2"]','["Fighting"]','Machoke',NULL,NULL,'[{"name":"Revenge","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20+","text":"If any of your Pokémon were Knocked Out by damage from an opponent''s attack during his or her last turn, this attack does 20 damage plus 50 more damage."},{"name":"Dynamic Punch","cost":["Fighting","Fighting","Fighting"],"convertedEnergyCost":3,"damage":"60+","text":"Flip a coin. If heads, this attack does 60 damage plus 30 more damage and the Defending Pokémon is now Confused."}]','[{"type":"Psychic","value":"+30"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[68]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-32','Medicham','Pokémon','32','Rare','Kouki Saitou','Through yoga training, it has honed its sixth sense. Its movements are elegant.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/32.png","large":"https://images.pokemontcg.io/dp1/32_hires.png"}',NULL,'90','42','["Stage 1"]','["Fighting"]','Meditite',NULL,NULL,'[{"name":"Force Palm","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Count the number of damage counters on Medicham. Put that many damage counters on 1 of your opponent''s Pokémon."},{"name":"Spinning Kick","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Medicham does 20 damage to itself."}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[308]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-33','Munchlax','Pokémon','33','Rare','Ken Sugimori','It wolfs down its weight in food once a day, swallowing food whole with almost no chewing.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/33.png","large":"https://images.pokemontcg.io/dp1/33_hires.png"}',NULL,'60','8','["Basic"]','["Colorless"]',NULL,'["Snorlax"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Snorlax from your hand onto Munchlax (this counts as evolving Munchlax) and remove all damage counters from Munchlax.","type":"Poké-Power"}]','[{"name":"Heave","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30×","text":"Discard 2 cards from your hand. (If you can''t discard 2 cards, this attack does nothing.) Flip 2 coins. This attack does 30 damage times the number of heads."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless","Colorless"]',2,'[446]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-34','Noctowl','Pokémon','34','Rare','Atsuko Nishida','Its eyes are special. They can pick out objects as long as there is the tiniest amount of light.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/34.png","large":"https://images.pokemontcg.io/dp1/34_hires.png"}',NULL,'90','40','["Stage 1"]','["Colorless"]','Hoothoot',NULL,NULL,'[{"name":"See Beyond","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose a card from your hand and put it as a Prize card face up. Then, choose 1 of your face-down Prize cards without looking and put it into your hand. This attack does nothing if all of your Prize cards are face up."},{"name":"Extrasensory","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"If you have the same number of cards in your hand as your opponent, this attack does 30 damage plus 50 more damage."}]','[{"type":"Lightning","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[164]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-35','Pachirisu','Pokémon','35','Rare','Ken Sugimori','It makes fur balls that crackle with static electricity. It stores them with berries in tree holes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/35.png","large":"https://images.pokemontcg.io/dp1/35_hires.png"}',NULL,'70','23','["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Minor Errand-Running","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."},{"name":"Thunder Jolt","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, Pachirisu does 10 damage to itself."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[417]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-36','Purugly','Pokémon','36','Rare','Masakazu Fukuda','It is a brazen brute that barges its way into another Pokémon''s nest and claims it as its own.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/36.png","large":"https://images.pokemontcg.io/dp1/36_hires.png"}',NULL,'90','44','["Stage 1"]','["Colorless"]','Glameow',NULL,NULL,'[{"name":"High Hat","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 card from your opponent''s hand without looking and discard it."},{"name":"Body Slam","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"50","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless"]',1,'[432]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-37','Snorlax','Pokémon','37','Rare','Ken Sugimori','Its stomach can digest any kind of food, even if it happens to be moldy or rotten.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/37.png","large":"https://images.pokemontcg.io/dp1/37_hires.png"}',NULL,'100','35','["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Block","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."},{"name":"Ease Up","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"40+","text":"Snorlax is now Asleep. If Snorlax is evolved from Munchlax, this attack does 40 damage plus 30 more damage."}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[143]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-38','Steelix','Pokémon','38','Rare','Kouki Saitou','Tempered underground under high pressure and heat, its body is harder than any metal.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/38.png","large":"https://images.pokemontcg.io/dp1/38_hires.png"}',NULL,'110','50','["Stage 1"]','["Metal"]','Onix',NULL,NULL,'[{"name":"Slam","cost":["Metal"],"convertedEnergyCost":1,"damage":"30×","text":"Flip 2 coins. This attack does 30 damage times the number of heads."},{"name":"Metal Slash","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Steelix can''t attack during your next turn."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-39','Vespiquen','Pokémon','39','Rare','Mitsuhiro Arita','Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by COMBEE.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/39.png","large":"https://images.pokemontcg.io/dp1/39_hires.png"}',NULL,'100','40','["Stage 1"]','["Grass"]','Combee',NULL,NULL,'[{"name":"Leaf Honey","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Discard a Grass Energy attached to Vespiquen and remove all damage counters from 1 of your Benched Grass Pokémon."},{"name":"Attack Order","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"10×","text":"Does 10 damage times the number of Grass Pokémon in play (both yours and your opponent''s)."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[416]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-40','Weavile','Pokémon','40','Rare','Naoyo Kimura','They live in cold regions, forming groups of four or five that hunt prey with impressive coordination.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/40.png","large":"https://images.pokemontcg.io/dp1/40_hires.png"}',NULL,'80','37','["Stage 1"]','["Darkness"]','Sneasel',NULL,NULL,'[{"name":"Nasty Plot","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for any 1 card and put it into your hand. Shuffle your deck afterward."},{"name":"Dark Pulse","cost":["Darkness","Darkness","Darkness"],"convertedEnergyCost":3,"damage":"10×","text":"Does 10 damage times the total amount of Darkness Energy attached to all of your Pokémon."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[461]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-41','Wobbuffet','Pokémon','41','Rare','Kouki Saitou','It desperately tries to keep its black tail hidden. It is said to be proof the tail hides a secret.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/41.png","large":"https://images.pokemontcg.io/dp1/41_hires.png"}',NULL,'80','25','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Countercharge","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, move all damage counters from Wobbuffet to the Defending Pokémon."}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[202]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-42','Wynaut','Pokémon','42','Rare','Masakazu Fukuda','It grows strong by pushing up against others en masse. It loves eating sweet fruit.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/42.png","large":"https://images.pokemontcg.io/dp1/42_hires.png"}',NULL,'40','6','["Basic"]','["Psychic"]',NULL,'["Wobbuffet"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Wobbuffet from your hand onto Wynaut (this counts as evolving Wynaut) and remove all damage counters from Wynaut.","type":"Poké-Power"}]','[{"name":"Astonish","cost":[],"convertedEnergyCost":0,"damage":"","text":"Choose 1 card from your opponent''s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[360]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-43','Budew','Pokémon','43','Uncommon','Ken Sugimori','Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/43.png","large":"https://images.pokemontcg.io/dp1/43_hires.png"}',NULL,'40','6','["Basic"]','["Grass"]',NULL,'["Roselia"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Roselia from your hand onto Budew (this counts as evolving Budew) and remove all damage counters from Budew.","type":"Poké-Power"}]','[{"name":"Errand-Running","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for a Trainer card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."}]','[{"type":"Fire","value":"+10"}]',NULL,'["Colorless"]',1,'[406]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-44','Cascoon','Pokémon','44','Uncommon','Ken Sugimori','It is hot inside its cocoon. All the cells in its body create the energy for it to evolve.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/44.png","large":"https://images.pokemontcg.io/dp1/44_hires.png"}',NULL,'80','8','["Stage 1"]','["Grass"]','Wurmple','["Dustox"]',NULL,'[{"name":"Harden","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, if Cascoon would be damaged by an attack, prevent that attack''s damage done to Cascoon if that damage is 30 or less."},{"name":"Gooey Thread","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[268]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-45','Cherrim','Pokémon','45','Uncommon','Atsuko Nishida','It blooms during times of strong sunlight. It tries to make up for everything it endured as a bud.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/45.png","large":"https://images.pokemontcg.io/dp1/45_hires.png"}',NULL,'80','26','["Stage 1"]','["Grass"]','Cherubi',NULL,NULL,'[{"name":"Worry Seed","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."},{"name":"Magical Leaf","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 20 more damage and remove 3 damage counters from Cherrim."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[421]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-46','Drifloon','Pokémon','46','Uncommon','Ken Sugimori','A Pokémon formed by the spirits of people and Pokémon. It loves damp, humid seasons.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/46.png","large":"https://images.pokemontcg.io/dp1/46_hires.png"}',NULL,'60','17','["Basic"]','["Psychic"]',NULL,'["Drifblim"]',NULL,'[{"name":"Blowing Wind","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, put 1 of your Benched Pokémon and all cards attached to on top of your deck. Shuffle your deck afterward."},{"name":"Ominous Wind","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused and can''t retreat during your opponent''s next turn."}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[425]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-47','Dusclops','Pokémon','47','Uncommon','Kouki Saitou','Its body is hollow. It is said that those who look into its body are sucked into the void.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/47.png","large":"https://images.pokemontcg.io/dp1/47_hires.png"}',NULL,'80','38','["Stage 1"]','["Psychic"]','Duskull','["Dusknoir"]',NULL,'[{"name":"Roam","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, put 2 damage counters on each of your opponent''s Pokémon. If tails, put 2 damage counters on 1 of your Pokémon."},{"name":"Gravity Wave","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"30","text":"Does 10 damage to each of your opponent''s Benched Pokémon that doesn''t have a Retreat Cost. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]','["Colorless","Colorless"]',2,'[356]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-48','Elekid','Pokémon','48','Uncommon','Kagemaru Himeno','It generates electricity by whirling its arms. However, it can''t store the energy it makes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/48.png","large":"https://images.pokemontcg.io/dp1/48_hires.png"}',NULL,'40','6','["Basic"]','["Lightning"]',NULL,'["Electabuzz"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Electabuzz from your hand onto Elekid (this counts as evolving Elekid) and remove all damage counters from Elekid.","type":"Poké-Power"}]','[{"name":"Outlet","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for a Lightning Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[239]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-49','Grotle','Pokémon','49','Uncommon','Ken Sugimori','It lives along water in forests. In the daytime, it leaves the forest to sunbathe its treed shell.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/49.png","large":"https://images.pokemontcg.io/dp1/49_hires.png"}',NULL,'90','21','["Stage 1"]','["Grass"]','Turtwig','["Torterra"]',NULL,'[{"name":"Synthesis","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Grass Energy card and attach it to 1 of your Pokémon. Shuffle your deck afterward."},{"name":"Cut","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]','[{"type":"Fire","value":"+20"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[388]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-50','Haunter','Pokémon','50','Uncommon','Naoyo Kimura','It can slip through any obstacle. It lurks inside walls to keep an eye on its foes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/50.png","large":"https://images.pokemontcg.io/dp1/50_hires.png"}',NULL,'70','32','["Stage 1"]','["Psychic"]','Gastly','["Gengar"]',NULL,'[{"name":"Hypnosis","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."},{"name":"Dream Eater","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"60","text":"If the Defending Pokémon is not Asleep, this attack does nothing."}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]',NULL,NULL,'[93]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-51','Hippopotas','Pokémon','51','Uncommon','Mitsuhiro Arita','It lives in arid places. Instead of perspiration, it expels grainy sand from its body.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/51.png","large":"https://images.pokemontcg.io/dp1/51_hires.png"}',NULL,'60','23','["Basic"]','["Fighting"]',NULL,'["Hippowdon"]',NULL,'[{"name":"Yawn","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."},{"name":"Sand Attack","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":"If the Defending Pokémon tries to attack during your opponent''s next turn, your opponent flips a coin. If tails, that attack does nothing."}]','[{"type":"Water","value":"+10"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless"]',2,'[449]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-52','Luxio','Pokémon','52','Uncommon','Ken Sugimori','Its claws loose electricity with enough amperage to cause fainting. They live in small groups.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/52.png","large":"https://images.pokemontcg.io/dp1/52_hires.png"}',NULL,'80','19','["Stage 1"]','["Lightning"]','Shinx','["Luxray"]',NULL,'[{"name":"Fasten Claws","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 30 more damage."},{"name":"Thunder Fang","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Metal","value":"-20"}]',NULL,NULL,'[404]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-53','Machoke','Pokémon','53','Uncommon','Kouki Saitou','MACHOKE''s boundless power is very dangerous, so it wears a belt that suppresses its energy.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/53.png","large":"https://images.pokemontcg.io/dp1/53_hires.png"}',NULL,'80','39','["Stage 1"]','["Fighting"]','Machop','["Machamp"]',NULL,'[{"name":"Karate Chop","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40-","text":"Does 40 damage minus 10 damage for each damage counter on Machoke."},{"name":"Seismic Toss","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[67]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-54','Magneton','Pokémon','54','Uncommon','Kouki Saitou','It is actually three MAGNEMITE linked by magnetism. A group can set off a magnetic storm.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/54.png","large":"https://images.pokemontcg.io/dp1/54_hires.png"}',NULL,'70','35','["Stage 1"]','["Metal"]','Magnemite','["Magnezone"]',NULL,'[{"name":"Tri Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 3 coins. This attack does 20 damage times the number of heads."},{"name":"Magnetic Ray","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Before doing damage, you may choose 1 of your opponent''s Benched Pokémon that has any Energy attached to it and switch that Pokémon with 1 of the Defending Pokémon."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[82]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-55','Mantyke','Pokémon','55','Uncommon','Midori Harada','A friendly Pokémon that captures the subtle flows of seawater using its two antennae.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/55.png","large":"https://images.pokemontcg.io/dp1/55_hires.png"}',NULL,'40','6','["Basic"]','["Water"]',NULL,'["Mantine"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Mantine from your hand onto Mantyke (this counts as evolving Mantyke) and remove all damage counters from Mantyke.","type":"Poké-Power"}]','[{"name":"Call for Friends","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for a Water Basic Pokémon, show it to your opponent, and put it into your hand. Shuffle your deck afterward."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[458]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-56','Monferno','Pokémon','56','Uncommon','Ken Sugimori','To intimidate attackers, it stretches the fire on its tail to make itself appear bigger.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/56.png","large":"https://images.pokemontcg.io/dp1/56_hires.png"}',NULL,'70','18','["Stage 1"]','["Fire"]','Chimchar','["Infernape"]',NULL,'[{"name":"Flame Dance","cost":["Fire"],"convertedEnergyCost":1,"damage":"30","text":"Search your discard pile for a Fire Energy card and attach it to Monferno."},{"name":"Fury Swipes","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 3 coins. This attack does 20 damage times the number of heads."}]','[{"type":"Water","value":"+20"}]',NULL,NULL,NULL,'[391]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-57','Nuzleaf','Pokémon','57','Uncommon','Kagemaru Himeno','The sound of its grass flute makes its listeners uneasy. It lives deep in forests.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/57.png","large":"https://images.pokemontcg.io/dp1/57_hires.png"}',NULL,'80','28','["Stage 1"]','["Darkness"]','Seedot','["Shiftry"]',NULL,'[{"name":"Dirty Trick","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, discard an Energy card attached to 1 of your opponent''s Pokémon."},{"name":"Razor Wind","cost":["Darkness","Darkness"],"convertedEnergyCost":2,"damage":"40","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[274]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-58','Prinplup','Pokémon','58','Uncommon','Ken Sugimori','It lives alone, away from others. Apparently, every one of them believes it is the most important.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/58.png","large":"https://images.pokemontcg.io/dp1/58_hires.png"}',NULL,'80','20','["Stage 1"]','["Water"]','Piplup','["Empoleon"]',NULL,'[{"name":"Aqua Shower","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Does 10 damage to each of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Brine","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"","text":"Choose 1 of your opponent''s Pokémon that has any damage counters on it. This attack does 40 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[394]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-59','Rapidash','Pokémon','59','Uncommon','Naoyo Kimura','It gallops at nearly 150 mph. With its mane blazing ferociously, it races as if it were an arrow.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/59.png","large":"https://images.pokemontcg.io/dp1/59_hires.png"}',NULL,'80','34','["Stage 1"]','["Fire"]','Ponyta',NULL,NULL,'[{"name":"Overrun","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Does 10 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Blaze Up","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"Flip a coin. If tails, discard a Fire Energy attached to Rapidash and this attack does 10 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Water","value":"+20"}]',NULL,NULL,NULL,'[78]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-60','Rhydon','Pokémon','60','Uncommon','Naoyo Kimura','Its brain developed after it stood up on its hind legs. Its drill horn bores tunnels through solid rock.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/60.png","large":"https://images.pokemontcg.io/dp1/60_hires.png"}',NULL,'90','43','["Stage 1"]','["Fighting"]','Rhyhorn','["Rhyperior"]',NULL,'[{"name":"Storm Up","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"If there is any Stadium card in play, this attack does 30 damage plus 20 more damage. Discard that Stadium card."},{"name":"Crash Impact","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Rhydon does 10 damage to itself. Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any."}]','[{"type":"Water","value":"+20"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless"]',2,'[112]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-61','Riolu','Pokémon','61','Uncommon','Ken Sugimori','The aura that emanates from its body intensifies to alert others if it is afraid or sad.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/61.png","large":"https://images.pokemontcg.io/dp1/61_hires.png"}',NULL,'60','7','["Basic"]','["Fighting"]',NULL,'["Lucario"]',NULL,'[{"name":"Wild Kick","cost":["Fighting"],"convertedEnergyCost":1,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[447]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-62','Seaking','Pokémon','62','Uncommon','Atsuko Nishida','It makes its nest by hollowing out boulders in streams with its horn. It defends its eggs with its life.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/62.png","large":"https://images.pokemontcg.io/dp1/62_hires.png"}',NULL,'80','41','["Stage 1"]','["Water"]','Goldeen',NULL,NULL,'[{"name":"Flail","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10×","text":"Does 10 damage times the number of damage counters on Seaking."},{"name":"Horn Drill","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[119]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-63','Silcoon','Pokémon','63','Uncommon','Ken Sugimori','It anchors itself by wrapping twigs with the silk from its body. It motionlessly awaits evolution.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/63.png","large":"https://images.pokemontcg.io/dp1/63_hires.png"}',NULL,'80','8','["Stage 1"]','["Grass"]','Wurmple','["Beautifly"]',NULL,'[{"name":"Harden","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, If Silcoon would be damaged by an attack, prevent that attack''s damage done to Silcoon if that damage is 30 or less."},{"name":"Entangling String","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon can''t attack during your opponent''s next turn."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[266]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-64','Staravia','Pokémon','64','Uncommon','Masakazu Fukuda','It flies around forests and fields in search of bug Pokémon. It stays within a huge flock.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/64.png","large":"https://images.pokemontcg.io/dp1/64_hires.png"}',NULL,'70','21','["Stage 1"]','["Colorless"]','Starly','["Staraptor"]',NULL,'[{"name":"Whirlwind","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Clutch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Lightning","value":"+20"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[397]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-65','Unown [A]','Pokémon','65','Uncommon','Nakaoka','Shaped like ancient writing, it is a huge mystery whether language or UNOWN came first.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/65.png","large":"https://images.pokemontcg.io/dp1/65_hires.png"}',NULL,'50','15','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"ANALYZE","text":"Once during your turn (before your attack), if Unown A is on your Bench, you may look at the top 2 cards of your deck and put them back on top of your deck in any order.","type":"Poké-Power"}]','[{"name":"Hidden Power","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[201]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-66','Unown [B]','Pokémon','66','Uncommon','Nakaoka','Shaped like ancient writing, it is a huge mystery whether language or UNOWN came first.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/66.png","large":"https://images.pokemontcg.io/dp1/66_hires.png"}',NULL,'50','12','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"BOUNCE","text":"Once during your turn (before your attack), if Unown B is on your Bench, you may flip a coin. If heads, discard all cards attached to any 1 of your Unown and shuffle that Pokémon back into your deck.","type":"Poké-Power"}]','[{"name":"Hidden Power","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[201]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-67','Unown [C]','Pokémon','67','Uncommon','Nakaoka','Shaped like ancient writing, it is a huge mystery whether language or UNOWN came first.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/67.png","large":"https://images.pokemontcg.io/dp1/67_hires.png"}',NULL,'50','18','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"CALL","text":"Once during your turn (before your attack), if Unown C is on your Bench, you may flip coin. If heads, search your deck for any 1 Unown and put it onto your Bench. Shuffle your deck afterward.","type":"Poké-Power"}]','[{"name":"Hidden Power","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[201]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-68','Unown [D]','Pokémon','68','Uncommon','Nakaoka','Shaped like ancient writing, it is a huge mystery whether language or UNOWN came first.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/68.png","large":"https://images.pokemontcg.io/dp1/68_hires.png"}',NULL,'50','14','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"DRAW","text":"Once during your turn (before your attack), if Unown D is on your Bench, you may flip a coin. If heads, each player may draw a card. (You draw your card first.)","type":"Poké-Power"}]','[{"name":"Hidden Power","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[201]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-69','Azurill','Pokémon','69','Common','Ken Sugimori','A Pokémon that lives by water. It moves quickly on land by bouncing on its big tail.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/69.png","large":"https://images.pokemontcg.io/dp1/69_hires.png"}',NULL,'40','6','["Basic"]','["Colorless"]',NULL,'["Marill"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Marill from your hand onto Azurill (this counts a evolving Azurill) and remove all damage counters from Azurill.","type":"Poké-Power"}]','[{"name":"Delivery","cost":[],"convertedEnergyCost":0,"damage":"","text":"Put any 1 card from your discard pile into your hand."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[298]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-70','Bidoof','Pokémon','70','Common','Ken Sugimori','With nerves of steel, nothing can perturb it. It is more agile and active than it appears.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/70.png","large":"https://images.pokemontcg.io/dp1/70_hires.png"}',NULL,'50','10','["Basic"]','["Colorless"]',NULL,'["Bibarel"]',NULL,'[{"name":"Amnesia","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of the Defending Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."},{"name":"Scavenge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your discard pile for a Trainer card, show it to your opponent, and put it into your hand."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[399]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-71','Bonsly','Pokémon','71','Common','Midori Harada','It looks as if it is always crying. It is actually adjusting its body''s fluid levels by eliminating excess.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/71.png","large":"https://images.pokemontcg.io/dp1/71_hires.png"}',NULL,'40','6','["Basic"]','["Fighting"]',NULL,'["Sudowoodo"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Sudowoodo from your hand onto Bonsly (this counts as evolving Bonsly) and remove all damage counters from Bonsly.","type":"Poké-Power"}]','[{"name":"Fake Tears","cost":[],"convertedEnergyCost":0,"damage":"","text":"Flip a coin. If heads, your opponent can''t play any Trainer cards from his or her hand during your opponent''s next turn, and any damage done to Bonsly by attacks is reduced by 30 (after applying Weakness and Resistance)."}]','[{"type":"Grass","value":"+10"}]',NULL,'["Colorless"]',1,'[438]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-72','Buizel','Pokémon','72','Common','Ken Sugimori','It has a flotation sac that is like an inflatable collar. It floats on water with its head out.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/72.png","large":"https://images.pokemontcg.io/dp1/72_hires.png"}',NULL,'60','10','["Basic"]','["Water"]',NULL,'["Floatzel"]',NULL,'[{"name":"Splash About","cost":["Water"],"convertedEnergyCost":1,"damage":"10+","text":"If Buizel has less Energy attached to it than the Defending Pokémon, this attack does 10 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[418]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-73','Buneary','Pokémon','73','Common','Ken Sugimori','It slams foes by sharply uncoiling its rolled ears. It stings enough to make a grown-up cry in pain.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/73.png","large":"https://images.pokemontcg.io/dp1/73_hires.png"}',NULL,'50','11','["Basic"]','["Colorless"]',NULL,'["Lopunny"]',NULL,'[{"name":"Splash","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Jump Kick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Does 10 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[427]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-74','Chatot','Pokémon','74','Common','Ken Sugimori','It can learn and speak human words. If they gather, they all learn the same saying.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/74.png","large":"https://images.pokemontcg.io/dp1/74_hires.png"}',NULL,'60','27','["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Me First","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw a card."},{"name":"Tone-Deaf","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[441]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-75','Cherubi','Pokémon','75','Common','Ken Sugimori','The small ball holds the nutrients needed for evolution. Apparently, it is very sweet and tasty.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/75.png","large":"https://images.pokemontcg.io/dp1/75_hires.png"}',NULL,'50','7','["Basic"]','["Grass"]',NULL,'["Cherrim"]',NULL,'[{"name":"Sleep Powder","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."},{"name":"Leech Seed","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"If this attack does any damage to the Defending Pokémon (after applying Weakness and Resistance), remove 1 damage counter from Cherubi."}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[420]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-76','Chimchar','Pokémon','76','Common','Ken Sugimori','It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/76.png","large":"https://images.pokemontcg.io/dp1/76_hires.png"}',NULL,'50','8','["Basic"]','["Fire"]',NULL,'["Monferno"]',NULL,'[{"name":"Scratch","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Ember","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, discard a Fire Energy attached to Chimchar."}]','[{"type":"Water","value":"+10"}]',NULL,'["Colorless"]',1,'[390]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-77','Clefairy','Pokémon','77','Common','Ken Sugimori','Thought to live with others on quiet mountains, it is popular for its adorable nature.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/77.png","large":"https://images.pokemontcg.io/dp1/77_hires.png"}',NULL,'60','18','["Basic"]','["Colorless"]',NULL,'["Clefable"]',NULL,'[{"name":"Sing","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."},{"name":"Moon Impact","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"If Clefairy is evolved from Cleffa, this attack does 20 damage plus 20 more damage."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[35]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-78','Cleffa','Pokémon','78','Common','Ken Sugimori','Its silhouette is like a star. It is believed to arrive riding on shooting stars.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/78.png","large":"https://images.pokemontcg.io/dp1/78_hires.png"}',NULL,'40','5','["Basic"]','["Colorless"]',NULL,'["Clefairy"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Clefairy from your hand onto Cleffa (this counts as evolving Cleffa) and remove all damage counters from Cleffa.","type":"Poké-Power"}]','[{"name":"Eeek","cost":[],"convertedEnergyCost":0,"damage":"","text":"Draw a card."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[173]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-79','Combee','Pokémon','79','Common','Ken Sugimori','A Pokémon formed by three others. It busily carries sweet floral honey to VESPIQUEN.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/79.png","large":"https://images.pokemontcg.io/dp1/79_hires.png"}',NULL,'50','8','["Basic"]','["Grass"]',NULL,'["Vespiquen"]',NULL,'[{"name":"Soliciting Nectar","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Switch 1 of your opponent''s Benched Pokémon with 1 of the Defending Pokémon. The new Defending Pokémon is now Asleep."},{"name":"Gust","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fire","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[415]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-80','Duskull','Pokémon','80','Common','Atsuko Nishida','It doggedly pursues its prey wherever it goes. However, the chase is abandoned at sunrise.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/80.png","large":"https://images.pokemontcg.io/dp1/80_hires.png"}',NULL,'50','15','["Basic"]','["Psychic"]',NULL,'["Dusclops"]',NULL,'[{"name":"Disable","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose 1 of the Defending Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."},{"name":"Night Shade","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Does 10 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[355]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-81','Electabuzz','Pokémon','81','Common','Kagemaru Himeno','Half of all blackouts occur when this Pokémon appears at power plants and eats electricity.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/81.png","large":"https://images.pokemontcg.io/dp1/81_hires.png"}',NULL,'70','29','["Basic"]','["Lightning"]',NULL,'["Electivire"]',NULL,'[{"name":"Thunderpunch","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 10 more damage. If tails, Electabuzz does 10 damage to itself."},{"name":"Shock Wave","cost":["Lightning","Lightning"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If Electabuzz is evolved from Elekid, this attack does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[125]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-82','Gastly','Pokémon','82','Common','Kouki Saitou','This Pokémon''s body is 95% made up of gases, which are blown away by strong gusts of wind.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/82.png","large":"https://images.pokemontcg.io/dp1/82_hires.png"}',NULL,'50','12','["Basic"]','["Psychic"]',NULL,'["Haunter"]',NULL,'[{"name":"Pain Payback","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Move 1 damage counter from Gastly to 1 of your opponent''s Pokémon."}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[92]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-83','Glameow','Pokémon','83','Common','Ken Sugimori','It claws if displeased and purrs when affectionate. Its fickleness if very popular among some.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/83.png","large":"https://images.pokemontcg.io/dp1/83_hires.png"}',NULL,'50','12','["Basic"]','["Colorless"]',NULL,'["Purugly"]',NULL,'[{"name":"Charm","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, any damage done by attacks from the Defending Pokémon is reduced by 20 (before applying Weakness and Resistance)."},{"name":"Pose","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[431]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-84','Goldeen','Pokémon','84','Common','Atsuko Nishida','It swims elegantly by flittering its tail as if it were a dress. It has the look of a queen.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/84.png","large":"https://images.pokemontcg.io/dp1/84_hires.png"}',NULL,'60','14','["Basic"]','["Water"]',NULL,'["Seaking"]',NULL,'[{"name":"Horn Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Take Down","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Goldeen does 10 damage to itself."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[118]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-85','Hoothoot','Pokémon','85','Common','Midori Harada','It always stands on one foot. Even when attacked, it does not brace itself using both feet.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/85.png","large":"https://images.pokemontcg.io/dp1/85_hires.png"}',NULL,'50','7','["Basic"]','["Colorless"]',NULL,'["Noctowl"]',NULL,'[{"name":"Hypnosis","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep."},{"name":"Kick Shot","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[163]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-86','Machop','Pokémon','86','Common','Atsuko Nishida','It hefts a GRAVELER repeatedly to strengthen its entire body. It uses every type of martial arts.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/86.png","large":"https://images.pokemontcg.io/dp1/86_hires.png"}',NULL,'60','20','["Basic"]','["Fighting"]',NULL,'["Machoke"]',NULL,'[{"name":"Low Kick","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless","Colorless"]',2,'[66]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-87','Magnemite','Pokémon','87','Common','Kouki Saitou','The units at its sides generate electromagnetic waves that keep it airborne. It feeds on electricity.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/87.png","large":"https://images.pokemontcg.io/dp1/87_hires.png"}',NULL,'50','10','["Basic"]','["Metal"]',NULL,'["Magneton"]',NULL,'[{"name":"Metal Sound","cost":["Metal"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."},{"name":"Resonance","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"If the Defending Pokémon is Confused, this attack does 20 damage plus 20 more damage."}]','[{"type":"Fire","value":"+10"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[81]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-88','Marill','Pokémon','88','Common','Atsuko Nishida','Using its tail as a float, it dives underwater. It likes eating plants that grow on river bottoms.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/88.png","large":"https://images.pokemontcg.io/dp1/88_hires.png"}',NULL,'60','12','["Basic"]','["Water"]',NULL,'["Azumarill"]',NULL,'[{"name":"Rollout","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10+","text":"If Marill is evolved from Azurill, this attack does 10 damage plus 20 more damage."},{"name":"Splashing Turn","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"20","text":"Switch Marill with 1 of your Benched Pokémon."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[183]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-89','Meditite','Pokémon','89','Common','Masakazu Fukuda','It eats just one berry a day. By enduring hunger, its spirit is tempered and made sharper.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/89.png","large":"https://images.pokemontcg.io/dp1/89_hires.png"}',NULL,'50','19','["Basic"]','["Fighting"]',NULL,'["Medicham"]',NULL,'[{"name":"Detect","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, prevent all effects of an attack, including damage, done to Meditite during your opponent''s next turn."},{"name":"Meditate","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Does 10 damage plus 10 more damage for each damage counter on the Defending Pokémon."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[307]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-90','Mime Jr.','Pokémon','90','Common','Ken Sugimori','It habitually mimics foes. Once mimicked, the foe cannot take its eyes off this Pokémon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/90.png","large":"https://images.pokemontcg.io/dp1/90_hires.png"}',NULL,'40','5','["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Mr. Mime from your hand onto Mime Jr. (this counts as evolving Mime Jr.) and remove all damage counters from Mime Jr.","type":"Poké-Power"}]','[{"name":"Mime","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Shuffle your hand into your deck. Then, draw a number of cards equal to the number of cards in your opponent''s hand."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[439]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-91','Misdreavus','Pokémon','91','Common','Ken Sugimori','It loves to sneak up on people late at night, then startle them with its shrieklike cry.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/91.png","large":"https://images.pokemontcg.io/dp1/91_hires.png"}',NULL,'60','16','["Basic"]','["Psychic"]',NULL,'["Mismagius"]',NULL,'[{"name":"Astonish","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 card from your opponent''s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck."},{"name":"Confuse Ray","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[200]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-92','Onix','Pokémon','92','Common','Ken Sugimori','When it travels underground, it causes rumbling and tremors. It can move at 50 mph.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/92.png","large":"https://images.pokemontcg.io/dp1/92_hires.png"}',NULL,'90','22','["Basic"]','["Fighting"]',NULL,'["Steelix"]',NULL,'[{"name":"Tunneling","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Choose up to 2 of your opponent''s Benched Pokémon. This attack does 10 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.) Onix can''t attack during your next turn."},{"name":"Headbutt","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[95]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-93','Piplup','Pokémon','93','Common','Ken Sugimori','Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/93.png","large":"https://images.pokemontcg.io/dp1/93_hires.png"}',NULL,'60','9','["Basic"]','["Water"]',NULL,'["Prinplup"]',NULL,'[{"name":"Peck","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Water Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[393]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-94','Ponyta','Pokémon','94','Common','Kagemaru Himeno','About an hour after birth, its fiery mane and tail grow out, giving it an impressive appearance.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/94.png","large":"https://images.pokemontcg.io/dp1/94_hires.png"}',NULL,'60','12','["Basic"]','["Fire"]',NULL,'["Rapidash"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Flame Tail","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"+10"}]',NULL,'["Colorless"]',1,'[77]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-95','Rhyhorn','Pokémon','95','Common','Kagemaru Himeno','Its body is clad in a thick hide, and its tackles topple buildings. Unfortunately, it is not smart.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/95.png","large":"https://images.pokemontcg.io/dp1/95_hires.png"}',NULL,'60','19','["Basic"]','["Fighting"]',NULL,'["Rhydon"]',NULL,'[{"name":"Horn Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Take Down","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Rhyhorn does 10 damage to itself."}]','[{"type":"Water","value":"+10"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless"]',2,'[111]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-96','Roselia','Pokémon','96','Common','Ken Sugimori','ROSELIA raised on clean drinking water are known to grow vividly colored flowers.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/96.png","large":"https://images.pokemontcg.io/dp1/96_hires.png"}',NULL,'70','31','["Basic"]','["Grass"]',NULL,'["Roserade"]',NULL,'[{"name":"Toxic Spikes","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Poisoned. If Roselia is evolved from Budew, this attack does 10 damage to the Defending Pokémon."},{"name":"Sweet Spike","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"10","text":"The Defending Pokémon is now Asleep. Remove 2 damage counters from 1 of your Pokémon."}]','[{"type":"Fire","value":"+10"}]',NULL,'["Colorless"]',1,'[315]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-97','Seedot','Pokémon','97','Common','Masakazu Fukuda','When it dangles from a tree branch, it looks just like an acorn. It enjoys scaring other Pokémon.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/97.png","large":"https://images.pokemontcg.io/dp1/97_hires.png"}',NULL,'50','9','["Basic"]','["Grass"]',NULL,'["Nuzleaf"]',NULL,'[{"name":"Bide","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, during your opponent''s next turn, if Seedot would be Knocked Out by damage from an attack, Seedot is not Knocked Out and its remaining HP becomes 10 instead."},{"name":"Rollout","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[273]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-98','Shinx','Pokémon','98','Common','Ken Sugimori','All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/98.png","large":"https://images.pokemontcg.io/dp1/98_hires.png"}',NULL,'60','7','["Basic"]','["Lightning"]',NULL,'["Luxio"]',NULL,'[{"name":"Spark","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Does 10 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[403]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-99','Skorupi','Pokémon','99','Common','Kouki Saitou','It grips prey with its tail claws and injects poison. It tenaciously hangs on until the poison takes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/99.png","large":"https://images.pokemontcg.io/dp1/99_hires.png"}',NULL,'60','9','["Basic"]','["Psychic"]',NULL,'["Drapion"]',NULL,'[{"name":"Poison Sting","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."},{"name":"Pin Missile","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10×","text":"Flip 4 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless","Colorless"]',2,'[451]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-100','Sneasel','Pokémon','100','Common','Ken Sugimori','It feeds on eggs stolen from nests. Its sharply hooked claws rip vulnerable spots on prey.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/100.png","large":"https://images.pokemontcg.io/dp1/100_hires.png"}',NULL,'60','21','["Basic"]','["Darkness"]',NULL,'["Weavile"]',NULL,'[{"name":"Double Slap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."},{"name":"Feint Attack","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 20 damage to that Pokémon. This attack''s damage isn''t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon."}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[215]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-101','Starly','Pokémon','101','Common','Ken Sugimori','They flock in great numbers. Though small, they flap their wings with great power.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/101.png","large":"https://images.pokemontcg.io/dp1/101_hires.png"}',NULL,'50','8','["Basic"]','["Colorless"]',NULL,'["Staravia"]',NULL,'[{"name":"Gust","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Quick Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[396]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-102','Stunky','Pokémon','102','Common','Ken Sugimori','It protects itself by spraying a noxious fluid from its rear. The stench lingers for 24 hours.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/102.png","large":"https://images.pokemontcg.io/dp1/102_hires.png"}',NULL,'60','17','["Basic"]','["Darkness"]',NULL,'["Skuntank"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Severe Gas","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[434]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-103','Turtwig','Pokémon','103','Common','Ken Sugimori','Made from soil, the shell on its back hardens when it drinks water. It lives along lakes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/103.png","large":"https://images.pokemontcg.io/dp1/103_hires.png"}',NULL,'60','10','["Basic"]','["Grass"]',NULL,'["Grotle"]',NULL,'[{"name":"Tackle","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Razor Leaf","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[387]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-104','Wurmple','Pokémon','104','Common','Ken Sugimori','It loves to eat leaves. If it is attacked by a STARLY, it will defend itself with its spiked rear.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/104.png","large":"https://images.pokemontcg.io/dp1/104_hires.png"}',NULL,'50','7','["Basic"]','["Grass"]',NULL,'["Silcoon","Cascoon"]',NULL,'[{"name":"Needling Sting","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 10 more damage."},{"name":"String Shot","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"+10"}]',NULL,'["Colorless"]',1,'[265]',NULL,NULL,'dp1');
INSERT INTO "Card" VALUES('dp1-105','Double Full Heal','Trainer','105','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/105.png","large":"https://images.pokemontcg.io/dp1/105_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all Special Conditions from each of your Active Pokémon."]','dp1');
INSERT INTO "Card" VALUES('dp1-106','Energy Restore','Trainer','106','Uncommon','Hideyuki Nakajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/106.png","large":"https://images.pokemontcg.io/dp1/106_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 3 coins. For each heads, put a basic Energy card from your discard pile into your hand. If you don''t have that many basic Energy cards in your discard pile, put all of them into your hand."]','dp1');
INSERT INTO "Card" VALUES('dp1-107','Energy Switch','Trainer','107','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/107.png","large":"https://images.pokemontcg.io/dp1/107_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Move a basic Energy card attached to 1 of your Pokémon to another of your Pokémon."]','dp1');
INSERT INTO "Card" VALUES('dp1-108','Night Pokémon Center','Trainer','108','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/108.png","large":"https://images.pokemontcg.io/dp1/108_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon. Flip 2 coins. If both are heads, remove all damage counters from that Pokémon. If both are tails, discard all Energy cards attached to that Pokémon."]','dp1');
INSERT INTO "Card" VALUES('dp1-109','PlusPower','Trainer','109','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/109.png","large":"https://images.pokemontcg.io/dp1/109_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach PlusPower to 1 of your Pokémon. Discard this card at the end of your turn.","If the Pokémon PlusPower is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance)."]','dp1');
INSERT INTO "Card" VALUES('dp1-110','Poké Ball','Trainer','110','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/110.png","large":"https://images.pokemontcg.io/dp1/110_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Pokémon, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','dp1');
INSERT INTO "Card" VALUES('dp1-111','Pokédex HANDY910is','Trainer','111','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/111.png","large":"https://images.pokemontcg.io/dp1/111_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 2 cards of your deck, choose 1 of them, and put it into your hand. Put the other card on the bottom of your deck."]','dp1');
INSERT INTO "Card" VALUES('dp1-112','Professor Rowan','Trainer','112','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/112.png","large":"https://images.pokemontcg.io/dp1/112_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Choose 1 card in your hand and shuffle the rest of your cards into your deck. Then, draw 4 cards. (If this is the only card in your hand, you can''t play this card.)"]','dp1');
INSERT INTO "Card" VALUES('dp1-113','Rival','Trainer','113','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/113.png","large":"https://images.pokemontcg.io/dp1/113_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Reveal the top 5 cards of your deck. Your opponent chooses 3 of those cards. Put those cards into your hand and put other 2 cards on top of your deck. Shuffle your deck afterward."]','dp1');
INSERT INTO "Card" VALUES('dp1-114','Speed Stadium','Trainer','114','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/114.png","large":"https://images.pokemontcg.io/dp1/114_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, the player may flip a coin until he or she gets tails. For each heads, that player draws a card."]','dp1');
INSERT INTO "Card" VALUES('dp1-115','Super Scoop Up','Trainer','115','Uncommon','Shizurow',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/115.png","large":"https://images.pokemontcg.io/dp1/115_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, return 1 of your Pokémon and all cards attached to it to your hand."]','dp1');
INSERT INTO "Card" VALUES('dp1-116','Warp Point','Trainer','116','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/116.png","large":"https://images.pokemontcg.io/dp1/116_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent switches 1 of his or her Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch 1 of your Active Pokémon with 1 of your Benched Pokémon, if any."]','dp1');
INSERT INTO "Card" VALUES('dp1-117','Energy Search','Trainer','117','Common','Kai Ishikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/117.png","large":"https://images.pokemontcg.io/dp1/117_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','dp1');
INSERT INTO "Card" VALUES('dp1-118','Potion','Trainer','118','Common','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/118.png","large":"https://images.pokemontcg.io/dp1/118_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove 2 damage counters from 1 of your Pokémon (remove 1 damage counter if that Pokémon has only 1)."]','dp1');
INSERT INTO "Card" VALUES('dp1-119','Switch','Trainer','119','Common','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/119.png","large":"https://images.pokemontcg.io/dp1/119_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch 1 of your Active Pokémon with 1 of your Benched Pokémon."]','dp1');
INSERT INTO "Card" VALUES('dp1-120','Empoleon LV.X','Pokémon','120','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/120.png","large":"https://images.pokemontcg.io/dp1/120_hires.png"}',NULL,'140','X','["Level-Up"]','["Water"]','Empoleon',NULL,'[{"name":"Supreme Command","text":"Once during your turn (before your attack), you may choose up to 2 cards from your opponent''s hand without looking and put them face down next to the Defending Pokémon. (These cards are not in play or in your opponent''s hand.) At the end of your opponent''s next turn, return those cards to your opponent''s hand. This power can''t be used if Empoleon is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Hydro Impact","cost":["Water","Water","Water"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 80 damage to that Pokémon (Don''t apply Weakness and Resistance for Benched Pokémon.) Empoleon can''t attack during your next turn."}]','[{"type":"Lightning","value":"+30"}]',NULL,'["Colorless","Colorless"]',2,'[395]',NULL,'["Put this card onto your Active Empoleon. Empoleon LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp1');
INSERT INTO "Card" VALUES('dp1-121','Infernape LV.X','Pokémon','121','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/121.png","large":"https://images.pokemontcg.io/dp1/121_hires.png"}',NULL,'120','X','["Level-Up"]','["Fire"]','Infernape',NULL,'[{"name":"Burning Head","text":"Once during your turn (before your attack), you may look at the top 3 cards of your deck, choose 1 of them, and put it into your hand. Discard the other 2 cards. This power can''t be used if Infernape is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Flare Up","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"150","text":"Search your discard pile for 8 Fire Energy cards, show them to your opponent, and shuffle them into your deck. (This attack does nothing if you don''t have 8 Fire Energy cards in your discard pile.)"}]','[{"type":"Water","value":"+30"}]',NULL,NULL,NULL,'[392]',NULL,'["Put this card onto your Active Infernape. Infernape LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp1');
INSERT INTO "Card" VALUES('dp1-122','Torterra LV.X','Pokémon','122','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/122.png","large":"https://images.pokemontcg.io/dp1/122_hires.png"}',NULL,'160','X','["Level-Up"]','["Grass"]','Torterra',NULL,'[{"name":"Forest Murmurs","text":"Once during your turn (before your attack), if you have more Prize cards left than your opponent, you may choose 1 of your opponent''s Benched Pokémon and switch it with 1 of the Defending Pokémon. This power can''t be used if Torterra is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Vigorous Dash","cost":["Grass","Grass","Grass","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Does 30 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) Torterra does 30 damage to itself."}]','[{"type":"Fire","value":"+30"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[389]',NULL,'["Put this card onto your Active Torterra. Torterra LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp1');
INSERT INTO "Card" VALUES('dp1-123','Grass Energy','Energy','123','Common',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp1/123.png","large":"https://images.pokemontcg.io/dp1/123_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'dp1');
