INSERT INTO "Card" VALUES('dp3-96','Natu','Pokémon','96','Common','Midori Harada','It picks food from cactus plants, deftly avoiding buds and spines. It seems to skip about to move.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp3/96.png","large":"https://images.pokemontcg.io/dp3/96_hires.png"}',NULL,'40','9','["Basic"]','["Psychic"]',NULL,'["Xatu"]',NULL,'[{"name":"Bothering Wave","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, this attack does nothing. If heads, discard an Energy card attached to the Defending Pokémon."},{"name":"Future Sight","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 5 cards of either player''s deck and put them back on top of that player''s deck in any order."}]','[{"type":"Psychic","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[177]',NULL,NULL,'dp3');
