INSERT INTO "Card" VALUES('dp3-101','Qwilfish','Pokémon','101','Common','Kenkichi Toyama','It shoots the poison spines on its body in all directions. Its round form makes it a poor swimmer.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp3/101.png","large":"https://images.pokemontcg.io/dp3/101_hires.png"}',NULL,'70','31','["Basic"]','["Water"]',NULL,NULL,'[{"name":"Balloon Sting","text":"Once during your opponent''s turn, if Qwilfish is your Active Pokémon and is damage by an attack (even if Qwilfish is Knocked Out), you may flip a coin. If heads, the Attacking Pokémon is now Poisoned. Put 2 damage counters instead of 1 on that Pokémon between turns.","type":"Poké-Power"}]','[{"name":"Nerve Shot","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[211]',NULL,NULL,'dp3');
