INSERT INTO "Card" VALUES('dp6-89','Corphish','Pokémon','89','Common','Sumiyoshi Kizuki','Its hardy vitality enables it to adapt to any environment. Its pincers will never release prey.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp6/89.png","large":"https://images.pokemontcg.io/dp6/89_hires.png"}',NULL,'50','6','["Basic"]','["Water"]',NULL,'["Crawdaunt"]',NULL,'[{"name":"Knock Off","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose 1 card from your opponent''s hand without looking and discard it."},{"name":"Irongrip","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[341]',NULL,NULL,'dp6');
