INSERT INTO "Card" VALUES('dp6-91','Dratini','Pokémon','91','Common','Ken Sugimori','It is called the "Mirage Pokémon" because so few have seen it. Its shed skin has been found.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp6/91.png","large":"https://images.pokemontcg.io/dp6/91_hires.png"}',NULL,'40','8','["Basic"]','["Colorless"]',NULL,'["Dragonair"]',NULL,'[{"name":"Tail Slap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Slam","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 2 coins. This attack does 20 damage times the number of heads."}]','[{"type":"Colorless","value":"+10"}]',NULL,'["Colorless"]',1,'[147]',NULL,NULL,'dp6');
