INSERT INTO "Card" VALUES('dp6-93','Exeggcute','Pokémon','93','Common','Midori Harada','Its six eggs converse using telepathy. They can quickly gather if they become separated.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp6/93.png","large":"https://images.pokemontcg.io/dp6/93_hires.png"}',NULL,'50','11','["Basic"]','["Psychic"]',NULL,'["Exeggutor"]',NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 in any combination of Grass Basic Pokémon and Psychic Basic Pokémon and put them onto your Bench. Shuffle your deck afterward."},{"name":"Hypnosis","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"The Defending Pokémon is now Asleep."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[102]',NULL,NULL,'dp6');
