INSERT INTO "Card" VALUES('dp7-28','Steelix','Pokémon','28','Rare','Naoyo Kimura','Tempered underground under high pressure and heat, its body is harder than any metal.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/28.png","large":"https://images.pokemontcg.io/dp7/28_hires.png"}',NULL,'130','63','["Stage 1"]','["Metal"]','Onix',NULL,NULL,'[{"name":"Outbreak Power","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose a number of your opponent''s Pokémon up to the amount of Energy attached to Steelix. This attack does 20 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Iron Tail","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100×","text":"Flip a coin until you get tails. This attack does 100 damage times the number of heads."}]','[{"type":"Fire","value":"+30"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,NULL,'dp7');
