INSERT INTO "Card" VALUES('dp7-34','Dusclops','Pokémon','34','Uncommon','Yukiko Baba','Its body is hollow. It is said that those who look into its body are sucked into the void.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/34.png","large":"https://images.pokemontcg.io/dp7/34_hires.png"}',NULL,'80','41','["Stage 1"]','["Psychic"]','Duskull','["Dusknoir"]',NULL,'[{"name":"Dark One-eye","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":"You may discard a card from your hand. If you do, your opponent discards a card from his or her hand."},{"name":"Ambush","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"Flip a coin. If heads, this attack does 40 damage plus 20 more damage."}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[356]',NULL,NULL,'dp7');
