INSERT INTO "Card" VALUES('dp7-46','Piloswine','Pokémon','46','Uncommon','Mitsuhiro Arita','Its shaggy coat makes it unable to see. It checks surroundings with its sensitive nose instead.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/46.png","large":"https://images.pokemontcg.io/dp7/46_hires.png"}',NULL,'90','34','["Stage 1"]','["Fighting"]','Swinub','["Mamoswine"]',NULL,'[{"name":"Rouse","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20+","text":"Does 20 damage plus 10 more damage for each damage counter on Piloswine. Then, remove 4 damage counters from Piloswine."},{"name":"Overrun","cost":["Fighting","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"Does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"+20"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless"]',2,'[221]',NULL,NULL,'dp7');
