INSERT INTO "Card" VALUES('dp7-51','Skarmory','Pokémon','51','Uncommon','Kagemaru Himeno','Despite being clad entirely in iron-hard armor, it flies at speeds over 180 mph.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/51.png","large":"https://images.pokemontcg.io/dp7/51_hires.png"}',NULL,'80','34','["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Quick Attack","cost":["Metal"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage."},{"name":"Mach Blade","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Flip a coin. If heads, this attack does 50 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[227]',NULL,NULL,'dp7');
