INSERT INTO "Card" VALUES('dp7-55','Bronzor','Pokémon','55','Common','Miki Tanaka','Implements shaped like it were discovered in ancient tombs. It is unknown if they are related.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/55.png","large":"https://images.pokemontcg.io/dp7/55_hires.png"}',NULL,'60','14','["Basic"]','["Psychic"]',NULL,'["Bronzong"]',NULL,'[{"name":"Gyro Swap","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Put a number of damage counters on the Defending Pokémon equal to the number of Colorless Energy in Bronzor''s Retreat Cost (after applying effects to the Retreat Cost)."},{"name":"Psyshock","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Psychic","value":"+10"}]','[{"type":"Fire","value":"-20"}]','["Colorless","Colorless"]',2,'[436]',NULL,NULL,'dp7');
