INSERT INTO "Card" VALUES('dp7-61','Finneon','Pokémon','61','Common','Kagemaru Himeno','After long exposure to sunlight, the patterns on its tail fins shine vividly when darkness arrives.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/61.png","large":"https://images.pokemontcg.io/dp7/61_hires.png"}',NULL,'50','16','["Basic"]','["Water"]',NULL,'["Lumineon"]',NULL,'[{"name":"Aqua Liner","cost":[],"convertedEnergyCost":0,"damage":"","text":"Choose 1 of your opponent''s Benched Pokémon. This attack does 10 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Mouth Pump","cost":["Water"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[456]',NULL,NULL,'dp7');
