INSERT INTO "Card" VALUES('dp7-69','Onix','Pokémon','69','Common','Kyoko Umemoto','When it travels underground, it causes rumbling and tremors. It can move at 50 mph.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/69.png","large":"https://images.pokemontcg.io/dp7/69_hires.png"}',NULL,'90','25','["Basic"]','["Fighting"]',NULL,'["Steelix"]',NULL,'[{"name":"Harden","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, if Onix would be damaged by an attack, prevent that attack''s damage done to Onix if that damage is 40 or less."},{"name":"Bind","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[95]',NULL,NULL,'dp7');
