INSERT INTO "Card" VALUES('dp7-72','Roselia','Pokémon','72','Common','Sumiyoshi Kizuki','Roselia raised on clean drinking water are known to grow vividly colored flowers.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/72.png","large":"https://images.pokemontcg.io/dp7/72_hires.png"}',NULL,'70','27','["Basic"]','["Psychic"]',NULL,'["Roserade"]',NULL,'[{"name":"Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Petal Spikes","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Asleep and Poisoned. If Budew is anywhere under Roselia, the Defending Pokémon is now Asleep and Poisoned."}]','[{"type":"Fire","value":"+10"}]',NULL,'["Colorless"]',1,'[315]',NULL,NULL,'dp7');
