INSERT INTO "Card" VALUES('dp7-79','Treecko','Pokémon','79','Common','Naoyo Kimura','The soles of its feet are covered by countless tiny spikes, enabling it to walk on walls and ceilings.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/79.png","large":"https://images.pokemontcg.io/dp7/79_hires.png"}',NULL,'50','11','["Basic"]','["Grass"]',NULL,'["Grovyle"]',NULL,'[{"name":"Call for Friends","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon, show it to your opponent, and put it into your hand. Shuffle your deck afterward."},{"name":"Poison Breath","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[252]',NULL,NULL,'dp7');
