INSERT INTO "Card" VALUES('dp7-81','Voltorb','Pokémon','81','Common','Miki Tanaka','It looks just like a Poké Ball. It is dangerous because it may electrocute or explode on touch.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/81.png","large":"https://images.pokemontcg.io/dp7/81_hires.png"}',NULL,'60','31','["Basic"]','["Lightning"]',NULL,'["Electrode"]',NULL,'[{"name":"Outlet","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Lightning Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."},{"name":"Bouncing Ball","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, Voltorb does 10 damage to itself."}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[100]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-82','Conductive Quarry','Trainer','82','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/82.png","large":"https://images.pokemontcg.io/dp7/82_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, the player may flip a coin. If heads, that player searches his or her discard pile for a Lightning or Metal Energy card, shows it to the opponent, and puts it into his or her hand."]','dp7');
INSERT INTO "Card" VALUES('dp7-83','Energy Link','Trainer','83','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/83.png","large":"https://images.pokemontcg.io/dp7/83_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Energy Link to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as Energy Link is attached to a Pokémon, you may move an Energy card attached to that Pokémon to another of your Pokémon that has Energy Link attached to it. You may use this effect as often as you like during your turn."]','dp7');
INSERT INTO "Card" VALUES('dp7-84','Energy Switch','Trainer','84','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/84.png","large":"https://images.pokemontcg.io/dp7/84_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Move a basic Energy card attached to 1 of your Pokémon to another of your Pokémon."]','dp7');
INSERT INTO "Card" VALUES('dp7-85','Great Ball','Trainer','85','Uncommon','Kent Kanetsuna',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/85.png","large":"https://images.pokemontcg.io/dp7/85_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward."]','dp7');
INSERT INTO "Card" VALUES('dp7-86','Luxury Ball','Trainer','86','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/86.png","large":"https://images.pokemontcg.io/dp7/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon (excluding Pokémon LV.X), show it to your opponent, and put it into your hand. Shuffle your deck afterward. If any Luxury Ball is in your discard pile, you can''t play this card."]','dp7');
INSERT INTO "Card" VALUES('dp7-87','Marley''s Request','Trainer','87','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/87.png","large":"https://images.pokemontcg.io/dp7/87_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your discard pile for 2 different Trainer, Supporter, or Stadium cards, show them to your opponent, and your opponent chooses 1 of them. Put that card into your hand, and discard the other card. (If all Trainer, Supporter, and Stadium cards in your discard pile have the same name, choose 1 of them. Show that card to your opponent and put it into your hand.)"]','dp7');
INSERT INTO "Card" VALUES('dp7-88','Poké Blower +','Trainer','88','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/88.png","large":"https://images.pokemontcg.io/dp7/88_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play 2 Poké Blower + at the same time. If you play 1 Poké Blower +, flip a coin. If heads, put 1 damage counter on 1 of your opponent''s Pokémon. If you play 2 Poké Blower +, choose 1 of your opponent''s Benched Pokémon and switch it with 1 of your opponent''s Active Pokémon."]','dp7');
INSERT INTO "Card" VALUES('dp7-89','Poké Drawer +','Trainer','89','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/89.png","large":"https://images.pokemontcg.io/dp7/89_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play 2 Poké Drawer + at the same time. If you play 1 Poké Drawer +, draw a card. If you play 2 Poké Drawer +, search your deck for up to 2 cards, and put them into your hand. Shuffle your deck afterward."]','dp7');
INSERT INTO "Card" VALUES('dp7-90','Poké Healer +','Trainer','90','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/90.png","large":"https://images.pokemontcg.io/dp7/90_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play 2 Poké Healer + at the same time. If you play 1 Poké Healer +, remove 1 damage counter and a Special Condition from 1 of your Active Pokémon. If you play 2 Poké Healer +, remove 8 damage counters and all Special Conditions from 1 of your Active Pokémon."]','dp7');
INSERT INTO "Card" VALUES('dp7-91','Premier Ball','Trainer','91','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/91.png","large":"https://images.pokemontcg.io/dp7/91_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck or your discard pile for a Pokémon LV.X, show it to your opponent, and put it into your hand. If you search your deck, shuffle your deck afterward."]','dp7');
INSERT INTO "Card" VALUES('dp7-92','Potion','Trainer','92','Common','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/92.png","large":"https://images.pokemontcg.io/dp7/92_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove 2 damage counters from 1 of your Pokémon (remove 1 damage counter if that Pokémon has only 1)."]','dp7');
INSERT INTO "Card" VALUES('dp7-93','Switch','Trainer','93','Common','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/93.png","large":"https://images.pokemontcg.io/dp7/93_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch 1 of your Active Pokémon with 1 of your Benched Pokémon."]','dp7');
INSERT INTO "Card" VALUES('dp7-94','Cyclone Energy','Energy','94','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/94.png","large":"https://images.pokemontcg.io/dp7/94_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Cyclone Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch 1 of the Defending Pokémon with 1 of your opponent''s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch."]','dp7');
INSERT INTO "Card" VALUES('dp7-95','Warp Energy','Energy','95','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/95.png","large":"https://images.pokemontcg.io/dp7/95_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Warp Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch that Pokémon with 1 of your Benched Pokémon."]','dp7');
INSERT INTO "Card" VALUES('dp7-96','Dusknoir LV.X','Pokémon','96','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/96.png","large":"https://images.pokemontcg.io/dp7/96_hires.png"}',NULL,'140','X','["Level-Up"]','["Psychic"]','Dusknoir',NULL,'[{"name":"Ectoplasm","text":"If Dusknoir is your Active Pokémon and would be Knocked Out by damage from your opponent''s attack, you may discard all cards attached to Dusknoir LV.X and put Dusknoir LV.X as a Stadium card into play instead of discarding it. This counts as Dusknoir being Knocked Out and your opponent takes a Prize card. As long as you have Dusknoir LV.X as a Stadium card in play, put 1 damage counter on each of your opponent''s Pokémon between turns. If another Stadium card comes into play or Dusknoir LV.X is discarded by the effects of any attacks, Poké-Powers, Poké-Bodies, Trainer, or Supporter cards, return Dusknoir LV.X to your hand.","type":"Poké-Power"}]',NULL,'[{"type":"Darkness","value":"×2"}]','[{"type":"Colorless","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[477]',NULL,'["Put this card onto your Active Dusknoir. Dusknoir LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp7');
INSERT INTO "Card" VALUES('dp7-97','Heatran LV.X','Pokémon','97','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/97.png","large":"https://images.pokemontcg.io/dp7/97_hires.png"}',NULL,'120','X','["Level-Up"]','["Fire"]','Heatran',NULL,'[{"name":"Heat Metal","text":"Your opponent can''t remove the Special Condition Burned by evolving or devolving his or her Burned Pokémon. (This also includes putting a Pokémon Level-Up card onto the Burned Pokémon.) Whenever your opponent flips a coin for the Special Condition Burned between turns, treat it as tails.","type":"Poké-Body"},{"name":"Heat Wave","text":"Once at the end of your turn, if Heatran is on your Bench, you may use this power. If you discarded basic Energy cards attached to your Fire or Metal Active Pokémon by using that Pokémon''s attack this turn, attach up to 2 of those Energy cards to that Pokémon.","type":"Poké-Power"}]',NULL,'[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[485]',NULL,'["Put this card onto your Active Heatran. Heatran LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp7');
INSERT INTO "Card" VALUES('dp7-98','Machamp LV.X','Pokémon','98','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/98.png","large":"https://images.pokemontcg.io/dp7/98_hires.png"}',NULL,'150','X','["Level-Up"]','["Fighting"]','Machamp',NULL,'[{"name":"No Guard","text":"As long as Machamp is your Active Pokémon, each of Machamp''s attacks does 60 more damage to the Active Pokémon (before applying Weakness and Resistance) and any damage done to Machamp by your opponent''s Pokémon is increased by 60 (after applying Weakness and Resistance).","type":"Poké-Body"}]','[{"name":"Strong-Willed","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"During your opponent''s next turn, if Machamp would be Knocked Out by damage from an attack, flip a coin. If heads, Machamp is not Knocked Out and its remaining HP becomes 10 instead."}]','[{"type":"Psychic","value":"+40"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[68]',NULL,'["Put this card onto your Active Machamp. Machamp LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp7');
INSERT INTO "Card" VALUES('dp7-99','Raichu LV.X','Pokémon','99','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/99.png","large":"https://images.pokemontcg.io/dp7/99_hires.png"}',NULL,'110','X','["Level-Up"]','["Lightning"]','Raichu',NULL,'[{"name":"Link Lightning","text":"Once during your turn, when you put Raichu LV.X onto Raichu and use Voltage Shoot, you may use another attack of Raichu afterward. This power can''t be used if Raichu is affected by a Special Condition.","type":"Poké-Body"}]','[{"name":"Voltage Shoot","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard 2 Lightning Energy cards from your hand and choose 1 of your opponent''s Pokémon. This attack does 80 to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]',NULL,NULL,'[26]',NULL,'["Put this card onto your Active Raichu. Raichu LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp7');
INSERT INTO "Card" VALUES('dp7-100','Regigigas LV.X','Pokémon','100','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/100.png","large":"https://images.pokemontcg.io/dp7/100_hires.png"}',NULL,'150','X','["Level-Up"]','["Colorless"]','Regigigas',NULL,'[{"name":"Sacrifice","text":"Once during your turn (before your attack), you may choose 1 of your Pokémon in play and that Pokémon is Knocked Out. Then, search your discard pile for up to 2 basic Energy cards, attach them to Regigigas, and remove 8 damage counters from Regigigas. This power can''t be used if Regigigas is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Giga Blaster","cost":["Water","Fighting","Metal","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Discard the top card from your opponent''s deck. Then, choose 1 card from your opponent''s hand without looking and discard it. Regigigas can''t use Giga Blaster during your next turn."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[486]',NULL,'["Put this card onto your Active Regigigas. Regigigas LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dp7');
INSERT INTO "Card" VALUES('dp7-101','Charmander','Pokémon','101','Rare Secret','Mitsuhiro Arita','From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/101.png","large":"https://images.pokemontcg.io/dp7/101_hires.png"}',NULL,'50','10','["Basic"]','["Fire"]',NULL,'["Charmeleon"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Ember","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Discard a Fire Energy attached to Charmander."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[4]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-102','Charmeleon','Pokémon','102','Rare Secret','Mitsuhiro Arita','It lashes about with its tail to knock down its foe. It then tears up the fallen opponent with sharp claws.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/102.png","large":"https://images.pokemontcg.io/dp7/102_hires.png"}',NULL,'80','32','["Stage 1"]','["Fire"]','Charmander','["Charizard"]',NULL,'[{"name":"Slash","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""},{"name":"Flamethrower","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"Discard a Fire Energy attached to Charmeleon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[5]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-103','Charizard','Pokémon','103','Rare Secret','Mitsuhiro Arita','Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/103.png","large":"https://images.pokemontcg.io/dp7/103_hires.png"}',NULL,'120','76','["Stage 2"]','["Fire"]','Charmeleon',NULL,'[{"name":"Energy Burn","text":"All Energy attached to Charizard are Fire Energy instead of their usual type.","type":"Poké-Body"}]','[{"name":"Fire Spin","cost":["Fire","Fire","Fire","Fire"],"convertedEnergyCost":4,"damage":"100","text":"Discard 2 Energy attached to Charizard."}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[6]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-SH1','Drifloon','Pokémon','SH1','Rare','Atsuko Nishida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/SH1.png","large":"https://images.pokemontcg.io/dp7/SH1_hires.png"}',NULL,'50','16','["Basic"]','["Psychic"]',NULL,'["Drifblim"]','[{"name":"Unburden","text":"If Drifloon has a Pokémon Tool card attached to it, Drifloon''s Retreat Cost is ColorlessColorless more.","type":"Poké-Body"}]','[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Big Explosion","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"Drifloon does 50 damage to itself."}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]',NULL,NULL,'[425]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-SH2','Duskull','Pokémon','SH2','Rare','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/SH2.png","large":"https://images.pokemontcg.io/dp7/SH2_hires.png"}',NULL,'60','18','["Basic"]','["Psychic"]',NULL,'["Dusclops"]',NULL,'[{"name":"Counting Song","cost":[],"convertedEnergyCost":0,"damage":"","text":"Put up to 3 damage counters on Duskull. Then, put that many damage counters on the Defending Pokémon."},{"name":"Ram","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Night Bind","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, your opponent can''t attach any Energy cards from his or her hand to the Active Pokémon during his or her next turn."}]','[{"type":"Darkness","value":"+10"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[355]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dp7-SH3','Voltorb','Pokémon','SH3','Rare','Kent Kanetsuna',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dp7/SH3.png","large":"https://images.pokemontcg.io/dp7/SH3_hires.png"}',NULL,'60','33','["Basic"]','["Lightning"]',NULL,'["Electrode"]',NULL,'[{"name":"Fastball","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon. Flip a coin. If heads, this attack does 20 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Charge Beam","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Search your discard pile for a Lightning Energy card and attach it to Voltorb."},{"name":"Thundershock","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"+10"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[100]',NULL,NULL,'dp7');
INSERT INTO "Card" VALUES('dpp-DP01','Turtwig','Pokémon','DP01','Promo','Masakazu Fukuda','Made from soil, the shell on its back hardens when it drinks water. It lives along lakes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP01.png","large":"https://images.pokemontcg.io/dpp/DP01_hires.png"}',NULL,'60','10','["Basic"]','["Grass"]',NULL,'["Grotle"]',NULL,'[{"name":"Tackle","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Razor Leaf","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[387]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP02','Chimchar','Pokémon','DP02','Promo','Kagemaru Himeno','It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP02.png","large":"https://images.pokemontcg.io/dpp/DP02_hires.png"}',NULL,'50','8','["Basic"]','["Fire"]',NULL,'["Monferno"]',NULL,'[{"name":"Scratch","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Ember","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, discard a Fire Energy attached to Chimchar."}]','[{"type":"Water","value":"+10"}]',NULL,'["Colorless"]',1,'[390]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP03','Piplup','Pokémon','DP03','Promo','Atsuko Nishida','Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP03.png","large":"https://images.pokemontcg.io/dpp/DP03_hires.png"}',NULL,'60','9','["Basic"]','["Water"]',NULL,'["Prinplup"]',NULL,'[{"name":"Peck","cost":[],"convertedEnergyCost":0,"damage":"10","text":""},{"name":"Water Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[393]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP04','Pachirisu','Pokémon','DP04','Promo','Atsuko Nishida','It makes fur balls that crackle with static electricity. It stores them with berries in tree holes.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP04.png","large":"https://images.pokemontcg.io/dpp/DP04_hires.png"}',NULL,'70','23','["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Minor Errand-Running","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."},{"name":"Thunder Jolt","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, Pachirisu does 10 damage to itself."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[417]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP05','Tropical Wind','Trainer','DP05','Promo','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP05.png","large":"https://images.pokemontcg.io/dpp/DP05_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, remove 2 damage counters from each Active Pokémon (remove 1 damage counter if a Pokémon has only 1). If tails, each Active Pokémon is now Asleep."]','dpp');
INSERT INTO "Card" VALUES('dpp-DP06','Buneary','Pokémon','DP06','Promo','Kagemaru Himeno','It slams foes by sharply uncoiling its rolled ears. It stings enough to make a grown-up cry in pain.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP06.png","large":"https://images.pokemontcg.io/dpp/DP06_hires.png"}',NULL,'50','11','["Basic"]','["Colorless"]',NULL,'["Lopunny"]',NULL,'[{"name":"Splash","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Jump Kick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Does 10 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[427]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP07','Cranidos','Pokémon','DP07','Promo','Mitsuhiro Arita','It lived in jungles around 100 million years ago. Its skull is as hard as iron.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP07.png","large":"https://images.pokemontcg.io/dpp/DP07_hires.png"}',NULL,'70','24','["Stage 1"]','["Fighting"]','Skull Fossil','["Rampardos"]',NULL,'[{"name":"Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Steamroll","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless"]',1,'[408]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP08','Shieldon','Pokémon','DP08','Promo','Kouki Saitou','A Pokémon that lived in jungles around 100 million years ago. Its facial hide is extremely hard.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP08.png","large":"https://images.pokemontcg.io/dpp/DP08_hires.png"}',NULL,'80','26','["Stage 1"]','["Metal"]','Armor Fossil','["Bastiodon"]',NULL,'[{"name":"Hard Face","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"During your opponent''s next turn, any damage done to Shieldon by attacks is reduced by 20 (after applying Weakness and Resistance)."},{"name":"Shield Attack","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"Flip a coin. If heads, this attack does 40 damage plus 20 more damage."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[410]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP09','Torterra LV.X','Pokémon','DP09','Promo','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP09.png","large":"https://images.pokemontcg.io/dpp/DP09_hires.png"}',NULL,'160','X','["Level-Up"]','["Grass"]','Torterra',NULL,'[{"name":"Forest Murmurs","text":"Once during your turn (before your attack), if you have more Prize cards left than your opponent, you may choose 1 of your opponent''s Benched Pokémon and switch it with 1 of the Defending Pokémon. This power can''t be used if Torterra is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Vigorous Dash","cost":["Grass","Grass","Grass","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Does 30 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) Torterra does 30 damage to itself."}]','[{"type":"Fire","value":"+30"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[389]',NULL,'["Put this card onto your Active Torterra. Torterra LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dpp');
INSERT INTO "Card" VALUES('dpp-DP10','Infernape LV.X','Pokémon','DP10','Promo','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP10.png","large":"https://images.pokemontcg.io/dpp/DP10_hires.png"}',NULL,'120','X','["Level-Up"]','["Fire"]','Infernape',NULL,'[{"name":"Burning Head","text":"Once during your turn (before your attack), you may look at the top 3 cards of your deck, choose 1 of them, and put it into your hand. Discard the other 2 cards. This power can''t be used if Infernape is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Flare Up","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"150","text":"Search your discard pile for 8 Fire Energy cards, show them to your opponent, and shuffle them into your deck. (This attack does nothing if you don''t have 8 Fire Energy cards in your discard pile.)"}]','[{"type":"Water","value":"+30"}]',NULL,NULL,NULL,'[392]',NULL,'["Put this card onto your Active Infernape. Infernape LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dpp');
INSERT INTO "Card" VALUES('dpp-DP11','Empoleon LV.X','Pokémon','DP11','Promo','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP11.png","large":"https://images.pokemontcg.io/dpp/DP11_hires.png"}',NULL,'140','X','["Level-Up"]','["Water"]','Empoleon',NULL,'[{"name":"Supreme Command","text":"Once during your turn (before your attack), you may choose up to 2 cards from your opponent''s hand without looking and put them face down next to the Defending Pokémon. (These cards are not in play or in your opponent''s hand.) At the end of your opponent''s next turn, return those cards to your opponent''s hand. This power can''t be used if Empoleon is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Hydro Impact","cost":["Water","Water","Water"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 80 damage to that Pokémon (Don''t apply Weakness and Resistance for Benched Pokémon.) Empoleon can''t attack during your next turn."}]','[{"type":"Lightning","value":"+30"}]',NULL,'["Colorless","Colorless"]',2,'[395]',NULL,'["Put this card onto your Active Empoleon. Empoleon LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dpp');
INSERT INTO "Card" VALUES('dpp-DP12','Lucario LV.X','Pokémon','DP12','Promo','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP12.png","large":"https://images.pokemontcg.io/dpp/DP12_hires.png"}',NULL,'110','X','["Level-Up"]','["Fighting"]','Lucario',NULL,'[{"name":"Stance","text":"Once during your turn (before your attack), when you put Lucario LV.X from your hand onto your Active Lucario, you may use this power. Prevent all effects of an attack, including damage, done to Lucario during your opponent''s next turn. (If Lucario is no longer your Active Pokémon, this effect ends.)","type":"Poké-Power"}]','[{"name":"Close Combat","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"During your opponent''s next turn, any damage done to Lucario by attacks is increased by 30 (after applying Weakness and Resistance)."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[448]',NULL,'["Put this card onto your Active Lucario. Lucario LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','dpp');
INSERT INTO "Card" VALUES('dpp-DP13','Buizel','Pokémon','DP13','Promo','Mitsuhiro Arita','It has a flotation sac that is like an inflatable collar. It floats on water with its head out.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP13.png","large":"https://images.pokemontcg.io/dpp/DP13_hires.png"}',NULL,'60','10','["Basic"]','["Water"]',NULL,'["Floatzel"]',NULL,'[{"name":"Splash About","cost":["Water"],"convertedEnergyCost":1,"damage":"10+","text":"If Buizel has less Energy attached to it than the Defending Pokémon, this attack does 10 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[418]',NULL,NULL,'dpp');
