INSERT INTO "Card" VALUES('dpp-DP43','Probopass G','Pokémon','DP43','Promo','Ryota Saito',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP43.png","large":"https://images.pokemontcg.io/dpp/DP43_hires.png"}',NULL,'90','53','["Basic","SP"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Nose Unit","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 20 damage to each of your opponent''s Pokémon that has any Poké-Bodies. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Loud Snort","cost":["Metal","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"70","text":"Probopass G''s Retreat Cost is 0 until the end of your next turn."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[476]',NULL,NULL,'dpp');
INSERT INTO "Card" VALUES('dpp-DP44','Magnezone','Pokémon','DP44','Promo','Kagemaru Himeno','It evolved from exposure to a special magnetic field. Three units generate magnetism.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP44.png","large":"https://images.pokemontcg.io/dpp/DP44_hires.png"}',NULL,'130','53','["Stage 2"]','["Lightning"]','Magneton',NULL,NULL,'[{"name":"Charge Beam","cost":["Lightning"],"convertedEnergyCost":1,"damage":"30","text":"Search your discard pile for an Energy card and attach it to Magnezone."},{"name":"Metallic Bolt","cost":["Lightning","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"You may discard a Lightning Energy and a Metal Energy attached to Magnezone. If you do, this attack''s base damage is 120 instead of 60."}]','[{"type":"Fighting","value":"+30"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[462]',NULL,NULL,'dpp');
