INSERT INTO "Card" VALUES('dpp-DP55','Ultimate Zone','Trainer','DP55','Promo','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/dpp/DP55.png","large":"https://images.pokemontcg.io/dpp/DP55_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","During each player''s turn, the player may move an Energy card attached to 1 of his or her Benched Pokémon to his or her Active Arceus as often as he or she likes."]','dpp');
