INSERT INTO "Card" VALUES('dv1-1','Dratini','Pokémon','1','Rare Holo','Masakazu Fukuda','It is called the "Mirage Pokémon" because so few have seen it. Its shed skin has been found.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/dv1/1.png","large":"https://images.pokemontcg.io/dv1/1_hires.png"}',NULL,'40',NULL,'["Basic"]','["Dragon"]',NULL,'["Dragonair"]',NULL,'[{"name":"Wrap","cost":["Grass","Lightning"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Dragon","value":"×2"}]',NULL,'["Colorless"]',1,'[147]',NULL,NULL,'dv1');
