INSERT INTO "Card" VALUES('ecard1-137','Bill''s Maintenance','Trainer','137','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard1/137.png","large":"https://images.pokemontcg.io/ecard1/137_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","If you have any cards in your hand, shuffle 1 of them into your deck, then draw 3 cards."]','ecard1');
INSERT INTO "Card" VALUES('ecard1-138','Copycat','Trainer','138','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard1/138.png","large":"https://images.pokemontcg.io/ecard1/138_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck. Then, count the number of cards in your opponent''s hand and draw that many cards."]','ecard1');
INSERT INTO "Card" VALUES('ecard1-139','Dual Ball','Trainer','139','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard1/139.png","large":"https://images.pokemontcg.io/ecard1/139_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. For each heads, search your deck for a Basic Pokémon card other than a Baby Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ecard1');
INSERT INTO "Card" VALUES('ecard1-140','Energy Removal 2','Trainer','140','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard1/140.png","large":"https://images.pokemontcg.io/ecard1/140_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, choose 1 Energy card attached to 1 of your opponent''s Pokémon and discard it."]','ecard1');
INSERT INTO "Card" VALUES('ecard1-141','Energy Restore','Trainer','141','Uncommon','Hideyuki Nakajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard1/141.png","large":"https://images.pokemontcg.io/ecard1/141_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 3 coins. For each heads, put a Basic Energy card from your discard pile into your hand. If you don''t have that many basic Energy cards in your discard pile, put all of them into your hand."]','ecard1');
