INSERT INTO "Card" VALUES('ecard2-3','Ariados','Pokémon','3','Rare','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/3.png","large":"https://images.pokemontcg.io/ecard2/3_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Spinarak',NULL,'[{"name":"Gluey Slime","text":"As long as Ariados is in play, each player must pay an additional Colorless to retreat his or her Active Pokémon. Gluey Slime can''t make a player pay more than an additional Colorless to retreat a Pokémon, even if there is more than 1 Ariados in play.","type":"Poké-Body"}]','[{"name":"Spider Force","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 10 more damage. If tails, this attack does 20 damage and the Defending Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[168]',NULL,NULL,'ecard2');
