INSERT INTO "Card" VALUES('ecard2-122','Fire Cube 01','Trainer','122','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/122.png","large":"https://images.pokemontcg.io/ecard2/122_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Singe","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Burned."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Fire Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Fire Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-123','Forest Guardian','Trainer','123','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/123.png","large":"https://images.pokemontcg.io/ecard2/123_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your deck. Then, look at the top 7 cards of your deck. Choose 1 of those cards and put it into your hand. Shuffle the rest into your deck afterward."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-124','Grass Cube 01','Trainer','124','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/124.png","large":"https://images.pokemontcg.io/ecard2/124_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Sleep Poison","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Asleep and Poisoned."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Grass Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Grass Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-125','Healing Berry','Trainer','125','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/125.png","large":"https://images.pokemontcg.io/ecard2/125_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Healing Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool card attached to it. If that Pokémon is Knocked Out, discard this card.","At the end of any turn, if the Pokémon this card is attached to has 20 HP or less, remove 3 damage counters from that Pokémon and discard this card."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-126','Juggler','Trainer','126','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/126.png","large":"https://images.pokemontcg.io/ecard2/126_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard up to 2 basic Energy cards from your hand. If you discarded 1 basic Energy card, draw 3 cards. If you discarded 2 basic Energy cards, draw 5 cards."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-127','Lightning Cube 01','Trainer','127','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/127.png","large":"https://images.pokemontcg.io/ecard2/127_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Discharge","cost":["Lightning"],"convertedEnergyCost":1,"damage":"40×","text":"Discard all Lightning Energy cards attached to this Pokémon. Then, flip a number of coins equal to the number of Energy cards discarded that way. This attack does 40 damage times the number of heads."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Lightning Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Lightning Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-128','Memory Berry','Trainer','128','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/128.png","large":"https://images.pokemontcg.io/ecard2/128_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Memory Berry to 1 of your Pokémon that doesn''t have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","The Pokémon this card is attached to can use any attack from its Basic Pokémon card or any Evolution card from which the Pokémon evolved. (You still have to pay for that attack''s Energy cost.) Discard this card at the end of any turn the Pokémon attacks."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-129','Metal Cube 01','Trainer','129','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/129.png","large":"https://images.pokemontcg.io/ecard2/129_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Metal Reversal","cost":["Metal"],"convertedEnergyCost":1,"damage":"10","text":"Before doing damage, you may choose 1 of your opponent''s Benched Pokémon and switch it with the Defending Pokémon."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Metal Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Metal Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-130','Pokémon Fan Club','Trainer','130','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/130.png","large":"https://images.pokemontcg.io/ecard2/130_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 Baby Pokémon and/or Basic Pokémon cards and put them onto your bench. Shuffle your deck afterward."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-131','Pokémon Park','Trainer','131','Uncommon','Kazuo Yazawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/131.png","large":"https://images.pokemontcg.io/ecard2/131_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each of his or her turns, whenever a player attaches an Energy card from his or her hand to 1 of his or her Benched Pokémon, he or she removes 1 damage counter, if any, from that Pokémon."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-132','Psychic Cube 01','Trainer','132','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/132.png","large":"https://images.pokemontcg.io/ecard2/132_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Psy Confuse","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Confused."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Psychic Pokémon in play. That Pokémon may us this card''s attack instead of its own. At the end of your turn, discard Psychic Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-133','Seer','Trainer','133','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/133.png","large":"https://images.pokemontcg.io/ecard2/133_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at the top 6 cards of your deck. Take all Basic Energy cards you find there, show them to your opponent, and then put them into your hand. Shuffle your deck afterward."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-134','Super Energy Removal 2','Trainer','134','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/134.png","large":"https://images.pokemontcg.io/ecard2/134_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. If both are heads, discard all Energy cards attached to the Defending Pokémon. If both are tails, discard all Energy cards attached to your Active Pokémon. If 1 is heads and 1 is tails, this card does nothing."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-135','Time Shard','Trainer','135','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/135.png","large":"https://images.pokemontcg.io/ecard2/135_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Time Shard to 1 of your Pokémon that doesn''t already have a Pokémon Tool card attached to it. If that Pokémon is Knocked Out, discard this card.","If the Pokémon this card is attached to is Knocked Out by damage from the Defending Pokémon''s attack during your opponent''s turn, you may return up to 2 basic Energy cards attached to that Pokémon to your hand."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-136','Town Volunteers','Trainer','136','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/136.png","large":"https://images.pokemontcg.io/ecard2/136_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Take 5 Baby Pokémon, Basic Pokémon, Evolution, and/or basic Energy cards from your discard pile and then show them to your opponent. Shuffle them into your deck."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-137','Traveling Salesman','Trainer','137','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/137.png","large":"https://images.pokemontcg.io/ecard2/137_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 Technical Machine and/or Pokémon Tool cards, show them to your opponent, and then put them into your hand. Shuffle your deck afterward."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-138','Undersea Ruins','Trainer','138','Uncommon','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/138.png","large":"https://images.pokemontcg.io/ecard2/138_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may flip a coin. If heads, that player chooses 1 of his or her Evolved Pokémon in play and discards the top Evolution card from that Pokémon, devolving it."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-139','Power Plant','Trainer','139','Uncommon','Kai Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/139.png","large":"https://images.pokemontcg.io/ecard2/139_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each of his or her turns, a player may discard a basic Energy card from his or her hand. If that player does, he or she chooses a basic Energy card from his or her discard pile, shows it to his or her opponent, and then puts it into his or her hand."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-140','Water Cube 01','Trainer','140','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/140.png","large":"https://images.pokemontcg.io/ecard2/140_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Splatter","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 20 damage to that Pokémon. Don''t apply Weakness or Resistance."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Water Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Water Cube 01."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-141','Weakness Guard','Trainer','141','Uncommon','Jungo Suzuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/141.png","large":"https://images.pokemontcg.io/ecard2/141_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon. Discard it at the end of your opponent''s next turn.","As long as this card is attached, this Pokémon has no Weakness."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-142','Darkness Energy','Energy','142','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/142.png","large":"https://images.pokemontcg.io/ecard2/142_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to damages the Defending Pokémon (after applying Weakness and Resistance), the attack does 10 more damage to the Defending Pokémon. At the end of every turn, put 1 damage counter on the Pokémon Darkness Energy is attached to, unless it''s Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','ecard2');
INSERT INTO "Card" VALUES('ecard2-143','Metal Energy','Energy','143','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/143.png","large":"https://images.pokemontcg.io/ecard2/143_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done to the Pokémon Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). If the Pokémon Metal Energy is attached to isn''t Metal, whenever it damages a Pokémon, reduce that damage by 10 (before applying Weakness and Resistance). Metal Energy provides Metal Energy. (Doesn''t count as a basic Energy card.)"]','ecard2');
INSERT INTO "Card" VALUES('ecard2-144','Rainbow Energy','Energy','144','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/144.png","large":"https://images.pokemontcg.io/ecard2/144_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Rainbow Energy to 1 of your Pokémon. While in play, Rainbow Energy provides every type of Energy but provides only 1 Energy at a time. (Doesn''t count as a basic Energy card when not in play.) When you attach this card from your hand to 1 of your Pokémon, put 1 damage counter on that Pokémon."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-145','Boost Energy','Energy','145','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/145.png","large":"https://images.pokemontcg.io/ecard2/145_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Boost Energy can be attached only to an Evolved Pokémon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides ColorlessColorlessColorless Energy. The Pokémon Boost Energy is attached to can''t retreat. When the Pokémon Boost Energy is attached to is no longer an Evolved Pokémon, discard Boost Energy."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-146','Crystal Energy','Energy','146','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/146.png","large":"https://images.pokemontcg.io/ecard2/146_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Crystal Energy provides 1 Energy of all types (colors) of basic Energy cards attached to the Pokémon Crystal Energy is attached to. If there are no basic Energy cards attached to the Pokémon Crystal Energy is attached to, Crystal Energy provides Colorless Energy."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-147','Warp Energy','Energy','147','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/147.png","large":"https://images.pokemontcg.io/ecard2/147_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Warp Energy provides 1 Colorless Energy. When you attach Warp Energy from your hand to your Active Pokémon, switch your Active Pokémon with 1 of your Benched Pokémon."]','ecard2');
INSERT INTO "Card" VALUES('ecard2-148','Kingdra','Pokémon','148','Rare Secret','Mikio Menjo',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/148.png","large":"https://images.pokemontcg.io/ecard2/148_hires.png"}',NULL,'110',NULL,'["Stage 2"]','["Colorless"]','Seadra',NULL,'[{"name":"Crystal Type","text":"Whenever you attach a Water, Lightning, or Psychic basic Energy card from your hand to Kingdra, Kingdra''s type (color) becomes the same as that Energy card type until the end of the turn.","type":"Poké-Body"}]','[{"name":"Aquabomb","cost":["Water","Water","Lightning"],"convertedEnergyCost":3,"damage":"40","text":"Kingdra does 10 damage to itself. (Don''t apply Weakness or Resistance when Kingdra damages itself with this attack.)"},{"name":"Dual Burn","cost":["Psychic","Psychic","Lightning","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"Flip 2 coins. For each tails, discard 1 Energy card attached to Kingdra."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[230]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-149','Lugia','Pokémon','149','Rare Secret','Naoyo Kimura',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/149.png","large":"https://images.pokemontcg.io/ecard2/149_hires.png"}',NULL,'80',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Crystal Type","text":"Whenever you attach a Fire, Water, or Psychic basic Energy card from your hand to Lugia, Lugia''s type (color) becomes the same as that Energy card type until the end of the turn.","type":"Poké-Body"}]','[{"name":"Psychic","cost":["Psychic","Fire"],"convertedEnergyCost":2,"damage":"10×","text":"This attack does 10 damage times the number of Energy cards attached to the Defending Pokémon."},{"name":"Steam Blast","cost":["Water","Water","Fire","Colorless"],"convertedEnergyCost":4,"damage":"50","text":"Discard an Energy card attached to Lugia."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[249]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-150','Nidoking','Pokémon','150','Rare Secret','Hironobu Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/150.png","large":"https://images.pokemontcg.io/ecard2/150_hires.png"}',NULL,'100',NULL,'["Stage 2"]','["Colorless"]','Nidorino',NULL,'[{"name":"Crystal Type","text":"Whenever you attach a Grass, Lightning, or Fire basic Energy card from your hand to Nidoking, Nidoking''s type (color) becomes the same as that Energy card type until the end of the turn.","type":"Poké-Body"}]','[{"name":"Poison Horn","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"The Defending Pokémon is now Poisoned."},{"name":"Rolling Thunder","cost":["Lightning","Lightning","Fighting","Fighting"],"convertedEnergyCost":4,"damage":"50","text":"Flip a coin, If heads, this attack does 10 damage to each of your opponent''s Benched Pokémon. If tails, this attack does 10 damage to each of your Benched Pokémon. (Don''t apply Weakness or Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[34]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H1','Ampharos','Pokémon','H1','Rare Holo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H1.png","large":"https://images.pokemontcg.io/ecard2/H1_hires.png"}',NULL,'100',NULL,'["Stage 2"]','["Lightning"]','Flaaffy',NULL,NULL,'[{"name":"Thundershock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Reflect Energy","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"If you have any Benched Pokémon and if there are any basic Energy cards attached to Ampharos, take 1 of those Energy cards and attach it to 1 of those Pokémon."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[181]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H2','Arcanine','Pokémon','H2','Rare Holo','Kyoko Umemoto',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H2.png","large":"https://images.pokemontcg.io/ecard2/H2_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fire"]','Growlithe',NULL,'[{"name":"Extreme Speed","text":"You pay Colorless less to retreat Arcanine for each Energy attached to it.","type":"Poké-Body"}]','[{"name":"Fire Blow","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"You may discard any number of Fire Energy cards attached to Arcanine when you use this attack. If you do, flip a number of coins equal to the number of Fire Energy cards you discarded. This attack does 30 damage plus 30 more damage for each heads."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[59]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H3','Ariados','Pokémon','H3','Rare Holo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H3.png","large":"https://images.pokemontcg.io/ecard2/H3_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Spinarak',NULL,'[{"name":"Gluey Slime","text":"As long as Ariados is in play, each player must pay an additional Colorless to retreat his or her Active Pokémon. Gluey Slime can''t make a player pay more than an additional Colorless to retreat a Pokémon, even if there is more than 1 Ariados in play.","type":"Poké-Body"}]','[{"name":"Spider Force","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 10 more damage. If tails, this attack does 20 damage and the defending Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[168]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H4','Azumarill','Pokémon','H4','Rare Holo','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H4.png","large":"https://images.pokemontcg.io/ecard2/H4_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Water"]','Marill',NULL,'[{"name":"Bubble Turn","text":"Once during your turn (before your attack), if Azumarill is on your Bench, you may flip a coin. If heads, return Azumarill and all cards attached to it to your hand.","type":"Poké-Power"}]','[{"name":"Aqua Sonic","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Don''t apply Resistance."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[184]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H5','Bellossom','Pokémon','H5','Rare Holo','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H5.png","large":"https://images.pokemontcg.io/ecard2/H5_hires.png"}',NULL,'90',NULL,'["Stage 2"]','["Grass"]','Gloom',NULL,'[{"name":"Flower Supplement","text":"Once during your turn (before your attack), you may flip a coin. If heads, attach 1 basic Energy card from your hand to 1 of your Benched Pokémon. This power can''t be used if Bellossom is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Knife Leaf","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"30×","text":"Flip 3 coins. This attack does 30 damage times the number of heads."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-30"}]','["Colorless","Colorless"]',2,'[182]',NULL,NULL,'ecard2');
