INSERT INTO "Card" VALUES('ecard2-H15','Lanturn','Pokémon','H15','Rare Holo','Yuka Morii',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H15.png","large":"https://images.pokemontcg.io/ecard2/H15_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Lightning"]','Chinchou',NULL,'[{"name":"Ion Coating","text":"You may use this power once during each of your turns (before your attack). All Lightning Energy attached to your Active Pokémon becomes Water Energy for the rest of the turn. (This effect ends if your Active Pokémon retreats or is returned to your hand.) This power can''t be used if Lanturn is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Electric Tackle","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"This attack does 20 damage plus 10 damage for each Lightning Energy attached to Lanturn. Flip a coin. If tails, Lanturn does 10 damage to itself for each Lightning Energy attached to it."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[171]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H16','Magneton','Pokémon','H16','Rare Holo','Hikaru Koike',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H16.png","large":"https://images.pokemontcg.io/ecard2/H16_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Metal"]','Magnemite','["Magnezone"]','[{"name":"Magnetic Flow","text":"Once during your turn (before your attack), if Magneton is your Active Pokémon, you may flip a coin. If heads, choose 2 of your opponent''s Pokémon that have Energy cards attached to them. Choose 1 of the Energy cards attached to each of those Pokémon and switch them between the Pokémon. This power can''t be used if Magneton is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Steel Wave","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"This attack does 10 damage to each of your opponent''s Benched Pokémon that are the same type (color) as the Defending Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless"]',2,'[82]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H17','Muk','Pokémon','H17','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H17.png","large":"https://images.pokemontcg.io/ecard2/H17_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Grimer',NULL,'[{"name":"Heavyweight","text":"As long as there is a Grass Energy attached to Muk, you must pay an additional ColorlessColorless to retreat it.","type":"Poké-Body"}]','[{"name":"Burning Sludge","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Flip a number of coins equal to the amount of Grass Energy attached to Muk. If any of them are heads, the Defending Pokémon is now Poisoned and Burned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[89]',NULL,NULL,'ecard2');
