INSERT INTO "Card" VALUES('ecard2-H23','Steelix','Pokémon','H23','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H23.png","large":"https://images.pokemontcg.io/ecard2/H23_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Metal"]','Onix',NULL,NULL,'[{"name":"Earth Rift","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"This attack does 10 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness or Resistance for Benched Pokémon.) Then, flip a coin. If tails, this attack can''t be used during your next turn."},{"name":"Iron Smash","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"50+","text":"Flip 2 coins. If both are heads, this attack does 50 damage plus 20 more damage. If both are tails, this attack does nothing. If 1 is heads and 1 is tails, this attack just does 50 damage."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H24','Sudowoodo','Pokémon','H24','Rare Holo','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H24.png","large":"https://images.pokemontcg.io/ecard2/H24_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Copy","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of the Defending Pokémon''s attacks. Copy copies that attack. This attack does nothing if Sudowoodo doesn''t have the Energy necessary to use that attack. (You must still do anything else required in order to use that attack.)"},{"name":"Energy Draw","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a basic Energy card and attach it to Sudowoodo. Shuffle your deck afterward."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[185]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H25','Suicune','Pokémon','H25','Rare Holo','Atsuko Nishida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H25.png","large":"https://images.pokemontcg.io/ecard2/H25_hires.png"}',NULL,'70',NULL,'["Basic"]','["Water"]',NULL,NULL,'[{"name":"Pure Body","text":"To attach a Water Energy card from your hand to Suicune, you must discard an Energy card attached to Suicune. (Attach the Water Energy, and then discard an Energy card from Suicune.)","type":"Poké-Body"}]','[{"name":"Hypno Wave","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 20 more damage. If tails, this attack does 30 damage and the Defending Pokémon is now Asleep."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[245]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H26','Tentacruel','Pokémon','H26','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H26.png","large":"https://images.pokemontcg.io/ecard2/H26_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Water"]','Tentacool',NULL,'[{"name":"Strange Tentacles","text":"Once during your turn (before your attack), as long as the number of Energy cards attached to the Defending Pokémon is less than the number of Energy cards attached to your Active Pokémon, you may choose an Energy card, if any, in your opponent''s discard pile and attach it to the Defending Pokémon. This power can''t be used if Tentacruel is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Poison Sting","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Lightning","value":"×2"}]',NULL,NULL,NULL,'[73]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H27','Togetic','Pokémon','H27','Rare Holo','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H27.png","large":"https://images.pokemontcg.io/ecard2/H27_hires.png"}',NULL,'60',NULL,'["Stage 1"]','["Colorless"]','Togepi','["Togekiss"]','[{"name":"Miracle Shift","text":"Once during your turn (before your attack), discard a basic Energy card attached to 1 of your Pokémon. Then, choose a basic Energy card from your discard pile and attach it to that Pokémon. This power can''t be used if Togetic is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Mini-Metronome","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, choose 1 of the Defending Pokémon''s attacks. Mini-Metronome copies that attack except for its Energy cost. (You must still do anything else required in order to use that attack.) (No matter what type the Defending Pokémon is, Togetic is still Colorless.) Togetic performs that attack."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[176]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H28','Tyranitar','Pokémon','H28','Rare Holo','Naoyo Kimura',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H28.png","large":"https://images.pokemontcg.io/ecard2/H28_hires.png"}',NULL,'120',NULL,'["Stage 2"]','["Darkness"]','Pupitar',NULL,NULL,'[{"name":"Destructive Roar","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, discard 1 Energy card attached to 1 of your opponent''s Pokémon."},{"name":"Tail Slap","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""},{"name":"Gigacrush","cost":["Darkness","Darkness","Colorless","Colorless","Colorless"],"convertedEnergyCost":5,"damage":"60","text":"Each player discards the top 3 cards from his or her deck."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[248]',NULL,NULL,'ecard2');
INSERT INTO "Card" VALUES('ecard2-H29','Umbreon','Pokémon','H29','Rare Holo','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard2/H29.png","large":"https://images.pokemontcg.io/ecard2/H29_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Darkness"]','Eevee',NULL,'[{"name":"Dark Moon","text":"As long as Umbreon is your Active Pokémon and has a Darkness Energy attached to it, once during your turn (before your attack), you may look at your opponent''s hand. Choose from it a number of cards up to the number of Darkness Energy attached to Umbreon and shuffle them into your opponent''s deck. Your opponent then draws the same number of cards from his or her deck. This power can''t be used if Umbreon is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Shadow Bind","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[197]',NULL,NULL,'ecard2');
