INSERT INTO "Card" VALUES('ecard3-19','Magneton','Pokémon','19','Rare','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/19.png","large":"https://images.pokemontcg.io/ecard3/19_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Lightning"]','Magnemite','["Magnezone"]','[{"name":"Attract Energy","text":"When you play Magneton from your hand to evolve 1 of your Pokémon, you may move any number of basic Energy cards attached to your other Pokémon to Magneton.","type":"Poké-Power"}]','[{"name":"Electric Blast","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"You may discard all Lightning Energy cards attached to Magneton when you use this attack. If you do, put damage counters equal to the amount of Energy cards removed in this way on any number of your opponent''s Benched Pokémon in the way you like. (For example, if you discard 3 Lightning Energy cards, you can put 1 damage counter on 1 of your opponent''s Benched Pokémon and 2 on another.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[82]',NULL,NULL,'ecard3');
