INSERT INTO "Card" VALUES('ecard3-111','Venomoth','Pokémon','111','Common','Yukiko Baba',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/111.png","large":"https://images.pokemontcg.io/ecard3/111_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Venonat',NULL,NULL,'[{"name":"Healing Dust","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip 2 coins. For each heads, remove 1 damage counter from each of your Pokémon. If a Pokémon has fewer damage counters than the number of heads, remove all of them."},{"name":"Miracle Powder","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin. If heads, choose a Special Condition (Asleep, Burned, Confused, Paralyzed, or Poisoned). The Defending Pokémon is now affected by that Special Condition."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[49]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-112','Venonat','Pokémon','112','Common','Tomokazu Komiya',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/112.png","large":"https://images.pokemontcg.io/ecard3/112_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Venomoth"]',NULL,'[{"name":"Double Spin","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."},{"name":"Supersonic","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[48]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-113','Voltorb','Pokémon','113','Common','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/113.png","large":"https://images.pokemontcg.io/ecard3/113_hires.png"}',NULL,'50',NULL,'["Basic"]','["Lightning"]',NULL,'["Electrode"]',NULL,'[{"name":"Magnetic Pull","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has any Benched Pokémon, choose 1 of them and switch it with the Defending Pokémon."},{"name":"Spin Tackle","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Voltorb does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[100]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-114','Weedle','Pokémon','114','Common','Keiko Fukuyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/114.png","large":"https://images.pokemontcg.io/ecard3/114_hires.png"}',NULL,'40',NULL,'["Basic"]','["Grass"]',NULL,'["Kakuna"]',NULL,'[{"name":"Fury Attack","cost":["Grass"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 3 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[13]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-115','Weedle','Pokémon','115','Common','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/115.png","large":"https://images.pokemontcg.io/ecard3/115_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Kakuna"]',NULL,'[{"name":"Entangling Thread","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Poison Horn","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[13]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-116','Yanma','Pokémon','116','Common','Miki Tanaka',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/116.png","large":"https://images.pokemontcg.io/ecard3/116_hires.png"}',NULL,'60',NULL,'["Basic"]','["Grass"]',NULL,'["Yanmega"]',NULL,'[{"name":"Agility","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all effects of attacks, including damage, done to Yanma."},{"name":"Triple Smash","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20+","text":"Flip 3 coins. This attack does 20 damage plus 10 more damage for each heads."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[193]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-117','Zubat','Pokémon','117','Common','Hisao Nakamura',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/117.png","large":"https://images.pokemontcg.io/ecard3/117_hires.png"}',NULL,'40',NULL,'["Basic"]','["Grass"]',NULL,'["Golbat"]',NULL,'[{"name":"Sound Waves","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."},{"name":"Flitter","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 10 damage to that Pokémon. Don''t apply Weakness and Resistance. (Any other effects that would happen after applying Weakness and Resistance still happen.)"}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[41]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-118','Zubat','Pokémon','118','Common','Kyoko Umemoto',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/118.png","large":"https://images.pokemontcg.io/ecard3/118_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Golbat"]',NULL,'[{"name":"Wing Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Poison Spray","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[41]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-119','Ancient Ruins','Trainer','119','Uncommon','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/119.png","large":"https://images.pokemontcg.io/ecard3/119_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before he or she attacks), if he or she has not played a Supporter card, that player may reveal his or her hand to his or her opponent. If that player reveals his or her hand and there is no Supporter card there, that player draws a card."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-120','Relic Hunter','Trainer','120','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/120.png","large":"https://images.pokemontcg.io/ecard3/120_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 Supporter and/or Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-121','Apricorn Maker','Trainer','121','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/121.png","large":"https://images.pokemontcg.io/ecard3/121_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 Trainer cards with Ball in their names, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-122','Crystal Shard','Trainer','122','Uncommon','Jungo Suzuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/122.png","large":"https://images.pokemontcg.io/ecard3/122_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Crystal Shard to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as this card is attached to a Pokémon, that Pokémon''s type (color) is Colorless. If that Pokémon attacks, discard this card at the end of the turn."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-123','Desert Shaman','Trainer','123','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/123.png","large":"https://images.pokemontcg.io/ecard3/123_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck and draw up to 4 cards. Your opponent does the same."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-124','Fast Ball','Trainer','124','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/124.png","large":"https://images.pokemontcg.io/ecard3/124_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal cards from your deck until you reveal an Evolution card. Show that card to your opponent and put it into your hand. Shuffle the other revealed cards into your deck. (If you don''t reveal an Evolution card, shuffle all the revealed cards back into your deck.)"]','ecard3');
INSERT INTO "Card" VALUES('ecard3-125','Fisherman','Trainer','125','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/125.png","large":"https://images.pokemontcg.io/ecard3/125_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Choose 4 basic Energy cards from your discard pile (if there are fewer basic Energy cards than choose, take all of them), show them to your opponent, and put them into your hand."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-126','Friend Ball','Trainer','126','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/126.png","large":"https://images.pokemontcg.io/ecard3/126_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your opponent''s Pokémon. Search your deck for a Baby Pokémon, Basic Pokémon, or Evolution card of the same type (color), show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-127','Hyper Potion','Trainer','127','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/127.png","large":"https://images.pokemontcg.io/ecard3/127_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon. Discard 1 or 2 basic Energy cards attached to that Pokémon. If you discarded 1 Energy card, remove up to 3 damage counters from that Pokémon. If you discarded 2 Energy cards, remove up to 5 damage counters from that Pokémon."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-128','Lure Ball','Trainer','128','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/128.png","large":"https://images.pokemontcg.io/ecard3/128_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 3 coins. For each heads, choose an Evolution card from your discard pile, show it to your opponent, and put it into your hand."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-129','Miracle Sphere α','Trainer','129','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/129.png","large":"https://images.pokemontcg.io/ecard3/129_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Fire Force","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"If the Pokémon using this attack has Fire and Lightning basic Energy cards attached to it, the Defending Pokémon is now Confused. If the Pokémon using this attack has Fire and Fighting basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and remove 3 damage counters from the Pokémon that Miracle Plate α is attached to."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Evolved Fire, Lightning, or Fighting Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Miracle Plate α."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-130','Miracle Sphere β','Trainer','130','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/130.png","large":"https://images.pokemontcg.io/ecard3/130_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Freezing Force","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"If the Pokémon using this attack has Fire and Water basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and the Defending Pokémon is now Burned. If the Pokémon using this attack has Water and Psychic basic Energy cards attached to it, choose an Energy card attached to the Defending Pokémon, if any, and your opponent shuffles that card into his or her deck."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Evolved Fire, Water, or Psychic Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Miracle Sphere β."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-131','Miracle Sphere γ','Trainer','131','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/131.png","large":"https://images.pokemontcg.io/ecard3/131_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Thunder Force","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"If the Pokémon using this attack has Grass and Lightning basic Energy cards attached to it, the Defending Pokémon is now Asleep and Poisoned. If the Pokémon using this attack has Water and Lightning basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and lets you put 1 damage counter on each of your opponent''s Benched Pokémon."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Evolved Grass, Water, or Lightning Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Miracle Sphere γ."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-132','Mirage Stadium','Trainer','132','Uncommon','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/132.png","large":"https://images.pokemontcg.io/ecard3/132_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Whenever a player tries to retreat a Pokémon during his or her turn, that player flips a coin. If heads, that player retreats that Pokémon (and discards Energy normally). If tails, that Pokémon can''t retreat this turn (the player doesn''t discard any Energy)."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-133','Mystery Plate α','Trainer','133','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/133.png","large":"https://images.pokemontcg.io/ecard3/133_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Desert Burn","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has 5 or more Prizes, search your deck for a Trainer card, show it to your opponent, and put it into your hand. If your opponent has only 1 Prize, the Defending Pokémon is now Burned, Paralyzed, and Poisoned."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Mystery Plate α."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-134','Mystery Plate β','Trainer','134','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/134.png","large":"https://images.pokemontcg.io/ecard3/134_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Stone Crush","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has 5 or more Prizes, draw 3 cards. If your opponent has only 1 Prize, choose 2 Energy cards attached to the Defending Pokémon (1 if there is only 1). Your opponent shuffles those cards into his or her deck."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Mystery Plate β."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-135','Mystery Plate γ','Trainer','135','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/135.png","large":"https://images.pokemontcg.io/ecard3/135_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Retro Cave","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has 5 or more Prizes, shuffle your hand into your deck and then draw 6 cards. If your opponent has exactly 2 Prizes, choose 1 of your opponent''s Evolved Pokémon. Your opponent puts the top card on that Evolved Pokémon on the bottom of his or her deck. (This counts as devolving that Pokémon.)"}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Mystery Plate γ."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-136','Mystery Plate δ','Trainer','136','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/136.png","large":"https://images.pokemontcg.io/ecard3/136_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Healing Oasis","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has 5 or more Prizes, search your deck for up to 3 basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. If your opponent has exactly 2 Prizes, remove all damage counters from 1 of your Pokémon."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon in play. That Pokémon may use this card''s attack instead of its own. At the end of your turn, discard Mystery Plate δ."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-137','Mystery Zone','Trainer','137','Uncommon','Ken Ikuji',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/137.png","large":"https://images.pokemontcg.io/ecard3/137_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before he or she attacks), if that player has an Evolution card in his or her hand, he or she may search his or her deck for a basic Energy card, show it to his or her opponent, and put it into his or her hand. Then that player chooses an Evolution card from his or her hand, shows it to his or her opponent, and puts it into his or her deck. That player shuffles his or her deck afterward."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-138','Oracle','Trainer','138','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/138.png","large":"https://images.pokemontcg.io/ecard3/138_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Choose 2 cards from your deck and shuffle the rest of your deck. Put the chosen cards on top of your deck in any order."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-139','Star Piece','Trainer','139','Uncommon','Jungo Suzuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/139.png","large":"https://images.pokemontcg.io/ecard3/139_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Star Piece to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","At any time between turns, if the Pokémon this card is attached to is Benched and has 2 or more damage counters on it, search your deck for an Evolution card that Pokémon evolves into and put it on top of that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward. Then, discard Star Piece."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-140','Underground Expedition','Trainer','140','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/140.png","large":"https://images.pokemontcg.io/ecard3/140_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at the bottom 4 cards of your deck. Put 2 of those cards into your hand, and then return the remaining cards to the bottom of your deck in any order."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-141','Underground Lake','Trainer','141','Uncommon','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/141.png","large":"https://images.pokemontcg.io/ecard3/141_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn, that player may put an Omanyte or a Kabuto card from his or her discard pile onto his or her Bench. (Cards put on the Bench this way are considered Basic Pokémon.)"]','ecard3');
INSERT INTO "Card" VALUES('ecard3-142','Bounce Energy','Energy','142','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/142.png","large":"https://images.pokemontcg.io/ecard3/142_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card provides ColorlessColorless Energy. You can attach this card to your Pokémon that has basic Energy cards attached to it. When you play this card from your hand and attach it to 1 of your Pokémon, return a basic Energy card attached to that Pokémon to your hand."]','ecard3');
INSERT INTO "Card" VALUES('ecard3-143','Cyclone Energy','Energy','143','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/143.png","large":"https://images.pokemontcg.io/ecard3/143_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card provides Colorless Energy. When you play this card from your hand and attach it to your Active Pokémon, your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon."]','ecard3');
