INSERT INTO "Card" VALUES('ecard3-145','Celebi','Pokémon','145','Rare Secret','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/145.png","large":"https://images.pokemontcg.io/ecard3/145_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Crystal Type","text":"Whenever you attach a Grass, Water, or Psychic basic Energy card from your hand to Celebi, Celebi''s type (color) becomes the same as that type of Energy until the end of the turn.","type":"Poké-Body"}]','[{"name":"Empathic Healing","cost":["Grass","Water"],"convertedEnergyCost":2,"damage":"","text":"Remove 2 damage counters from Celebi and each Pokémon that''s the same type (color) as Celebi."},{"name":"Mind Bend","cost":["Grass","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[251]',NULL,NULL,'ecard3');
