INSERT INTO "Card" VALUES('ecard3-H2','Arcanine','Pokémon','H2','Rare Holo','Aya Kusube',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H2.png","large":"https://images.pokemontcg.io/ecard3/H2_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fire"]','Growlithe',NULL,'[{"name":"Energy Recharge","text":"When you play Arcanine from your hand to evolve your Active Pokémon, you may flip 3 coins. For each heads, choose a basic Energy card from your discard pile and attach it to Arcanine.","type":"Poké-Power"}]','[{"name":"Shake","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any."},{"name":"White Flames","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Discard all Fire Energy cards attached to Arcanine."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[59]',NULL,NULL,'ecard3');
