INSERT INTO "Card" VALUES('ecard3-H5','Crobat','Pokémon','H5','Rare Holo','Kimiya Masago',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H5.png","large":"https://images.pokemontcg.io/ecard3/H5_hires.png"}',NULL,'90',NULL,'["Stage 2"]','["Grass"]','Golbat',NULL,'[{"name":"Carry Off","text":"Once during your turn (before your attack), you may flip a coin. If heads, look at your opponent''s hand. If your opponent has any Baby Pokémon, Basic Pokémon, or Evolution cards there, choose 1 of them. Your opponent shuffles that card into his or her deck. This power can''t be used if Crobat is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Double Cross","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40×","text":"Flip 2 coins. This attack does 40 damage times the number of heads. If both of them are tails, the Defending Pokémon is now Confused and Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,NULL,NULL,'[169]',NULL,NULL,'ecard3');
