INSERT INTO "Card" VALUES('ecard3-H14','Ledian','Pokémon','H14','Rare Holo','Hikaru Koike',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H14.png","large":"https://images.pokemontcg.io/ecard3/H14_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Ledyba',NULL,NULL,'[{"name":"Pollen Shield","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"During your opponent''s next turn, Ledian can''t become affected by a Special Condition. (Any other effects of attacks, Poké-Powers, Poké-Bodies, and Trainer cards still happen.)"},{"name":"Swift","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"This attack''s damage isn''t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[166]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-H15','Machamp','Pokémon','H15','Rare Holo','Naoyo Kimura',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H15.png","large":"https://images.pokemontcg.io/ecard3/H15_hires.png"}',NULL,'120',NULL,'["Stage 2"]','["Fighting"]','Machoke',NULL,'[{"name":"Immunity","text":"Prevent all effects of your opponent''s attacks done to Machamp.","type":"Poké-Body"}]','[{"name":"Drag Off","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Before doing damage, if your opponent has any Benched Pokémon, choose 1 of them and switch it with the Defending Pokémon. If your opponent has no Benched Pokémon, ignore this effect."},{"name":"Hurricane Punch","cost":["Fighting","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"30×","text":"Flip 4 coins. This attack does 30 damage times the number of heads."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[68]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-H16','Magcargo','Pokémon','H16','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H16.png","large":"https://images.pokemontcg.io/ecard3/H16_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fire"]','Slugma',NULL,NULL,'[{"name":"Eruption","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Each player discard the top card of his or her deck. This attack does 20 damage plus 20 more damage for each Fire Energy card discarded in this way."},{"name":"Fire Stream","cost":["Fire","Fire","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"60","text":"Discard a Fire Energy card attached to Magcargo in order to use this attack. If your opponent has any Benched Pokémon, this attack does 10 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[219]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-H17','Magcargo','Pokémon','H17','Rare Holo','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H17.png","large":"https://images.pokemontcg.io/ecard3/H17_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fighting"]','Slugma',NULL,'[{"name":"Streaming Mantle","text":"When you play Magcargo from your hand to evolve your Active Pokémon, you may discard the top 3 cards of your deck and and then shuffle 3 basic Energy cards from your discard pile into your deck. If you do, your opponent does the same.","type":"Poké-Power"}]','[{"name":"Crushing Lava","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"You may discard a Fire or Fighting basic Energy card attached to Magcargo. If you discard a Fire Energy card in this way, the Defending Pokémon is now Burned. If you discard a Fighting Energy card in this way, this attack does 40 damage plus 20 more damage."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[219]',NULL,NULL,'ecard3');
INSERT INTO "Card" VALUES('ecard3-H18','Magneton','Pokémon','H18','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ecard3/H18.png","large":"https://images.pokemontcg.io/ecard3/H18_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Lightning"]','Magnemite','["Magnezone"]','[{"name":"Attract Energy","text":"When you play Magneton from your hand to evolve 1 of your Pokémon, you may move any number of basic Energy cards attached to your other Pokémon to Magneton.","type":"Poké-Power"}]','[{"name":"Electric Blast","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"You may discard all Lightning Energy cards attached to Magneton when you use this attack. If you do, put damage counters equal to the amount of Energy cards removed in this way on any number of your opponent''s Benched Pokémon in the way you like. (For example, if you discard 3 Lightning Energy cards, you can put 1 damage counter on 1 of your opponent''s Benched Pokémon and 2 on another.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[82]',NULL,NULL,'ecard3');
