INSERT INTO "Card" VALUES('ex1-81','Energy Restore','Trainer','81','Uncommon','Hideyuki Nakajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/81.png","large":"https://images.pokemontcg.io/ex1/81_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 3 coins. For each heads, put a Basic Energy card from your discard pile into your hand. If you don''t have that many basic Energy cards in your discard pile, put all of them into your hand."]','ex1');
