INSERT INTO "Card" VALUES('ex1-83','Lady Outing','Trainer','83','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/83.png","large":"https://images.pokemontcg.io/ex1/83_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 different types of basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex1');
INSERT INTO "Card" VALUES('ex1-84','Lum Berry','Trainer','84','Uncommon','Kazuo Yazawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/84.png","large":"https://images.pokemontcg.io/ex1/84_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Lum Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","At any time between turns, if the Pokémon this card is attached to is affected by any Special Conditions, remove all of them. Then discard Lum Berry."]','ex1');
INSERT INTO "Card" VALUES('ex1-85','Oran Berry','Trainer','85','Uncommon','Kazuo Yazawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/85.png","large":"https://images.pokemontcg.io/ex1/85_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Oran Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","At any time between turns, if the Pokémon this card is attached to has at least 2 damage counters on it, remove 2 damage counters from it. Then discard Oran Berry."]','ex1');
INSERT INTO "Card" VALUES('ex1-86','Poké Ball','Trainer','86','Uncommon','K. Hoshiba',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/86.png","large":"https://images.pokemontcg.io/ex1/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Basic Pokémon or Evolution card, show it to your opponent and put it into your hand. Shuffle your deck afterward."]','ex1');
INSERT INTO "Card" VALUES('ex1-87','Pokémon Reversal','Trainer','87','Uncommon','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/87.png","large":"https://images.pokemontcg.io/ex1/87_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, your opponent switches 1 of his or her Active Pokémon with 1 of his or her Benched Pokémon."]','ex1');
