INSERT INTO "Card" VALUES('ex1-89','Professor Birch','Trainer','89','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/89.png","large":"https://images.pokemontcg.io/ex1/89_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw cards from your deck until you have 6 cards in your hand."]','ex1');
