INSERT INTO "Card" VALUES('ex1-93','Darkness Energy','Energy','93','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex1/93.png","large":"https://images.pokemontcg.io/ex1/93_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','ex1');
