INSERT INTO "Card" VALUES('ex10-1','Ampharos','Pokémon','1','Rare Holo','Kyoko Umemoto',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex10/1.png","large":"https://images.pokemontcg.io/ex10/1_hires.png"}',NULL,'120',NULL,'["Stage 2"]','["Lightning"]','Flaaffy',NULL,'[{"name":"Energy Connect","text":"As often as you like during your turn (before your attack), you may move a basic Energy card attached to 1 of your Benched Pokémon to your Active Pokémon. This power can''t be used if Ampharos is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Miraculous Thunder","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"You may discard all Lightning Energy attached to Ampharos. If you do, the Defending Pokémon is now Burned and Confused."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-30"}]','["Colorless","Colorless"]',2,'[181]',NULL,NULL,'ex10');
