INSERT INTO "Card" VALUES('ex10-96','Darkness Energy','Energy','96','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex10/96.png","large":"https://images.pokemontcg.io/ex10/96_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attack, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','ex10');
INSERT INTO "Card" VALUES('ex10-97','Metal Energy','Energy','97','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex10/97.png","large":"https://images.pokemontcg.io/ex10/97_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn''t Metal. Metal Energy provides Metal Energy. (Doesn''t count as a basic Energy card.)"]','ex10');
