INSERT INTO "Card" VALUES('ex11-89','Dual Ball','Trainer','89','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/89.png","large":"https://images.pokemontcg.io/ex11/89_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. For each heads, search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-90','Great Ball','Trainer','90','Uncommon','Nakaoka',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/90.png","large":"https://images.pokemontcg.io/ex11/90_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Pokémon (excluding Pokémon-ex) and put it onto your Bench. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-91','Holon Farmer','Trainer','91','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/91.png","large":"https://images.pokemontcg.io/ex11/91_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Search your discard pile for 3 basic Energy cards and any combination of 3 Basic Pokémon or Evolution cards, show them to your opponent, and put them on top of your deck. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-92','Holon Lass','Trainer','92','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/92.png","large":"https://images.pokemontcg.io/ex11/92_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Count the total number of Prize cards left (both yours and your opponent''s). Look at that many cards from the top of your deck, choose as many Energy cards as you like, show them to your opponent, and put them into your hand. Put the other cards back on top of your deck. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-93','Holon Mentor','Trainer','93','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/93.png","large":"https://images.pokemontcg.io/ex11/93_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Search your deck for up to 3 Basic Pokémon that each has 100 HP or less, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-94','Holon Research Tower','Trainer','94','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/94.png","large":"https://images.pokemontcg.io/ex11/94_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player''s basic Energy cards attached to Pokémon that has δ on its card are both their usual Energy type and Metal type but provide only 1 Energy at a time. (Has no effect other than providing Energy.)"]','ex11');
INSERT INTO "Card" VALUES('ex11-95','Holon Researcher','Trainer','95','Uncommon','Kanako Eo',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/95.png","large":"https://images.pokemontcg.io/ex11/95_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Search your deck for a Metal Energy card or a Basic Pokémon (or Evolution card) that has δ on its card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex11');
INSERT INTO "Card" VALUES('ex11-96','Holon Ruins','Trainer','96','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/96.png","large":"https://images.pokemontcg.io/ex11/96_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player that has any Pokémon in play that has δ on its card may draw a card once during his or her turn. If the player does, he or she discards a card from his or her hand."]','ex11');
INSERT INTO "Card" VALUES('ex11-97','Holon Scientist','Trainer','97','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/97.png","large":"https://images.pokemontcg.io/ex11/97_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","If you have less cards in your hand than your opponent, draw cards until you have the same number of cards as your opponent."]','ex11');
INSERT INTO "Card" VALUES('ex11-98','Holon Transceiver','Trainer','98','Uncommon','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/98.png","large":"https://images.pokemontcg.io/ex11/98_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Supporter card that has Holon in its name, show it to your opponent, and put it into your hand. Shuffle your deck afterward. Or, search your discard pile for a Supporter card that has Holon in its name, show it to your opponent, and put it into your hand."]','ex11');
INSERT INTO "Card" VALUES('ex11-99','Master Ball','Trainer','99','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex11/99.png","large":"https://images.pokemontcg.io/ex11/99_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards from your deck. Choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, and put it into your hand. Put the other 6 cards back on top of your deck. Shuffle your deck afterward."]','ex11');
