INSERT INTO "Card" VALUES('ex12-72','Cursed Stone','Trainer','72','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/72.png","large":"https://images.pokemontcg.io/ex12/72_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","At any time between turns, each player puts 1 damage counter on his or her Pokémon that has a Poké-Power."]','ex12');
INSERT INTO "Card" VALUES('ex12-73','Fieldworker','Trainer','73','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/73.png","large":"https://images.pokemontcg.io/ex12/73_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw 3 cards. Your opponent may also draw a card."]','ex12');
INSERT INTO "Card" VALUES('ex12-74','Full Flame','Trainer','74','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/74.png","large":"https://images.pokemontcg.io/ex12/74_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Put 4 damage counters instead of 2 on each Burned Pokémon between turns. The Special Condition Burned can''t be removed by evolving or devolving the Burned Pokémon."]','ex12');
INSERT INTO "Card" VALUES('ex12-75','Giant Stump','Trainer','75','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/75.png","large":"https://images.pokemontcg.io/ex12/75_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player can''t have more than 3 Benched Pokémon.","When Giant Stump comes into play, each player discards Benched Pokémon and any cards attached to them until he or she has 3 Benched Pokémon. (You discard your Pokémon first.)"]','ex12');
INSERT INTO "Card" VALUES('ex12-76','Power Tree','Trainer','76','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/76.png","large":"https://images.pokemontcg.io/ex12/76_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, if the player has no Special Energy cards in his or her discard pile, that player searches his or her discard pile for a basic Energy card, show it to the opponent, and put it into his or her hand."]','ex12');
INSERT INTO "Card" VALUES('ex12-77','Strange Cave','Trainer','77','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/77.png","large":"https://images.pokemontcg.io/ex12/77_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, that player may put an Omanyte, Kabuto, Aerodactyl, Aerodactyl ex, Lileep, or Anorith onto his or her Bench from his or her hand. Treat the new Benched Pokémon as Basic Pokémon."]','ex12');
INSERT INTO "Card" VALUES('ex12-78','Claw Fossil','Trainer','78','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/78.png","large":"https://images.pokemontcg.io/ex12/78_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Jagged Stone","text":"If Claw Fossil is your Active Pokémon and is damaged by an opponent''s attack (even if Claw Fossil is Knocked Out), put 1 damage counter on the Attacking Pokémon.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Claw Fossil as if it were a Basic Pokémon. While in play, Claw Fossil counts as a Colorless Pokémon (as well as a Trainer card). Claw Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Claw Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Claw Fossil from play."]','ex12');
INSERT INTO "Card" VALUES('ex12-79','Mysterious Fossil','Trainer','79','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/79.png","large":"https://images.pokemontcg.io/ex12/79_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Colorless Pokémon (as well as a Trainer card). Mysterious Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Mysterious Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play."]','ex12');
INSERT INTO "Card" VALUES('ex12-80','Root Fossil','Trainer','80','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/80.png","large":"https://images.pokemontcg.io/ex12/80_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Spongy Stone","text":"At any time between turns, remove 1 damage counter from Root Fossil.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Root Fossil as if it were a Basic Pokémon. While in play, Root Fossil counts as a Colorless Pokémon (as well as a Trainer card). Root Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Root Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Root Fossil from play."]','ex12');
INSERT INTO "Card" VALUES('ex12-81','Rainbow Energy','Energy','81','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex12/81.png","large":"https://images.pokemontcg.io/ex12/81_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Rainbow Energy to 1 of your Pokémon. While in play, Rainbow Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) When you attach this card from your hand to 1 of your Pokémon, put 1 damage counter on that Pokémon."]','ex12');
