INSERT INTO "Card" VALUES('ex13-85','Holon Adventurer','Trainer','85','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/85.png","large":"https://images.pokemontcg.io/ex13/85_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Draw 3 cards. If you discarded a Pokémon that has δ on its card, draw 4 cards instead."]','ex13');
INSERT INTO "Card" VALUES('ex13-86','Holon Fossil','Trainer','86','Uncommon','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/86.png","large":"https://images.pokemontcg.io/ex13/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for an Omanyte, Kabuto, Aerodactyl, Aerodactyl ex, Lileep, or Anorith and put it onto your Bench. Shuffle your deck afterward. If tails, put an Omanyte, Kabuto, Aerodactyl, Aerodactyl ex, Lileep, or Anorith from your hand onto your Bench. Treat the new Benched Pokémon as a Basic Pokémon."]','ex13');
INSERT INTO "Card" VALUES('ex13-87','Holon Lake','Trainer','87','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/87.png","large":"https://images.pokemontcg.io/ex13/87_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,'[{"name":"Delta Call","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Pokémon that has δ on its card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player''s Pokémon that has δ on its card can use attacks on this card instead of its own."]','ex13');
INSERT INTO "Card" VALUES('ex13-88','Mr. Stone''s Project','Trainer','88','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/88.png","large":"https://images.pokemontcg.io/ex13/88_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. Or, search your discard pile for up to 2 basic Energy cards, show them to your opponent, and put them into your hand."]','ex13');
INSERT INTO "Card" VALUES('ex13-89','Professor Cozmo''s Discovery','Trainer','89','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/89.png","large":"https://images.pokemontcg.io/ex13/89_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Flip a coin. If heads, draw the bottom 3 cards of your deck. If tails, draw the top 2 cards of your deck."]','ex13');
INSERT INTO "Card" VALUES('ex13-90','Rare Candy','Trainer','90','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/90.png","large":"https://images.pokemontcg.io/ex13/90_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.)"]','ex13');
INSERT INTO "Card" VALUES('ex13-91','Claw Fossil','Trainer','91','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/91.png","large":"https://images.pokemontcg.io/ex13/91_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Jagged Stone","text":"If Claw Fossil is your Active Pokémon and is damaged by an opponent''s attack (even if Claw Fossil is Knocked Out), put 1 damage counter on the Attacking Pokémon.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Claw Fossil as if it were a Basic Pokémon. While in play, Claw Fossil counts as a Colorless Pokémon (as well as a Trainer card). Claw Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Claw Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Claw Fossil from play."]','ex13');
INSERT INTO "Card" VALUES('ex13-92','Mysterious Fossil','Trainer','92','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/92.png","large":"https://images.pokemontcg.io/ex13/92_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Colorless Pokémon (as well as a Trainer card). Mysterious Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Mysterious Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play."]','ex13');
INSERT INTO "Card" VALUES('ex13-93','Root Fossil','Trainer','93','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/93.png","large":"https://images.pokemontcg.io/ex13/93_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Spongy Stone","text":"At any times between turns, remove 1 damage counter from Root Fossil.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Root Fossil as if it were a Basic Pokémon. While in play, Root Fossil counts as a Colorless Pokémon (as well as a Trainer card). Root Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Root Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Root Fossil from play."]','ex13');
INSERT INTO "Card" VALUES('ex13-94','Darkness Energy','Energy','94','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/94.png","large":"https://images.pokemontcg.io/ex13/94_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','ex13');
INSERT INTO "Card" VALUES('ex13-95','Metal Energy','Energy','95','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/95.png","large":"https://images.pokemontcg.io/ex13/95_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn''t Metal. Metal Energy provides Metal Energy. (Doesn''t count as a basic Energy card.)"]','ex13');
INSERT INTO "Card" VALUES('ex13-96','Multi Energy','Energy','96','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/96.png","large":"https://images.pokemontcg.io/ex13/96_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it."]','ex13');
INSERT INTO "Card" VALUES('ex13-97','Dark Metal Energy','Energy','97','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/97.png","large":"https://images.pokemontcg.io/ex13/97_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Dark Metal Energy to 1 of your Pokémon. While in play, Dark Metal Energy provides Darkness Energy and Metal Energy, but provides only 1 Energy at a time. (Doesn''t count as a basic Energy card when not in play and has no effect other than providing Energy.)"]','ex13');
INSERT INTO "Card" VALUES('ex13-98','δ Rainbow Energy','Energy','98','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/98.png","large":"https://images.pokemontcg.io/ex13/98_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["δ Rainbow Energy provides Colorless Energy. While attached to a Pokémon that has δ on its card, δ Rainbow Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.)"]','ex13');
