INSERT INTO "Card" VALUES('ex13-100','Mew ex','Pokémon','100','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/100.png","large":"https://images.pokemontcg.io/ex13/100_hires.png"}',NULL,'90',NULL,'["Basic","ex"]','["Psychic"]',NULL,NULL,'[{"name":"Psychic Vision","text":"Once during your turn (before your attack), if Mew ex is on your Bench, you may look at your opponent''s hand.","type":"Poké-Power"}]','[{"name":"Super Psy Bolt","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Devo Crush","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"You may discard 2 Energy attached to Mew ex. If you do, you may remove the highest Stage Evolution card from the Defending Pokémon and shuffle that card into your opponent''s deck."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex13');
INSERT INTO "Card" VALUES('ex13-101','Mightyena ex','Pokémon','101','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/101.png","large":"https://images.pokemontcg.io/ex13/101_hires.png"}',NULL,'100',NULL,'["Stage 1","ex"]','["Darkness"]','Poochyena',NULL,'[{"name":"Driving Howl","text":"Once during your turn (before your attack), you may choose 1 of the Defending Pokémon and switch it with 1 of your opponent''s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch. This power can''t be used if Mightyena ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Sharp Fang","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Hyper Claws","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"If the Defending Pokémon is a Stage 2 Evolved Pokémon, this attack does 50 damage plus 40 more damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]',NULL,NULL,'[262]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex13');
INSERT INTO "Card" VALUES('ex13-102','Gyarados ★ δ','Pokémon','102','Rare Holo Star','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex13/102.png","large":"https://images.pokemontcg.io/ex13/102_hires.png"}',NULL,'80',NULL,'["Basic","Star"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Spiral Growth","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin until you get tails. For each heads, search your discard pile for a basic Energy card and attach it to Gyarados Star."},{"name":"All-out Blast","cost":["Fire","Fire","Fire","Fire"],"convertedEnergyCost":4,"damage":"50+","text":"Discard cards from the top of your deck until you have 1 card left. This attack does 50 damage plus 20 more damage for each Energy card you discarded in this way."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[130]',NULL,'["You can''t have more than 1 Pokémon Star in your deck."]','ex13');
