INSERT INTO "Card" VALUES('ex14-71','Bill''s Maintenance','Trainer','71','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/71.png","large":"https://images.pokemontcg.io/ex14/71_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","If you have any cards in your hand, shuffle 1 of them into your deck, then draw 3 cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-72','Castaway','Trainer','72','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/72.png","large":"https://images.pokemontcg.io/ex14/72_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for a Supporter card, a Pokémon Tool card, and a basic Energy card. Show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex14');
INSERT INTO "Card" VALUES('ex14-73','Celio''s Network','Trainer','73','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/73.png","large":"https://images.pokemontcg.io/ex14/73_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for a Basic Pokémon or Evolution card (excluding Pokémon-ex), show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex14');
INSERT INTO "Card" VALUES('ex14-74','Cessation Crystal','Trainer','74','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/74.png","large":"https://images.pokemontcg.io/ex14/74_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Cessation Crystal to 1 of your Pokémon (excluding Pokémon-ex) that doesn''t already have a Pokémon Tool attached to it. If the Pokémon Cessation Crystal is attached to is a Pokémon-ex, discard this card.","As long as Cessation Crystal is attached to an Active Pokémon, each player''s Pokémon (both yours and your opponent''s) can''t use any Poké-Powers or Poké-Bodies."]','ex14');
INSERT INTO "Card" VALUES('ex14-75','Crystal Beach','Trainer','75','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/75.png","large":"https://images.pokemontcg.io/ex14/75_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each Special Energy card that provides 2 or more Energy (both yours and your opponent''s) now provides only 1 Colorless Energy. This isn''t affected by any Poké-Powers or Poké-Bodies."]','ex14');
INSERT INTO "Card" VALUES('ex14-76','Crystal Shard','Trainer','76','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/76.png","large":"https://images.pokemontcg.io/ex14/76_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Crystal Shard to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as Crystal Shard is attached to a Pokémon, that Pokémon''s type is Colorless. If that Pokémon attacks, discard this card at the end of the turn."]','ex14');
INSERT INTO "Card" VALUES('ex14-77','Double Full Heal','Trainer','77','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/77.png","large":"https://images.pokemontcg.io/ex14/77_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all Special Conditions from each of your Active Pokémon."]','ex14');
INSERT INTO "Card" VALUES('ex14-78','Dual Ball','Trainer','78','Uncommon','"Big Mama" Tagawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/78.png","large":"https://images.pokemontcg.io/ex14/78_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. For each heads, search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex14');
INSERT INTO "Card" VALUES('ex14-79','Holon Circle','Trainer','79','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/79.png","large":"https://images.pokemontcg.io/ex14/79_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Prevent all effects of an attack, including damage, done by either player''s Active Pokémon. If an Active Pokémon uses an attack, that attack ends, and discard this card."]','ex14');
INSERT INTO "Card" VALUES('ex14-80','Memory Berry','Trainer','80','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/80.png","large":"https://images.pokemontcg.io/ex14/80_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Memory Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","The Pokémon this card is attached to can use any attack from its Basic Pokémon or its Stage 1 Evolution card. (You still have to pay for that attack''s Energy cost.) If that Pokémon attacks, discard this card at the end of the turn."]','ex14');
INSERT INTO "Card" VALUES('ex14-81','Mysterious Shard','Trainer','81','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/81.png","large":"https://images.pokemontcg.io/ex14/81_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Mysterious Shard to 1 of your Pokémon (excluding Pokémon-ex) that doesn''t already have a Pokémon Tool attached to it. If the Pokémon Mysterious Shard is attached to is a Pokémon-ex, discard this card.","Prevent all effects of attacks, including damage, done to the Pokémon that Mysterious Shard is attached to by your opponent''s Pokémon-ex. Discard this card at the end of your opponent''s next turn."]','ex14');
INSERT INTO "Card" VALUES('ex14-82','Poké Ball','Trainer','82','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/82.png","large":"https://images.pokemontcg.io/ex14/82_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Basic Pokémon or Evolution card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex14');
INSERT INTO "Card" VALUES('ex14-83','PokéNav','Trainer','83','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/83.png","large":"https://images.pokemontcg.io/ex14/83_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 3 cards of your deck, and choose a Basic Pokémon, Evolution card, or Energy card. Show it to your opponent and put it into your hand. Put the 2 other cards back on top of your deck in any order."]','ex14');
INSERT INTO "Card" VALUES('ex14-84','Warp Point','Trainer','84','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/84.png","large":"https://images.pokemontcg.io/ex14/84_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent switches 1 of his or her Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch 1 of your Active Pokémon with 1 of your Benched Pokémon, if any."]','ex14');
INSERT INTO "Card" VALUES('ex14-85','Windstorm','Trainer','85','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/85.png","large":"https://images.pokemontcg.io/ex14/85_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose up to 2 in any combination of Pokémon Tool cards and Stadium cards in play (both yours and your opponent''s) and discard them."]','ex14');
INSERT INTO "Card" VALUES('ex14-86','Energy Search','Trainer','86','Common','Kai Ishikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/86.png","large":"https://images.pokemontcg.io/ex14/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex14');
INSERT INTO "Card" VALUES('ex14-87','Potion','Trainer','87','Common','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/87.png","large":"https://images.pokemontcg.io/ex14/87_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove 2 damage counters from 1 of your Pokémon (remove 1 damage counter if that Pokémon has only 1)."]','ex14');
INSERT INTO "Card" VALUES('ex14-88','Double Rainbow Energy','Energy','88','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/88.png","large":"https://images.pokemontcg.io/ex14/88_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Has no effect other than providing Energy.) Damage done to your opponent''s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (before applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy."]','ex14');
INSERT INTO "Card" VALUES('ex14-89','Aggron ex','Pokémon','89','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/89.png","large":"https://images.pokemontcg.io/ex14/89_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Metal"]','Lairon',NULL,'[{"name":"Intimidating Armor","text":"As long as Aggron ex is your Active Pokémon, your opponent''s Basic Pokémon can''t attack or use any Poké-Powers or Poké-Bodies.","type":"Poké-Body"}]','[{"name":"Split Bomb","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Choose 2 of your opponent''s Pokémon. This attack doe 30 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Mega Burn","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"During your next turn, Aggron ex can''t use Mega Burn."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[306]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-90','Blaziken ex','Pokémon','90','Rare Holo EX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/90.png","large":"https://images.pokemontcg.io/ex14/90_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Fighting"]','Combusken',NULL,NULL,'[{"name":"Drag Off","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Before doing damage, you may choose 1 of your opponent''s Benched Pokémon and switch it with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch."},{"name":"Burn Away","cost":["Fire","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Before doing damage, count the remaining HP of the Defending Pokémon. If that Pokémon is Knocked Out by this attack, Blaziken ex does damage to itself equal to the attack''s damage minus the remaining HP of the Defending Pokémon. This attack''s damage isn''t by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[257]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-91','Delcatty ex','Pokémon','91','Rare Holo EX','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/91.png","large":"https://images.pokemontcg.io/ex14/91_hires.png"}',NULL,'90',NULL,'["Stage 1","ex"]','["Colorless"]','Skitty',NULL,'[{"name":"Constrain","text":"Once during your turn (before your attack), you may use this power. Each player discards cards until that player has 6 cards in his or her hand. (You discard first.) This power can''t be used if Delcatty ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Upstream","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Search your discard pile for all Energy cards. This attack does 10 damage times the number of Energy cards you find there. Show them to your opponent, and put them on top of your deck. Shuffle your deck afterward."},{"name":"Tail Slap","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[301]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-92','Exploud ex','Pokémon','92','Rare Holo EX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/92.png","large":"https://images.pokemontcg.io/ex14/92_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Colorless"]','Loudred',NULL,'[{"name":"Extra Noise","text":"As long as Exploud ex is your Active Pokémon, put 1 damage counter on each of your opponent''s Pokémon-ex between turns.","type":"Poké-Body"}]','[{"name":"Derail","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Discard a Special Energy card, if any, attached to the Defending Pokémon."},{"name":"Hyper Tail","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"If the Defending Pokémon has any Poké-Powers or Poké-Bodies, this attack does 60 damage plus 20 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[295]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-93','Groudon ex','Pokémon','93','Rare Holo EX','Takabon',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/93.png","large":"https://images.pokemontcg.io/ex14/93_hires.png"}',NULL,'100',NULL,'["Basic","ex"]','["Fighting"]',NULL,NULL,'[{"name":"Hard Rock","text":"As long as Groudon ex has 1 Energy or less attached to it, damage done to any of your Groudon ex in play by attacks is reduced by 20 (after applying Weakness and Resistance). You can''t use more than 1 Hard Rock Poké-Body each turn.","type":"Poké-Body"}]','[{"name":"Power Blast","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"Discard 2 Energy attached to Groudon ex."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[383]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
INSERT INTO "Card" VALUES('ex14-94','Jirachi ex','Pokémon','94','Rare Holo EX','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex14/94.png","large":"https://images.pokemontcg.io/ex14/94_hires.png"}',NULL,'90',NULL,'["Basic","ex"]','["Psychic"]',NULL,NULL,'[{"name":"Star Light","text":"As long as your opponent has any Pokémon-ex or Stage 2 Evolved Pokémon in play, Jirachi ex pays Colorless less Energy to use Shield Beam or Super Psy Bolt.","type":"Poké-Body"}]','[{"name":"Shield Beam","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"During your opponent''s next turn, your opponent can''t use any Poké-Powers on his or her Pokémon."},{"name":"Super Psy Bolt","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]',NULL,NULL,'["Colorless"]',1,'[385]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex14');
