INSERT INTO "Card" VALUES('ex15-72','Buffer Piece','Trainer','72','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/72.png","large":"https://images.pokemontcg.io/ex15/72_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Buffer Piece to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","Damage done to the Pokémon Buffer Piece is attached to by an opponent''s attack is reduced by 20 (after applying Weakness and Resistance). At the end of your opponent''s turn after you played Buffer Piece, discard Buffer Piece."]','ex15');
INSERT INTO "Card" VALUES('ex15-73','Copycat','Trainer','73','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/73.png","large":"https://images.pokemontcg.io/ex15/73_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck. Then, count the number of cards in your opponent''s hand and draw that many cards."]','ex15');
INSERT INTO "Card" VALUES('ex15-74','Holon Legacy','Trainer','74','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/74.png","large":"https://images.pokemontcg.io/ex15/74_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each Pokémon in play that has δ on its card (both yours and your opponent''s) has no Weakness and can''t use any Poké-Powers."]','ex15');
INSERT INTO "Card" VALUES('ex15-75','Holon Mentor','Trainer','75','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/75.png","large":"https://images.pokemontcg.io/ex15/75_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. If you can''t discard a card from your hand, you can''t play this card.","Search your deck for up to 3 Basic Pokémon that each has 100 HP or less, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex15');
INSERT INTO "Card" VALUES('ex15-76','Island Hermit','Trainer','76','Uncommon','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/76.png","large":"https://images.pokemontcg.io/ex15/76_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Choose up to 2 of your Prize cards and put them face up. (These cards remain face up for the rest of the game.) Draw 2 cards."]','ex15');
INSERT INTO "Card" VALUES('ex15-77','Mr. Stone''s Project','Trainer','77','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/77.png","large":"https://images.pokemontcg.io/ex15/77_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. Or, search your discard pile for up to 2 basic Energy cards, show them to your opponent, and put them into your hand."]','ex15');
INSERT INTO "Card" VALUES('ex15-78','Old Rod','Trainer','78','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/78.png","large":"https://images.pokemontcg.io/ex15/78_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. If both are heads, search your discard pile for a Basic Pokémon or Evolution card, show it to your opponent, and put it into your hand. If both are tails, search your discard pile for a Trainer card, show it to your opponent, and put it into your hand."]','ex15');
INSERT INTO "Card" VALUES('ex15-79','Professor Elm''s Training Method','Trainer','79','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/79.png","large":"https://images.pokemontcg.io/ex15/79_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for an Evolution card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex15');
INSERT INTO "Card" VALUES('ex15-80','Professor Oak''s Research','Trainer','80','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/80.png","large":"https://images.pokemontcg.io/ex15/80_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck, then draw 5 cards."]','ex15');
INSERT INTO "Card" VALUES('ex15-81','Strength Charm','Trainer','81','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/81.png","large":"https://images.pokemontcg.io/ex15/81_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Strength Charm to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","Whenever an attack from the Pokémon that Strength Charm is attached to does damage to the Active Pokémon, this attack does 10 more damage (before applying Weakness and Resistance). Discard Strength Charm at the end of the turn in which this Pokémon attacks."]','ex15');
INSERT INTO "Card" VALUES('ex15-82','TV Reporter','Trainer','82','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/82.png","large":"https://images.pokemontcg.io/ex15/82_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw 3 cards. Then discard any 1 card from your hand."]','ex15');
INSERT INTO "Card" VALUES('ex15-83','Switch','Trainer','83','Common','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/83.png","large":"https://images.pokemontcg.io/ex15/83_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch 1 of your Active Pokémon with 1 of your Benched Pokémon."]','ex15');
INSERT INTO "Card" VALUES('ex15-84','Holon Energy FF','Energy','84','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/84.png","large":"https://images.pokemontcg.io/ex15/84_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Holon Energy FF provides Colorless Energy.","If the Pokémon that Holon Energy FF is attached to also has a basic Fire Energy card attached to it, that Pokémon has no Weakness. If the Pokémon that Holon Energy FF is attached to also has a basic Fighting Energy card attached to it, damage done by that Pokémon''s attack isn''t affected by Resistance. Ignore these effects if Holon Energy FF is attached to Pokémon-ex."]','ex15');
INSERT INTO "Card" VALUES('ex15-85','Holon Energy GL','Energy','85','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/85.png","large":"https://images.pokemontcg.io/ex15/85_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Holon Energy GL provides Colorless Energy.","If the Pokémon that Holon Energy GL is attached to also has a basic Grass Energy card attached to it, that Pokémon can''t be affected by any Special Conditions. If the Pokémon that Holon Energy GL is attached to also has a basic Lightning Energy card attached to it, damage done to that Pokémon by attacks from your opponent''s Pokémon-ex is reduced by 10. Ignore these effects if Holon Energy GL is attached to Pokémon-ex."]','ex15');
INSERT INTO "Card" VALUES('ex15-86','Holon Energy WP','Energy','86','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/86.png","large":"https://images.pokemontcg.io/ex15/86_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Holon Energy WP provides Colorless Energy.","If the Pokémon that Holon Energy WP is attached to also has a basic Water Energy card attached to it, prevent all effects of attacks, excluding damage, done to that Pokémon by your opponent''s Pokémon. If the Pokémon that Holon Energy WP is attached to also has a basic Psychic Energy card attached to it, that Pokémon''s Retreat Cost is 0. Ignore these effects if Holon Energy WP is attached to Pokémon-ex."]','ex15');
INSERT INTO "Card" VALUES('ex15-87','Boost Energy','Energy','87','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/87.png","large":"https://images.pokemontcg.io/ex15/87_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Boost Energy can be attached only to an Evolved Pokémon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides ColorlessColorlessColorless Energy. The Pokémon Boost Energy is attached to can''t retreat. If the Pokémon Boost Energy is attached to isn''t an Evolved Pokémon, discard Boost Energy."]','ex15');
INSERT INTO "Card" VALUES('ex15-88','δ Rainbow Energy','Energy','88','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/88.png","large":"https://images.pokemontcg.io/ex15/88_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["δ Rainbow Energy provides Colorless Energy. While attached to a Pokémon that has δ on its card, δ Rainbow Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.)"]','ex15');
INSERT INTO "Card" VALUES('ex15-89','Scramble Energy','Energy','89','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/89.png","large":"https://images.pokemontcg.io/ex15/89_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Scramble Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). Scramble Energy provides Colorless Energy. While in play, if you have more Prize cards left than your opponent, Scramble Energy provides every type of Energy but provides only 3 in any combination at a time. If the Pokémon Scramble Energy is attached to isn''t an Evolved Pokémon (or evolves into Pokémon-ex), discard Scramble Energy."]','ex15');
INSERT INTO "Card" VALUES('ex15-90','Altaria ex δ','Pokémon','90','Rare Holo EX','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex15/90.png","large":"https://images.pokemontcg.io/ex15/90_hires.png"}',NULL,'100',NULL,'["Stage 1","ex"]','["Water"]','Swablu',NULL,'[{"name":"Extra Boost","text":"Once during your turn (before your attack), you may attach a basic Energy card from your hand to 1 of your Stage 2 Pokémon-ex. This power can''t be used if Altaria ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Healing Light","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Remove 1 damage counter from each of your Pokémon."}]','[{"type":"Colorless","value":"×2"}]','[{"type":"Grass","value":"-30"},{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[334]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex15');
