INSERT INTO "Card" VALUES('ex16-78','Master Ball','Trainer','78','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/78.png","large":"https://images.pokemontcg.io/ex16/78_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards from your deck. Choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, and put it into your hand. Put the other 6 cards back on top of your deck. Shuffle your deck afterward."]','ex16');
INSERT INTO "Card" VALUES('ex16-79','Phoebe''s Stadium','Trainer','79','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/79.png","large":"https://images.pokemontcg.io/ex16/79_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player pays ColorlessColorless less to retreat his or her Psychic Pokémon."]','ex16');
INSERT INTO "Card" VALUES('ex16-80','Professor Birch','Trainer','80','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/80.png","large":"https://images.pokemontcg.io/ex16/80_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw cards from your deck until you have 6 cards in your hand."]','ex16');
INSERT INTO "Card" VALUES('ex16-81','Scott','Trainer','81','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/81.png","large":"https://images.pokemontcg.io/ex16/81_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 cards in any combination of Supporter cards and Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex16');
INSERT INTO "Card" VALUES('ex16-82','Sidney''s Stadium','Trainer','82','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/82.png","large":"https://images.pokemontcg.io/ex16/82_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player''s Darkness Pokémon can''t be Asleep, Confused, or Paralyzed."]','ex16');
INSERT INTO "Card" VALUES('ex16-83','Steven''s Advice','Trainer','83','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/83.png","large":"https://images.pokemontcg.io/ex16/83_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw a number of cards up to the number of your opponent''s Pokémon in play.","If you have 7 or more cards (including this one) in your hand, you can''t play this card."]','ex16');
INSERT INTO "Card" VALUES('ex16-84','Claw Fossil','Trainer','84','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/84.png","large":"https://images.pokemontcg.io/ex16/84_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Jagged Stone","text":"If Claw Fossil is your Active Pokémon and is damaged by an opponent''s attack (even if Claw Fossil is Knocked Out), put 1 damage counter on the Attacking Pokémon.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Claw Fossil as if it were a Basic Pokémon. While in play Claw Fossil counts as a Colorless Pokémon (as well as a Trainer card). Claw Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Claw Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Claw Fossil from play."]','ex16');
INSERT INTO "Card" VALUES('ex16-85','Mysterious Fossil','Trainer','85','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/85.png","large":"https://images.pokemontcg.io/ex16/85_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Colorless Pokémon (as well as a Trainer card). Mysterious Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Mysterious Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play."]','ex16');
INSERT INTO "Card" VALUES('ex16-86','Root Fossil','Trainer','86','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/86.png","large":"https://images.pokemontcg.io/ex16/86_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Spongy Stone","text":"At any time between turns, remove 1 damage counter from Root Fossil.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Root Fossil as if it were a Basic Pokémon. While in play, Root Fossil counts as a Colorless Pokémon (as well as a Trainer card). Root Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Root Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Root Fossil from play."]','ex16');
INSERT INTO "Card" VALUES('ex16-87','Darkness Energy','Energy','87','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/87.png","large":"https://images.pokemontcg.io/ex16/87_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','ex16');
INSERT INTO "Card" VALUES('ex16-88','Metal Energy','Energy','88','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/88.png","large":"https://images.pokemontcg.io/ex16/88_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn''t Metal. Metal Energy provides Metal Energy. (Doesn''t count as a basic Energy card.)"]','ex16');
INSERT INTO "Card" VALUES('ex16-89','Multi Energy','Energy','89','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/89.png","large":"https://images.pokemontcg.io/ex16/89_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it."]','ex16');
INSERT INTO "Card" VALUES('ex16-90','Cyclone Energy','Energy','90','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/90.png","large":"https://images.pokemontcg.io/ex16/90_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Cyclone Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch 1 of the Defending Pokémon with 1 of your opponent''s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch."]','ex16');
INSERT INTO "Card" VALUES('ex16-91','Warp Energy','Energy','91','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/91.png","large":"https://images.pokemontcg.io/ex16/91_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Warp Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch that Pokémon with 1 of your Benched Pokémon."]','ex16');
INSERT INTO "Card" VALUES('ex16-92','Absol ex','Pokémon','92','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/92.png","large":"https://images.pokemontcg.io/ex16/92_hires.png"}',NULL,'100',NULL,'["Basic","ex"]','["Darkness"]',NULL,NULL,'[{"name":"Cursed Eyes","text":"Once during your turn, when you put Absol ex from your hand onto your Bench, you may move 3 damage counters from 1 of your opponent''s Pokémon to another of his or her Pokémon.","type":"Poké-Power"}]','[{"name":"Psychic Pulse","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Does 10 damage to each of your opponent''s Benched Pokémon that has any damage counters on it. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[359]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-93','Claydol ex','Pokémon','93','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/93.png","large":"https://images.pokemontcg.io/ex16/93_hires.png"}',NULL,'120',NULL,'["Stage 1","ex"]','["Psychic"]','Baltoy',NULL,'[{"name":"Type Shift","text":"Once during your turn (before your attack), you may use this power. Claydol ex''s type is Fighting until the end of your turn.","type":"Poké-Power"}]','[{"name":"Psychic Boom","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Does 20 damage plus 10 more damage for each Energy attached to the Defending Pokémon."},{"name":"Shadow Crush","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"You may discard a Psychic Energy card attached to Claydol ex. If you do, discard an Energy card attached to the Defending Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[344]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-94','Flygon ex','Pokémon','94','Rare Holo EX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/94.png","large":"https://images.pokemontcg.io/ex16/94_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Colorless"]','Vibrava',NULL,'[{"name":"Psychic Protector","text":"If Flygon ex is damaged by an opponent''s attack, you may discard up to 4 cards from your hand. If you do, any damage done to Flygon ex is reduced by 10 for each card you discarded.","type":"Poké-Body"}]','[{"name":"Slashing Strike","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Flip a coin. If tails, Flygon ex can''t use Slashing Strike during your next turn."}]','[{"type":"Colorless","value":"×2"}]','[{"type":"Lightning","value":"-30"},{"type":"Fighting","value":"-30"}]',NULL,NULL,'[330]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-95','Metagross ex','Pokémon','95','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/95.png","large":"https://images.pokemontcg.io/ex16/95_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Metal"]','Metang',NULL,'[{"name":"Magnetic Redraw","text":"Once during your turn (before your attack), if Metagross ex is your Active Pokémon, you may use this power. Each player shuffles his or her hand into his or her deck. Then, each player draws 4 cards. This power can''t be used if Metagross ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Scanblast","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Does 70 damage to each of your opponent''s Benched Pokémon that has the same name as the Defending Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[376]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-96','Salamence ex','Pokémon','96','Rare Holo EX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/96.png","large":"https://images.pokemontcg.io/ex16/96_hires.png"}',NULL,'160',NULL,'["Stage 2","ex"]','["Colorless"]','Shelgon',NULL,NULL,'[{"name":"Volcanic Flame","cost":["Fire","Fire","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"150","text":"Discard the top 5 cards from your deck."},{"name":"Hydro Wave","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Discard all Water Energy attached to Salamence ex. This attack does 30 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Colorless","value":"×2"}]','[{"type":"Fire","value":"-30"},{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[373]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-97','Shiftry ex','Pokémon','97','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/97.png","large":"https://images.pokemontcg.io/ex16/97_hires.png"}',NULL,'140',NULL,'["Stage 2","ex"]','["Darkness"]','Nuzleaf',NULL,NULL,'[{"name":"Skill Hack","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Look at your opponent''s hand and choose a Basic Pokémon or Evolution card you find there. Choose 1 of that Pokémon''s attacks. Skill Hack copies that attack except for its Energy cost. (You must still do anything else required for that attack.) (No matter what type that Pokémon is, Shiftry ex''s type is still Darkness.) Shiftry ex performs that attack."},{"name":"Dirge","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Does 60 damage to each of your opponent''s Benched Pokémon that has the same name as the Defending Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[275]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-98','Skarmory ex','Pokémon','98','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/98.png","large":"https://images.pokemontcg.io/ex16/98_hires.png"}',NULL,'100',NULL,'["Basic","ex"]','["Metal"]',NULL,NULL,'[{"name":"Metal Gravity","text":"If your opponent''s Active Pokémon retreats and has 40 or more remaining HP, put 3 damage counters on that Pokémon. You can''t use more than 1 Metal Gravity Poké-Body each turn.","type":"Poké-Body"}]','[{"name":"Whirlwind","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Razor Wing","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[227]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-99','Walrein ex','Pokémon','99','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/99.png","large":"https://images.pokemontcg.io/ex16/99_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Water"]','Sealeo',NULL,'[{"name":"Chilling Breath","text":"Once during your turn, when you play Walrein ex from your hand to evolve 1 of your Pokémon, you may use this power. Your opponent can''t play any Trainer cards from his or her hand during your opponent''s next turn.","type":"Poké-Power"}]','[{"name":"Wreck","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"70+","text":"If there is any Stadium card in play, this attack does 70 damage plus 20 more damage. Discard that Stadium card."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[365]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex16');
INSERT INTO "Card" VALUES('ex16-100','Flareon ★','Pokémon','100','Rare Holo Star','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/100.png","large":"https://images.pokemontcg.io/ex16/100_hires.png"}',NULL,'70',NULL,'["Basic","Star"]','["Fire"]',NULL,NULL,'[{"name":"Crimson Ray","text":"Once during your turn, when you put Flareon Star from your hand onto your Bench, you may use this power. Each Active Pokémon (both yours and your opponent''s) is now Burned.","type":"Poké-Power"}]','[{"name":"Flamethrower","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"Discard a Fire Energy attached to Flareon Star."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[136]',NULL,'["You can''t have more than 1 Pokémon Star in your deck."]','ex16');
INSERT INTO "Card" VALUES('ex16-101','Jolteon ★','Pokémon','101','Rare Holo Star','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/101.png","large":"https://images.pokemontcg.io/ex16/101_hires.png"}',NULL,'70',NULL,'["Basic","Star"]','["Lightning"]',NULL,NULL,'[{"name":"Yellow Ray","text":"Once during your turn, when you put Jolteon Star from your hand onto your Bench, you may put 1 damage counter on each Active Pokémon (both yours and your opponent''s).","type":"Poké-Power"}]','[{"name":"Agility","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Flip a coin. If heads, prevent all effects of an attack, including damage, done to Jolteon Star during your opponent''s next turn."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-30"}]','["Colorless"]',1,'[135]',NULL,'["You can''t have more than 1 Pokémon Star in your deck."]','ex16');
INSERT INTO "Card" VALUES('ex16-102','Vaporeon ★','Pokémon','102','Rare Holo Star','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex16/102.png","large":"https://images.pokemontcg.io/ex16/102_hires.png"}',NULL,'70',NULL,'["Basic","Star"]','["Water"]',NULL,NULL,'[{"name":"Blue Ray","text":"Once during your turn, when you put Vaporeon Star from your hand onto your Bench, you may remove all Special Conditions and 3 damage counters from each Active Pokémon (both yours and your opponent''s).","type":"Poké-Power"}]','[{"name":"Whirlpool","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Flip a coin. If heads, discard an Energy card attached to the Defending Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[134]',NULL,'["You can''t have more than 1 Pokémon Star in your deck."]','ex16');
