INSERT INTO "Card" VALUES('ex2-87','Lanette''s Net Search','Trainer','87','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/87.png","large":"https://images.pokemontcg.io/ex2/87_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 different types of Basic Pokémon cards (excluding Baby Pokémon), show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex2');
INSERT INTO "Card" VALUES('ex2-88','Rare Candy','Trainer','88','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/88.png","large":"https://images.pokemontcg.io/ex2/88_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.)"]','ex2');
INSERT INTO "Card" VALUES('ex2-89','Wally''s Training','Trainer','89','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/89.png","large":"https://images.pokemontcg.io/ex2/89_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for a card that evolves from your Active Pokémon (choose 1 if there are 2) and put it on your Active Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward."]','ex2');
INSERT INTO "Card" VALUES('ex2-90','Claw Fossil','Trainer','90','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/90.png","large":"https://images.pokemontcg.io/ex2/90_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Jagged Stone","text":"If Claw Fossil is your Active Pokémon and is damaged by an opponent''s attack (even if Claw Fossil is Knocked Out), put 1 damage counter on the Attacking Pokémon.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Claw Fossil as if it were a Basic Pokémon. While in play, Claw Fossil counts as a Colorless Pokémon (instead of a Trainer card). Claw Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Claw Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Claw Fossil from play."]','ex2');
INSERT INTO "Card" VALUES('ex2-91','Mysterious Fossil','Trainer','91','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/91.png","large":"https://images.pokemontcg.io/ex2/91_hires.png"}',NULL,'10',NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Colorless Pokémon (instead of a Trainer card). Mysterious Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Mysterious is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play."]','ex2');
INSERT INTO "Card" VALUES('ex2-92','Root Fossil','Trainer','92','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/92.png","large":"https://images.pokemontcg.io/ex2/92_hires.png"}',NULL,'40',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Spongy Stone","text":"At any time between turns, remove 1 damage counter from Root Fossil.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Root Fossil as if it were a Basic Pokémon. While in play, Root Fossil counts as a Colorless Pokémon (instead of a Trainer card). Root Fossil has no attacks of its own, can''t retreat, and can''t be affected by any Special Conditions. If Root Fossil is Knocked Out, it doesn''t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Root Fossil from play."]','ex2');
INSERT INTO "Card" VALUES('ex2-93','Multi Energy','Energy','93','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex2/93.png","large":"https://images.pokemontcg.io/ex2/93_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Doesn''t count as a basic Energy card when not in play.) Multi energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it."]','ex2');
