INSERT INTO "Card" VALUES('ex3-82','Balloon Berry','Trainer','82','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex3/82.png","large":"https://images.pokemontcg.io/ex3/82_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Balloon Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","When the Pokémon Balloon Berry is attached to retreats, discard Balloon Berry instead of discarding Energy cards."]','ex3');
INSERT INTO "Card" VALUES('ex3-83','Buffer Piece','Trainer','83','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex3/83.png","large":"https://images.pokemontcg.io/ex3/83_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Buffer Piece to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","Damage done to the Pokémon Buffer Piece is attached to by an opponent''s attack is reduced by 20 (after applying Weakness and Resistance). At the end of your opponent''s turn after you played Buffer Piece, discard Buffer Piece."]','ex3');
