INSERT INTO "Card" VALUES('ex6-104','Blastoise ex','Pokémon','104','Rare Holo EX','Hikaru Koike',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex6/104.png","large":"https://images.pokemontcg.io/ex6/104_hires.png"}',NULL,'150',NULL,'["Stage 2","ex"]','["Water"]','Wartortle',NULL,'[{"name":"Energy Rain","text":"As often as you like during your turn (before your attack), you may attach a Water Energy card from your hand to 1 of your Pokémon. Put 1 damage counter on that Pokémon. This power can''t be used if Blastoise ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Hyper Whirlpool","cost":["Water","Water","Water","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"Flip a coin until you get tails. For each heads, your opponent discards an Energy card attached to the Defending Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[9]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex6');
