INSERT INTO "Card" VALUES('ex7-83','Copycat','Trainer','83','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/83.png","large":"https://images.pokemontcg.io/ex7/83_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck. Then, count the number of cards in your opponent''s hand and draw that many cards."]','ex7');
INSERT INTO "Card" VALUES('ex7-84','Pokémon Retriever','Trainer','84','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/84.png","large":"https://images.pokemontcg.io/ex7/84_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your discard pile for Basic Pokémon and Evolution cards. You may either show 1 Basic Pokémon or Evolution card to your opponent and put it into your hand, or show a combination of 3 Basic Pokémon or Evolution cards to your opponent and shuffle them into your deck."]','ex7');
INSERT INTO "Card" VALUES('ex7-85','Pow! Hand Extension','Trainer','85','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/85.png","large":"https://images.pokemontcg.io/ex7/85_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may use this card only if you have more Prize cards left than your opponent.","Move 1 Energy card attached to the Defending Pokémon to another of your opponent''s Pokémon. Or, switch 1 of your opponent''s Benched Pokémon with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch."]','ex7');
INSERT INTO "Card" VALUES('ex7-86','Rocket''s Admin.','Trainer','86','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/86.png","large":"https://images.pokemontcg.io/ex7/86_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Each player shuffles his or her hand into his or her deck. Then, each player counts his or her Prize cards left and draws up to that many cards. (You draw your cards first.)"]','ex7');
INSERT INTO "Card" VALUES('ex7-87','Rocket''s Hideout','Trainer','87','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/87.png","large":"https://images.pokemontcg.io/ex7/87_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each Pokémon with Dark or Rocket''s in its name (both yours and your opponent''s) gets +20 HP."]','ex7');
INSERT INTO "Card" VALUES('ex7-88','Rocket''s Mission','Trainer','88','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/88.png","large":"https://images.pokemontcg.io/ex7/88_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Discard a card from your hand. Then, draw 3 cards. If you discarded a Pokémon that has Dark or Rocket''s in its name, draw 4 cards instead."]','ex7');
INSERT INTO "Card" VALUES('ex7-89','Rocket''s Poké Ball','Trainer','89','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/89.png","large":"https://images.pokemontcg.io/ex7/89_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon with Dark in its name, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','ex7');
INSERT INTO "Card" VALUES('ex7-90','Rocket''s Tricky Gym','Trainer','90','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/90.png","large":"https://images.pokemontcg.io/ex7/90_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,'[{"name":"Feint Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Does 20 damage to 1 of your opponent''s Pokémon. This attack''s damage isn''t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each Pokémon with Dark or Rocket''s in its name (both yours and your opponent''s) can use attacks on this card instead of its own."]','ex7');
INSERT INTO "Card" VALUES('ex7-91','Surprise! Time Machine','Trainer','91','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/91.png","large":"https://images.pokemontcg.io/ex7/91_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Evolved Pokémon, remove the highest Stage Evolution card from it, and shuffle it into your deck (this counts as devolving that Pokémon). If that Pokémon remains in play, search your deck for an Evolution card that evolves from that Pokémon and put it onto that Pokémon (this counts as evolving that Pokémon). Shuffle your deck afterward."]','ex7');
INSERT INTO "Card" VALUES('ex7-92','Swoop! Teleporter','Trainer','92','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/92.png","large":"https://images.pokemontcg.io/ex7/92_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Pokémon (excluding Pokémon-ex) and switch it with 1 of your Basic Pokémon (excluding Pokémon-ex) in play. (Any cards attached to that Pokémon, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) Place the first Basic Pokémon in the discard pile. Shuffle your deck afterward."]','ex7');
INSERT INTO "Card" VALUES('ex7-93','Venture Bomb','Trainer','93','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex7/93.png","large":"https://images.pokemontcg.io/ex7/93_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, put 1 damage counter on 1 of your opponent''s Pokémon. If tails, put 1 damage counter on 1 of your Pokémon."]','ex7');
