INSERT INTO "Card" VALUES('ex8-84','Balloon Berry','Trainer','84','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/84.png","large":"https://images.pokemontcg.io/ex8/84_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Balloon Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as Balloon Berry is attached to a Pokémon, that Pokémon''s Retreat Cost is 0. When this Pokémon retreats, discard Balloon Berry."]','ex8');
INSERT INTO "Card" VALUES('ex8-85','Crystal Shard','Trainer','85','Uncommon','Jungo Suzuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/85.png","large":"https://images.pokemontcg.io/ex8/85_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Crystal Shard to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as this card is attached to a Pokémon, that Pokémon''s type is Colorless. If that Pokémon attacks, discard this card at the end of the turn."]','ex8');
INSERT INTO "Card" VALUES('ex8-86','Energy Charge','Trainer','86','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/86.png","large":"https://images.pokemontcg.io/ex8/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your discard pile for 2 Energy cards (1 if there is only 1), show them to your opponent, and shuffle them into your deck."]','ex8');
INSERT INTO "Card" VALUES('ex8-87','Lady Outing','Trainer','87','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/87.png","large":"https://images.pokemontcg.io/ex8/87_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 different types of basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex8');
INSERT INTO "Card" VALUES('ex8-88','Master Ball','Trainer','88','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/88.png","large":"https://images.pokemontcg.io/ex8/88_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards from your deck. Choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, and put it into your hand. Put the other 6 cards back on top of your deck. Shuffle your deck afterward."]','ex8');
INSERT INTO "Card" VALUES('ex8-89','Meteor Falls','Trainer','89','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/89.png","large":"https://images.pokemontcg.io/ex8/89_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each player''s Active Evolved Pokémon (excluding Pokémon-ex) can use any attack from its Basic Pokémon or its Stage 1 Evolution card. (You still have to pay for that attack''s Energy cost.)"]','ex8');
INSERT INTO "Card" VALUES('ex8-90','Professor Cozmo''s Discovery','Trainer','90','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/90.png","large":"https://images.pokemontcg.io/ex8/90_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Flip a coin. If heads, draw the bottom 3 cards of your deck. If tails, draw the top 2 cards of your deck."]','ex8');
INSERT INTO "Card" VALUES('ex8-91','Space Center','Trainer','91','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/91.png","large":"https://images.pokemontcg.io/ex8/91_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Ignore Poké-Bodies for all Basic Pokémon in play (both yours and your opponent''s) (excluding Pokémon-ex and Pokémon that has an owner in its name)."]','ex8');
INSERT INTO "Card" VALUES('ex8-92','Strength Charm','Trainer','92','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/92.png","large":"https://images.pokemontcg.io/ex8/92_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Strength Charm to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","Whenever an attack from the Pokémon that Strength Charm is attached to does damage to the Active Pokémon, the attack does 10 more damage (before applying Weakness and Resistance). Discard Strength Charm at the end of the turn in which this Pokémon attacks."]','ex8');
INSERT INTO "Card" VALUES('ex8-93','Boost Energy','Energy','93','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/93.png","large":"https://images.pokemontcg.io/ex8/93_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Boost Energy can be attached only to an Evolved Pokémon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides ColorlessColorlessColorless Energy. The Pokémon Boost Energy is attached to can''t retreat. If the Pokémon Boost Energy is attached to isn''t an Evolved Pokémon, discard Boost Energy."]','ex8');
INSERT INTO "Card" VALUES('ex8-94','Heal Energy','Energy','94','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/94.png","large":"https://images.pokemontcg.io/ex8/94_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Heal Energy provides Colorless Energy. When you attach this card from your hand to 1 of your Pokémon, remove 1 damage counter and all Special Conditions from that Pokémon. If Heal Energy is attached to Pokémon-ex, Heal Energy has no effect other than providing Energy."]','ex8');
INSERT INTO "Card" VALUES('ex8-95','Scramble Energy','Energy','95','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/95.png","large":"https://images.pokemontcg.io/ex8/95_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Scramble Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). Scramble Energy provides Colorless Energy. While in play, if you have more Prize cards left than your opponent, Scramble Energy provides every type of Energy but provides only 3 in any combination at a time. If the Pokémon Scramble Energy is attached to isn''t an Evolved Pokémon (or evolves into Pokémon-ex), discard Scramble Energy."]','ex8');
INSERT INTO "Card" VALUES('ex8-96','Crobat ex','Pokémon','96','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex8/96.png","large":"https://images.pokemontcg.io/ex8/96_hires.png"}',NULL,'130',NULL,'["Stage 2","ex"]','["Grass"]','Golbat',NULL,'[{"name":"Distortion","text":"Once during your turn (before your attack), if Crobat ex is your Active Pokémon, you may put 1 damage counter on 1 of your opponent''s Pokémon. This power can''t be used if Crobat ex is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Cross Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 4 coins. This attack does 20 damage times the number of heads. If you get 2 or more heads, the Defending Pokémon is now Confused."},{"name":"Pester","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"If the Defending Pokémon is affected by a Special Condition, this attack does 60 damage plus 40 more damage."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[169]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex8');
