INSERT INTO "Card" VALUES('ex9-75','Battle Frontier','Trainer','75','Uncommon','Midori Harada',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/75.png","large":"https://images.pokemontcg.io/ex9/75_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each player''s Colorless Evolved Pokémon, Darkness Evolved Pokémon, and Metal Evolved Pokémon can''t use any Poké-Powers or Poké-Bodies."]','ex9');
INSERT INTO "Card" VALUES('ex9-76','Double Full Heal','Trainer','76','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/76.png","large":"https://images.pokemontcg.io/ex9/76_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all Special Conditions from each of your Active Pokémon."]','ex9');
INSERT INTO "Card" VALUES('ex9-77','Lanette''s Net Search','Trainer','77','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/77.png","large":"https://images.pokemontcg.io/ex9/77_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 different types of Basic Pokémon cards (excluding Baby Pokémon), show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex9');
INSERT INTO "Card" VALUES('ex9-78','Lum Berry','Trainer','78','Uncommon','Kazuo Yazawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/78.png","large":"https://images.pokemontcg.io/ex9/78_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Lum Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","At any time between turns, if the Pokémon this card is attached to is affected by any Special Conditions, remove all of them. Then, discard Lum Berry."]','ex9');
INSERT INTO "Card" VALUES('ex9-79','Mr. Stone''s Project','Trainer','79','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/79.png","large":"https://images.pokemontcg.io/ex9/79_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 2 Basic cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. Or, search your discard pile for up to 2 Basic cards, show them to your opponent, and put them into your hand."]','ex9');
INSERT INTO "Card" VALUES('ex9-80','Oran Berry','Trainer','80','Uncommon','Kazuo Yazawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/80.png","large":"https://images.pokemontcg.io/ex9/80_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Oran Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","At any time between turns, if the Pokémon this card is attached to has at least 2 damage counters on it, remove 2 damage counters from it. Then, discard Oran Berry."]','ex9');
INSERT INTO "Card" VALUES('ex9-81','PokéNav','Trainer','81','Uncommon','Katsura Tabata',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/81.png","large":"https://images.pokemontcg.io/ex9/81_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 3 cards of your deck, and choose a Basic Pokémon, Evolution card, or Energy card. Show it to your opponent and put it into your hand. Put the 2 other cards back on top of your deck in any order."]','ex9');
INSERT INTO "Card" VALUES('ex9-82','Professor Birch','Trainer','82','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/82.png","large":"https://images.pokemontcg.io/ex9/82_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw cards from your deck until you have 6 cards in your hand."]','ex9');
INSERT INTO "Card" VALUES('ex9-83','Rare Candy','Trainer','83','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/83.png","large":"https://images.pokemontcg.io/ex9/83_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.)"]','ex9');
INSERT INTO "Card" VALUES('ex9-84','Scott','Trainer','84','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/84.png","large":"https://images.pokemontcg.io/ex9/84_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 cards in any combination of Supporter cards and Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','ex9');
INSERT INTO "Card" VALUES('ex9-85','Wally''s Training','Trainer','85','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/85.png","large":"https://images.pokemontcg.io/ex9/85_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for a card that evolves from your Active Pokémon (choose 1 if there are 2) and put it on your Active Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward."]','ex9');
INSERT INTO "Card" VALUES('ex9-86','Darkness Energy','Energy','86','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/86.png","large":"https://images.pokemontcg.io/ex9/86_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn''t count as a Basic card.)"]','ex9');
INSERT INTO "Card" VALUES('ex9-87','Double Rainbow Energy','Energy','87','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/87.png","large":"https://images.pokemontcg.io/ex9/87_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Has no effect other than providing Energy.) Damage done to your opponent''s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (before applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy."]','ex9');
INSERT INTO "Card" VALUES('ex9-88','Metal Energy','Energy','88','Rare','Milky Isobe',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/88.png","large":"https://images.pokemontcg.io/ex9/88_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn''t Metal. Metal Energy provides Metal Energy. (Doesn''t count as a Basic card.)"]','ex9');
INSERT INTO "Card" VALUES('ex9-89','Multi Energy','Energy','89','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/89.png","large":"https://images.pokemontcg.io/ex9/89_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it."]','ex9');
INSERT INTO "Card" VALUES('ex9-90','Altaria ex','Pokémon','90','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/90.png","large":"https://images.pokemontcg.io/ex9/90_hires.png"}',NULL,'100',NULL,'["Stage 1","ex"]','["Colorless"]','Swablu',NULL,'[{"name":"Mist","text":"Any damage done to Altaria ex by attacks from Stage 2 Evolved Pokémon (both yours and your opponent''s) is reduced by 30 (after applying Weakness and Resistance).","type":"Poké-Body"}]','[{"name":"Dive","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Dragon Mist","cost":["Water","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"This attack''s damage isn''t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon."}]',NULL,NULL,'["Colorless"]',1,'[334]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex9');
INSERT INTO "Card" VALUES('ex9-91','Cacturne ex','Pokémon','91','Rare Holo EX','Hikaru Koike',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/91.png","large":"https://images.pokemontcg.io/ex9/91_hires.png"}',NULL,'110',NULL,'["Stage 1","ex"]','["Grass"]','Cacnea',NULL,'[{"name":"Cursed Glare","text":"As long as Cacturne ex is your Active Pokémon, your opponent can''t attach any Special Energy cards (except for Darkness and Metal Energy cards) from his or her hand to his or her Active Pokémon.","type":"Poké-Body"}]','[{"name":"Psybeam","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":"The Defending Pokémon is now Confused."},{"name":"Spike Rend","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"If the Defending Pokémon already has any damage counters on it, this attack does 50 damage plus 20 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[332]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex9');
INSERT INTO "Card" VALUES('ex9-92','Camerupt ex','Pokémon','92','Rare Holo EX','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/92.png","large":"https://images.pokemontcg.io/ex9/92_hires.png"}',NULL,'120',NULL,'["Stage 1","ex"]','["Fire"]','Numel',NULL,'[{"name":"Magma Armor","text":"Camerupt ex can''t be Asleep or Paralyzed.","type":"Poké-Body"}]','[{"name":"Searing Flame","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"The Defending Pokémon is now Burned."},{"name":"Eruption","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"Each player discards the top card of his or her deck. This attack does 60 damage plus 20 more damage for each Energy card discarded in this way."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[323]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex9');
INSERT INTO "Card" VALUES('ex9-93','Deoxys ex','Pokémon','93','Rare Holo EX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/ex9/93.png","large":"https://images.pokemontcg.io/ex9/93_hires.png"}',NULL,'110',NULL,'["Basic","ex"]','["Psychic"]',NULL,NULL,'[{"name":"Form Change","text":"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can''t use more than 1 Form Change Poké-Power each turn.","type":"Poké-Power"}]','[{"name":"Fastwave","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"This attack''s damage isn''t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[386]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','ex9');
