INSERT INTO "Card" VALUES('g1-39','Dugtrio','Pokémon','39','Rare','Toyste Beach','In battle, it digs through the ground and strikes the unsuspecting foe from an unexpected direction.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/g1/39.png","large":"https://images.pokemontcg.io/g1/39_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fighting"]','Diglett',NULL,NULL,'[{"name":"Earthquake","cost":["Fighting"],"convertedEnergyCost":1,"damage":"60","text":"This attack does 10 damage to each of your Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Rock Tumble","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"This attack''s damage isn''t affected by Resistance."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[51]',NULL,NULL,'g1');
INSERT INTO "Card" VALUES('g1-40','Machop','Pokémon','40','Common','Mina Nakai','It hefts a Graveler repeatedly to strengthen its entire body. It uses every type of martial arts.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/g1/40.png","large":"https://images.pokemontcg.io/g1/40_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fighting"]',NULL,'["Machoke"]',NULL,'[{"name":"Knuckle Punch","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[66]',NULL,NULL,'g1');
