INSERT INTO "Card" VALUES('g1-49','Rhyhorn','Pokémon','49','Common','Midori Harada','It is inept at turning because of its four short legs. It can only charge and run in one direction.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/g1/49.png","large":"https://images.pokemontcg.io/g1/49_hires.png"}',NULL,'80',NULL,'["Basic"]','["Fighting"]',NULL,'["Rhydon"]',NULL,'[{"name":"Take Down","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"40","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[111]',NULL,NULL,'g1');
