INSERT INTO "Card" VALUES('g1-52','Mr. Mime','Pokémon','52','Uncommon','kirisAki','It is adept at conning people. It is said to be able to create walls out of thin air by miming.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/g1/52.png","large":"https://images.pokemontcg.io/g1/52_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fairy"]',NULL,NULL,'[{"name":"Bench Barrier","text":"Prevent all damage done to your Benched Pokémon by attacks.","type":"Ability"}]','[{"name":"Juggling","cost":["Fairy","Colorless"],"convertedEnergyCost":2,"damage":"10×","text":"Flip 4 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[122]',NULL,NULL,'g1');
INSERT INTO "Card" VALUES('g1-53','Meowth','Pokémon','53','Common','kirisAki','Adores round objects. It wanders the streets on a nightly basis to look for dropped loose change.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/g1/53.png","large":"https://images.pokemontcg.io/g1/53_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Persian"]',NULL,'[{"name":"Exhausted Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, this attack does 30 damage to your opponent''s Active Pokémon. If tails, this Pokémon does 30 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[52]',NULL,NULL,'g1');
