INSERT INTO "Card" VALUES('gym1-99','Charity','Trainer','99','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/99.png","large":"https://images.pokemontcg.io/gym1/99_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Charity to your Active Pokémon. Unless that Pokémon gets Knocked Out, return Charity to your hand at the end of your turn. If that Pokémon attacks and does damage to the Defending Pokémon, you may reduce that damage by any amount (rounded to the nearest 10)."]','gym1');
INSERT INTO "Card" VALUES('gym1-100','Erika','Trainer','100','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/100.png","large":"https://images.pokemontcg.io/gym1/100_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may draw up to 3 cards, then your opponent may draw up to 3 cards."]','gym1');
INSERT INTO "Card" VALUES('gym1-101','Lt. Surge','Trainer','101','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/101.png","large":"https://images.pokemontcg.io/gym1/101_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you have at least 1 Basic Pokémon card in your hand. Put a Basic Pokémon card from your hand into play as your Active Pokémon. Put your old Active Pokémon onto your Bench. (You can''t play this card if your Bench is full.)"]','gym1');
INSERT INTO "Card" VALUES('gym1-102','Misty','Trainer','102','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/102.png","large":"https://images.pokemontcg.io/gym1/102_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 of the other cards in your hand in order to play this card. If this turn''s attack does damage to the Defending Pokémon (after applying Weakness and Resistance), and if the attacking Pokémon has Misty in its name, the attack does 20 more damage to the Defending Pokémon."]','gym1');
INSERT INTO "Card" VALUES('gym1-103','No Removal Gym','Trainer','103','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/103.png","large":"https://images.pokemontcg.io/gym1/103_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","A player must discard 2 cards from his or her hand in order to play an Energy Removal or Super Energy Removal card."]','gym1');
INSERT INTO "Card" VALUES('gym1-104','The Rocket''s Training Gym','Trainer','104','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/104.png","large":"https://images.pokemontcg.io/gym1/104_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each player pays Colorless more to retreat his or her Active Pokémon."]','gym1');
INSERT INTO "Card" VALUES('gym1-105','Blaine''s Last Resort','Trainer','105','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/105.png","large":"https://images.pokemontcg.io/gym1/105_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t play this card if you have any cards in your hand other than Blaine''s Last Resort. Show your hand to your opponent, then draw 5 cards."]','gym1');
INSERT INTO "Card" VALUES('gym1-106','Brock''s Training Method','Trainer','106','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/106.png","large":"https://images.pokemontcg.io/gym1/106_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Pokémon or Evolution card with Brock in its name. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward."]','gym1');
INSERT INTO "Card" VALUES('gym1-107','Celadon City Gym','Trainer','107','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/107.png","large":"https://images.pokemontcg.io/gym1/107_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","During each player''s turn, that player may choose to discard an Energy card attached to 1 of his or her Pokémon with Erika in its name. If that player does so, that Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned."]','gym1');
INSERT INTO "Card" VALUES('gym1-108','Cerulean City Gym','Trainer','108','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/108.png","large":"https://images.pokemontcg.io/gym1/108_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each player pays Colorless less to retreat his or her Pokémon if it has Misty in its name."]','gym1');
INSERT INTO "Card" VALUES('gym1-109','Erika''s Maids','Trainer','109','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/109.png","large":"https://images.pokemontcg.io/gym1/109_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Trade 2 of the other cards in your hand for up to 2 Basic Pokémon and/or Evolution cards with Erika in their names from your deck. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward."]','gym1');
INSERT INTO "Card" VALUES('gym1-110','Erika''s Perfume','Trainer','110','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/110.png","large":"https://images.pokemontcg.io/gym1/110_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your opponent''s hand. If he or she has any Basic Pokémon cards there, you may put any number of them onto your opponent''s Bench (as long as there''s room)."]','gym1');
INSERT INTO "Card" VALUES('gym1-111','Good Manners','Trainer','111','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/111.png","large":"https://images.pokemontcg.io/gym1/111_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["In order to play this card, you can''t have any Basic Pokémon cards in your hand. Show your hand to your opponent, then search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','gym1');
INSERT INTO "Card" VALUES('gym1-112','Lt. Surge''s Treaty','Trainer','112','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/112.png","large":"https://images.pokemontcg.io/gym1/112_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent chooses 1 of the following: everyone chooses 1 of his or her own Prizes and put it into his or her hand, or you draw a card."]','gym1');
INSERT INTO "Card" VALUES('gym1-113','Minion of Team Rocket','Trainer','113','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/113.png","large":"https://images.pokemontcg.io/gym1/113_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. If both of them are heads, choose 1 of your opponent''s Benched Pokémon and return it and all cards attached to it to his or her hand. If 1 or both of them are tails, your turn ends immediately (you can''t attack this turn)."]','gym1');
INSERT INTO "Card" VALUES('gym1-114','Misty''s Wrath','Trainer','114','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/114.png","large":"https://images.pokemontcg.io/gym1/114_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards of your deck. Choose 2 of those cards and put them into your hand. Discard the rest."]','gym1');
INSERT INTO "Card" VALUES('gym1-115','Pewter City Gym','Trainer','115','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/115.png","large":"https://images.pokemontcg.io/gym1/115_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Don''t apply Resistance to any attacks made by Pokémon with Brock in their names."]','gym1');
INSERT INTO "Card" VALUES('gym1-116','Recall','Trainer','116','Uncommon','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/116.png","large":"https://images.pokemontcg.io/gym1/116_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["For your attack this turn, your Active Pokémon can use any attack from its Basic Pokémon card or any Evolution card attached to it. (You still have to pay for that attack''s Energy cost.)"]','gym1');
INSERT INTO "Card" VALUES('gym1-117','Sabrina''s ESP','Trainer','117','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/117.png","large":"https://images.pokemontcg.io/gym1/117_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Sabrina''s ESP to 1 of your Pokémon with Sabrina in its name. At the end of your turn, discard Sabrina''s ESP. If that Pokémon uses and attack that involves flipping coins, Sabrina''s ESP lets you re-flip those coins once. If you do, re-flip all the coins."]','gym1');
INSERT INTO "Card" VALUES('gym1-118','Secret Mission','Trainer','118','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/118.png","large":"https://images.pokemontcg.io/gym1/118_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your opponent''s hand. Then, you may discard as many other cards as you want from your hand and draw that many cards."]','gym1');
INSERT INTO "Card" VALUES('gym1-119','Tickling Machine','Trainer','119','Uncommon','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/119.png","large":"https://images.pokemontcg.io/gym1/119_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, your opponent sets aside all the cards in his or her hand face down. Nobody may look at those cards. At the end of your opponent''s next turn, your opponent puts those cards back into his or her hand. If tails, your turn ends immediately (you can''t attack this turn)."]','gym1');
INSERT INTO "Card" VALUES('gym1-120','Vermilion City Gym','Trainer','120','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/120.png","large":"https://images.pokemontcg.io/gym1/120_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Whenever a player attacks with a Pokémon with Lt. Surge in its name, he or she may flip a coin. If heads, and if that Pokémon''s attack does damage to the Defending Pokémon (after applying Weakness and Resistance), that attack does 10 more damage to the Defending Pokémon. If tails, the attacking Pokémon does 10 damage to itself in addition to whatever its attack usually does."]','gym1');
INSERT INTO "Card" VALUES('gym1-121','Blaine''s Gamble','Trainer','121','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/121.png","large":"https://images.pokemontcg.io/gym1/121_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard any number of other cards from your hand, then flip a coin. If heads, draw twice that many cards."]','gym1');
INSERT INTO "Card" VALUES('gym1-122','Energy Flow','Trainer','122','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/122.png","large":"https://images.pokemontcg.io/gym1/122_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["For each of your Pokémon, you may return any number of Energy cards attached to it to your hand."]','gym1');
INSERT INTO "Card" VALUES('gym1-123','Misty''s Duel','Trainer','123','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/123.png","large":"https://images.pokemontcg.io/gym1/123_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You and your opponent play a game of Rock-Paper-Scissors. The winner shuffles his or her hand into his or her deck and draws a new hand of 5 cards. (If you don''t know how to play Rock-Paper-Scissors, flip a coin to decide who''s the winner.)"]','gym1');
INSERT INTO "Card" VALUES('gym1-124','Narrow Gym','Trainer','124','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/124.png","large":"https://images.pokemontcg.io/gym1/124_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","No player may have more than 4 Pokémon on his or her Bench. When this card is played, if a player has 5 Pokémon on his or her Bench, that player chooses 1 of them and returns it and all cards attached to it to his or her hand. (If both players have to return a Pokémon, your opponent returns a Pokémon first.)"]','gym1');
INSERT INTO "Card" VALUES('gym1-125','Sabrina''s Gaze','Trainer','125','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/125.png","large":"https://images.pokemontcg.io/gym1/125_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player shuffles his or her hand into his or her deck and draws a new hand of the same number of cards."]','gym1');
INSERT INTO "Card" VALUES('gym1-126','Trash Exchange','Trainer','126','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/126.png","large":"https://images.pokemontcg.io/gym1/126_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Count the number of cards in your discard pile and shuffle them into your deck. Then discard that many cards from the top of your deck."]','gym1');
INSERT INTO "Card" VALUES('gym1-127','Fighting Energy','Energy','127',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/127.png","large":"https://images.pokemontcg.io/gym1/127_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym1-128','Fire Energy','Energy','128',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/128.png","large":"https://images.pokemontcg.io/gym1/128_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym1-129','Grass Energy','Energy','129',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/129.png","large":"https://images.pokemontcg.io/gym1/129_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym1-130','Lightning Energy','Energy','130',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/130.png","large":"https://images.pokemontcg.io/gym1/130_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym1-131','Psychic Energy','Energy','131',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/131.png","large":"https://images.pokemontcg.io/gym1/131_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym1-132','Water Energy','Energy','132',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym1/132.png","large":"https://images.pokemontcg.io/gym1/132_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym1');
INSERT INTO "Card" VALUES('gym2-1','Blaine''s Arcanine','Pokémon','1','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/1.png","large":"https://images.pokemontcg.io/gym2/1_hires.png"}',NULL,'90','42','["Stage 1"]','["Fire"]','Blaine''s Growlithe',NULL,NULL,'[{"name":"Heat Tackle","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Blaine''s Arcanine does 10 damage to itself."},{"name":"Firestorm","cost":["Fire","Fire","Fire","Fire"],"convertedEnergyCost":4,"damage":"120","text":"Discard 3 Fire Energy cards attached to Blaine''s Arcanine in order to use this attack."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[59]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-2','Blaine''s Charizard','Pokémon','2','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/2.png","large":"https://images.pokemontcg.io/gym2/2_hires.png"}',NULL,'100','50','["Stage 2"]','["Fire"]','Blaine''s Charmeleon',NULL,NULL,'[{"name":"Roaring Flames","cost":["Fire"],"convertedEnergyCost":1,"damage":"20+","text":"Discard all Fire Energy cards attached to Blaine''s Charizard. If all Energy cards attached to Blaine''s Charizard provide 2 Fire Energy, discard all of them. This attack does 20 damage plus 20 more damage for each Fire Energy discarded in this way."},{"name":"Flame Jet","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, choose 1 of your opponent''s Pokémon. This attack does 40 damage to that Pokémon. Don''t apply Weakness and Resistance for this attack. (Any other effects that would happen after applying Weakness and Resistance still happen.)"}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[6]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-3','Brock''s Ninetales','Pokémon','3','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/3.png","large":"https://images.pokemontcg.io/gym2/3_hires.png"}',NULL,'70','30','["Stage 1"]','["Fire"]','Brock''s Vulpix',NULL,'[{"name":"Shapeshift","text":"Once during your turn (before your attack), you may attach an Evolution card from your hand to Brock''s Ninetales. (This doesn''t count as evolving Brock''s Ninetales.) Treat Brock''s Ninetales as if it were that Pokémon instead. It can''t evolve, devolve, or use the Pokémon Power of that Pokémon. During your turn, you may discard the Evolution card attached to Brock''s Ninetales. This power can''t be used if Brock''s Ninetales is Asleep, Confused, or Paralyzed. If Brock''s Ninetales becomes Asleep, Confused, or Paralyzed, discard all Evolution cards attached to it.","type":"Pokémon Power"}]','[{"name":"Will-o''-the-wisp","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[38]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-4','Erika''s Venusaur','Pokémon','4','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/4.png","large":"https://images.pokemontcg.io/gym2/4_hires.png"}',NULL,'90','45','["Stage 2"]','["Grass"]','Erika''s Ivysaur',NULL,NULL,'[{"name":"Growth","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, you may attach up to 2 Grass Energy cards from your hand to Erika''s Venusaur."},{"name":"Wide Solarbeam","cost":["Grass","Grass","Grass","Grass"],"convertedEnergyCost":4,"damage":"20","text":"If your opponent has any Benched Pokémon, choose 2 of them (or 1 if he or she only has 1). This attack does 20 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[3]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-5','Giovanni''s Gyarados','Pokémon','5','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/5.png","large":"https://images.pokemontcg.io/gym2/5_hires.png"}',NULL,'90','40','["Stage 1"]','["Water"]','Giovanni''s Magikarp',NULL,NULL,'[{"name":"Summon Storm","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Flip 2 coins. If both of them are heads, this attack does 20 damage to each other Pokémon (even your own). Don''t apply Weakness and Resistance for this attack."},{"name":"Dragon Tornado","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"40","text":"Unless this attack Knocks Out the Defending Pokémon, choose 1 of your opponent''s Benched Pokémon and switch it with the Defending Pokémon."}]','[{"type":"Grass","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[130]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-6','Giovanni''s Machamp','Pokémon','6','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/6.png","large":"https://images.pokemontcg.io/gym2/6_hires.png"}',NULL,'100','50','["Stage 2"]','["Fighting"]','Giovanni''s Machoke',NULL,'[{"name":"Fortitude","text":"If Giovanni''s Machamp would be Knocked Out by an opponent''s attack, flip a coin. If heads, Giovanni''s Machamp is not Knocked Out and its remaining HP become 10 instead. This power can''t be used if Giovanni''s Machamp is already Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Hurricane Punch","cost":["Fighting","Fighting","Fighting","Colorless"],"convertedEnergyCost":4,"damage":"30×","text":"Flip 4 coins. This attack does 30 damage times the number of heads."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[68]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-7','Giovanni''s Nidoking','Pokémon','7','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/7.png","large":"https://images.pokemontcg.io/gym2/7_hires.png"}',NULL,'120','58','["Stage 2"]','["Grass"]','Giovanni''s Nidorino',NULL,NULL,'[{"name":"Intimidate","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"If the Defending Pokémon''s maximum HP is 50 or less, it can''t attack Giovanni''s Nidoking during your opponent''s next turn. (Benching or evolving either Pokémon ends this effect.)"},{"name":"Tumbling Attack","cost":["Grass","Grass","Grass","Colorless"],"convertedEnergyCost":4,"damage":"40+","text":"Flip a coin. If heads, this attack does 40 damage plus 30 more damage; if tails, this attack does 40 damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[34]',NULL,NULL,'gym2');
