INSERT INTO "Card" VALUES('gym2-14','Rocket''s Mewtwo','Pokémon','14','Rare Holo','Shin-ichi Yoshida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/14.png","large":"https://images.pokemontcg.io/gym2/14_hires.png"}',NULL,'70','35','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Juxtapose","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, switch the number of damage counters on Rocket''s Mewtwo with the number of damage counters on the Defending Pokémon (even if it would Knock Out either Pokémon). (It''s okay if 1 of the Pokémon has no damage counters on it.)"},{"name":"Hypnoblast","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Asleep."},{"name":"Psyburn","cost":["Psychic","Psychic","Psychic","Colorless"],"convertedEnergyCost":4,"damage":"60","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,NULL,'gym2');
