INSERT INTO "Card" VALUES('gym2-17','Blaine','Trainer','17','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/17.png","large":"https://images.pokemontcg.io/gym2/17_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During this turn, instead of attaching your free Energy card, you may instead attach 2 Fire Energy cards to 1 of your Pokémon with Blaine in its name. (Playing additional copies of this card this turn has no effect.)"]','gym2');
