INSERT INTO "Card" VALUES('gym2-93','Sabrina''s Abra','Pokémon','93','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/93.png","large":"https://images.pokemontcg.io/gym2/93_hires.png"}',NULL,'40','12','["Basic"]','["Psychic"]',NULL,'["Kadabra"]',NULL,'[{"name":"Pound","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Synchronize","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"This attack can''t be used unless Sabrina''s Abra and the Defending Pokémon have the same number of Energy cards attached to them."}]','[{"type":"Psychic","value":"×2"}]',NULL,NULL,NULL,'[63]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-94','Sabrina''s Abra','Pokémon','94','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/94.png","large":"https://images.pokemontcg.io/gym2/94_hires.png"}',NULL,'50','18','["Basic"]','["Psychic"]',NULL,'["Kadabra"]',NULL,'[{"name":"Psyscan","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Look at your opponent''s hand."},{"name":"Quick Attack","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[63]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-95','Sabrina''s Drowzee','Pokémon','95','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/95.png","large":"https://images.pokemontcg.io/gym2/95_hires.png"}',NULL,'50','18','["Basic"]','["Psychic"]',NULL,'["Hypno"]',NULL,'[{"name":"Energy Support","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Psychic Energy card. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward."},{"name":"Mind Shock","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Don''t apply Weakness and Resistance for this attack. (Any other effects that would happen after applying Weakness and Resistance still happen.)"}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[96]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-96','Sabrina''s Gastly','Pokémon','96','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/96.png","large":"https://images.pokemontcg.io/gym2/96_hires.png"}',NULL,'30','9','["Basic"]','["Psychic"]',NULL,'["Haunter"]',NULL,'[{"name":"Lick","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Fade Out","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"30","text":"Return Sabrina''s Gastly and all Energy cards attached to it to your hand. (Discard all other cards attached to Sabrina''s Gastly.)"}]',NULL,'[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[92]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-97','Sabrina''s Gastly','Pokémon','97','Common','Atsuko Nishida',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/97.png","large":"https://images.pokemontcg.io/gym2/97_hires.png"}',NULL,'40','10','["Basic"]','["Psychic"]',NULL,'["Haunter"]','[{"name":"Gaseous Form","text":"Sabrina''s Gastly gets +10 HP for each Psychic Energy card attached to it. This power works even if Sabrina''s Gastly is Asleep, Confused, or Paralyzed.","type":"Pokémon Power"}]','[{"name":"Suffocating Gas","cost":["Psychic","Psychic"],"convertedEnergyCost":2,"damage":"30","text":""}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[92]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-98','Sabrina''s Porygon','Pokémon','98','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/98.png","large":"https://images.pokemontcg.io/gym2/98_hires.png"}',NULL,'40','17','["Basic"]','["Colorless"]',NULL,'["Porygon2"]',NULL,'[{"name":"Sharp Point","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Barrier Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"All damage done by attacks to Sabrina''s Porygon during your opponent''s next turn is reduced by 10 (after applying Weakness and Resistance)."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-30"}]','["Colorless"]',1,'[137]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-99','Sabrina''s Psyduck','Pokémon','99','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/99.png","large":"https://images.pokemontcg.io/gym2/99_hires.png"}',NULL,'50','16','["Basic"]','["Water"]',NULL,'["Golduck"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Random ESP","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Confused. If tails, this attack does no damage and Sabrina''s Psyduck is now Confused."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[54]',NULL,NULL,'gym2');
INSERT INTO "Card" VALUES('gym2-100','Blaine','Trainer','100','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/100.png","large":"https://images.pokemontcg.io/gym2/100_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During this turn, instead of attaching your free Energy card, you may instead attach 2 Fire Energy cards to 1 of your Pokémon with Blaine in its name. (Playing additional copies of this card this turn has no effect.)"]','gym2');
INSERT INTO "Card" VALUES('gym2-101','Brock''s Protection','Trainer','101','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/101.png","large":"https://images.pokemontcg.io/gym2/101_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Brock''s Protection to 1 of your Pokémon with Brock in its name. Energy cards attached to that Pokémon can''t be removed by your opponent''s attacks or Trainer cards. (This doesn''t stop the rest of the attack or Trainer card from working normally.)"]','gym2');
INSERT INTO "Card" VALUES('gym2-102','Chaos Gym','Trainer','102','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/102.png","large":"https://images.pokemontcg.io/gym2/102_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Whenever a player plays a Trainer card other than a Stadium card, he or she flips a coin. If heads, that player plays that card normally. If tails, the player can''t play that card. If the card isn''t put into play, the player''s opponent may use that card instead, if he or she does everything required in order to play that card (like discarding cards). Either way, the card goes to its owner''s discard pile."]','gym2');
INSERT INTO "Card" VALUES('gym2-103','Erika''s Kindness','Trainer','103','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/103.png","large":"https://images.pokemontcg.io/gym2/103_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove 2 damage counters from each Pokémon (yours and your opponent''s) with any damage counters on it. If a Pokémon has just 1 damage counter, remove it."]','gym2');
INSERT INTO "Card" VALUES('gym2-104','Giovanni','Trainer','104','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/104.png","large":"https://images.pokemontcg.io/gym2/104_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon in play with Giovanni in its name. For the rest of your turn, you may evolve that Pokémon even if you just played or evolved it this turn or if this is your first turn. This effect also applies to the Pokémon it evolves into."]','gym2');
INSERT INTO "Card" VALUES('gym2-105','Giovanni''s Last Resort','Trainer','105','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/105.png","large":"https://images.pokemontcg.io/gym2/105_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all damage counters from 1 of your Pokémon with Giovanni in its name. Then discard your hand."]','gym2');
INSERT INTO "Card" VALUES('gym2-106','Koga','Trainer','106','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/106.png","large":"https://images.pokemontcg.io/gym2/106_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If an attack from a Pokémon with Koga in its name does damage to a Defending Pokémon this turn, that Pokémon is then Poisoned."]','gym2');
INSERT INTO "Card" VALUES('gym2-107','Lt. Surge''s Secret Plan','Trainer','107','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/107.png","large":"https://images.pokemontcg.io/gym2/107_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 1 card from your hand face down onto your Bench. (You can''t play this card if your Bench is full.) Treat that card as a Basic Pokémon as long as it''s face down. Flip the card if either player needs to know what it is in order to use an attack, a Pokémon Power, or a Trainer card. Flip the card if it ever uses an attack or Pokémon Power, evolves, retreats, is damaged by an attack, or is otherwise affected by an attack. At any time during your turn, you may flip the card over. When you flip that card over, if it isn''t a Basic Pokémon, discard it and all cards attached to it."]','gym2');
INSERT INTO "Card" VALUES('gym2-108','Misty''s Wish','Trainer','108','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/108.png","large":"https://images.pokemontcg.io/gym2/108_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at 1 of your Prize cards. Then, ask your opponent if you may switch that card with 1 of the cards in your hand. If your opponent accepts and if you have any other cards in your hand, switch those cards. If your opponent declines, return the Prize card face down and draw a card."]','gym2');
INSERT INTO "Card" VALUES('gym2-109','Resistance Gym','Trainer','109','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/109.png","large":"https://images.pokemontcg.io/gym2/109_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Each Pokémon''s Resistance is reduced by 20. (If a Pokémon''s Resistance is -30, it becomes -10.)"]','gym2');
INSERT INTO "Card" VALUES('gym2-110','Sabrina','Trainer','110','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/110.png","large":"https://images.pokemontcg.io/gym2/110_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Take all Energy cards attached to 1 of your Pokémon with Sabrina in its name and attach them to another 1 of your Pokémon with Sabrina in its name."]','gym2');
INSERT INTO "Card" VALUES('gym2-111','Blaine''s Quiz #2','Trainer','111','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/111.png","large":"https://images.pokemontcg.io/gym2/111_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a card from your hand face down in front of you. Your opponent guesses whether it is an Energy card, a Trainer card, or a Pokémon (Basic or Evolution) card. Flip the card over. If your opponent guessed right, he or she draws 2 cards. If your opponent guessed wrong, you draw 2 cards. Either way, return the card to your hand."]','gym2');
INSERT INTO "Card" VALUES('gym2-112','Blaine''s Quiz #3','Trainer','112','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/112.png","large":"https://images.pokemontcg.io/gym2/112_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Basic or Evolution card from your hand face down in front of you and tell your opponent the name of an attack of that card. Your opponent guesses the name of that card. Flip the card over. If your opponent guessed right, he or she draws 3 cards. If your opponent guessed wrong, you draw 3 cards. Either way, return the card to your hand."]','gym2');
INSERT INTO "Card" VALUES('gym2-113','Cinnabar City Gym','Trainer','113','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/113.png","large":"https://images.pokemontcg.io/gym2/113_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Ignore Weakness when a Water Pokémon does damage to a Pokémon with Blaine in its name."]','gym2');
INSERT INTO "Card" VALUES('gym2-114','Fuchsia City Gym','Trainer','114','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/114.png","large":"https://images.pokemontcg.io/gym2/114_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may flip a coin. If heads, that player may shuffle 1 of his or her Pokémon in play with Koga in its name and any cards attached to it into his or her deck."]','gym2');
INSERT INTO "Card" VALUES('gym2-115','Koga''s Ninja Trick','Trainer','115','Uncommon','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/115.png","large":"https://images.pokemontcg.io/gym2/115_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Koga''s Ninja Trick to your Active Pokémon with Koga in its name. If this Pokémon goes to your Bench, discard this card. When your opponent attacks, you may switch this Pokémon with 1 of your Benched Pokémon (before damage or other effects of attacks)."]','gym2');
INSERT INTO "Card" VALUES('gym2-116','Master Ball','Trainer','116','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/116.png","large":"https://images.pokemontcg.io/gym2/116_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at 7 cards from the top of your deck. You may choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, then put it into your hand. Shuffle the rest into your deck."]','gym2');
INSERT INTO "Card" VALUES('gym2-117','Max Revive','Trainer','117','Uncommon','Hikaru Koike',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/117.png","large":"https://images.pokemontcg.io/gym2/117_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 2 Energy cards from your hand in order to put 1 Basic Pokémon from your discard pile onto your Bench. (You can''t play Max Revive if your Bench is full.)"]','gym2');
INSERT INTO "Card" VALUES('gym2-118','Misty''s Tears','Trainer','118','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/118.png","large":"https://images.pokemontcg.io/gym2/118_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard 1 of the other cards in your hand in order to search your deck for up to 2 Water Energy cards. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward."]','gym2');
INSERT INTO "Card" VALUES('gym2-119','Rocket''s Minefield Gym','Trainer','119','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/119.png","large":"https://images.pokemontcg.io/gym2/119_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Whenever a player puts a Basic Pokémon onto his or her Bench from his or her hand, he or she flips a coin. If tails, put damage counters on that Pokémon."]','gym2');
INSERT INTO "Card" VALUES('gym2-120','Rocket''s Secret Experiment','Trainer','120','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/120.png","large":"https://images.pokemontcg.io/gym2/120_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for any card and put it into your hand. Shuffle your deck afterward. If tails, you can''t play Trainer cards until the end of your next turn."]','gym2');
INSERT INTO "Card" VALUES('gym2-121','Sabrina''s Psychic Control','Trainer','121','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/121.png","large":"https://images.pokemontcg.io/gym2/121_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, choose a Trainer card in your opponent''s discard pile that isn''t put in play (like PlusPower or Mysterious Fossil). You may use that card as if it were in your hand, if you do everything required in order to play that card (like discarding cards). The card stays in your opponent''s discard pile."]','gym2');
INSERT INTO "Card" VALUES('gym2-122','Saffron City Gym','Trainer','122','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/122.png","large":"https://images.pokemontcg.io/gym2/122_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","As often as each player like during his or her turn (before attacking), that player may return 1 basic Energy card attached to 1 of his or her Pokémon with Sabrina in its name to his or her hand."]','gym2');
INSERT INTO "Card" VALUES('gym2-123','Viridian City Gym','Trainer','123','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/123.png","large":"https://images.pokemontcg.io/gym2/123_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play after being played. Discard this card if another Stadium card comes into play.","Whenever a Pokémon with Giovanni in its name evolves, its owner removes 2 damage counters from that Pokémon (or 1 if it only has 1)."]','gym2');
INSERT INTO "Card" VALUES('gym2-124','Fervor','Trainer','124','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/124.png","large":"https://images.pokemontcg.io/gym2/124_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Show the top 3 cards of your deck to all players. Put any Fire Energy cards there into your hand and discard the rest."]','gym2');
INSERT INTO "Card" VALUES('gym2-125','Transparent Walls','Trainer','125','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/125.png","large":"https://images.pokemontcg.io/gym2/125_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Until the end of your opponent''s next turn, prevent all damage from attacks done to your Benched Pokémon. (Any other effects of attacks still happen.)"]','gym2');
INSERT INTO "Card" VALUES('gym2-126','Warp Point','Trainer','126','Common','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/126.png","large":"https://images.pokemontcg.io/gym2/126_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with his or her Active Pokémon, then, if you have any Benched Pokémon, you switch 1 of them with your Active Pokémon."]','gym2');
INSERT INTO "Card" VALUES('gym2-127','Fighting Energy','Energy','127',NULL,'Keiji Kinebuchi',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/gym2/127.png","large":"https://images.pokemontcg.io/gym2/127_hires.png"}',NULL,NULL,NULL,'["Basic"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gym2');
