INSERT INTO "Card" VALUES('hgss1-89','Bill','Trainer','89','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss1/89.png","large":"https://images.pokemontcg.io/hgss1/89_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw 2 cards."]','hgss1');
INSERT INTO "Card" VALUES('hgss1-90','Copycat','Trainer','90','Uncommon','Kanako Eo',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/hgss1/90.png","large":"https://images.pokemontcg.io/hgss1/90_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Shuffle your hand into your deck. Then, draw a number of cards equal to the number of cards in your opponent''s hand."]','hgss1');
