INSERT INTO "Card" VALUES('hgss2-81','Pokémon Circulator','Trainer','81','Uncommon','Hideaki Hakozaki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss2/81.png","large":"https://images.pokemontcg.io/hgss2/81_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon."]','hgss2');
INSERT INTO "Card" VALUES('hgss2-82','Rare Candy','Trainer','82','Uncommon','Noriko Hotta',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/hgss2/82.png","large":"https://images.pokemontcg.io/hgss2/82_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.) If you choose a Stage 2 Pokémon in your hand, put that Pokémon on the Basic Pokémon instead of on a Stage 1 Pokémon."]','hgss2');
INSERT INTO "Card" VALUES('hgss2-83','Super Scoop Up','Trainer','83','Uncommon','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss2/83.png","large":"https://images.pokemontcg.io/hgss2/83_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, return 1 of your Pokémon and all cards attached to it to your hand."]','hgss2');
