INSERT INTO "Card" VALUES('hgss2-87','Steelix','Pokémon','87','Rare Prime','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss2/87.png","large":"https://images.pokemontcg.io/hgss2/87_hires.png"}',NULL,'140',NULL,'["Stage 1","Prime"]','["Metal"]','Onix',NULL,'[{"name":"Perfect Metal","text":"Steelix can''t be affected by any Special Conditions","type":"Poké-Body"}]','[{"name":"Energy Stream","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Search your discard pile for an Energy card and attach it to Steelix."},{"name":"Gaia Crush","cost":["Metal","Metal","Colorless","Colorless","Colorless"],"convertedEnergyCost":5,"damage":"100","text":"You may discard any Stadium card in play."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,NULL,'hgss2');
INSERT INTO "Card" VALUES('hgss2-88','Tyranitar','Pokémon','88','Rare Prime','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss2/88.png","large":"https://images.pokemontcg.io/hgss2/88_hires.png"}',NULL,'160',NULL,'["Stage 2","Prime"]','["Darkness"]','Pupitar',NULL,NULL,'[{"name":"Darkness Howl","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"This attack does 20 damage to each Pokémon in play (both yours and your opponent''s) (excluding any Darkness Pokémon). (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Power Claw","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"This attack''s damage isn''t affected by Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon."},{"name":"Megaton Tail","cost":["Darkness","Darkness","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"120","text":"Discard the top 3 cards of your deck."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[248]',NULL,NULL,'hgss2');
