INSERT INTO "Card" VALUES('hgss3-46','Drifloon','Pokémon','46','Common','Kagemaru Himeno','It is whispered that any child who mistakes Drifloon for a balloon and holds on to it could wind up missing.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/46.png","large":"https://images.pokemontcg.io/hgss3/46_hires.png"}',NULL,'50',NULL,'["Basic"]','["Psychic"]',NULL,'["Drifblim"]',NULL,'[{"name":"Minimize","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, any damage done to Drifloon by attacks is reduced by 20 (after applying Weakness and Resistance)."},{"name":"Pull","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, switch the Defending Pokémon with 1 of your opponent''s Benched Pokémon."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[425]',NULL,NULL,'hgss3');
