INSERT INTO "Card" VALUES('hgss3-71','Burned Tower','Trainer','71','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/71.png","large":"https://images.pokemontcg.io/hgss3/71_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, that player may flip a coin. If heads, the player searches his or her discard pile for a basic Energy card, shows it to his or her opponent, and put it into his or her hand."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-72','Defender','Trainer','72','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/72.png","large":"https://images.pokemontcg.io/hgss3/72_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Defender to 1 of your Pokémon. Discard this card at the end of your opponent''s next turn. Any damage done to the Pokémon Defender is attached to by an opponent''s attack is reduced by 20 (after applying Weakness and Resistance)."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-73','Energy Exchanger','Trainer','73','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/73.png","large":"https://images.pokemontcg.io/hgss3/73_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose an Energy card from your hand, show it to your opponent, and put it on top of your deck. Search your deck for an Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-74','Flower Shop Lady','Trainer','74','Uncommon','Kanako Eo',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/74.png","large":"https://images.pokemontcg.io/hgss3/74_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your discard pile for 3 Pokémon and 3 basic Energy cards. Show them to your opponent and shuffle them into your deck."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-75','Legend Box','Trainer','75','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/75.png","large":"https://images.pokemontcg.io/hgss3/75_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal the top 10 cards of your deck. If you reveal both halves of a Pokémon LEGEND, put those cards onto your Bench and attach all revealed Energy cards to that Pokémon LEGEND. Shuffle the other cards back into your deck. (You can play only 1 Pokémon LEGEND in this way.)"]','hgss3');
INSERT INTO "Card" VALUES('hgss3-76','Ruins of Alph','Trainer','76','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/76.png","large":"https://images.pokemontcg.io/hgss3/76_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each Pokémon in play has no Resistance."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-77','Sage''s Training','Trainer','77','Uncommon','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/77.png","large":"https://images.pokemontcg.io/hgss3/77_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at the top 5 cards of your deck. Choose any 2 cards you find there and put them into your hand. Discard the other cards."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-78','Team Rocket''s Trickery','Trainer','78','Uncommon','Takao Unno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/78.png","large":"https://images.pokemontcg.io/hgss3/78_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw 2 cards. Then, your opponent discards a card from his or her hand."]','hgss3');
INSERT INTO "Card" VALUES('hgss3-79','Darkness Energy','Energy','79','Uncommon','Kent Kanetsuna',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/79.png","large":"https://images.pokemontcg.io/hgss3/79_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect if the Pokémon that Darkness Energy is attached to isn''t Darkness. Darkness Energy provides Darkness Energy. (Doesn''t count as a basic Energy card.)"]','hgss3');
INSERT INTO "Card" VALUES('hgss3-80','Metal Energy','Energy','80','Uncommon','Kent Kanetsuna',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/80.png","large":"https://images.pokemontcg.io/hgss3/80_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn''t Metal Metal Energy provides Metal Energy. (Doesn''t count as a basic Energy card.)"]','hgss3');
INSERT INTO "Card" VALUES('hgss3-81','Espeon','Pokémon','81','Rare Prime','Hideaki Hakozaki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/81.png","large":"https://images.pokemontcg.io/hgss3/81_hires.png"}',NULL,'100',NULL,'["Stage 1","Prime"]','["Psychic"]','Eevee',NULL,'[{"name":"Evolution Memories","text":"Espeon can use the attacks of all Pokémon you have in play that evolve from Eevee as its own. (You still need the necessary Energy to use each attack.)","type":"Poké-Body"}]','[{"name":"Solar Ray","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Remove 1 damage counter from each of your Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[196]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-82','Houndoom','Pokémon','82','Rare Prime','Hideaki Hakozaki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/82.png","large":"https://images.pokemontcg.io/hgss3/82_hires.png"}',NULL,'110',NULL,'["Stage 1","Prime"]','["Darkness"]','Houndour',NULL,'[{"name":"Fire Breath","text":"Once during your turn (before your attack), you may flip a coin. If heads, the Defending Pokémon is now Burned. This power can''t be used if Houndoom is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Dark Clamp","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[229]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-83','Raichu','Pokémon','83','Rare Prime','Takashi Yamaguchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/83.png","large":"https://images.pokemontcg.io/hgss3/83_hires.png"}',NULL,'100',NULL,'["Stage 1","Prime"]','["Lightning"]','Pikachu',NULL,'[{"name":"Voltage Increase","text":"As often as you like during your turn (before your attack), you may move a Lightning Energy attached to 1 of your Pokémon to Raichu. This power can''t be used if Raichu is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Mega Thunderbolt","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"120","text":"Discard all Energy attached to Raichu."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[26]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-84','Scizor','Pokémon','84','Rare Prime','Noriko Hotta',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/84.png","large":"https://images.pokemontcg.io/hgss3/84_hires.png"}',NULL,'100',NULL,'["Stage 1","Prime"]','["Metal"]','Scyther',NULL,'[{"name":"Red Armor","text":"Prevent all damage done to Scizor by attacks from your opponent''s Pokémon that have any Special Energy cards attached to them.","type":"Poké-Body"}]','[{"name":"Metal Scissors","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Does 30 damage plus 20 more damage for each Metal Energy attached to Scizor."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[212]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-85','Slowking','Pokémon','85','Rare Prime','Noriko Hotta',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/85.png","large":"https://images.pokemontcg.io/hgss3/85_hires.png"}',NULL,'100',NULL,'["Stage 1","Prime"]','["Psychic"]','Slowpoke',NULL,'[{"name":"Opponent''s Choice","text":"Once during your turn (before your attack), you may reveal the top 2 cards of your deck and your opponent chooses 1 of them. Put that card into your hand and the other card on the bottom of your deck. This power can''t be used if Slowking is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Super Psy Bolt","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[199]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-86','Umbreon','Pokémon','86','Rare Prime','Hideaki Hakozaki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/86.png","large":"https://images.pokemontcg.io/hgss3/86_hires.png"}',NULL,'100',NULL,'["Stage 1","Prime"]','["Darkness"]','Eevee',NULL,'[{"name":"Cloud-Covered Moon","text":"Once during your turn (before your attack), if Umbreon is your Active Pokémon, you may flip a coin. If heads, return Umbreon and all cards attached to it to your hand. This power can''t be used if Umbreon is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Evoblast","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"Does 50 damage plus 10 more damage for each of your Pokémon in play that evolves from Eevee."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[197]',NULL,NULL,'hgss3');
INSERT INTO "Card" VALUES('hgss3-87','Kyogre & Groudon LEGEND','Pokémon','87','LEGEND','Shinji Higuchi + Sachiko Eba',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/hgss3/87.png","large":"https://images.pokemontcg.io/hgss3/87_hires.png"}',NULL,'150',NULL,'["LEGEND"]','["Water","Fighting"]',NULL,NULL,NULL,'[{"name":"Mega Tidal Wave","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Discard the top 5 cards from your opponent''s deck. This attack does 30 damage times the number of Energy cards you discarded to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Massive Eruption","cost":["Fighting","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100×","text":"Discard the top 5 cards from your deck. This attack does 100 damage times the number of Energy cards you discarded."}]','[{"type":"Lightning","value":"×2"},{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[382,383]',NULL,'["Put this card from your hand onto your Bench only with the other half of Kyogre & Groudon LEGEND.","When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards."]','hgss3');
