INSERT INTO "Card" VALUES('mcd17-2','Grubbin','Pokémon','2',NULL,'Akira Komayama','They often gather near places frequented by electric Pokémon in order to avoid being attacked by bird Pokémon.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/mcd17/2.png","large":"https://images.pokemontcg.io/mcd17/2_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,'["Charjabug"]',NULL,'[{"name":"Vice Grip","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[736]',NULL,NULL,'mcd17');
