INSERT INTO "Card" VALUES('mcd21-11','Torchic','Pokémon','11',NULL,'sui','A fire burns inside, so it feels very warm to hug. It launches fireballs of 1,800 degrees Fahrenheit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/mcd21/11.png","large":"https://images.pokemontcg.io/mcd21/11_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Combusken"]',NULL,'[{"name":"Ember","cost":["Fire"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, discard a Fire Energy attached to this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[255]',NULL,NULL,'mcd21');
