INSERT INTO "Card" VALUES('me1-117','Forest of Vitality','Trainer','117','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me1/117.png","large":"https://images.pokemontcg.io/me1/117_hires.png"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player''s Grass Pokémon can evolve into Grass Pokémon during the turn they play those Pokémon, except during their first turn.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','me1');
INSERT INTO "Card" VALUES('me1-118','Iron Defender','Trainer','118','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me1/118.png","large":"https://images.pokemontcg.io/me1/118_hires.png"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During your opponent''s next turn, all of your Metal Pokémon take 30 less damage from attacks from your opponent''s Pokémon (after applying Weakness and Resistance). (This includes new Pokémon that come into play.)","You may play any number of Item cards during your turn."]','me1');
INSERT INTO "Card" VALUES('me1-119','Lillie''s Determination','Trainer','119','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me1/119.png","large":"https://images.pokemontcg.io/me1/119_hires.png"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Shuffle your hand into your deck. Then, draw 6 cards. If you have exactly 6 Prize cards remaining, draw 8 cards instead.","You may play only 1 Supporter card during your turn."]','me1');
INSERT INTO "Card" VALUES('me1-120','Lt. Surge''s Bargain','Trainer','120','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me1/120.png","large":"https://images.pokemontcg.io/me1/120_hires.png"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Ask your opponent if each player may take a Prize card. If yes, each player takes a Prize card. If no, you draw 4 cards.","You may play only 1 Supporter card during your turn."]','me1');
INSERT INTO "Card" VALUES('me1-121','Mega Signal','Trainer','121','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me1/121.png","large":"https://images.pokemontcg.io/me1/121_hires.png"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Mega Evolution Pokémon ex, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','me1');
