INSERT INTO "Card" VALUES('me2-85','Battle Cage','Trainer','85','Uncommon','MARINA Chikazawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/85.png","large":"https://images.pokemontcg.io/me2/85_hires.png"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Prevent all damage counters from being placed on Benched Pokémon (both yours and your opponent''s) by effects of attacks and Abilities from the opponent''s Pokémon. (Damage from attacks is still taken.)","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','me2');
INSERT INTO "Card" VALUES('me2-86','Blowtorch','Trainer','86','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/86.png","large":"https://images.pokemontcg.io/me2/86_hires.png"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you discard a Basic Fire Energy card from your hand.  Discard a Pokémon Tool or Special Energy card from 1 of your opponent''s Pokémon, or discard a Stadium in play.","You may play any number of Item cards during your turn."]','me2');
