INSERT INTO "Card" VALUES('me2-88','Dizzying Valley','Trainer','88','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/88.png","large":"https://images.pokemontcg.io/me2/88_hires.png"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Confused Pokémon (both yours and your opponent''s) don''t recover from that Special Condition when they evolve or devolve.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','me2');
