INSERT INTO "Card" VALUES('me2-98','Piplup','Pokémon','98','Illustration Rare','Jiro Sasumo','A poor walker, it often falls down. However, its strong pride makes it puff up its chest without a care.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/98.png","large":"https://images.pokemontcg.io/me2/98_hires.png"}','I','70',NULL,'["Basic"]','["Water"]',NULL,'["Prinplup"]',NULL,'[{"name":"Call for Support","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Tackle","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[393]',NULL,NULL,'me2');
