INSERT INTO "Card" VALUES('me2-103','Toxtricity','Pokémon','103','Illustration Rare','Terada Tera','As it scatters toxic sweat and emits electricity, a melody that sounds like it came from a guitar reverberates through the surrounding area.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/103.png","large":"https://images.pokemontcg.io/me2/103_hires.png"}','I','140',NULL,'["Stage 1"]','["Darkness"]','Toxel',NULL,'[{"name":"Sinister Surge","text":"Once during your turn, you may use this Ability. Search your deck for a Basic Darkness Energy card and attach it to 1 of your Benched Darkness Pokémon. Then, shuffle your deck. If you attached Energy to a Pokémon in this way, place 2 damage counters on that Pokémon.","type":"Ability"}]','[{"name":"Gentle Slap","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[849]',NULL,NULL,'me2');
