INSERT INTO "Card" VALUES('me2-107','Ambipom','Pokémon','107','Illustration Rare','Shigenori Negishi','They live on large trees. They are said to communicate by connecting their tails to those of others.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/me2/107.png","large":"https://images.pokemontcg.io/me2/107_hires.png"}','I','110',NULL,'["Stage 1"]','["Colorless"]','Aipom',NULL,NULL,'[{"name":"Slap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""},{"name":"Dual Tail","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard 2 Energy from this Pokémon, and this attack does 60 damage to each of 2 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[424]',NULL,NULL,'me2');
