INSERT INTO "Card" VALUES('me2pt5-105','Lunatone','Pokémon','105','Rare','Whisker','It was discovered at the site of a meteor strike 40 years ago. Its stare can lull its foes to sleep.','{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-105/small","large":"https://images.scrydex.com/pokemon/me2pt5-105/large"}','I','110',NULL,'["Basic"]','["Fighting"]',NULL,NULL,'[{"name":"Lunar Cycle","text":"Once during your turn, if you have Solrock in play, you may discard a Basic Fighting Energy card from your hand in order to use this Ability. Draw 3 cards. You can''t use more than 1 Lunar Cycle Ability each turn.","type":"Ability"}]','[{"name":"Power Gem","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[337]',NULL,NULL,'me2pt5');
