INSERT INTO "Card" VALUES('me2pt5-122','Okidogi','Pokémon','122','Rare','Mitsuhiro Arita','Okidogi is a ruffian with a short temper. It can pulverize anything by swinging around the chain on its neck.','{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-122/small","large":"https://images.scrydex.com/pokemon/me2pt5-122/large"}','I','140',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Light Punch","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Settle the Score","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80+","text":"This attack does 60 more damage for each Prize card your opponent took during their last turn."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,NULL,NULL,NULL,'me2pt5');
