INSERT INTO "Card" VALUES('me2pt5-186','Counter Gain','Trainer','186','Common','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-186/small","large":"https://images.scrydex.com/pokemon/me2pt5-186/large"}','H',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If you have more Prize cards remaining than your opponent, attacks used by the Pokémon this card is attached to cost Colorless less.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','me2pt5');
