INSERT INTO "Card" VALUES('me2pt5-189','Glass Trumpet','Trainer','189','Common','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-189/small","large":"https://images.scrydex.com/pokemon/me2pt5-189/large"}','H',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you have any Tera Pokémon in play.  Choose up to 2 of your Benched Colorless Pokémon and attach a Basic Energy card from your discard pile to each of them.","You may play any number of Item cards during your turn."]','me2pt5');
