INSERT INTO "Card" VALUES('me2pt5-191','Light Ball','Trainer','191','Uncommon','Studio Bora Inc.',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-191/small","large":"https://images.scrydex.com/pokemon/me2pt5-191/large"}','I',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attacks used by the Pikachu ex this card is attached to do 50 more damage to your opponent''s Active Pokémon ex (before applying Weakness and Resistance).","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-192','Lillie''s Determination','Trainer','192','Uncommon','Atsushi Furusawa',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-192/small","large":"https://images.scrydex.com/pokemon/me2pt5-192/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Shuffle your hand into your deck. Then, draw 6 cards. If you have exactly 6 Prize cards remaining, draw 8 cards instead.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-193','Mega Signal','Trainer','193','Common','inose yukie',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-193/small","large":"https://images.scrydex.com/pokemon/me2pt5-193/large"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Mega Evolution Pokémon ex, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-194','Mystery Garden','Trainer','194','Uncommon','AYUMI ODASHIMA',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-194/small","large":"https://images.scrydex.com/pokemon/me2pt5-194/large"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard an Energy card from their hand in order to draw cards until they have as many cards in their hand as they have Psychic Pokémon in play.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can’t be played."]','me2pt5');
