INSERT INTO "Card" VALUES('me2pt5-196','Night Stretcher','Trainer','196','Common','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-196/small","large":"https://images.scrydex.com/pokemon/me2pt5-196/large"}','H',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Pokémon or a Basic Energy card from your discard pile into your hand.","You may play any number of Item cards during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-197','Nighttime Mine','Trainer','197','Uncommon','Takashi Yamaguchi',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-197/small","large":"https://images.scrydex.com/pokemon/me2pt5-197/large"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attacks used by each Tera Pokémon in play (both yours and your opponent''s) cost Colorless more.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can’t be played."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-198','Poké Pad','Trainer','198','Common','Studio Bora Inc.',NULL,'{"standard":"Not Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-198/small","large":"https://images.scrydex.com/pokemon/me2pt5-198/large"}','J',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon that doesn''t have a Rule Box, reveal it, and put it into your hand. Then, shuffle your deck. (Pokémon ex, Pokémon V, etc. have Rule Boxes.)","You may play any number of Item cards during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-199','Premium Power Pro','Trainer','199','Uncommon','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-199/small","large":"https://images.scrydex.com/pokemon/me2pt5-199/large"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During this turn, attacks used by your Fighting Pokémon do 30 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","You may play any number of Item cards during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-200','Surfer','Trainer','200','Common','Hideki Ishikawa',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-200/small","large":"https://images.scrydex.com/pokemon/me2pt5-200/large"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch your Active Pokémon with 1 of your Benched Pokémon. If you do, draw cards until you have 5 cards in your hand.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-201','Team Rocket''s Archer','Trainer','201','Uncommon','Hideki Ishikawa',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-201/small","large":"https://images.scrydex.com/pokemon/me2pt5-201/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if any of your Team Rocket''s Pokémon were Knocked Out during your opponent''s last turn.  Each player shuffles their hand into their deck. Then, you draw 5 cards, and your opponent draws 3 cards.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-202','Team Rocket''s Ariana','Trainer','202','Uncommon','hncl',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-202/small","large":"https://images.scrydex.com/pokemon/me2pt5-202/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw cards until you have 5 cards in your hand. If all of your Pokémon in play are Team Rocket''s Pokémon, draw cards until you have 8 cards in your hand instead.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-203','Team Rocket''s Factory','Trainer','203','Uncommon','imoniii',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-203/small","large":"https://images.scrydex.com/pokemon/me2pt5-203/large"}','I',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, if they played a Supporter card that has \"Team Rocket\" in its name from their hand this turn, they may draw 2 cards.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can’t be played."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-204','Team Rocket''s Giovanni','Trainer','204','Uncommon','DOM',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-204/small","large":"https://images.scrydex.com/pokemon/me2pt5-204/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch your Active Team Rocket''s Pokémon with 1 of your Benched Team Rocket''s Pokémon. If you do, switch in 1 of your opponent''s Benched Pokémon to the Active Spot.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-205','Team Rocket''s Great Ball','Trainer','205','Uncommon','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-205/small","large":"https://images.scrydex.com/pokemon/me2pt5-205/large"}','I',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for an Evolution Team Rocket''s Pokémon, reveal it, and put it into your hand. If tails, search your deck for a Basic Team Rocket''s Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-206','Team Rocket''s Hypnotizer','Trainer','206','Uncommon','Toyste Beach',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-206/small","large":"https://images.scrydex.com/pokemon/me2pt5-206/large"}','I',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[97]',NULL,'["If the Team Rocket''s Pokémon this card is attached to is in the Active Spot and is damaged by an attack from your opponent''s Pokémon (even if this Team Rocket''s Pokémon is Knocked Out), the Attacking Pokémon is now Asleep.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-207','Team Rocket''s Petrel','Trainer','207','Uncommon','GOSSAN',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-207/small","large":"https://images.scrydex.com/pokemon/me2pt5-207/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Trainer card, reveal it, and put it into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','me2pt5');
INSERT INTO "Card" VALUES('me2pt5-208','Team Rocket''s Proton','Trainer','208','Uncommon','Naoki Saito',NULL,'{"standard":"Legal","unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.scrydex.com/pokemon/me2pt5-208/small","large":"https://images.scrydex.com/pokemon/me2pt5-208/large"}','I',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If you go first, you may use this card during your first turn.  Search your deck for up to 3 Basic Team Rocket''s Pokémon, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','me2pt5');
