INSERT INTO "Card" VALUES('neo4-92','Broken Ground Gym','Trainer','92','Rare','Tomokazu Komiya',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/92.png","large":"https://images.pokemontcg.io/neo4/92_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Each player pays Colorless more to retreat a Baby Pokémon or Basic Pokémon."]','neo4');
INSERT INTO "Card" VALUES('neo4-93','EXP.ALL','Trainer','93','Rare','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/93.png","large":"https://images.pokemontcg.io/neo4/93_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach EXP.ALL to 1 of your Pokémon that doesn''t have a Pokémon Tool attached to it.","During your opponent''s turn, if your Active Pokémon would be Knocked Out by your opponent''s attack, you may take 1 of the basic Energy cards attached to your Active Pokémon and attach it to the Pokémon with EXP.ALL attached to it. If you do, discard EXP.ALL."]','neo4');
INSERT INTO "Card" VALUES('neo4-94','Impostor Professor Oak''s Invention','Trainer','94','Rare','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/94.png","large":"https://images.pokemontcg.io/neo4/94_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your opponent''s Prize cards. You may have your opponent shuffle them into his or her deck. If you do, your opponent takes that many cards from the top of his or her deck and sets them aside as his or her new Prize cards (without looking at them)."]','neo4');
INSERT INTO "Card" VALUES('neo4-95','Radio Tower','Trainer','95','Rare','Yousuke Hirata, CR CG gangs',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/95.png","large":"https://images.pokemontcg.io/neo4/95_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may look at the top 2 cards of his or her deck and put them back in the same order."]','neo4');
INSERT INTO "Card" VALUES('neo4-96','Thought Wave Machine','Trainer','96','Rare','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/96.png","large":"https://images.pokemontcg.io/neo4/96_hires.png"}',NULL,NULL,NULL,'["Rocket''s Secret Machine"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin until you get tails. For each heads, return an Energy card attached to your opponent''s Active Pokémon to your opponent''s hand. If the Pokémon has fewer attached Energy cards than that, return all of them to your opponent''s hand. Your turn is over now (you don''t get to attack)."]','neo4');
INSERT INTO "Card" VALUES('neo4-97','Counterattack Claws','Trainer','97','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/97.png","large":"https://images.pokemontcg.io/neo4/97_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Counterattack Claws to 1 of your Pokémon that doesn''t have a Pokémon Tool attached to it.","During your opponent''s turn, if the Pokémon Counterattack Claws is attached to is your Active Pokémon and an opponent''s attack damages it (even if it is Knocked Out), flip a coin. If heads, put 2 damage counters on the Defending Pokémon. Then, discard Counterattack Claws."]','neo4');
INSERT INTO "Card" VALUES('neo4-98','Energy Amplifier','Trainer','98','Uncommon','"Big Mama" Tagawa, CR CG gangs',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/98.png","large":"https://images.pokemontcg.io/neo4/98_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose an Energy card in your hand, show it to your opponent, and shuffle it into your deck. Then flip a coin. If heads, search your deck for up to 3 basic Energy cards. Show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','neo4');
INSERT INTO "Card" VALUES('neo4-99','Energy Stadium','Trainer','99','Uncommon','Hideki Kazama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/99.png","large":"https://images.pokemontcg.io/neo4/99_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may flip a coin. If heads, that player puts a basic Energy card from his or her discard pile into his or her hand."]','neo4');
INSERT INTO "Card" VALUES('neo4-100','Lucky Stadium','Trainer','100','Uncommon','Imakuni?',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/100.png","large":"https://images.pokemontcg.io/neo4/100_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play.","Once during each player''s turn (before attacking), that player may flip a coin. If heads, that player draws a card."]','neo4');
INSERT INTO "Card" VALUES('neo4-101','Magnifier','Trainer','101','Uncommon','Keiji Kinebuchi',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/101.png","large":"https://images.pokemontcg.io/neo4/101_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Magnifier to 1 of your Pokémon. At the end of your turn, discard Magnifier. If the Pokémon Magnifier is attached to attacks, don''t apply Resistance for that attack."]','neo4');
INSERT INTO "Card" VALUES('neo4-102','Pokémon Personality Test','Trainer','102','Uncommon','Tomokazu Komiya',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/102.png","large":"https://images.pokemontcg.io/neo4/102_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put an Evolution card from your hand face down in front of you. Your opponent guesses whether it is a Pokémon card with Light in its name, a Pokémon card with Dark in its name, or neither one. Flip the card over. If your opponent guessed right, he or she draws 3 cards. If your opponent guessed wrong, you draw 3 cards. Either way, return the card to your hand."]','neo4');
INSERT INTO "Card" VALUES('neo4-103','Team Rocket''s Evil Deeds','Trainer','103','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/103.png","large":"https://images.pokemontcg.io/neo4/103_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your opponent''s hand and choose a card there. Your opponent shuffles that card into his or her deck. Then, your opponent may draw up to 2 cards."]','neo4');
INSERT INTO "Card" VALUES('neo4-104','Heal Powder','Trainer','104','Common','Ryuta Kusumi, CR CG gangs',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/104.png","large":"https://images.pokemontcg.io/neo4/104_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, your Active Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned and remove 2 damage counters from it. If your Active Pokémon has fewer damage counters than that, remove all of them."]','neo4');
INSERT INTO "Card" VALUES('neo4-105','Mail from Bill','Trainer','105','Common','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/105.png","large":"https://images.pokemontcg.io/neo4/105_hires.png"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t play this card if you have 5 or more cards in your hand (including this one). Draw cards until you have exactly 4 cards in your hand."]','neo4');
INSERT INTO "Card" VALUES('neo4-106','Shining Celebi','Pokémon','106','Rare Shining','Hironobu Yoshida','It is worshipped as a god of the forest. It appears only in undisturbed old-growth forests.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/106.png","large":"https://images.pokemontcg.io/neo4/106_hires.png"}',NULL,'50','18','["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Healing Water","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Remove a number of damage counters from 1 of your Benched Pokémon equal to the number of Water Energy cards attached to Shining Celebi. If the Pokémon has fewer damage counters than that, remove all of them."},{"name":"Miracle Leaf","cost":["Grass","Psychic"],"convertedEnergyCost":2,"damage":"10","text":"Flip a number of coins equal to the number of Energy attached to the Defending Pokémon. If you get 1 or more heads, the Defending Pokémon is now Asleep, Confused, or Poisoned (your choice)."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[251]',NULL,'["You can''t have more than 1 Shining Celebi in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-107','Shining Charizard','Pokémon','107','Rare Shining','Hironobu Yoshida','The flames it breathes are so hot that they can melt anything.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/107.png","large":"https://images.pokemontcg.io/neo4/107_hires.png"}',NULL,'100','61','["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"White-hot Flame","cost":["Fire","Fire","Fire","Lightning","Lightning"],"convertedEnergyCost":5,"damage":"100","text":"Discard 1 Fire Energy card and 1 Lightning Energy card attached to Shining Charizard or this attack does nothing. Flip a coin. If tails, Shining Charizard does 30 damage to itself."}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[6]',NULL,'["You can''t have more than 1 Shining Charizard in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-108','Shining Kabutops','Pokémon','108','Rare Shining','Hironobu Yoshida','This ancient Pokémon uses its razor-sharp claws to cut open its prey and gain access to its blood.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/108.png","large":"https://images.pokemontcg.io/neo4/108_hires.png"}',NULL,'80','40','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Lightning Cut","cost":["Fighting","Fighting","Lightning"],"convertedEnergyCost":3,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 10 more damage and does 10 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) If tails, this attack does 30 damage and Shining Kabutops does 10 damage to itself."},{"name":"Water Slash","cost":["Fighting","Fighting","Water","Water"],"convertedEnergyCost":4,"damage":"50+","text":"Does 50 damage plus 10 more damage for each Water Energy attached to Shining Kabutops but not used to pay for this attack''s Energy cost. Don''t apply Resistance."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[141]',NULL,'["You can''t have more than 1 Shining Kabutops in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-109','Shining Mewtwo','Pokémon','109','Rare Shining','Hironobu Yoshida','It uses its highly developed psychic powers to defeat its enemies before they even have time to think.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/109.png","large":"https://images.pokemontcg.io/neo4/109_hires.png"}',NULL,'70','63','["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Reflect Shield","cost":["Psychic","Lightning"],"convertedEnergyCost":2,"damage":"","text":"If an attack does damage to Shining Mewtwo during your opponent''s next turn (even if Shining Mewtwo is Knocked Out), flip a coin. If heads, prevent all damage done to Shining Mewtwo from that attack (any other effects of attacks still happen) and do 20 damage to the attacking Pokémon."},{"name":"Psyburst","cost":["Psychic","Psychic","Fire"],"convertedEnergyCost":3,"damage":"40+","text":"Discard a Fire Energy card attached to Shining Mewtwo or this attack does nothing. This attack does 40 damage plus 10 damage for each Energy attached to the Defending Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[150]',NULL,'["You can''t have more than 1 Shining Mewtwo in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-110','Shining Noctowl','Pokémon','110','Rare Shining','Ken Sugimori','It speeds up its thought processes by turning its head around 180 degrees.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/110.png","large":"https://images.pokemontcg.io/neo4/110_hires.png"}',NULL,'60','24','["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Flashing Eyes","cost":["Psychic","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Flip 3 coins. If exactly 1 is heads, the Defending Pokémon is now Asleep. If exactly 2 are heads, the Defending Pokémon is now Confused. If all 3 are heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[164]',NULL,'["You can''t have more than 1 Shining Noctowl in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-111','Shining Raichu','Pokémon','111','Rare Shining','Hironobu Yoshida','If the electricity in its cheeks runs out, it sticks its tail straight up and uses it to collect energy from the air.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/111.png","large":"https://images.pokemontcg.io/neo4/111_hires.png"}',NULL,'70','30','["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Thundersquall","cost":["Lightning","Lightning","Water","Water"],"convertedEnergyCost":4,"damage":"40","text":"If your opponent has any Benched Pokémon, choose 1 of them and this attack does 10 damage to that Pokémon for each Water Energy attached to Shining Raichu. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[26]',NULL,'["You can''t have more than 1 Shining Raichu in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-112','Shining Steelix','Pokémon','112','Rare Shining','Ken Sugimori','If an Onix lives 100 years or more, its skin hardens, eventually becoming even harder than a diamond.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/112.png","large":"https://images.pokemontcg.io/neo4/112_hires.png"}',NULL,'90','51','["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Crushing Earth","cost":["Metal","Metal","Fighting","Fighting"],"convertedEnergyCost":4,"damage":"80","text":"Flip a coin. If heads, this attack does 10 damage to each Benched Pokémon (yours and your opponent''s). (Don''t apply Weakness and Resistance for Benched Pokémon.) If tails, this attack does nothing. Either way, Shining Steelix can''t attack during your next turn."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,'["You can''t have more than 1 Shining Steelix in your deck."]','neo4');
INSERT INTO "Card" VALUES('neo4-113','Shining Tyranitar','Pokémon','113','Rare Shining','Ken Sugimori','It is so powerful, it can knock down a mountain with hust one arm.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/neo4/113.png","large":"https://images.pokemontcg.io/neo4/113_hires.png"}',NULL,'80','41','["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"name":"Mountain Crush","cost":["Darkness","Fighting","Fighting"],"convertedEnergyCost":3,"damage":"30","text":"Flip a coin until you get tails. For each heads, your opponent discards the top card from his or her deck."},{"name":"Destructive Fire","cost":["Darkness","Fire","Fire","Fire"],"convertedEnergyCost":4,"damage":"50","text":"Flip a coin for each Fire Energy card attached to Shining Tyranitar. For each heads, discard a Fire Energy card attached to Shining Tyranitar or this attack does nothing. Then, for each heads, choose an Energy card attached to the Defending Pokémon and discard it. If it has fewer Energy cards than that, remove all of them."}]',NULL,'[{"type":"Psychic","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[248]',NULL,'["You can''t have more than 1 Shining Tyranitar in your deck."]','neo4');
INSERT INTO "Card" VALUES('np-1','Kyogre ex','Pokémon','1','Promo','Hiromichi Sugiyama',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/np/1.png","large":"https://images.pokemontcg.io/np/1_hires.png"}',NULL,'120',NULL,'["Basic","EX"]','["Water"]',NULL,NULL,NULL,'[{"name":"Major Flood","cost":["Water","Water","Water","Water"],"convertedEnergyCost":4,"damage":"60","text":"Discard a Water Energy card attached to Kyogre ex. Does 10 damage to each Benched Pokémon (both yours and your opponent''s). (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[382]',NULL,'["When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards."]','np');
