INSERT INTO "Card" VALUES('pl1-2','Blastoise','Pokémon','2','Rare Holo','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/2.png","large":"https://images.pokemontcg.io/pl1/2_hires.png"}',NULL,'130','60','["Stage 2"]','["Water"]','Wartortle',NULL,'[{"name":"Dig Well","text":"Once during your turn (before your attack), you may look at the top 3 cards of your deck, choose as many Water Energy cards as you like, and attach them to your Pokémon in any way you like. Discard the other cards. This power can''t be used if Blastoise is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Aqua Press","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Does 20 damage plus 10 more damage for each Energy attached to all Pokémon (both yours and your opponent''s)."},{"name":"Double Launcher","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Discard 2 Energy attached to Blastoise. Choose 2 of your opponent''s Benched Pokémon. This attack does 60 damage to each of them. (Don''t apply Weakness and Resistance for Benched Pokémon.) Blastoise can''t use Double Launcher during your next turn."}]','[{"type":"Lightning","value":"+30"}]',NULL,'["Colorless","Colorless"]',2,'[9]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-3','Blaziken','Pokémon','3','Rare Holo','Hajime Kusajima',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/3.png","large":"https://images.pokemontcg.io/pl1/3_hires.png"}',NULL,'130','59','["Stage 2"]','["Fire"]','Combusken',NULL,'[{"name":"Fire Breath","text":"Once during your turn (before your attack), you may choose 1 of the Defending Pokémon. That Pokémon is now Burned. This power can''t be used if Blaziken is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Clutch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."},{"name":"Fire Spin","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"Discard 2 Energy attached to Blaziken."}]','[{"type":"Water","value":"+30"}]',NULL,'["Colorless"]',1,'[257]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-4','Delcatty','Pokémon','4','Rare Holo','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/4.png","large":"https://images.pokemontcg.io/pl1/4_hires.png"}',NULL,'90','53','["Stage 1"]','["Colorless"]','Skitty',NULL,'[{"name":"Power Circulation","text":"Once during your turn (before your attack), you may search your discard pile for up to 2 basic Energy cards, show them to your opponent, and put those cards on top of your deck in any order. If you do, put 2 damage counters on Delcatty. This power can''t be used if Delcatty is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Power Heal","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10+","text":"Does 10 damage plus 10 more damage for each damage counter on Delcatty. Then, remove 2 damage counters from Delcatty."},{"name":"Rear Kick","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fighting","value":"+20"}]',NULL,'["Colorless"]',1,'[301]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-5','Dialga','Pokémon','5','Rare Holo','Mitsuhiro Arita','It has the power to control time. It appears in Sinnoh-region myths as an ancient deity.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/5.png","large":"https://images.pokemontcg.io/pl1/5_hires.png"}',NULL,'100','72','["Basic"]','["Metal"]',NULL,NULL,'[{"name":"Reverse Time","text":"Once during your turn, when you put Dialga from your hand onto your Bench, you may search your discard pile for up to 3 in any combination of Pokémon (excluding Pokémon LV.X) and basic Energy cards. Show them to your opponent and put them on top of your deck in any order.","type":"Poké-Power"}]','[{"name":"Time-Space Traveling","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"Draw cards until you have 7 cards in your hand."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[483]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-6','Dialga','Pokémon','6','Rare Holo','Kouki Saitou','It has the power to control time. It appears in Sinnoh-region myths as an ancient deity.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/6.png","large":"https://images.pokemontcg.io/pl1/6_hires.png"}',NULL,'100','70','["Basic"]','["Metal"]',NULL,NULL,'[{"name":"Time Aura","text":"As long as Dialga is your Active Pokémon, your opponent can''t play any Pokémon from his or her hand to evolve his or her Active Pokémon.","type":"Poké-Body"}]','[{"name":"Metal Burn","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Discard all Metal Energy attached to Dialga."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[483]',NULL,NULL,'pl1');
