INSERT INTO "Card" VALUES('pl1-11','Manectric','Pokémon','11','Rare Holo','Kouki Saitou',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/11.png","large":"https://images.pokemontcg.io/pl1/11_hires.png"}',NULL,'90','45','["Stage 1"]','["Lightning"]','Electrike',NULL,'[{"name":"Electric Barrier","text":"Prevent all damage done to your Benched Pokémon (excluding any Manectric) by attacks.","type":"Poké-Body"}]','[{"name":"Power Wave","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"This attack does 30 damage to each Pokémon that has any Poké-Powers (both yours and your opponent''s). (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Attract Current","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Search your deck for a Lightning Energy card and attach it to 1 of your Pokémon. Shuffle your deck afterward."}]','[{"type":"Fighting","value":"+20"}]','[{"type":"Metal","value":"-20"}]',NULL,NULL,'[310]',NULL,NULL,'pl1');
