INSERT INTO "Card" VALUES('pl1-13','Rampardos','Pokémon','13','Rare Holo','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/13.png","large":"https://images.pokemontcg.io/pl1/13_hires.png"}',NULL,'130','54','["Stage 2"]','["Fighting"]','Cranidos',NULL,'[{"name":"Iron Skull","text":"Rampardos''s attack''s damage isn''t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.","type":"Poké-Body"}]','[{"name":"Head Smash","cost":["Fighting"],"convertedEnergyCost":1,"damage":"80","text":"If the Defending Pokémon would be Knocked Out by this attack, Rampardos does 40 damage to itself."},{"name":"Mold Breaker","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Any damage done to Rampardos by attacks is reduced by 20 (after applying Weakness and Resistance) until the end of your next turn."}]','[{"type":"Grass","value":"+30"}]',NULL,'["Colorless"]',1,'[409]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-14','Shaymin','Pokémon','14','Rare Holo','Kagemaru Himeno','It lives in flower patches and avoids detection by curling up to look like a flowering plant.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/14.png","large":"https://images.pokemontcg.io/pl1/14_hires.png"}',NULL,'70','42','["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Flower Aroma","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Remove 2 damage counters from Shaymin. The Defending Pokémon is now Asleep."},{"name":"Damage Aid","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"If the Defending Pokémon is affected by a Special Condition, this attack does 30 damage plus 50 more damage. Then, remove all Special Conditions from the Defending Pokémon."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[492]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-15','Shaymin','Pokémon','15','Rare Holo','Atsuko Nishida','The flowers all over its body burst into bloom if it is lovingly hugged and senses gratitude.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/15.png","large":"https://images.pokemontcg.io/pl1/15_hires.png"}',NULL,'80','56','["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Growth","cost":[],"convertedEnergyCost":0,"damage":"","text":"Attach a Grass Energy card from your hand to Shaymin."},{"name":"Air Slash","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"Flip a coin. If tails, discard an Energy attached to Shaymin."}]','[{"type":"Fire","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[492]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-16','Slaking','Pokémon','16','Rare Holo','Masakazu Fukuda','The world''s laziest Pokémon. When it is lounging, it is actually saving energy for striking back.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/16.png","large":"https://images.pokemontcg.io/pl1/16_hires.png"}',NULL,'150','62','["Stage 2"]','["Colorless"]','Vigoroth',NULL,'[{"name":"Lazy Paunch","text":"If Slaking used any attacks during your last turn, Slaking can''t attack.","type":"Poké-Body"}]','[{"name":"Best Dash","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"150","text":"During your opponent''s next turn, any damage done to Slaking by attacks is increased by 50 (after applying Weakness and Resistance)."}]','[{"type":"Fighting","value":"+30"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[289]',NULL,NULL,'pl1');
