INSERT INTO "Card" VALUES('pl1-19','Banette','Pokémon','19','Rare','Tomokazu Komiya',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/19.png","large":"https://images.pokemontcg.io/pl1/19_hires.png"}',NULL,'90','48','["Stage 1"]','["Psychic"]','Shuppet',NULL,'[{"name":"Temper Tantrum","text":"Once during your turn (before your attack), you may discard as many cards as you like from your hand. If you do, put that many damage counters on Banette. This power can''t be used if Banette is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Darkness Switch","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Discard an Energy card attached to Banette, and then switch all damage counters on Banette with those on the Defending Pokémon. (If an effect of this attack is prevented, this attack does nothing.)"},{"name":"Loneliness","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"You may show your hand to your opponent. If you do and if you don''t have any Pokémon in your hand, this attack does 30 damage plus 30 more damage."}]','[{"type":"Darkness","value":"+20"}]','[{"type":"Colorless","value":"-20"}]','["Colorless"]',1,'[354]',NULL,NULL,'pl1');
