INSERT INTO "Card" VALUES('pl1-23','Dialga','Pokémon','23','Rare','Kent Kanetsuna','A legendary Pokémon of Sinnoh. It is said that time flows when Dialga''s heart beats.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/23.png","large":"https://images.pokemontcg.io/pl1/23_hires.png"}',NULL,'100','73','["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Energy Stream","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, search your discard pile for a basic Energy card and attach it to Dialga."},{"name":"Diamond Blow","cost":["Metal","Metal","Metal","Colorless"],"convertedEnergyCost":4,"damage":"100","text":"Dialga can''t attack during your next turn."}]','[{"type":"Fire","value":"+30"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[483]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-24','Dugtrio','Pokémon','24','Rare','Sumiyoshi Kizuki',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/24.png","large":"https://images.pokemontcg.io/pl1/24_hires.png"}',NULL,'90','50','["Stage 1"]','["Fighting"]','Diglett',NULL,'[{"name":"Sinkhole","text":"If your opponent''s Active Pokémon retreats, put 2 damage counters on that Pokémon.","type":"Poké-Body"}]','[{"name":"Push Down","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon."},{"name":"Magnitude","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Does 10 damage to each Benched Pokémon (both yours and your opponent''s). (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Water","value":"+20"}]','[{"type":"Lightning","value":"-20"}]',NULL,NULL,'[51]',NULL,NULL,'pl1');
