INSERT INTO "Card" VALUES('pl1-44','Cascoon','Pokémon','44','Uncommon','Yukiko Baba','It never forgets any attack it endured while in the cocoon. After evolution, it seeks payback.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/44.png","large":"https://images.pokemontcg.io/pl1/44_hires.png"}',NULL,'80','10','["Stage 1"]','["Grass"]','Wurmple','["Dustox"]',NULL,'[{"name":"Ascension","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for a card that evolves from Cascoon and put it onto Cascoon. (This counts as evolving Cascoon.) Shuffle your deck afterward."},{"name":"Poison Thread","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"The Defending Pokémon is now Poisoned."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[268]',NULL,NULL,'pl1');
