INSERT INTO "Card" VALUES('pl1-60','Probopass','Pokémon','60','Uncommon','Mitsuhiro Arita','It freely controls three small units called Mini-Noses using magnetic force.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/60.png","large":"https://images.pokemontcg.io/pl1/60_hires.png"}',NULL,'90','49','["Stage 1"]','["Fighting"]','Nosepass',NULL,NULL,'[{"name":"Stealth Rock","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 30 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Hyper Beam","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Flip a coin. If heads, discard an Energy card attached to the Defending Pokémon."}]','[{"type":"Water","value":"+20"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[476]',NULL,NULL,'pl1');
