INSERT INTO "Card" VALUES('pl1-62','Shieldon','Pokémon','62','Uncommon','Mitsuhiro Arita','It is outstandingly armored. As a result, it can eat grass and berries without having to fight.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/62.png","large":"https://images.pokemontcg.io/pl1/62_hires.png"}',NULL,'80','21','["Stage 1"]','["Metal"]','Armor Fossil','["Bastiodon"]',NULL,'[{"name":"Endure","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, during your opponent''s next turn, if Shieldon would be Knocked Out by damage from an attack, Shieldon is not Knocked Out and its remaining HP becomes 10 instead."},{"name":"Rock Slide","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Does 10 damage to 2 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"+20"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[410]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-63','Silcoon','Pokémon','63','Uncommon','Kyoko Umemoto','It wraps silk around the branches of a tree. It drinks rainwater on its silk while awaiting evolution.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/63.png","large":"https://images.pokemontcg.io/pl1/63_hires.png"}',NULL,'80','10','["Stage 1"]','["Grass"]','Wurmple','["Beautifly"]',NULL,'[{"name":"Ascension","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for a card that evolves from Silcoon and put it onto Silcoon. (This counts as evolving Silcoon.) Shuffle your deck afterward."},{"name":"Sticky String","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[266]',NULL,NULL,'pl1');
