INSERT INTO "Card" VALUES('pl1-76','Happiny','Pokémon','76','Common','Kagemaru Himeno','It likes to carry around a small rock. It may wander around others'' feet and cause them to stumble.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/76.png","large":"https://images.pokemontcg.io/pl1/76_hires.png"}',NULL,'60','5','["Basic"]','["Colorless"]',NULL,'["Chansey"]','[{"name":"Baby Evolution","text":"Once during your turn (before your attack), you may put Chansey from your hand onto Happiny (this counts as evolving Happiny) and remove all damage counters from Happiny.","type":"Poké-Power"}]','[{"name":"Hospitality","cost":[],"convertedEnergyCost":0,"damage":"","text":"Switch the Defending Pokémon with 1 of your opponent''s Benched Pokémon. Remove 2 damage counters from the new Defending Pokémon."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[440]',NULL,NULL,'pl1');
