INSERT INTO "Card" VALUES('pl1-89','Ralts','Pokémon','89','Common','Miki Tanaka','If its horns capture the warm feelings of people or Pokémon, its body warms up slightly.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/89.png","large":"https://images.pokemontcg.io/pl1/89_hires.png"}',NULL,'60','16','["Basic"]','["Psychic"]',NULL,'["Kirlia"]',NULL,'[{"name":"Future Sight","cost":[],"convertedEnergyCost":0,"damage":"","text":"Look at the top 5 cards in either player''s deck and put them back on top of that player''s deck in any order."},{"name":"Hypnoblast","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Asleep."}]','[{"type":"Psychic","value":"+10"}]',NULL,'["Colorless"]',1,'[280]',NULL,NULL,'pl1');
