INSERT INTO "Card" VALUES('pl1-104','Broken Time-Space','Trainer','104','Uncommon','Kent Kanetsuna',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/104.png","large":"https://images.pokemontcg.io/pl1/104_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Each player may evolve a Pokémon that he or she just played or evolved during that turn."]','pl1');
INSERT INTO "Card" VALUES('pl1-105','Cyrus''s Conspiracy','Trainer','105','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/105.png","large":"https://images.pokemontcg.io/pl1/105_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for a Supporter card, a basic Energy card, and a Trainer card that has Team Galactic''s Invention in its name, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','pl1');
INSERT INTO "Card" VALUES('pl1-106','Galactic HQ','Trainer','106','Uncommon','Ryota Saito',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/106.png","large":"https://images.pokemontcg.io/pl1/106_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Whenever any player plays any Pokémon from his or her hand to evolve his or her Pokémon, put 2 damage counters on that Pokémon."]','pl1');
INSERT INTO "Card" VALUES('pl1-107','Level Max','Trainer','107','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/107.png","large":"https://images.pokemontcg.io/pl1/107_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Pokémon LV.X that levels up from 1 of your Pokémon, and put it onto that Pokémon. (This counts as leveling up that Pokémon.) Shuffle your deck afterward."]','pl1');
INSERT INTO "Card" VALUES('pl1-108','Life Herb','Trainer','108','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/108.png","large":"https://images.pokemontcg.io/pl1/108_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, choose 1 of your Pokémon, and remove all Special Conditions and 6 damage counters from that Pokémon (all if there are less than 6)."]','pl1');
INSERT INTO "Card" VALUES('pl1-109','Looker''s Investigation','Trainer','109','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/109.png","large":"https://images.pokemontcg.io/pl1/109_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at your opponent''s hand, then choose you or your opponent. That player shuffles his or her hand into his or her deck and draws up to 5 cards."]','pl1');
INSERT INTO "Card" VALUES('pl1-110','Memory Berry','Trainer','110','Uncommon','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/110.png","large":"https://images.pokemontcg.io/pl1/110_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Memory Berry to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","The Pokémon this card is attached to can use any attack from its Basic Pokémon or its Stage 1 Evolution card. (You still have to pay for that attack''s Energy cost.)"]','pl1');
INSERT INTO "Card" VALUES('pl1-111','Miasma Valley','Trainer','111','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/111.png","large":"https://images.pokemontcg.io/pl1/111_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Whenever any player puts a Basic Pokémon (excluding Grass or Psychic Pokémon) from his or her hand onto his or her Bench, put 2 damage counters on that Pokémon."]','pl1');
INSERT INTO "Card" VALUES('pl1-112','PlusPower','Trainer','112','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/112.png","large":"https://images.pokemontcg.io/pl1/112_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach PlusPower to 1 of your Pokémon. Discard this card at the end of your turn.","If the Pokémon PlusPower is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance)."]','pl1');
INSERT INTO "Card" VALUES('pl1-113','Poké Ball','Trainer','113','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/113.png","large":"https://images.pokemontcg.io/pl1/113_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Pokémon, show it to your opponent, and put it into your hand. Shuffle your deck afterward."]','pl1');
INSERT INTO "Card" VALUES('pl1-114','Pokédex HANDY910is','Trainer','114','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/114.png","large":"https://images.pokemontcg.io/pl1/114_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 2 cards of your deck, choose 1 of them, and put it into your hand. Put the other card on the bottom of your deck."]','pl1');
INSERT INTO "Card" VALUES('pl1-115','Pokémon Rescue','Trainer','115','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/115.png","large":"https://images.pokemontcg.io/pl1/115_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your discard pile for a Pokémon, show it to your opponent, and put it into your hand."]','pl1');
INSERT INTO "Card" VALUES('pl1-116','Team Galactic''s Invention G-101 Energy Gain','Trainer','116','Uncommon','Makoto Imai',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/116.png","large":"https://images.pokemontcg.io/pl1/116_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Team Galactic''s Invention G-101 Energy Gain to 1 of your Pokémon SP that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card. When the Pokémon this card is attached to is no longer a Pokémon SP, discard this card.","As long as Team Galactic''s Invention G-101 Energy Gain is attached to a Pokémon, the attack cost of that Pokémon''s attacks is Colorless less."]','pl1');
INSERT INTO "Card" VALUES('pl1-117','Team Galactic''s Invention G-103 Power Spray','Trainer','117','Uncommon','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/117.png","large":"https://images.pokemontcg.io/pl1/117_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play this card during your opponent''s turn when your opponent''s Pokémon uses any Poké-Power. Prevent all effects of that Poké-Power. (This counts as that Pokémon using its Poké-Power.) If you have 2 or less Pokémon SP in play, you can''t play this card."]','pl1');
INSERT INTO "Card" VALUES('pl1-118','Team Galactic''s Invention G-105 Poké Turn','Trainer','118','Uncommon','Makoto Imai',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/118.png","large":"https://images.pokemontcg.io/pl1/118_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Return 1 of your Pokémon SP and all cards attached to it to your hand."]','pl1');
INSERT INTO "Card" VALUES('pl1-119','Armor Fossil','Trainer','119','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/119.png","large":"https://images.pokemontcg.io/pl1/119_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Armor Stone","text":"Whenever Armor Fossil would be damaged by your opponent''s attack, flip a coin until you get tails. For each heads, reduce that damage by 10.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Armor Fossil as if it were a Colorless Basic Pokémon. (Armor Fossil counts as a Trainer card as well, but if Armor Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Armor Fossil can''t be affected by any Special Conditions and can''t retreat. At any time during your turn before your attack, you may discard Armor Fossil from play. (This doesn''t count as a Knocked Out Pokémon.)"]','pl1');
INSERT INTO "Card" VALUES('pl1-120','Skull Fossil','Trainer','120','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/120.png","large":"https://images.pokemontcg.io/pl1/120_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Skull Stone","text":"During your opponent''s turn, if Skull Fossil would be Knocked Out by damage from an opponent''s attack, flip a coin until you get tails. For each heads, put 1 damage counter on the Attacking Pokémon.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Skull Fossil as if it were a Colorless Basic Pokémon. (Skull Fossil counts as a Trainer card as well, but if Skull Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Skull Fossil can''t be affected by any Special Conditions and can''t retreat. At any time during your turn before your attack, you may discard Skull Fossil from play. (This doesn''t count as a Knocked Out Pokémon.)"]','pl1');
INSERT INTO "Card" VALUES('pl1-121','Rainbow Energy','Energy','121','Uncommon','Takumi Akabane',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/121.png","large":"https://images.pokemontcg.io/pl1/121_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Rainbow Energy to 1 of your Pokémon. While in play, Rainbow Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) When you attach this card from your hand to 1 of your Pokémon, put 1 damage counter on that Pokémon."]','pl1');
INSERT INTO "Card" VALUES('pl1-122','Dialga G LV.X','Pokémon','122','Rare Holo LV.X','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/122.png","large":"https://images.pokemontcg.io/pl1/122_hires.png"}',NULL,'120','X','["Level-Up","SP"]','["Metal"]','Dialga G',NULL,'[{"name":"Time Crystal","text":"Each Pokémon (both yours and your opponent''s) (excluding Pokémon SP) can''t use any Poké-Bodies.","type":"Poké-Body"}]','[{"name":"Remove Lost","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"Flip a coin until you get tails. For each heads, remove an Energy card attached to the Defending Pokémon and put it in the Lost Zone."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[483]',NULL,'["Put this card onto your Active Dialga G. Dialga G LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-123','Drapion LV.X','Pokémon','123','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/123.png","large":"https://images.pokemontcg.io/pl1/123_hires.png"}',NULL,'130','X','["Level-Up"]','["Darkness"]','Drapion',NULL,'[{"name":"Tri-Poison","text":"Once during your turn (before your attack), you may flip a coin. If heads, choose 1 of the Defending Pokémon. That Pokémon is now Poisoned. Put 3 damage counters instead of 1 on that Pokémon between turns. This power can''t be used if Drapion is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Sniping Tail","cost":["Darkness","Darkness","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"40","text":"Does 40 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[452]',NULL,'["Put this card onto your Active Drapion. Drapion LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-124','Giratina LV.X','Pokémon','124','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/124.png","large":"https://images.pokemontcg.io/pl1/124_hires.png"}',NULL,'130','X','["Level-Up"]','["Psychic"]','Giratina',NULL,'[{"name":"Invisible Tentacles","text":"Whenever your opponent''s Pokémon tries to attack, your opponent discards 1 card from his or her hand. (If your opponent can''t discard 1 card, your opponent''s Pokémon can''t attack.) You can''t use more than 1 Invisible Tentacles Poké-Body each turn.","type":"Poké-Body"}]','[{"name":"Darkness Lost","cost":["Psychic","Psychic","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"","text":"This attack does 30 damage to each of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) If any of your opponent''s Pokémon would be Knocked Out by damage from this attack, put that Pokémon and all cards attached to it in the Lost Zone instead of discarding it."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Colorless","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[487]',NULL,'["Put this card onto your Active Giratina. Giratina LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-125','Palkia G LV.X','Pokémon','125','Rare Holo LV.X','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/125.png","large":"https://images.pokemontcg.io/pl1/125_hires.png"}',NULL,'120','X','["Level-Up","SP"]','["Water"]','Palkia G',NULL,'[{"name":"Lost Cyclone","text":"Once during your turn (before your attack), you may use this power. Any player who has 4 or more Benched Pokémon chooses 3 of his or her Benched Pokémon. Put the other Benched Pokémon and all cards attached to them in the Lost Zone. (You choose your Pokémon first.) This power can''t be used it Palkia G is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Hydro Shot","cost":["Water","Water","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Discard 2 Energy attached to Palkia G. Choose 1 of your opponent''s Pokémon. This attack does 80 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[484]',NULL,'["Put this card onto your Active Palkia G. Palkia G LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-126','Shaymin LV.X','Pokémon','126','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/126.png","large":"https://images.pokemontcg.io/pl1/126_hires.png"}',NULL,'100','X','["Level-Up"]','["Grass"]','Shaymin',NULL,'[{"name":"Thankfulness","text":"Each of your Grass Pokémon (excluding any Shaymin) gets +40 HP. You can''t use more than 1 Thankfulness Poké-Body each turn.","type":"Poké-Body"}]','[{"name":"Seed Flare","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"Choose as many Grass Energy cards from your hand as you like and attach them to your Pokémon in any way you like. If you do, this attack does 40 damage plus 20 more damage for each Grass Energy attached in this way."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Water","value":"-20"}]','["Colorless"]',1,'[492]',NULL,'["Put this card onto your Active Shaymin. Shaymin LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-127','Shaymin LV.X','Pokémon','127','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/127.png","large":"https://images.pokemontcg.io/pl1/127_hires.png"}',NULL,'110','X','["Level-Up"]','["Grass"]','Shaymin',NULL,'[{"name":"Revenge Seed","text":"If any of your Grass Pokémon were Knocked Out by damage from an opponent''s attack during his or her last turn, each of Shaymin''s attacks does 60 more damage to the Active Pokémon (before applying Weakness and Resistance).","type":"Poké-Body"}]','[{"name":"Energy Flare","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"You may move any number of Energy cards attached to your Pokémon to your other Pokémon in any way you like."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[492]',NULL,'["Put this card onto your Active Shaymin. Shaymin LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl1');
INSERT INTO "Card" VALUES('pl1-128','Electabuzz','Pokémon','128','Rare Secret','Ken Sugimori','It loves to feed on strong electricity. It occasionally appears around large power plants and so on.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/128.png","large":"https://images.pokemontcg.io/pl1/128_hires.png"}',NULL,'70','35','["Basic"]','["Lightning"]',NULL,'["Electivire"]',NULL,'[{"name":"Thundershock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed."},{"name":"Thunderpunch","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 10 more damage. If tails, Electabuzz does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[125]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-129','Hitmonchan','Pokémon','129','Rare Secret','Ken Sugimori','The spirit of a pro boxer has infused this POKéMON. It throws punches that are faster than a bullet train.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/129.png","large":"https://images.pokemontcg.io/pl1/129_hires.png"}',NULL,'70','33','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Jab","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Special Punch","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[107]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-130','Scyther','Pokémon','130','Rare Secret','Ken Sugimori','It tears and shreds prey with its wickedly sharp scythes. It very rarely spreads its wings to fly.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/130.png","large":"https://images.pokemontcg.io/pl1/130_hires.png"}',NULL,'70','25','["Basic"]','["Grass"]',NULL,'["Scizor"]',NULL,'[{"name":"Swords Dance","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"During your next turn, Scyther''s Slash attack''s base damage is 60."},{"name":"Slash","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[123]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-SH4','Lotad','Pokémon','SH4','Rare','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/SH4.png","large":"https://images.pokemontcg.io/pl1/SH4_hires.png"}',NULL,'50','14','["Basic"]','["Grass"]',NULL,'["Lombre"]','[{"name":"Swift Swim","text":"If Lotad has any Water Energy attached to it, Lotad''s Retreat Cost is 0.","type":"Poké-Body"}]','[{"name":"Blot","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"Remove 1 damage counter from Lotad."},{"name":"Jump On","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 damage plus 20 more damage."}]','[{"type":"Lightning","value":"+10"}]',NULL,'["Colorless"]',1,'[270]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-SH5','Swablu','Pokémon','SH5','Rare','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/SH5.png","large":"https://images.pokemontcg.io/pl1/SH5_hires.png"}',NULL,'50','16','["Basic"]','["Colorless"]',NULL,'["Altaria"]',NULL,'[{"name":"Roost","cost":[],"convertedEnergyCost":0,"damage":"","text":"Remove 4 damage counters from Swablu. Swablu can''t retreat during your next turn."},{"name":"Mirror Move","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If Swablu was damaged by an attack during your opponent''s last turn, this attack does the same amount of damage done to Swablu to the Defending Pokémon."},{"name":"Fury Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 3 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[333]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl1-SH6','Vulpix','Pokémon','SH6','Rare','Mitsuhiro Arita',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl1/SH6.png","large":"https://images.pokemontcg.io/pl1/SH6_hires.png"}',NULL,'60','20','["Basic"]','["Fire"]',NULL,'["Ninetales"]',NULL,'[{"name":"Find Wildfire","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for up to 2 Fire Energy cards, show them to your opponent, and put them in your hand. Shuffle your deck afterward."},{"name":"Brushfire","cost":["Fire"],"convertedEnergyCost":1,"damage":"10","text":"Does 10 damage to each of your opponent''s Benched Grass Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Inflame","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Discard a Fire Energy card from your hand. (If you can''t discard a card from your hand, this attack does nothing.)"}]','[{"type":"Water","value":"+10"}]',NULL,'["Colorless"]',1,'[37]',NULL,NULL,'pl1');
INSERT INTO "Card" VALUES('pl2-1','Arcanine','Pokémon','1','Rare Holo','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/1.png","large":"https://images.pokemontcg.io/pl2/1_hires.png"}',NULL,'100','53','["Stage 1"]','["Fire"]','Growlithe',NULL,'[{"name":"Flare Condition","text":"As long as Arcanine has any Fire Energy attached to it, Arcanine has no Weakness.","type":"Poké-Body"}]','[{"name":"Burn Out","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"You may do 30 damage plus 30 more damage. If you do, Arcanine is now Burned."},{"name":"Flames of Rage","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"Discard a Fire Energy attached to Arcanine. This attack does 60 damage plus 10 more damage for each damage counter on Arcanine."}]','[{"type":"Water","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[59]',NULL,NULL,'pl2');
