INSERT INTO "Card" VALUES('pl2-66','Kakuna','Pokémon','66','Common','Midori Harada','While awaiting evolution, it hides from predators under leaves and in nooks of branches.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/66.png","large":"https://images.pokemontcg.io/pl2/66_hires.png"}',NULL,'80','8','["Stage 1"]','["Grass"]','Weedle','["Beedrill"]','[{"name":"Exoskeleton","text":"Any damage done to Kakuna by attacks is reduced by 20 (after applying Weakness and Resistance).","type":"Poké-Body"}]','[{"name":"Dangerous Evolution","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"The Defending Pokémon is now Poisoned. Flip a coin. If heads, search your deck for an Evolution card that evolves from Kakuna and put it onto Kakuna. (This counts as evolving Kakuna.) Shuffle your deck afterward."}]','[{"type":"Fire","value":"+20"}]',NULL,'["Colorless","Colorless"]',2,'[14]',NULL,NULL,'pl2');
