INSERT INTO "Card" VALUES('pl2-91','Flint''s Willpower','Trainer','91','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/91.png","large":"https://images.pokemontcg.io/pl2/91_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Attach a basic Energy card from your hand to 1 of your Pokémon SP."]','pl2');
INSERT INTO "Card" VALUES('pl2-92','Lucian''s Assignment','Trainer','92','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/92.png","large":"https://images.pokemontcg.io/pl2/92_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Move as many Energy cards attached to 1 of your Pokémon as you like to another of your Pokémon."]','pl2');
INSERT INTO "Card" VALUES('pl2-93','Pokémon Contest Hall','Trainer','93','Uncommon','Makoto Imai',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/93.png","large":"https://images.pokemontcg.io/pl2/93_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Once during each player''s turn, if that player''s Bench isn''t full, the player may flip a coin. If heads, that player searches his or her deck for a Basic Pokémon and puts it onto his or her Bench. If the player does, he or she may search his or her deck for a Pokémon Tool card and attach it to that Pokémon. If that player searched his or her deck, the player shuffles his or her deck afterward."]','pl2');
INSERT INTO "Card" VALUES('pl2-94','Sunyshore City Gym','Trainer','94','Uncommon','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/94.png","large":"https://images.pokemontcg.io/pl2/94_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Any damage done by attacks from Lightning Pokémon (both yours and your opponent''s) to the Defending Pokémon isn''t affected by Resistance. Each Lightning Pokémon in play (both yours and your opponent''s) has no Weakness."]','pl2');
INSERT INTO "Card" VALUES('pl2-95','Team Galactic''s Invention G-107 Technical Machine G','Trainer','95','Uncommon','Makoto Imai',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/95.png","large":"https://images.pokemontcg.io/pl2/95_hires.png"}',NULL,NULL,NULL,'["Technical Machine"]',NULL,NULL,NULL,NULL,'[{"name":"Damage Porter","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 10 damage times the number of damage counters on the Pokémon this card is attached to to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach this card to 1 of your Pokémon SP in play. That Pokémon may use this card''s attack instead of its own. When the Pokémon this card is attached to is no longer Pokémon SP, discard this card."]','pl2');
INSERT INTO "Card" VALUES('pl2-96','Team Galactic''s Invention G-109 SP Radar','Trainer','96','Uncommon','Kent Kanetsuna',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/96.png","large":"https://images.pokemontcg.io/pl2/96_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a card from your hand and put it on top of your deck. Search your deck for a Pokémon SP, show it to your opponent, and put it into your hand. Shuffle your deck afterward. (If this is the only card in your hand, you can''t play this card.)"]','pl2');
INSERT INTO "Card" VALUES('pl2-97','Underground Expedition','Trainer','97','Uncommon','Kagemaru Himeno',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/97.png","large":"https://images.pokemontcg.io/pl2/97_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at the 4 cards from the bottom of your deck. Choose any 2 cards there and put them into your hand. Put the remaining cards back on the bottom of your deck in any order."]','pl2');
INSERT INTO "Card" VALUES('pl2-98','Volkner''s Philosophy','Trainer','98','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/98.png","large":"https://images.pokemontcg.io/pl2/98_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","You may discard a card from your hand. Then, draw cards until you have 6 cards in your hand. (If you can''t draw any cards, you can''t play this card.)"]','pl2');
