INSERT INTO "Card" VALUES('pl2-112','Pikachu','Pokémon','112','Rare Secret','Mitsuhiro Arita','It has small electric sacs on both its cheeks. If threatened, it looses electric charges from the sacs.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl2/112.png","large":"https://images.pokemontcg.io/pl2/112_hires.png"}',NULL,'40','12','["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Gnaw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Thunder Jolt","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, Pikachu does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[25]',NULL,NULL,'pl2');
