INSERT INTO "Card" VALUES('pl3-58','Floatzel','Pokémon','58','Uncommon','Kagemaru Himeno','It is a common sight around fishing ports. It is known to rescue people and carry off prey.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/58.png","large":"https://images.pokemontcg.io/pl3/58_hires.png"}',NULL,'70','27','["Stage 1"]','["Water"]','Buizel',NULL,NULL,'[{"name":"Razor Fin","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""},{"name":"Jet Screw","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 damage plus 10 more damage."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[419]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-59','Gabite','Pokémon','59','Uncommon','Tomokazu Komiya','It loves sparkly things. It seeks treasures in caves and hoards the loot in its nest.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/59.png","large":"https://images.pokemontcg.io/pl3/59_hires.png"}',NULL,'80','36','["Stage 1"]','["Colorless"]','Gible','["Garchomp"]',NULL,'[{"name":"Healing Scale","cost":[],"convertedEnergyCost":0,"damage":"","text":"Remove 1 damage counter from each of your Pokémon."},{"name":"Sand Tomb","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Colorless","value":"+20"}]',NULL,'["Colorless"]',1,'[444]',NULL,NULL,'pl3');
