INSERT INTO "Card" VALUES('pl3-79','Relicanth','Pokémon','79','Uncommon','Sumiyoshi Kizuki','A rare Pokémon discovered during a deep-sea exploration. It has not changed in over 100 million years.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/79.png","large":"https://images.pokemontcg.io/pl3/79_hires.png"}',NULL,'80','36','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Grand Swell","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of your opponent''s Pokémon. This attack does 30 damage to that Pokémon for each Pokémon Tool and Stadium card your opponent has in play. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Amnesia","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Choose 1 of the Defending Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless"]',1,'[369]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-80','Rhydon','Pokémon','80','Uncommon','Masakazu Fukuda','Standing on its hind legs freed its forelegs and made it smarter. It is very forgetful, however.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/80.png","large":"https://images.pokemontcg.io/pl3/80_hires.png"}',NULL,'90','45','["Stage 1"]','["Fighting"]','Rhyhorn','["Rhyperior"]',NULL,'[{"name":"Fury Attack","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20×","text":"Flip 3 coins. This attack does 20 damage times the number of heads."},{"name":"Rock Tumble","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"This attack''s damage isn''t affected by Resistance."}]','[{"type":"Water","value":"+20"}]','[{"type":"Lightning","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[112]',NULL,NULL,'pl3');
