INSERT INTO "Card" VALUES('pl3-88','Yanma','Pokémon','88','Uncommon','Midori Harada','It can hover is one spot by flapping its wings at high speed. It flits about to guard its territory.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/88.png","large":"https://images.pokemontcg.io/pl3/88_hires.png"}',NULL,'70','17','["Basic"]','["Grass"]',NULL,'["Yanmega"]',NULL,'[{"name":"Supersonic","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."},{"name":"Air Slash","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, discard an Energy attached to Yanma."}]','[{"type":"Lightning","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[193]',NULL,NULL,'pl3');
