INSERT INTO "Card" VALUES('pl3-95','Chatot','Pokémon','95','Common','Satoshi Ohta','Its tongue is just like a human''s. As a result, it can cleverly mimic human speech.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/95.png","large":"https://images.pokemontcg.io/pl3/95_hires.png"}',NULL,'60','28','["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward."},{"name":"Nosedive","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, Chatot does 10 damage to itself."}]','[{"type":"Lightning","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[441]',NULL,NULL,'pl3');
