INSERT INTO "Card" VALUES('pl3-131','Turtwig','Pokémon','131','Common','Atsuko Nishida','The shell on its back is made of soil. On a very healthy Turtwig, the shell should feel moist.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/131.png","large":"https://images.pokemontcg.io/pl3/131_hires.png"}',NULL,'60','8','["Basic"]','["Grass"]',NULL,'["Grotle"]',NULL,'[{"name":"Shell Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Stomp","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 damage plus 10 more damage."}]','[{"type":"Fire","value":"+10"}]','[{"type":"Water","value":"-20"}]','["Colorless","Colorless"]',2,'[387]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-132','Whismur','Pokémon','132','Common','Yuka Morii','Usually, its cries are like quiet murmurs. If frightened, it shrieks at the same volume as a jet plane.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/132.png","large":"https://images.pokemontcg.io/pl3/132_hires.png"}',NULL,'60','11','["Basic"]','["Colorless"]',NULL,'["Loudred"]',NULL,'[{"name":"Tone-Deaf","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, the Defending Pokémon is now Confused."},{"name":"Rollout","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[293]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-133','Zubat','Pokémon','133','Common','Masakazu Fukuda','It checks its surroundings and location using reflections of the ultrasonic waves from its mouth.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/133.png","large":"https://images.pokemontcg.io/pl3/133_hires.png"}',NULL,'50','6','["Basic"]','["Psychic"]',NULL,'["Golbat"]',NULL,'[{"name":"Quick Turn","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Psychic","value":"+10"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[41]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-134','Battle Tower','Trainer','134','Uncommon','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/134.png","large":"https://images.pokemontcg.io/pl3/134_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","Whenever any player plays any Pokémon from his or her hand to Level-Up 1 of his or her Pokémon, remove 4 damage counters from that Pokémon."]','pl3');
INSERT INTO "Card" VALUES('pl3-135','Champion''s Room','Trainer','135','Uncommon','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/135.png","large":"https://images.pokemontcg.io/pl3/135_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","The Retreat cost for each Pokémon SP (both yours and your opponent''s) is Colorless less."]','pl3');
INSERT INTO "Card" VALUES('pl3-136','Cynthia''s Guidance','Trainer','136','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/136.png","large":"https://images.pokemontcg.io/pl3/136_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Look at the top 7 cards of your deck, choose 1 of them, and put it into your hand. Put the other cards back on top of your deck. Shuffle your deck afterward."]','pl3');
INSERT INTO "Card" VALUES('pl3-137','Cyrus''s Initiative','Trainer','137','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/137.png","large":"https://images.pokemontcg.io/pl3/137_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Flip 2 coins. If either of them is heads, look at your opponent''s hand. For each heads, choose 1 card from your opponent''s hand and put it on the bottom of your opponent''s deck in any order."]','pl3');
INSERT INTO "Card" VALUES('pl3-138','Night Teleporter','Trainer','138','Uncommon','Ryota Saito',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/138.png","large":"https://images.pokemontcg.io/pl3/138_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, put all cards in your hand on top of your deck. Then, search your deck for any 1 card and put it into your hand. Shuffle your deck afterward."]','pl3');
INSERT INTO "Card" VALUES('pl3-139','Palmer''s Contribution','Trainer','139','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/139.png","large":"https://images.pokemontcg.io/pl3/139_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your discard pile for up to 5 in any combination of Pokémon and basic Energy cards. Show them to your opponent and shuffle them into your deck."]','pl3');
