INSERT INTO "Card" VALUES('pl3-141','Absol G LV.X','Pokémon','141','Rare Holo LV.X','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/141.png","large":"https://images.pokemontcg.io/pl3/141_hires.png"}',NULL,'100','X','["Level-Up","SP"]','["Darkness"]','Absol G',NULL,'[{"name":"Darkness Send","text":"Once during your turn (before your attack), when you put Absol G LV.X from your hand onto your Active Absol G, you may flip 3 coins. For each heads, put the top card from your opponent''s deck in the Lost Zone.","type":"Poké-Power"}]','[{"name":"Darkness Slugger","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"You may discard a card from your hand. If you do, this attack does 30 damage plus 30 more damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[359]',NULL,'["Put this card onto your Active Absol G. Absol G LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-142','Blaziken FB LV.X','Pokémon','142','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/142.png","large":"https://images.pokemontcg.io/pl3/142_hires.png"}',NULL,'110','X','["Level-Up","SP"]','["Fire"]','Blaziken FB',NULL,'[{"name":"Burning Spirit","text":"Any damage done by attacks to a Burned Pokémon (both yours and your opponent''s) is increased by 40 (after applying Weakness and Resistance). No more than 40 damage can be added by all Burning Spirit Poké-Bodies.","type":"Poké-Body"}]','[{"name":"Jet Shoot","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"80","text":"During your opponent''s next turn, any damage done to Blaziken FB by attacks is increased by 40 (after applying Weakness and Resistance)."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[257]',NULL,'["Put this card onto your Active Blaziken FB. Blaziken FB LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-143','Charizard G LV.X','Pokémon','143','Rare Holo LV.X','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/143.png","large":"https://images.pokemontcg.io/pl3/143_hires.png"}',NULL,'120','X','["Level-Up","SP"]','["Fire"]','Charizard G',NULL,'[{"name":"Call for Power","text":"As often as you like during your turn (before your attack), you may move an Energy attached to 1 of your Pokémon to Charizard G. This power can''t be used if Charizard G is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Malevolent Fire","cost":["Fire","Fire","Colorless","Colorless","Colorless"],"convertedEnergyCost":5,"damage":"150","text":"Flip a coin. If tails, discard all Energy attached to Charizard G."}]','[{"type":"Water","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[6]',NULL,'["Put this card onto your Active Charizard G. Charizard G LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-144','Electivire FB LV.X','Pokémon','144','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/144.png","large":"https://images.pokemontcg.io/pl3/144_hires.png"}',NULL,'120','X','["Level-Up","SP"]','["Lightning"]','Electivire FB',NULL,'[{"name":"Energy Recycle","text":"Once during your turn (before your attack), you may use this power. If you do, your turn ends. Search your discard pile for up to 3 Energy cards and attach them to your Pokémon in any way you like. This power can''t be used if Electivire FB is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Powerful Spark","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"This attack does 30 damage plus 10 more damage for each Energy attached to all of your Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[466]',NULL,'["Put this card onto your Active Electivire FB. Electivire FB LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-145','Garchomp C LV.X','Pokémon','145','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/145.png","large":"https://images.pokemontcg.io/pl3/145_hires.png"}',NULL,'110','X','["Level-Up","SP"]','["Colorless"]','Garchomp C',NULL,'[{"name":"Healing Breath","text":"Once during your turn (before your attack), when you put Garchomp C LV.X from your hand onto your Active Garchomp C, you may remove all damage counters from each of your Pokémon SP.","type":"Poké-Power"}]','[{"name":"Dragon Rush","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard 2 Energy attached to Garchomp C. Choose 1 of your opponent''s Pokémon. This attack does 80 damage to that Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.) Garchomp C can''t use Dragon Rush during your next turn."}]','[{"type":"Colorless","value":"×2"}]',NULL,NULL,NULL,'[445]',NULL,'["Put this card onto your Active Garchomp C. Garchomp C LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-146','Rayquaza C LV.X','Pokémon','146','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/146.png","large":"https://images.pokemontcg.io/pl3/146_hires.png"}',NULL,'120','X','["Level-Up","SP"]','["Colorless"]','Rayquaza C',NULL,'[{"name":"Dragon Spirit","text":"If Rayquaza C is your Active Pokémon and is damaged but not Knocked Out by an opponent''s attack, you may search your discard pile for an Energy card and attach it to Rayquaza C.","type":"Poké-Body"}]','[{"name":"Final Blowup","cost":["Water","Psychic","Fighting","Colorless"],"convertedEnergyCost":4,"damage":"200","text":"Discard all Energy attached to Rayquaza C. Ignore this effect if you have no cards in your hand."}]','[{"type":"Colorless","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[384]',NULL,'["Put this card onto your Active Rayquaza C. Rayquaza C LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-147','Staraptor FB LV.X','Pokémon','147','Rare Holo LV.X','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/147.png","large":"https://images.pokemontcg.io/pl3/147_hires.png"}',NULL,'100','X','["Level-Up","SP"]','["Colorless"]','Staraptor FB',NULL,'[{"name":"Fast Call","text":"Once during your turn (before your attack), you may search your deck for a Supporter card, show it to your opponent, and put it into your hand. Shuffle your deck afterward. This power can''t be used if Staraptor FB is affected by a Special Condition.","type":"Poké-Power"}]','[{"name":"Defog","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":"Before doing damage, you may discard any Stadium card in play. If you do, this attack''s base damage is 70 instead of 40."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[398]',NULL,'["Put this card onto your Active Staraptor FB. Staraptor FB LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl3');
INSERT INTO "Card" VALUES('pl3-148','Articuno','Pokémon','148','Rare Secret','Toshinao Aoki','This legendary Pokémon is said to freeze the water in the air during winter, causing snow.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/148.png","large":"https://images.pokemontcg.io/pl3/148_hires.png"}',NULL,'70','34','["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Diamond Dust","cost":["Water","Water","Water"],"convertedEnergyCost":3,"damage":"20","text":"Flip a coin. If heads, the Defending Pokémon is now Paralyzed and this attack does 10 damage to each of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]',NULL,'[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[144]',NULL,NULL,'pl3');
