INSERT INTO "Card" VALUES('pl3-SH8','Relicanth','Pokémon','SH8','Rare','Sumiyoshi Kizuki','A rare Pokémon discovered during a deep-sea exploration. It has not changed in over 100 million years.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/SH8.png","large":"https://images.pokemontcg.io/pl3/SH8_hires.png"}',NULL,'80','39','["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Deep Sea Pressure","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"During your opponent''s next turn, the Defending Pokémon''s Retreat Cost is ColorlessColorless more."},{"name":"Aqua Wave","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"Flip 2 coins. This attack does 40 damage plus 10 more damage for each heads."}]','[{"type":"Grass","value":"+20"}]',NULL,'["Colorless"]',1,'[369]',NULL,NULL,'pl3');
INSERT INTO "Card" VALUES('pl3-SH9','Yanma','Pokémon','SH9','Rare','Midori Harada','It can hover in one spot by flapping its wings at high speed. It flits about to guard its territory.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl3/SH9.png","large":"https://images.pokemontcg.io/pl3/SH9_hires.png"}',NULL,'70','22','["Basic"]','["Grass"]',NULL,'["Yanmega"]',NULL,'[{"name":"Sonicboom","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"This attack''s damage isn''t affected by Weakness or Resistance."},{"name":"Baton Pass","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"You may switch Yanma with 1 of your Benched Pokémon. If you do, move as many Energy cards attached to Yanma as you like to the new Active Pokémon."}]','[{"type":"Lightning","value":"+20"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[193]',NULL,NULL,'pl3');
