INSERT INTO "Card" VALUES('pl4-83','Bench Shield','Trainer','83','Uncommon','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/83.png","large":"https://images.pokemontcg.io/pl4/83_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Bench Shield to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","As long as the Pokémon this card is attached to is on your Bench, prevent all damage done to that Pokémon by attacks (both yours and your opponent''s)."]','pl4');
INSERT INTO "Card" VALUES('pl4-84','Buffer Piece','Trainer','84','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/84.png","large":"https://images.pokemontcg.io/pl4/84_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Buffer Piece to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","Any damage done to the Pokémon this card is attached to by an opponent''s attack is reduced by 20 (after applying Weakness and Resistance). At the end of your opponent''s turn after you played Buffer Piece, discard Buffer Piece."]','pl4');
INSERT INTO "Card" VALUES('pl4-85','Department Store Girl','Trainer','85','Uncommon','Kanako Eo',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/85.png","large":"https://images.pokemontcg.io/pl4/85_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Search your deck for up to 3 Pokémon Tool cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward."]','pl4');
INSERT INTO "Card" VALUES('pl4-86','Energy Restore','Trainer','86','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/86.png","large":"https://images.pokemontcg.io/pl4/86_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 3 coins. For each heads, put a basic Energy card from your discard pile into your hand. If you don''t have that many basic Energy cards in your discard pile, put all of them into your hand."]','pl4');
INSERT INTO "Card" VALUES('pl4-87','Expert Belt','Trainer','87','Uncommon','Wataru Kawahara',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/87.png","large":"https://images.pokemontcg.io/pl4/87_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Expert Belt to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","The Pokémon this card is attached to gets +20 HP and that Pokémon''s attacks do 20 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance). When the Pokémon this card is attached to is Knocked Out, your opponent takes 1 more Prize card."]','pl4');
INSERT INTO "Card" VALUES('pl4-88','Lucky Egg','Trainer','88','Uncommon','Nobuyuki Fujimoto',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/88.png","large":"https://images.pokemontcg.io/pl4/88_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach Lucky Egg to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.","When the Pokémon this card is attached to is Knocked Out by damage from an opponent''s attack, draw cards until you have 7 cards in your hand."]','pl4');
INSERT INTO "Card" VALUES('pl4-89','Old Amber','Trainer','89','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/89.png","large":"https://images.pokemontcg.io/pl4/89_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Hard Amber","text":"As long as Old Amber is on your Bench, prevent all damage done to Old Amber by attacks (both yours and your opponent''s).","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Old Amber as if it were a Colorless Basic Pokémon. (Old Amber counts as a Trainer card as well, but if Old Amber is Knocked Out, this counts as a Knocked Out Pokémon.) Old Amber can''t be affected by any Special Conditions and can''t retreat. At any time during your turn before your attack, you may discard Old Amber from play. (This doesn''t count as a Knocked Out Pokémon.)"]','pl4');
INSERT INTO "Card" VALUES('pl4-90','Professor Oak''s Visit','Trainer','90','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/90.png","large":"https://images.pokemontcg.io/pl4/90_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.","Draw 3 cards. Then, choose a card from your hand and put it on the bottom of your deck."]','pl4');
INSERT INTO "Card" VALUES('pl4-91','Ultimate Zone','Trainer','91','Uncommon','Yusuke Ishikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/91.png","large":"https://images.pokemontcg.io/pl4/91_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","During each player''s turn, the player may move an Energy card attached to 1 of his or her Benched Pokémon to his or her Active Arceus as often as he or she likes."]','pl4');
INSERT INTO "Card" VALUES('pl4-92','Dome Fossil','Trainer','92','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/92.png","large":"https://images.pokemontcg.io/pl4/92_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Rock Reaction","text":"When you attach a Fighting Energy card from your hand to Dome Fossil (excluding effects of attacks or Poké-Powers), search your deck for a card that evolves from Dome Fossil and put it onto Dome Fossil (this counts as evolving Dome Fossil). Shuffle your deck afterward.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Dome Fossil as if it were a Colorless Basic Pokémon. (Dome Fossil counts as a Trainer card as well, but if Dome Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Dome Fossil can''t be affected by any Special Conditions and can''t retreat. At any time during your turn before your attack, you may discard Dome Fossil from play. (This doesn''t count as a Knocked Out Pokémon.)"]','pl4');
INSERT INTO "Card" VALUES('pl4-93','Helix Fossil','Trainer','93','Common','Ryo Ueda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/93.png","large":"https://images.pokemontcg.io/pl4/93_hires.png"}',NULL,'50',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Aqua Reaction","text":"When you attach a Water Energy card from your hand to Helix Fossil (excluding effects of attacks or Poké-Powers), search your deck for a card that evolves from Helix Fossil and put it onto Helix Fossil (this counts as evolving Helix Fossil). Shuffle your deck afterward.","type":"Poké-Body"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play Helix Fossil as if it were a Colorless Basic Pokémon. (Helix Fossil counts as a Trainer card as well, but if Helix Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Helix Fossil can''t be affected by any Special Conditions and can''t retreat. At any time during your turn before your attack, you may discard Helix Fossil from play. (This doesn''t count as a Knocked Out Pokémon.)"]','pl4');
INSERT INTO "Card" VALUES('pl4-94','Arceus LV.X','Pokémon','94','Rare Holo LV.X','Shizurow',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pl4/94.png","large":"https://images.pokemontcg.io/pl4/94_hires.png"}',NULL,'120','X','["Level-Up"]','["Colorless"]','Arceus',NULL,'[{"name":"Multi-type","text":"Arceus LV. X''s type is the same type as its previous Level.","type":"Poké-Body"},{"name":"Omniscient","text":"Arceus can use the attacks of all Arceus you have in play as its own. (You still need the necessary Energy to use each attack.)","type":"Poké-Body"}]',NULL,NULL,NULL,'["Colorless"]',1,'[493]',NULL,'["You may have as many of this card in your deck as you like.","Put this card onto your Active Arceus. Arceus LV.X can use any attack, Poké-Power, or Poké-Body from its previous level."]','pl4');
