INSERT INTO "Card" VALUES('pop5-3','Mew δ','Pokémon','3','Rare','Masakazu Fukuda',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop5/3.png","large":"https://images.pokemontcg.io/pop5/3_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Copy","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of the Defending Pokémon''s attacks. Copy copies that attack. This attack does nothing if Mew doesn''t have the Energy necessary to use that attack. (You must still do anything else required for that attack.) Mew performs that attack."},{"name":"Extra Draw","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"If your opponent has any Pokémon-ex in play, search your deck for up to 2 basic Energy cards and attach them to Mew. Shuffle your deck afterward."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[151]',NULL,NULL,'pop5');
INSERT INTO "Card" VALUES('pop5-4','Double Rainbow Energy','Energy','4','Rare','Takumi Akabane',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop5/4.png","large":"https://images.pokemontcg.io/pop5/4_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Has no effect other than providing Energy.) Damage done to your opponent''s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (before applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy."]','pop5');
