INSERT INTO "Card" VALUES('pop5-7','Rare Candy','Trainer','7','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/pop5/7.png","large":"https://images.pokemontcg.io/pop5/7_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.)"]','pop5');
INSERT INTO "Card" VALUES('pop5-8','Boost Energy','Energy','8','Uncommon','Shin-ichi Yoshikawa',NULL,'{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop5/8.png","large":"https://images.pokemontcg.io/pop5/8_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Boost Energy can be attached only to an Evolved Pokémon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides ColorlessColorlessColorless Energy. The Pokémon Boost Energy is attached to can''t retreat. If the Pokémon Boost Energy is attached to isn''t an Evolved Pokémon, discard Boost Energy."]','pop5');
