INSERT INTO "Card" VALUES('pop6-1','Bastiodon','Pokémon','1','Rare','Kazuyuki Kano','Any frontal attack is repulsed. It is a docile Pokémon that feeds on grass and berries.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop6/1.png","large":"https://images.pokemontcg.io/pop6/1_hires.png"}',NULL,'130','51','["Stage 2"]','["Metal"]','Shieldon',NULL,'[{"name":"Protective Wall","text":"Prevent all damage done to your Benched Pokémon by your opponent''s attacks.","type":"Poké-Body"}]','[{"name":"Anger Revenge","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"If Bastiodon was damaged by an attack during your opponent''s last turn, this attack does 40 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fire","value":"+40"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[411]',NULL,NULL,'pop6');
INSERT INTO "Card" VALUES('pop6-2','Lucario','Pokémon','2','Rare','Kouki Saitou','It has the ability to sense the auras of all things. It understands human speech.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop6/2.png","large":"https://images.pokemontcg.io/pop6/2_hires.png"}',NULL,'90','30','["Stage 1"]','["Fighting"]','Riolu',NULL,NULL,'[{"name":"Feint","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"This attack''s damage isn''t affected by Resistance."},{"name":"Aura Sphere","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"40","text":"Does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Psychic","value":"+20"}]',NULL,'["Colorless"]',1,'[448]',NULL,NULL,'pop6');
INSERT INTO "Card" VALUES('pop6-3','Manaphy','Pokémon','3','Rare','Atsuko Nishida','Born on a cold seafloor, it will swim great distances to return to its birthplace.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop6/3.png","large":"https://images.pokemontcg.io/pop6/3_hires.png"}',NULL,'70','20','["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward."},{"name":"Aqua Ring","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"30","text":"Switch Manaphy with 1 of your Benched Pokémon."}]','[{"type":"Lightning","value":"+20"}]',NULL,'["Colorless"]',1,'[490]',NULL,NULL,'pop6');
