INSERT INTO "Card" VALUES('pop6-5','Rampardos','Pokémon','5','Rare','Kazuyuki Kano','Its powerful head butt has enough power to shatter even the most durable things upon impact.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop6/5.png","large":"https://images.pokemontcg.io/pop6/5_hires.png"}',NULL,'120','48','["Stage 2"]','["Fighting"]','Cranidos',NULL,NULL,'[{"name":"Assurance","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"As long as the Defending Pokémon''s remaining HP is 60 or less, this attack''s base damage is 60 instead of 30."},{"name":"Hasty Headbutt","cost":["Fighting","Fighting","Fighting"],"convertedEnergyCost":3,"damage":"100","text":"Rampardos does 20 damage to itself. This attack''s damage isn''t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon."}]','[{"type":"Grass","value":"+30"}]',NULL,'["Colorless"]',1,'[409]',NULL,NULL,'pop6');
