INSERT INTO "Card" VALUES('pop6-11','Bidoof','Pokémon','11','Common','Mitsuhiro Arita','With nerves of steel, nothing can perturb it. It is more agile and active than it appears.','{"unlimited":"Legal"}','{"small":"https://images.pokemontcg.io/pop6/11.png","large":"https://images.pokemontcg.io/pop6/11_hires.png"}',NULL,'50','10','["Basic"]','["Colorless"]',NULL,'["Bibarel"]',NULL,'[{"name":"Amnesia","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose 1 of the Defending Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."},{"name":"Scavenge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your discard pile for a Trainer card, show it to your opponent, an put it into your hand."}]','[{"type":"Fighting","value":"+10"}]',NULL,'["Colorless"]',1,'[399]',NULL,NULL,'pop6');
