INSERT INTO "Card" VALUES('rsv10pt5-41','Gothita','Pokémon','41','Common','Mousho','Their ribbonlike feelers increase their psychic power. They are always staring at something.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/rsv10pt5/41.png","large":"https://images.pokemontcg.io/rsv10pt5/41_hires.png"}','I','70',NULL,'["Basic"]','["Psychic"]',NULL,'["Gothorita"]',NULL,'[{"name":"Super Psy Bolt","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[574]',NULL,NULL,'rsv10pt5');
