INSERT INTO "Card" VALUES('rsv10pt5-43','Gothitelle','Pokémon','43','Rare','Mousho','Starry skies thousands of light-years away are visible in the space distorted by their intense psychic power.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/rsv10pt5/43.png","large":"https://images.pokemontcg.io/rsv10pt5/43_hires.png"}','I','150',NULL,'["Stage 2"]','["Psychic"]','Gothorita',NULL,'[{"name":"Distorted Future","text":"Once during your turn, if this Pokémon is in the Active Spot, you may have your opponent shuffle their hand into their deck and draw 3 cards.","type":"Ability"}]','[{"name":"Synchro Shot","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"90+","text":"If you have the same number of cards in your hand as your opponent, this attack does 90 more damage."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[576]',NULL,NULL,'rsv10pt5');
INSERT INTO "Card" VALUES('rsv10pt5-44','Frillish','Pokémon','44','Common','MARINA Chikazawa','With its thin, veil-like arms wrapped around the body of its opponent, it sinks to the ocean floor.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/rsv10pt5/44.png","large":"https://images.pokemontcg.io/rsv10pt5/44_hires.png"}','I','80',NULL,'["Basic"]','["Psychic"]',NULL,'["Jellicent"]',NULL,'[{"name":"Oceanic Gloom","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":"During your opponent''s next turn, they can''t play any Item cards from their hand."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[592]',NULL,NULL,'rsv10pt5');
