INSERT INTO "Card" VALUES('rsv10pt5-58','Scrafty','Pokémon','58','Uncommon','osare','Groups of them beat up anything that enters their territory. Each can spit acidic liquid from its mouth.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/rsv10pt5/58.png","large":"https://images.pokemontcg.io/rsv10pt5/58_hires.png"}','I','120',NULL,'["Stage 1"]','["Darkness"]','Scraggy',NULL,NULL,'[{"name":"Ruffians Attack","cost":["Darkness","Darkness"],"convertedEnergyCost":2,"damage":"60×","text":"Flip a coin for each Darkness Pokémon you have in play. This attack does 60 damage for each heads."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[560]',NULL,NULL,'rsv10pt5');
