INSERT INTO "Card" VALUES('sm1-76','Alolan Rattata','Pokémon','76','Common','Kouki Saitou','When the sun goes down, it becomes active. It runs around town on a chase for good food for the boss of its nest—Raticate.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/76.png","large":"https://images.pokemontcg.io/sm1/76_hires.png"}',NULL,'40',NULL,'["Basic"]','["Darkness"]',NULL,'["Raticate"]',NULL,'[{"name":"Gnaw","cost":[],"convertedEnergyCost":0,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]',NULL,NULL,'[19]',NULL,NULL,'sm1');
INSERT INTO "Card" VALUES('sm1-77','Alolan Raticate','Pokémon','77','Uncommon','match','This gourmet Pokémon is particular about the taste and freshness of its food. Restaurants where Raticate live have a good reputation.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/77.png","large":"https://images.pokemontcg.io/sm1/77_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Darkness"]','Alolan Rattata',NULL,NULL,'[{"name":"Evil Orders","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Search your deck for a number of cards up to the number of your Benched Pokémon and put them into your hand. Then, shuffle your deck."},{"name":"Endeavor","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"Flip 2 coins. This attack does 30 more damage for each heads."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[20]',NULL,NULL,'sm1');
