INSERT INTO "Card" VALUES('sm1-79','Alolan Persian','Pokémon','79','Uncommon','kirisAki','Its round face and smooth coat—softer than the most high-class velvet—have made this a very popular Pokémon in Alola.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/79.png","large":"https://images.pokemontcg.io/sm1/79_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Darkness"]','Alolan Meowth',NULL,NULL,'[{"name":"Taunt","cost":[],"convertedEnergyCost":0,"damage":"","text":"Switch 1 of your opponent''s Benched Pokémon with their Active Pokémon."},{"name":"Claw Rend","cost":["Darkness"],"convertedEnergyCost":1,"damage":"30+","text":"If your opponent''s Active Pokémon already has any damage counters on it, this attack does 30 more damage."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[53]',NULL,NULL,'sm1');
