INSERT INTO "Card" VALUES('sm1-81','Carvanha','Pokémon','81','Common','Sumiyoshi Kizuki','If they scent the faintest trace of blood, they rush to attack en masse. When alone, they''re rather cowardly.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/81.png","large":"https://images.pokemontcg.io/sm1/81_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Sharpedo"]',NULL,'[{"name":"Gnaw Through","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Discard all Pokémon Tool cards from your opponent''s Active Pokémon."},{"name":"Bite","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[318]',NULL,NULL,'sm1');
