INSERT INTO "Card" VALUES('sm1-92','Cutiefly','Pokémon','92','Common','Hitoshi Ariga','It feeds on the nectar and pollen of flowers. Because it''s able to sense auras, it can identify which flowers are about to bloom.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/92.png","large":"https://images.pokemontcg.io/sm1/92_hires.png"}',NULL,'30',NULL,'["Basic"]','["Fairy"]',NULL,'["Ribombee"]',NULL,'[{"name":"Fly Around","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":"If any damage is done to this Pokémon by attacks during your opponent''s next turn, flip a coin. If heads, prevent that damage."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[742]',NULL,NULL,'sm1');
