INSERT INTO "Card" VALUES('sm1-94','Dratini','Pokémon','94','Common','Naoyo Kimura','After a 10-hour struggle, a fisherman was able to pull one up and confirm its existence.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm1/94.png","large":"https://images.pokemontcg.io/sm1/94_hires.png"}',NULL,'60',NULL,'["Basic"]','["Dragon"]',NULL,'["Dragonair"]',NULL,'[{"name":"Signs of Evolution","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Dratini, a Dragonair, and a Dragonite, reveal them, and put them into your hand. Then, shuffle your deck."},{"name":"Tail Smack","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[147]',NULL,NULL,'sm1');
