INSERT INTO "Card" VALUES('sm10-11','Venomoth','Pokémon','11','Rare','Mina Nakai','The scales it scatters will paralyze anyone who touches them, making that person unable to stand.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/11.png","large":"https://images.pokemontcg.io/sm10/11_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Grass"]','Venonat',NULL,NULL,'[{"name":"Assassin Flight","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"You can use this attack only if your opponent''s Active Pokémon is affected by a Special Condition. This attack does 90 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Poison Powder","cost":["Grass"],"convertedEnergyCost":1,"damage":"30","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[49]',NULL,NULL,'sm10');
