INSERT INTO "Card" VALUES('sm10-13','Bellsprout','Pokémon','13','Common','Ken Sugimori','Even though its body is extremely skinny, it is blindingly fast when catching its prey.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/13.png","large":"https://images.pokemontcg.io/sm10/13_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Weepinbell"]',NULL,'[{"name":"Razor Leaf","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[69]',NULL,NULL,'sm10');
