INSERT INTO "Card" VALUES('sm10-90','Cubone','Pokémon','90','Common','Mizue','At night, it weeps loudly for its dead mother, but those cries only attract its natural enemy—Mandibuzz.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/90.png","large":"https://images.pokemontcg.io/sm10/90_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Marowak"]',NULL,'[{"name":"Focus Energy","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your next turn, this Pokémon''s Beat attack''s base damage is 80."},{"name":"Beat","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[104]',NULL,NULL,'sm10');
INSERT INTO "Card" VALUES('sm10-91','Marowak','Pokémon','91','Rare','kirisAki','It throws bones at Mandibuzz to knock it down. It''s thought that Marowak is trying to avenge its parent.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/91.png","large":"https://images.pokemontcg.io/sm10/91_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Fighting"]','Cubone',NULL,NULL,'[{"name":"Bone Rush","cost":["Fighting"],"convertedEnergyCost":1,"damage":"50×","text":"Flip a coin until you get tails. This attack does 50 damage for each heads."},{"name":"Assault Boom","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70+","text":"If your opponent''s Active Pokémon has a Pokémon Tool card attached to it, this attack does 70 more damage."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[105]',NULL,NULL,'sm10');
