INSERT INTO "Card" VALUES('sm10-94','Rhydon','Pokémon','94','Uncommon','kirisAki','Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees Fahrenheit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/94.png","large":"https://images.pokemontcg.io/sm10/94_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Fighting"]','Rhyhorn','["Rhyperior"]',NULL,'[{"name":"Dirty Work","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Discard the top card of your opponent''s deck. If you played Giovanni''s Exile from your hand during this turn, discard the top 5 cards instead."},{"name":"Horn Attack","cost":["Fighting","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"90","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[112]',NULL,NULL,'sm10');
INSERT INTO "Card" VALUES('sm10-95','Rhyperior','Pokémon','95','Rare','kawayoo','From holes in its palms, it fires out Geodude. Its carapace can withstand volcanic eruptions.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/95.png","large":"https://images.pokemontcg.io/sm10/95_hires.png"}',NULL,'170',NULL,'["Stage 2"]','["Fighting"]','Rhydon',NULL,NULL,'[{"name":"Hefty Cannon","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"If the Defending Pokémon is a Basic Pokémon, it can''t attack during your opponent''s next turn."},{"name":"Break Ground","cost":["Fighting","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"160","text":"This attack does 20 damage to each of your Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[464]',NULL,NULL,'sm10');
