INSERT INTO "Card" VALUES('sm10-100','Tyrogue','Pokémon','100','Uncommon','Mina Nakai','It is always bursting with energy. To make itself stronger, it keeps on fighting even if it loses.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/100.png","large":"https://images.pokemontcg.io/sm10/100_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Hitmonlee","Hitmonchan","Hitmontop"]','[{"name":"Bratty Kick","text":"Once during your turn (before your attack), you may flip a coin. If heads, put 3 damage counters on 1 of your opponent''s Pokémon. If you use this Ability, your turn ends.","type":"Ability"}]',NULL,NULL,NULL,NULL,NULL,'[236]',NULL,NULL,'sm10');
INSERT INTO "Card" VALUES('sm10-101','Hitmontop','Pokémon','101','Uncommon','Tomokazu Komiya','It fights while spinning like a top. The centrifugal force boosts its destructive power by 10.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/101.png","large":"https://images.pokemontcg.io/sm10/101_hires.png"}',NULL,'90',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Finishing Combo","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"You can use this attack only if your Hitmonlee used Special Combo during your last turn. This attack does 60 damage to each of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Spinning Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[237]',NULL,NULL,'sm10');
