INSERT INTO "Card" VALUES('sm10-104','Crabrawler','Pokémon','104','Common','Akira Komayama','Its hard pincers are well suited to both offense and defense. Fights between two Crabrawler are like boxing matches.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/104.png","large":"https://images.pokemontcg.io/sm10/104_hires.png"}',NULL,'80',NULL,'["Basic"]','["Fighting"]',NULL,'["Crabominable"]',NULL,'[{"name":"Corkscrew Punch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""},{"name":"Knuckle Blast","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30+","text":"If you have more Prize cards remaining than your opponent, this attack does 60 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[739]',NULL,NULL,'sm10');
INSERT INTO "Card" VALUES('sm10-105','Crabominable','Pokémon','105','Rare','Tomokazu Komiya','It stores coldness in its pincers and pummels its foes. It can even smash thick walls of ice to bits!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/105.png","large":"https://images.pokemontcg.io/sm10/105_hires.png"}',NULL,'140',NULL,'["Stage 1"]','["Fighting"]','Crabrawler',NULL,NULL,'[{"name":"Fight Alone","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"If you have fewer Pokémon in play than your opponent, this attack does 50 more damage for each Pokémon fewer you have in play."},{"name":"Magnum Punch","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[740]',NULL,NULL,'sm10');
INSERT INTO "Card" VALUES('sm10-106','Stakataka','Pokémon','106','Rare Holo','nagimiso','It appeared from an Ultra Wormhole. Each one appears to be made up of many life-forms stacked one on top of each other.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/106.png","large":"https://images.pokemontcg.io/sm10/106_hires.png"}',NULL,'120',NULL,'["Basic","Ultra Beast"]','["Fighting"]',NULL,NULL,'[{"name":"Wall of Stone","text":"If your opponent has 3 or fewer Prize cards remaining, this Pokémon''s maximum HP is 200.","type":"Ability"}]','[{"name":"Top Down","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"110","text":"Flip a coin until you get tails. For each heads, discard the top card of your opponent''s deck."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[805]',NULL,NULL,'sm10');
