INSERT INTO "Card" VALUES('sm10-114','Sandile','Pokémon','114','Common','Akira Komayama','Alola, where it''s warm all year round, is a comfortable environment for this Pokémon. Sometimes you''ll even see it outside of deserts.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/114.png","large":"https://images.pokemontcg.io/sm10/114_hires.png"}',NULL,'70',NULL,'["Basic"]','["Darkness"]',NULL,'["Krokorok"]',NULL,'[{"name":"Grandiose Fangs","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"If your opponent''s Pokémon is Knocked Out by damage from this attack, this Pokémon''s attacks do 120 more damage to your opponent''s Active Pokémon during your next turn (before applying Weakness and Resistance)."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[551]',NULL,NULL,'sm10');
