INSERT INTO "Card" VALUES('sm10-121','Alolan Diglett','Pokémon','121','Common','Atsuko Nishida','Although it''s powerful enough to dig right through volcanic rock, it doesn''t allow itself to be seen very often.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/121.png","large":"https://images.pokemontcg.io/sm10/121_hires.png"}',NULL,'50',NULL,'["Basic"]','["Metal"]',NULL,'["Dugtrio"]',NULL,'[{"name":"Ram","cost":[],"convertedEnergyCost":0,"damage":"10","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[50]',NULL,NULL,'sm10');
