INSERT INTO "Card" VALUES('sm10-126','Lucario','Pokémon','126','Rare Holo','Midori Harada','It concentrates its mental energy and fires off mysterious waves called auras, which can crush boulders of large size to dust.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/126.png","large":"https://images.pokemontcg.io/sm10/126_hires.png"}',NULL,'130',NULL,'["Stage 1"]','["Metal"]','Riolu',NULL,NULL,'[{"name":"Low Sweep","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":""},{"name":"Rush Up","cost":["Metal","Metal"],"convertedEnergyCost":2,"damage":"60+","text":"If you attached a Pokémon Tool card from your hand to this Pokémon during this turn, this attack does 70 more damage."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[448]',NULL,NULL,'sm10');
