INSERT INTO "Card" VALUES('sm10-130','Gardevoir & Sylveon-GX','Pokémon','130','Rare Holo GX','Mitsuhiro Arita',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/130.png","large":"https://images.pokemontcg.io/sm10/130_hires.png"}',NULL,'260',NULL,'["Basic","TAG TEAM","GX"]','["Fairy"]',NULL,NULL,NULL,'[{"name":"Fairy Song","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Fairy Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck."},{"name":"Kaleidostorm","cost":["Fairy","Fairy","Colorless"],"convertedEnergyCost":3,"damage":"150","text":"Move any number of Energy from your Pokémon to your other Pokémon in any way you like."},{"name":"Magical Miracle-GX","cost":["Fairy","Fairy","Fairy"],"convertedEnergyCost":3,"damage":"200","text":"If this Pokémon has at least 3 extra Fairy Energy attached to it (in addition to this attack''s cost), your opponent shuffles their hand into their deck. (You can''t use more than 1 GX attack in a game.)"}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless","Colorless"]',2,'[282,700]',NULL,'["TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards."]','sm10');
INSERT INTO "Card" VALUES('sm10-131','Cleffa','Pokémon','131','Uncommon','Shibuzoh.','On nights with many shooting stars, they gather in packs and dance in circles. If you should see them, something good will happen!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm10/131.png","large":"https://images.pokemontcg.io/sm10/131_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fairy"]',NULL,'["Clefairy"]','[{"name":"Excitable Draw","text":"Once during your turn (before your attack), you may flip a coin. If heads, shuffle your hand into your deck and then draw 6 cards. If you use this Ability, your turn ends.","type":"Ability"}]',NULL,NULL,NULL,NULL,NULL,'[173]',NULL,NULL,'sm10');
