INSERT INTO "Card" VALUES('sm11-27','Litwick','Pokémon','27','Common','MAHOU','While shining a light and pretending to be a guide, it leeches off the life force of any who follow it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/27.png","large":"https://images.pokemontcg.io/sm11/27_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Lampent"]',NULL,'[{"name":"Find a Friend","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Fire Pokémon, reveal it, and put it into your hand. Then, shuffle your deck."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[607]',NULL,NULL,'sm11');
