INSERT INTO "Card" VALUES('sm11-63','Tynamo','Pokémon','63','Common','Mina Nakai','While one alone doesn''t have much power, a chain of many Tynamo can be as powerful as lightning.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/63.png","large":"https://images.pokemontcg.io/sm11/63_hires.png"}',NULL,'30',NULL,'["Basic"]','["Lightning"]',NULL,'["Eelektrik"]',NULL,'[{"name":"Wild River","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Switch this Pokémon with 1 of your Benched Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[602]',NULL,NULL,'sm11');
