INSERT INTO "Card" VALUES('sm11-73','Exeggcute','Pokémon','73','Common','otumami','Six of them form a single Pokémon. Should one of the six be lost, the next morning there will once more be six.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/73.png","large":"https://images.pokemontcg.io/sm11/73_hires.png"}',NULL,'50',NULL,'["Basic"]','["Psychic"]',NULL,'["Exeggutor"]',NULL,'[{"name":"Leech Seed","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":"Heal 10 damage from this Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[102]',NULL,NULL,'sm11');
