INSERT INTO "Card" VALUES('sm11-82','Skorupi','Pokémon','82','Common','Ken Sugimori','It grips prey with its tail claws and injects poison. It tenaciously hangs on until the poison takes.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/82.png","large":"https://images.pokemontcg.io/sm11/82_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,'["Drapion"]',NULL,'[{"name":"Knock Off","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Discard a random card from your opponent''s hand."},{"name":"Bug Bite","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[451]',NULL,NULL,'sm11');
INSERT INTO "Card" VALUES('sm11-83','Uxie','Pokémon','83','Rare Holo','kodama','Known as "The Being of Knowledge." It is said that it can wipe out the memory of those who see its eyes.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/83.png","large":"https://images.pokemontcg.io/sm11/83_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Secret Territory","text":"If you have Mesprit and Azelf in play, apply Weakness for each Pokémon (both yours and your opponent''s) as ×4 instead.","type":"Ability"}]','[{"name":"Psyshot","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[480]',NULL,NULL,'sm11');
