INSERT INTO "Card" VALUES('sm11-86','Giratina','Pokémon','86','Rare Holo','Misa Tsutsui','This Pokémon is said to live in a world on the reverse side of ours, where common knowledge is distorted and strange.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/86.png","large":"https://images.pokemontcg.io/sm11/86_hires.png"}',NULL,'130',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Dimension Breach","text":"When you play this Pokémon from your hand onto your Bench during your turn, you may discard a Special Energy from your opponent''s Active Pokémon.","type":"Ability"}]','[{"name":"Fade to Black","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Your opponent''s Active Pokémon is now Confused."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[487]',NULL,NULL,'sm11');
