INSERT INTO "Card" VALUES('sm11-107','Heracross','Pokémon','107','Uncommon','Sanosuke Sakuma','It''s proud of its thick horn. In Alola, its biggest rival is Vikavolt, which it''s always fighting with.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/107.png","large":"https://images.pokemontcg.io/sm11/107_hires.png"}',NULL,'100',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Turn the Tables","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If 1 of your opponent''s Pokémon used a GX attack during their last turn, your opponent shuffles their Active Pokémon and all cards attached to it into their deck."},{"name":"Tackle","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[214]',NULL,NULL,'sm11');
INSERT INTO "Card" VALUES('sm11-108','Breloom','Pokémon','108','Uncommon','Atsuko Nishida','Its short arms stretch when it throws punches. Its technique is equal to that of pro boxers.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/108.png","large":"https://images.pokemontcg.io/sm11/108_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Fighting"]','Shroomish',NULL,NULL,'[{"name":"Spore","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Asleep."},{"name":"Pre-Dawn Strike","cost":["Grass"],"convertedEnergyCost":1,"damage":"30+","text":"If your opponent''s Active Pokémon is Asleep, this attack does 90 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[286]',NULL,NULL,'sm11');
