INSERT INTO "Card" VALUES('sm11-110','Medicham','Pokémon','110','Rare','Shigenori Negishi','It elegantly avoids attacks with dance-like steps, then launches a devastating blow in the same motion.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/110.png","large":"https://images.pokemontcg.io/sm11/110_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Fighting"]','Meditite',NULL,NULL,'[{"name":"Pure Power","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Put 4 damage counters on your opponent''s Pokémon in any way you like."},{"name":"Master Strike","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"60+","text":"If this Pokémon has a Karate Belt card attached to it, this attack does 60 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[308]',NULL,NULL,'sm11');
