INSERT INTO "Card" VALUES('sm11-151','Dragonite','Pokémon','151','Rare','Misa Tsutsui','It flies over raging seas as if they were nothing. Observing this, a ship''s captain dubbed this Pokémon "the sea incarnate."','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/151.png","large":"https://images.pokemontcg.io/sm11/151_hires.png"}',NULL,'160',NULL,'["Stage 2"]','["Dragon"]','Dragonair',NULL,'[{"name":"Hurricane Charge","text":"Once during your turn (before your attack), you may attach a Water Energy card, a Lightning Energy card, or 1 of each from your hand to your Pokémon in any way you like.","type":"Ability"}]','[{"name":"Dragon Impact","cost":["Water","Lightning","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"170","text":"Discard 3 Energy from this Pokémon."}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[149]',NULL,NULL,'sm11');
