INSERT INTO "Card" VALUES('sm11-194','Ear-Ringing Bell','Trainer','194','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/194.png","large":"https://images.pokemontcg.io/sm11/194_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If the Pokémon this card is attached to is your Active Pokémon and is damaged by an opponent''s attack (even if that Pokémon is Knocked Out), the Attacking Pokémon is now Confused.","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
INSERT INTO "Card" VALUES('sm11-195','Flyinium Z: Air Slash','Trainer','195','Uncommon','aky CG Works',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/195.png","large":"https://images.pokemontcg.io/sm11/195_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,'[{"name":"Speeding Skystrike-GX","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"180","text":"Prevent all effects of attacks, including damage, done to this Pokémon during your opponent''s next turn. (You can''t use more than 1 GX attack in a game.)"}]',NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If the Pokémon this card is attached to has the Air Slash attack, it can use the GX attack on this card. (You still need the necessary Energy to use this attack.)","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
INSERT INTO "Card" VALUES('sm11-196','Giant Bomb','Trainer','196','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/196.png","large":"https://images.pokemontcg.io/sm11/196_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If this card is attached to 1 of your Pokémon, discard it at the end of your opponent''s turn.","If the Pokémon this card is attached to is your Active Pokémon and takes 180 or more damage from an opponent''s attack (even if this Pokémon is Knocked Out), put 10 damage counters on the Attacking Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
INSERT INTO "Card" VALUES('sm11-197','Giant Hearth','Trainer','197','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/197.png","large":"https://images.pokemontcg.io/sm11/197_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard a card from their hand. If they do, that player searches their deck for up to 2 Fire Energy cards, reveals them, and puts them into their hand. Then, that player shuffles their deck.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','sm11');
