INSERT INTO "Card" VALUES('sm11-206','Reset Stamp','Trainer','206','Uncommon','sadaji',NULL,'{"unlimited":"Legal","expanded":"Banned"}','{"small":"https://images.pokemontcg.io/sm11/206.png","large":"https://images.pokemontcg.io/sm11/206_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent shuffles their hand into their deck and draws a card for each of their remaining Prize cards.","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
