INSERT INTO "Card" VALUES('sm11-251','Giant Bomb','Trainer','251','Rare Secret','Studio Bora Inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/251.png","large":"https://images.pokemontcg.io/sm11/251_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If this card is attached to 1 of your Pokémon, discard it at the end of your opponent''s turn.","If the Pokémon this card is attached to is your Active Pokémon and takes 180 or more damage from an opponent''s attack (even if this Pokémon is Knocked Out), put 10 damage counters on the Attacking Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
INSERT INTO "Card" VALUES('sm11-252','Karate Belt','Trainer','252','Rare Secret','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm11/252.png","large":"https://images.pokemontcg.io/sm11/252_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If you have more Prize cards remaining than your opponent, the attacks of the Pokémon this card is attached to cost Fighting less.","You may play as many Item cards as you like during your turn (before your attack)."]','sm11');
