INSERT INTO "Card" VALUES('sm115-37','Cubone','Pokémon','37','Common','Hasuno','The skull it wears on its head is that of its dead mother. According to some, it will evolve when it comes to terms with the pain of her death.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/37.png","large":"https://images.pokemontcg.io/sm115/37_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Marowak"]',NULL,'[{"name":"Sharpshooting","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[104]',NULL,NULL,'sm115');
INSERT INTO "Card" VALUES('sm115-38','Clefairy','Pokémon','38','Common','Saya Tsuruta','They''re popular, but they''re rare. Trainers who show them off recklessly may be targeted by thieves.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/38.png","large":"https://images.pokemontcg.io/sm115/38_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fairy"]',NULL,'["Clefable"]',NULL,'[{"name":"Lead","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Pound","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[35]',NULL,NULL,'sm115');
