INSERT INTO "Card" VALUES('sm115-40','Clefable','Pokémon','40','Rare','sui','It can''t help but hear a pin drop from over half a mile away, so it lives deep in the mountains where there aren''t many people or Pokémon.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/40.png","large":"https://images.pokemontcg.io/sm115/40_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Fairy"]','Clefairy',NULL,NULL,'[{"name":"Pound","cost":["Fairy","Colorless"],"convertedEnergyCost":2,"damage":"40","text":""},{"name":"Moon Impact","cost":["Fairy","Fairy","Colorless"],"convertedEnergyCost":3,"damage":"90","text":""}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless","Colorless"]',2,'[36]',NULL,NULL,'sm115');
INSERT INTO "Card" VALUES('sm115-41','Jigglypuff','Pokémon','41','Common','Mizue','Recordings of Jigglypuff''s strange lullabies can be purchased from department stores. These CDs can be found near the bedding area.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/41.png","large":"https://images.pokemontcg.io/sm115/41_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fairy"]',NULL,'["Wigglytuff"]',NULL,'[{"name":"Singing Voice","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Rollout","cost":["Fairy","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[39]',NULL,NULL,'sm115');
