INSERT INTO "Card" VALUES('sm115-43','Mr. Mime','Pokémon','43','Rare','Hideki Ishikawa','Its pantomime skills are wonderful. You may become enraptured while watching it, but next thing you know, Mr. Mime has made a real wall.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/43.png","large":"https://images.pokemontcg.io/sm115/43_hires.png"}',NULL,'90',NULL,'["Basic"]','["Fairy"]',NULL,NULL,NULL,'[{"name":"Happy Mime","cost":["Fairy"],"convertedEnergyCost":1,"damage":"","text":"Each player draws a card."},{"name":"Double Slap","cost":["Fairy","Fairy"],"convertedEnergyCost":2,"damage":"40×","text":"Flip 2 coins. This attack does 40 damage for each heads."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[122]',NULL,NULL,'sm115');
