INSERT INTO "Card" VALUES('sm115-45','Farfetch''d','Pokémon','45','Uncommon','Eri Yamaki','The plant stalk it holds is its weapon. The stalk is used like a sword to cut all sorts of things.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm115/45.png","large":"https://images.pokemontcg.io/sm115/45_hires.png"}',NULL,'80',NULL,'["Basic"]','["Colorless"]',NULL,'["Sirfetch''d"]',NULL,'[{"name":"Leek Slap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[83]',NULL,NULL,'sm115');
