INSERT INTO "Card" VALUES('sm12-7','Sunkern','Pokémon','7','Common','0313','It may plummet from the sky. If attacked by a Spearow, it will violently shake its leaves.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/7.png","large":"https://images.pokemontcg.io/sm12/7_hires.png"}',NULL,'50',NULL,'["Basic"]','["Grass"]',NULL,'["Sunflora"]',NULL,'[{"name":"Leech Seed","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":"Heal 10 damage from this Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[191]',NULL,NULL,'sm12');
