INSERT INTO "Card" VALUES('sm12-96','Mimikyu','Pokémon','96','Uncommon','HYOGONOSUKE','Although it''s a quiet, lonely Pokémon, if you try to look at what''s under its rag, it will become agitated and resist violently.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/96.png","large":"https://images.pokemontcg.io/sm12/96_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Impersonation","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Discard a Supporter card from your hand. If you do, use the effect of that card as the effect of this attack."},{"name":"Mischievous Hands","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Choose 2 of your opponent''s Pokémon and put 2 damage counters on each of them."}]',NULL,NULL,'["Colorless"]',1,'[778]',NULL,NULL,'sm12');
