INSERT INTO "Card" VALUES('sm12-147','Cottonee','Pokémon','147','Common','Pani Kobayashi','To protect itself, it shoots cotton from its body. When it gets wet in the rain, its cotton grows moist and heavy, and it can''t move as well.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/147.png","large":"https://images.pokemontcg.io/sm12/147_hires.png"}',NULL,'40',NULL,'["Basic"]','["Fairy"]',NULL,'["Whimsicott"]',NULL,'[{"name":"Lost March","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"This attack does 20 damage for each of your Pokémon, except p (Prism Star) Pokémon, in the Lost Zone."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[546]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-148','Whimsicott','Pokémon','148','Rare','Yumi','This nuisance sneaks into people''s homes, where it hides important things and scatters cotton all over the place.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/148.png","large":"https://images.pokemontcg.io/sm12/148_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Fairy"]','Cottonee',NULL,NULL,'[{"name":"Sneaky Pocket","cost":["Fairy"],"convertedEnergyCost":1,"damage":"","text":"Put a card from your hand in the Lost Zone. If you do, draw 3 cards."},{"name":"Lost March","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"This attack does 20 damage for each of your Pokémon, except p (Prism Star) Pokémon, in the Lost Zone."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]',NULL,NULL,'[547]',NULL,NULL,'sm12');
