INSERT INTO "Card" VALUES('sm12-208','Will','Trainer','208','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/208.png","large":"https://images.pokemontcg.io/sm12/208_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The next time you flip any number of coins for the effect of an attack, Ability, or Trainer card this turn, choose heads or tails for the first coin flip.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
