INSERT INTO "Card" VALUES('sm12-227','Silvally-GX','Pokémon','227','Rare Ultra','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/227.png","large":"https://images.pokemontcg.io/sm12/227_hires.png"}',NULL,'210',NULL,'["Stage 1","GX"]','["Colorless"]','Type: Null',NULL,'[{"name":"Disk Reload","text":"Once during your turn (before your attack), you may draw cards until you have 5 cards in your hand.","type":"Ability"}]','[{"name":"Brave Buddies","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50+","text":"If you played a Supporter card from your hand during this turn, this attack does 70 more damage."},{"name":"Silver Knight-GX","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"If your opponent''s Active Pokémon is an Ultra Beast, it is Knocked Out. (You can''t use more than 1 GX attack in a game.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[773]',NULL,'["Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards."]','sm12');
INSERT INTO "Card" VALUES('sm12-228','Cynthia & Caitlin','Trainer','228','Rare Ultra','Sakiko Maeda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/228.png","large":"https://images.pokemontcg.io/sm12/228_hires.png"}',NULL,NULL,NULL,'["Supporter","TAG TEAM"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Supporter card from your discard pile into your hand. You can''t choose Cynthia & Caitlin or a card you discarded with the effect of this card.","When you play this card, you may discard another card from your hand. If you do, draw 3 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-229','Guzma & Hala','Trainer','229','Rare Ultra','Junsei Kuninobu',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/229.png","large":"https://images.pokemontcg.io/sm12/229_hires.png"}',NULL,NULL,NULL,'["Supporter","TAG TEAM"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Stadium card, reveal it, and put it into your hand. Then, shuffle your deck.","When you play this card, you may discard 2 other cards from your hand. If you do, you may also search for a Pokémon Tool card and a Special Energy card in this way.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-230','Lillie''s Full Force','Trainer','230','Rare Ultra','Noriko Uono',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/230.png","large":"https://images.pokemontcg.io/sm12/230_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 4 cards.","At the end of this turn, if you have 3 or more cards in your hand, shuffle cards from your hand into your deck until you have 2 cards in your hand.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-231','Mallow & Lana','Trainer','231','Rare Ultra','kirisAki',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/231.png","large":"https://images.pokemontcg.io/sm12/231_hires.png"}',NULL,NULL,NULL,'["Supporter","TAG TEAM"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch your Active Pokémon with 1 of your Benched Pokémon.","When you play this card, you may discard 2 other cards from your hand. If you do, heal 120 damage from the Pokémon you moved to your Bench.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-232','N''s Resolve','Trainer','232','Rare Ultra','Mana Ibe',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/232.png","large":"https://images.pokemontcg.io/sm12/232_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard the top 6 cards of your deck. If any of those cards are basic Energy cards, attach them to 1 of your Benched Dragon Pokémon.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-233','Professor Oak''s Setup','Trainer','233','Rare Ultra','Nabana Kensaku',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/233.png","large":"https://images.pokemontcg.io/sm12/233_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for up to 3 Basic Pokémon of different types and put them onto your Bench. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-234','Red & Blue','Trainer','234','Rare Ultra','Hitoshi Ariga',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/234.png","large":"https://images.pokemontcg.io/sm12/234_hires.png"}',NULL,NULL,NULL,'["Supporter","TAG TEAM"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon-GX that evolves from 1 of your Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck. (You can''t use this card during your first turn or on a Pokémon that was put into play this turn.)","When you play this card, you may discard 2 other cards from your hand. If you do, search your deck for up to 2 basic Energy cards and attach them to the Pokémon you evolved in this way.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-235','Roller Skater','Trainer','235','Rare Ultra','nagimiso',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/235.png","large":"https://images.pokemontcg.io/sm12/235_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand. If you do, draw 2 cards. If you discarded an Energy card in this way, draw 2 more cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-236','Rosa','Trainer','236','Rare Ultra','kirisAki',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/236.png","large":"https://images.pokemontcg.io/sm12/236_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if 1 of your Pokémon was Knocked Out during your opponent''s last turn.","Search your deck for a Pokémon, a Trainer card, and a basic Energy card, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm12');
INSERT INTO "Card" VALUES('sm12-237','Torkoal','Pokémon','237','Rare Secret','Ryota Murayama','You can tell how it''s feeling by the smoke spouting from its shell. Tremendous velocity is a sign of good health.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/237.png","large":"https://images.pokemontcg.io/sm12/237_hires.png"}',NULL,'110',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Fire Fling","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Put 4 Fire Energy cards from your discard pile into your hand."},{"name":"Kindle","cost":["Fire","Fire","Fire"],"convertedEnergyCost":3,"damage":"100","text":"Discard an Energy from this Pokémon. If you do, discard an Energy from your opponent''s Active Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[324]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-238','Weavile','Pokémon','238','Rare Secret','nagimiso','One Weavile will trip a Sandshrew and flip it over, and then another Weavile will deal the finishing blow with its sharp claws.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/238.png","large":"https://images.pokemontcg.io/sm12/238_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Water"]','Sneasel',NULL,NULL,'[{"name":"Nasty Plot","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck."},{"name":"Slashing Claw","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"110","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,NULL,NULL,'[461]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-239','Piplup','Pokémon','239','Rare Secret','Tomomi Kaneko','It doesn''t like to be taken care of. It''s difficult to bond with since it won''t listen to its Trainer.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/239.png","large":"https://images.pokemontcg.io/sm12/239_hires.png"}',NULL,'60',NULL,'["Basic"]','["Water"]',NULL,'["Prinplup"]',NULL,'[{"name":"Bubble Hold","cost":["Water","Water","Water"],"convertedEnergyCost":3,"damage":"80","text":"If the Defending Pokémon is a Basic Pokémon, it can''t attack during your opponent''s next turn."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[393]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-240','Wishiwashi','Pokémon','240','Rare Secret','Misaki Hashimoto','Wishiwashi assemble in this formation to face off against strong foes. It boasts a strength that earned it the name "demon of the sea."','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/240.png","large":"https://images.pokemontcg.io/sm12/240_hires.png"}',NULL,'180',NULL,'["Basic"]','["Water"]',NULL,NULL,'[{"name":"Scatter","text":"At the end of your opponent''s turn, if this Pokémon has any damage counters on it, flip a coin. If tails, shuffle this Pokémon and all cards attached to it into your deck.","type":"Ability"}]','[{"name":"Hydro Splash","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"130","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[746]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-241','Pikachu','Pokémon','241','Rare Secret','Hitoshi Ariga','Its nature is to store up electricity. Forests where nests of Pikachu live are dangerous, since the trees are so often struck by lightning.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/241.png","large":"https://images.pokemontcg.io/sm12/241_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,'["Raichu"]',NULL,'[{"name":"Nuzzle","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."},{"name":"Volt Tackle","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[25]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-242','Magnemite','Pokémon','242','Rare Secret','Fumie Kittaka','It''s frequently the cause of power outages, which is why some power plants send out electrical signals that it can''t stand.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/242.png","large":"https://images.pokemontcg.io/sm12/242_hires.png"}',NULL,'60',NULL,'["Basic"]','["Lightning"]',NULL,'["Magneton"]',NULL,'[{"name":"Mirror Shot","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"If the Defending Pokémon tries to attack during your opponent''s next turn, your opponent flips a coin. If tails, that attack doesn''t happen."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[81]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-243','Koffing','Pokémon','243','Rare Secret','HYOGONOSUKE','Its thin, balloon-like body is inflated by horribly toxic gases. It reeks when it is nearby.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/243.png","large":"https://images.pokemontcg.io/sm12/243_hires.png"}',NULL,'60',NULL,'["Basic"]','["Psychic"]',NULL,'["Weezing"]','[{"name":"Blow-Away Bomb","text":"Once during your turn, when you discard this Pokémon with the effect of Roxie, you may put 1 damage counter on each of your opponent''s Pokémon. (Place damage counters after the effect of Roxie.)","type":"Ability"}]','[{"name":"Poison Gas","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"10","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[109]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-244','Gallade','Pokémon','244','Rare Secret','Huang Tzu En','Because it can sense what its foe is thinking, its attacks burst out first, fast, and fierce.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/244.png","large":"https://images.pokemontcg.io/sm12/244_hires.png"}',NULL,'160',NULL,'["Stage 2"]','["Psychic"]','Kirlia',NULL,'[{"name":"Double Type","text":"As long as this Pokémon is in play, it is Psychic and Fighting type.","type":"Ability"}]','[{"name":"Power Cyclone","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"120","text":"Move an Energy from this Pokémon to 1 of your Benched Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[475]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-245','Mimikyu','Pokémon','245','Rare Secret','You Iribi','Although it''s a quiet, lonely Pokémon, if you try to look at what''s under its rag, it will become agitated and resist violently.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/245.png","large":"https://images.pokemontcg.io/sm12/245_hires.png"}',NULL,'70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Impersonation","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Discard a Supporter card from your hand. If you do, use the effect of that card as the effect of this attack."},{"name":"Mischievous Hands","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Choose 2 of your opponent''s Pokémon and put 2 damage counters on each of them."}]',NULL,NULL,'["Colorless"]',1,'[778]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-246','Excadrill','Pokémon','246','Rare Secret','Mitsuhiro Arita','It can help in tunnel construction. Its drill has evolved into steel strong enough to bore through iron plates.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/246.png","large":"https://images.pokemontcg.io/sm12/246_hires.png"}',NULL,'140',NULL,'["Stage 1"]','["Fighting"]','Drilbur',NULL,NULL,'[{"name":"Eleventh Hour Tackle","cost":["Fighting"],"convertedEnergyCost":1,"damage":"30+","text":"If there are 3 or fewer cards in your deck, this attack does 150 more damage."},{"name":"Drill Bazooka","cost":["Fighting"],"convertedEnergyCost":1,"damage":"120","text":"Discard the top 4 cards of your deck."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[530]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-247','Steelix','Pokémon','247','Rare Secret','Avec Yoko','Tempered underground under high pressure and heat, its body is harder than any metal.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/247.png","large":"https://images.pokemontcg.io/sm12/247_hires.png"}',NULL,'170',NULL,'["Stage 1"]','["Metal"]','Onix',NULL,NULL,'[{"name":"Thumping Fall","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50×","text":"Discard any number of Pokémon with a Retreat Cost of exactly 4 from your hand. This attack does 50 damage for each card you discarded in this way."},{"name":"Iron Tail","cost":["Metal","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100×","text":"Flip a coin until you get tails. This attack does 100 damage for each heads."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[208]',NULL,NULL,'sm12');
INSERT INTO "Card" VALUES('sm12-248','Stoutland','Pokémon','248','Rare Secret','Mizue','It pays no mind to the cold, thanks to its long warm coat. Stoutland in Alola look a little uncomfortable.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm12/248.png","large":"https://images.pokemontcg.io/sm12/248_hires.png"}',NULL,'150',NULL,'["Stage 2"]','["Colorless"]','Herdier',NULL,'[{"name":"Arf Arf Bark","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may discard an Energy from your opponent''s Active Pokémon. If this Pokémon is your Active Pokémon and is Knocked Out by damage from an opponent''s attack, you may discard an Energy from your opponent''s Active Pokémon.","type":"Ability"}]','[{"name":"Overrun","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"110","text":"This attack does 30 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[508]',NULL,NULL,'sm12');
