INSERT INTO "Card" VALUES('sm2-46','Oricorio','Pokémon','46','Rare','Naoki Saito','This Oricorio has sipped bright yellow nectar. Its bright, cheerful dance melts the hearts of its enemies.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm2/46.png","large":"https://images.pokemontcg.io/sm2/46_hires.png"}',NULL,'90',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Feather Dance","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"During your next turn, this Pokémon''s Pom-Pom Punch attack''s base damage is 100."},{"name":"Pom-Pom Punch","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[741]',NULL,NULL,'sm2');
