INSERT INTO "Card" VALUES('sm2-61','Lunala','Pokémon','61','Rare','5ban Graphics','It is said to be a female evolution of Cosmog. When its third eye activates, away it flies to another world.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm2/61.png","large":"https://images.pokemontcg.io/sm2/61_hires.png"}',NULL,'160',NULL,'["Stage 2"]','["Psychic"]','Cosmoem',NULL,NULL,'[{"name":"Shatter Shot","cost":["Psychic"],"convertedEnergyCost":1,"damage":"40×","text":"This attack does 40 damage times the amount of Psychic Energy attached to this Pokémon."},{"name":"Wings of the Moone","cost":["Psychic","Psychic","Psychic"],"convertedEnergyCost":3,"damage":"130","text":"Move all Energy from this Pokémon to your Benched Pokémon in any way you like."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[792]',NULL,NULL,'sm2');
