INSERT INTO "Card" VALUES('sm2-97','Drampa','Pokémon','97','Rare Holo','match','It has a compassionate personality, but if it is angered, it will completely destroy its surroundings with its intense breath.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm2/97.png","large":"https://images.pokemontcg.io/sm2/97_hires.png"}',NULL,'120',NULL,'["Basic"]','["Dragon"]',NULL,NULL,NULL,'[{"name":"Amass","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a basic Energy card and attach it to this Pokémon. Then, shuffle your deck."},{"name":"Power Cyclone","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Move an Energy from this Pokémon to 1 of your Benched Pokémon."}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[780]',NULL,NULL,'sm2');
