INSERT INTO "Card" VALUES('sm2-107','Patrat','Pokémon','107','Common','Ayaka Yoshida','Using food stored in cheek pouches, they can keep watch for days. They use their tails to communicate with others.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm2/107.png","large":"https://images.pokemontcg.io/sm2/107_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Watchog"]',NULL,'[{"name":"Glance","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Look at the top card of your opponent''s deck."},{"name":"Tackle","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[504]',NULL,NULL,'sm2');
