INSERT INTO "Card" VALUES('sm3-81','Alolan Rattata','Pokémon','81','Common','nagimiso','With its incisors, it gnaws through doors and infiltrates people''s homes. Then, with a twitch of its whiskers, it steals whatever food it finds.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/81.png","large":"https://images.pokemontcg.io/sm3/81_hires.png"}',NULL,'40',NULL,'["Basic"]','["Darkness"]',NULL,'["Raticate"]',NULL,'[{"name":"Focus Energy","cost":[],"convertedEnergyCost":0,"damage":"","text":"During your next turn, this Pokémon''s Bite attack''s base damage is 60."},{"name":"Bite","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[19]',NULL,NULL,'sm3');
INSERT INTO "Card" VALUES('sm3-82','Alolan Raticate','Pokémon','82','Rare','Kouki Saitou','It forms a group of Rattata, which it assumes command of. Each group has its own territory, and disputes over food happen often.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/82.png","large":"https://images.pokemontcg.io/sm3/82_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Darkness"]','Alolan Rattata',NULL,NULL,'[{"name":"Enhanced Fang","cost":[],"convertedEnergyCost":0,"damage":"10+","text":"If this Pokémon has a Pokémon Tool card attached to it, this attack does 50 more damage."},{"name":"Hyper Fang","cost":["Darkness"],"convertedEnergyCost":1,"damage":"60","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[20]',NULL,NULL,'sm3');
INSERT INTO "Card" VALUES('sm3-83','Alolan Grimer','Pokémon','83','Common','Kouki Saitou','A Grimer, which had been brought in to solve a problem with garbage, developed over time into this form.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/83.png","large":"https://images.pokemontcg.io/sm3/83_hires.png"}',NULL,'80',NULL,'["Basic"]','["Darkness"]',NULL,'["Muk"]',NULL,'[{"name":"Division","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for Alolan Grimer and put it onto your Bench. Then, shuffle your deck."},{"name":"Slippery Sludge","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Your opponent''s Active Pokémon is now Confused."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[88]',NULL,NULL,'sm3');
