INSERT INTO "Card" VALUES('sm3-124','Super Scoop Up','Trainer','124','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/124.png","large":"https://images.pokemontcg.io/sm3/124_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, put 1 of your Pokémon and all cards attached to it into your hand.","You may play as many Item cards as you like during your turn (before your attack)."]','sm3');
INSERT INTO "Card" VALUES('sm3-125','Tormenting Spray','Trainer','125','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/125.png","large":"https://images.pokemontcg.io/sm3/125_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a random card from your opponent''s hand. Your opponent reveals that card. If it''s a Supporter card, discard it.","You may play as many Item cards as you like during your turn (before your attack)."]','sm3');
INSERT INTO "Card" VALUES('sm3-126','Weakness Policy','Trainer','126','Uncommon','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/126.png","large":"https://images.pokemontcg.io/sm3/126_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Pokémon this card is attached to has no Weakness.","You may play as many Item cards as you like during your turn (before your attack)."]','sm3');
INSERT INTO "Card" VALUES('sm3-127','Wicke','Trainer','127','Uncommon','take',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/127.png","large":"https://images.pokemontcg.io/sm3/127_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player counts the cards in their hand, shuffles those cards into their deck, then draws that many cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm3');
INSERT INTO "Card" VALUES('sm3-128','Wishful Baton','Trainer','128','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm3/128.png","large":"https://images.pokemontcg.io/sm3/128_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If the Pokémon this card is attached to is your Active Pokémon and is Knocked Out by damage from an opponent''s attack, move up to 3 basic Energy cards from that Pokémon to 1 of your Benched Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm3');
