INSERT INTO "Card" VALUES('sm35-54','Yveltal','Pokémon','54','Rare Holo','Shin Nagasawa','When this legendary Pokémon''s wings and tail feathers spread wide and glow red, it absorbs the life force of living creatures.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm35/54.png","large":"https://images.pokemontcg.io/sm35/54_hires.png"}',NULL,'120',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"name":"Strafe","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"You may switch this Pokémon with 1 of your Benched Pokémon."},{"name":"Oblivion Wing","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"Attach a Darkness Energy card from your discard pile to 1 of your Benched Pokémon."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[717]',NULL,NULL,'sm35');
