INSERT INTO "Card" VALUES('sm35-60','Great Ball','Trainer','60','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm35/60.png","large":"https://images.pokemontcg.io/sm35/60_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards of your deck. You may reveal a Pokémon you find there and put it into your hand. Shuffle the other cards back into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm35');
INSERT INTO "Card" VALUES('sm35-61','Hau','Trainer','61','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm35/61.png","large":"https://images.pokemontcg.io/sm35/61_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 3 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm35');
