INSERT INTO "Card" VALUES('sm35-63','Pokémon Breeder','Trainer','63','Uncommon','Kanako Eo',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm35/63.png","large":"https://images.pokemontcg.io/sm35/63_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 2 cards and heal 20 damage from your Active Pokémon. If you have no cards in your deck, you can''t play this card.","You may play only 1 Supporter card during your turn (before your attack)."]','sm35');
