INSERT INTO "Card" VALUES('sm4-91','Counter Catcher','Trainer','91','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/91.png","large":"https://images.pokemontcg.io/sm4/91_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you have more Prize cards remaining than your opponent.","Switch 1 of your opponent''s Benched Pokémon with their Active Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm4');
INSERT INTO "Card" VALUES('sm4-92','Dashing Pouch','Trainer','92','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/92.png","large":"https://images.pokemontcg.io/sm4/92_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If the Pokémon this card is attached to discards Energy for its Retreat Cost, put that Energy into your hand instead of the discard pile.","You may play as many Item cards as you like during your turn (before your attack)."]','sm4');
INSERT INTO "Card" VALUES('sm4-93','Devoured Field','Trainer','93','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/93.png","large":"https://images.pokemontcg.io/sm4/93_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The attacks of Darkness Pokémon and Dragon Pokémon (both yours and your opponent''s) do 10 more damage to the opponent''s Active Pokémon (before applying Weakness and Resistance).","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','sm4');
