INSERT INTO "Card" VALUES('sm4-95','Gladion','Trainer','95','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/95.png","large":"https://images.pokemontcg.io/sm4/95_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your face-down Prize cards and put 1 of them into your hand. Then, shuffle this Gladion into your remaining Prize cards and put them back face down. If you didn''t play this Gladion from your hand, it does nothing.","You may play only 1 Supporter card during your turn (before your attack)."]','sm4');
INSERT INTO "Card" VALUES('sm4-96','Lusamine','Trainer','96','Uncommon','take',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/96.png","large":"https://images.pokemontcg.io/sm4/96_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 2 in any combination of Supporter and Stadium cards from your discard pile into your hand.","You may play only 1 Supporter card during your turn (before your attack)."]','sm4');
INSERT INTO "Card" VALUES('sm4-97','Peeking Red Card','Trainer','97','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm4/97.png","large":"https://images.pokemontcg.io/sm4/97_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your opponent reveals their hand. You may have your opponent count the cards in their hand, shuffle those cards into their deck, then draw that many cards.","You may play as many Item cards as you like during your turn (before your attack)."]','sm4');
