INSERT INTO "Card" VALUES('sm5-62','Lunala ◇','Pokémon','62','Rare Prism Star','Hitoshi Ariga','Said to live in another world, this Pokémon devours light, drawing the moonless dark veil of night over the brightness of day.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm5/62.png","large":"https://images.pokemontcg.io/sm5/62_hires.png"}',NULL,'160',NULL,'["Basic","Prism Star"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Full Moon Star","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"For each of your opponent''s Pokémon in play, attach a Psychic Energy card from your discard pile to your Pokémon in any way you like."},{"name":"Psystorm","cost":["Psychic","Psychic","Psychic","Psychic"],"convertedEnergyCost":4,"damage":"20×","text":"This attack does 20 damage times the amount of Energy attached to all Pokémon."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[792]',NULL,'["◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm5');
