INSERT INTO "Card" VALUES('sm5-117','Drampa','Pokémon','117','Rare Holo','Hasuno','This Pokémon is friendly to people and loves children most of all. It comes from deep in the mountains to play with children it likes in town.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm5/117.png","large":"https://images.pokemontcg.io/sm5/117_hires.png"}',NULL,'130',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Outrage","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"This attack does 10 more damage for each damage counter on this Pokémon."},{"name":"Dragon Pulse","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"Discard the top 2 cards of your deck."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[780]',NULL,NULL,'sm5');
