INSERT INTO "Card" VALUES('sm5-172','Lunala-GX','Pokémon','172','Rare Secret','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm5/172.png","large":"https://images.pokemontcg.io/sm5/172_hires.png"}',NULL,'250',NULL,'["Stage 2","GX"]','["Psychic"]','Cosmoem',NULL,'[{"name":"Psychic Transfer","text":"As often as you like during your turn (before your attack), you may move a Psychic Energy from 1 of your Pokémon to another of your Pokémon.","type":"Ability"}]','[{"name":"Moongeist Beam","cost":["Psychic","Psychic","Psychic","Psychic"],"convertedEnergyCost":4,"damage":"120","text":"The Defending Pokémon can''t be healed during your opponent''s next turn."},{"name":"Lunar Fall-GX","cost":["Psychic","Psychic","Psychic"],"convertedEnergyCost":3,"damage":"","text":"Knock Out 1 of your opponent''s Basic Pokémon that isn''t a Pokémon-GX. (You can''t use more than 1 GX attack in a game.)"}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[792]',NULL,'["Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards."]','sm5');
