INSERT INTO "Card" VALUES('sm6-13','Heatran','Pokémon','13','Rare','tetsuya koizumi','Boiling blood, like magma, circulates through its body. It makes its dwelling place in volcanic caves.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/13.png","large":"https://images.pokemontcg.io/sm6/13_hires.png"}',NULL,'130',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Guard Press","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"During your opponent''s next turn, this Pokémon takes 30 less damage from attacks (after applying Weakness and Resistance)."},{"name":"Boiling Impact","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"130","text":"Discard 2 Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[485]',NULL,NULL,'sm6');
