INSERT INTO "Card" VALUES('sm6-16','Braixen','Pokémon','16','Uncommon','Kagemaru Himeno','When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/16.png","large":"https://images.pokemontcg.io/sm6/16_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fire"]','Fennekin','["Delphox"]',NULL,'[{"name":"Flare","cost":["Fire"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Flamethrower","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Discard an Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[654]',NULL,NULL,'sm6');
