INSERT INTO "Card" VALUES('sm6-80','Guzzlord','Pokémon','80','Rare Holo','Anesaki Dynamic','A dangerous Ultra Beast, it appears to be eating constantly, but for some reason its droppings have never been found.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/80.png","large":"https://images.pokemontcg.io/sm6/80_hires.png"}',NULL,'160',NULL,'["Basic","Ultra Beast"]','["Darkness"]',NULL,NULL,NULL,'[{"name":"Lord''s Valley","cost":["Darkness","Darkness","Darkness","Darkness"],"convertedEnergyCost":4,"damage":"160","text":"If you have exactly 2, 4, or 6 Prize cards remaining, discard the top 10 cards of your deck."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[799]',NULL,NULL,'sm6');
