INSERT INTO "Card" VALUES('sm6-83','Flabébé','Pokémon','83','Common','kirisAki','When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.','{"unlimited":"Legal","expanded":"Banned"}','{"small":"https://images.pokemontcg.io/sm6/83.png","large":"https://images.pokemontcg.io/sm6/83_hires.png"}',NULL,'30',NULL,'["Basic"]','["Fairy"]',NULL,'["Floette"]','[{"name":"Evolutionary Advantage","text":"If you go second, this Pokémon can evolve during your first turn.","type":"Ability"}]','[{"name":"Tackle","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[669]',NULL,NULL,'sm6');
