INSERT INTO "Card" VALUES('sm6-91','Goomy','Pokémon','91','Common','Midori Harada','Its source of protection is its slimy, germ-laden mucous membrane. Anyone who touches it needs some thorough hand-washing.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/91.png","large":"https://images.pokemontcg.io/sm6/91_hires.png"}',NULL,'40',NULL,'["Basic"]','["Dragon"]',NULL,'["Sliggoo"]','[{"name":"Sticky Membrane","text":"As long as this Pokémon is your Active Pokémon, your opponent''s Pokémon''s attacks cost Colorless more.","type":"Ability"}]','[{"name":"Ram","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless"]',1,'[704]',NULL,NULL,'sm6');
