INSERT INTO "Card" VALUES('sm6-107','Fossil Excavation Map','Trainer','107','Uncommon','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/107.png","large":"https://images.pokemontcg.io/sm6/107_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1:\n• Search your deck for an Unidentified Fossil card, reveal it, and put it into your hand. Then, shuffle your deck.\n• Put an Unidentified Fossil card from your discard pile into your hand.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-108','Judge','Trainer','108','Uncommon','Sanosuke Sakuma',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/108.png","large":"https://images.pokemontcg.io/sm6/108_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player shuffles their hand into their deck and draws 4 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-109','Lady','Trainer','109','Uncommon','Yusuke Ohmura',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/109.png","large":"https://images.pokemontcg.io/sm6/109_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for up to 4 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-110','Lysandre ◇','Trainer','110','Rare Prism Star','Hitoshi Ariga',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/110.png","large":"https://images.pokemontcg.io/sm6/110_hires.png"}',NULL,NULL,NULL,'["Supporter","Prism Star"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["For each of your Fire Pokémon in play, put a card from your opponent''s discard pile in the Lost Zone.","You may play only 1 Supporter card during your turn (before your attack).","◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm6');
INSERT INTO "Card" VALUES('sm6-111','Lysandre Labs','Trainer','111','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/111.png","large":"https://images.pokemontcg.io/sm6/111_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Pokémon Tool cards in play (both yours and your opponent''s) have no effect.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','sm6');
INSERT INTO "Card" VALUES('sm6-112','Metal Frying Pan','Trainer','112','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/112.png","large":"https://images.pokemontcg.io/sm6/112_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Metal Pokémon this card is attached to takes 30 less damage from your opponent''s attacks (after applying Weakness and Resistance) and has no Weakness.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-112a','Metal Frying Pan','Trainer','112a','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/112a.png","large":"https://images.pokemontcg.io/sm6/112a_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Metal Pokémon this card is attached to takes 30 less damage from your opponent''s attacks (after applying Weakness and Resistance) and has no Weakness.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-113','Mysterious Treasure','Trainer','113','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/113.png","large":"https://images.pokemontcg.io/sm6/113_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand. If you do, search your deck for a Psychic or Dragon Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-113a','Mysterious Treasure','Trainer','113a','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/113a.png","large":"https://images.pokemontcg.io/sm6/113a_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard a card from your hand. If you do, search your deck for a Psychic or Dragon Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-114','Ultra Recon Squad','Trainer','114','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/114.png","large":"https://images.pokemontcg.io/sm6/114_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard up to 2 Ultra Beast cards from your hand. Draw 3 cards for each card you discarded in this way.","You may play only 1 Supporter card during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-115','Ultra Space','Trainer','115','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/115.png","large":"https://images.pokemontcg.io/sm6/115_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may search their deck for an Ultra Beast card, reveal it, put it into their hand, and shuffle their deck.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','sm6');
INSERT INTO "Card" VALUES('sm6-116','Unidentified Fossil','Trainer','116','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/116.png","large":"https://images.pokemontcg.io/sm6/116_hires.png"}',NULL,'60',NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play this card as if it were a 60-HP Colorless Basic Pokémon. At any time during your turn (before your attack), you may discard this card from play.","This card can''t retreat.","You may play as many Item cards as you like during your turn (before your attack)."]','sm6');
INSERT INTO "Card" VALUES('sm6-117','Beast Energy ◇','Energy','117','Rare Prism Star',NULL,NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/117.png","large":"https://images.pokemontcg.io/sm6/117_hires.png"}',NULL,NULL,NULL,'["Special","Prism Star"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card provides Colorless Energy.","While this card is attached to an Ultra Beast, it provides every type of Energy but provides only 1 Energy at a time. The attacks of the Ultra Beast this card is attached to do 30 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm6');
INSERT INTO "Card" VALUES('sm6-118','Unit Energy FightingDarknessFairy','Energy','118','Uncommon',NULL,NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/118.png","large":"https://images.pokemontcg.io/sm6/118_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card provides Colorless Energy.","While this card is attached to a Pokémon, it provides Fighting, Darkness, and Fairy Energy but provides only 1 Energy at a time."]','sm6');
