INSERT INTO "Card" VALUES('sm6-121','Naganadel-GX','Pokémon','121','Rare Ultra','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm6/121.png","large":"https://images.pokemontcg.io/sm6/121_hires.png"}',NULL,'210',NULL,'["Stage 1","GX","Ultra Beast"]','["Psychic"]','Poipole',NULL,NULL,'[{"name":"Beast Raid","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20×","text":"This attack does 20 damage for each of your Ultra Beasts in play."},{"name":"Jet Needle","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"110","text":"This attack''s damage isn''t affected by Weakness or Resistance."},{"name":"Stinger-GX","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Both players shuffle their Prize cards into their decks. Then, each player puts the top 3 cards of their deck face down as their Prize cards. (You can''t use more than 1 GX attack in a game.)"}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[804]',NULL,'["Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards."]','sm6');
