INSERT INTO "Card" VALUES('sm7-17','Volbeat','Pokémon','17','Uncommon','Saya Tsuruta','It lives around clean ponds. At night, its rear lights up. It converses with others by flashing its light.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/17.png","large":"https://images.pokemontcg.io/sm7/17_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Pheromone Catch","cost":["Grass"],"convertedEnergyCost":1,"damage":"20+","text":"If your Illumise used Pheromone Signals during your last turn, this attack does 100 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[313]',NULL,NULL,'sm7');
