INSERT INTO "Card" VALUES('sm7-20','Cacturne','Pokémon','20','Uncommon','Atsuko Nishida','Packs of them follow travelers through the desert until the travelers can no longer move.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/20.png","large":"https://images.pokemontcg.io/sm7/20_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Grass"]','Cacnea',NULL,'[{"name":"Poison Payback","text":"If this Pokémon is your Active Pokémon and is damaged by an opponent''s attack (even if this Pokémon is Knocked Out), the Attacking Pokémon is now Poisoned.","type":"Ability"}]','[{"name":"Feint Attack","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"This attack does 50 damage to 1 of your opponent''s Pokémon. This damage isn''t affected by Weakness, Resistance, or any other effects on that Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[332]',NULL,NULL,'sm7');
