INSERT INTO "Card" VALUES('sm7-46','Kyogre','Pokémon','46','Rare Holo','Shin Nagasawa','It is said to have widened the seas by causing downpours. It had been asleep in a marine trench.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/46.png","large":"https://images.pokemontcg.io/sm7/46_hires.png"}',NULL,'130',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Dual Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 30 damage to 2 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Grand Wave","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"120","text":"This Pokémon can''t use Grand Wave during your next turn."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[382]',NULL,NULL,'sm7');
