INSERT INTO "Card" VALUES('sm7-53','Plusle','Pokémon','53','Uncommon','Kanako Eo','It absorbs electricity from telephone poles. It shorts out its body to create crackling noises.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/53.png","large":"https://images.pokemontcg.io/sm7/53_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Draw for Everybody","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Shuffle your hand into your deck. Then, draw a card for each Benched Pokémon (both yours and your opponent''s)."},{"name":"Electro Ball","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[311]',NULL,NULL,'sm7');
