INSERT INTO "Card" VALUES('sm7-58','Swalot','Pokémon','58','Uncommon','Yuka Morii','It gulps anything that fits in its mouth. Its special enzymes can dissolve anything.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/58.png","large":"https://images.pokemontcg.io/sm7/58_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Psychic"]','Gulpin',NULL,NULL,'[{"name":"Amnesia","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"Choose 1 of your opponent''s Active Pokémon''s attacks. That Pokémon can''t use that attack during your opponent''s next turn."},{"name":"Swallow Up","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40+","text":"If, before doing damage, your opponent''s Active Pokémon has less remaining HP than this Pokémon, this attack does 80 more damage."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[317]',NULL,NULL,'sm7');
