INSERT INTO "Card" VALUES('sm7-61','Lunatone','Pokémon','61','Rare Holo','Hisao Nakamura','It was discovered at the site of a meteor strike 40 years ago. Its stare can lull its foes to sleep.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/61.png","large":"https://images.pokemontcg.io/sm7/61_hires.png"}',NULL,'80',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Sol Shade","text":"If you have Solrock in play, Fire Pokémon in play (both yours and your opponent''s) have no Abilities, except Pokémon-GX and Pokémon-EX.","type":"Ability"}]','[{"name":"Psyshock","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[337]',NULL,NULL,'sm7');
