INSERT INTO "Card" VALUES('sm7-133','Hiker','Trainer','133','Uncommon','Naoki Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm7/133.png","large":"https://images.pokemontcg.io/sm7/133_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 5 cards of either player''s deck and choose 1 of them. That player shuffles the other cards back into their deck. Then, put the card you chose on top of that deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm7');
