INSERT INTO "Card" VALUES('sm75-55','Kangaskhan','Pokémon','55','Common','Naoyo Kimura','The child in its pouch leaves home after roughly three years. That is the only time the mother is heard to cry wildly.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm75/55.png","large":"https://images.pokemontcg.io/sm75/55_hires.png"}',NULL,'120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Fetch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw a card."},{"name":"Headbutt","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"One-Two Punch","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"Flip a coin. If heads, this attack does 30 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[115]',NULL,NULL,'sm75');
