INSERT INTO "Card" VALUES('sm75-58','Blaine''s Last Stand','Trainer','58','Rare Holo','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm75/58.png","large":"https://images.pokemontcg.io/sm75/58_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only when it is the last card in your hand.","Draw 2 cards for each Fire Pokémon you have in play.","You may play only 1 Supporter card during your turn (before your attack)."]','sm75');
