INSERT INTO "Card" VALUES('sm8-8','Meganium','Pokémon','8','Rare Holo','nagimiso','Meganium''s breath has the power to revive dead grass and plants. It can make them healthy again.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/8.png","large":"https://images.pokemontcg.io/sm8/8_hires.png"}',NULL,'150',NULL,'["Stage 2"]','["Grass"]','Bayleef',NULL,'[{"name":"Quick-Ripening Herb","text":"Once during your turn (before your attack), you may use this Ability. Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card onto the Basic Pokémon to evolve it. You can use this Ability during your first turn or on a Pokémon that was put into play this turn.","type":"Ability"}]','[{"name":"Solar Beam","cost":["Grass","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"110","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[154]',NULL,NULL,'sm8');
