INSERT INTO "Card" VALUES('sm8-10','Ariados','Pokémon','10','Uncommon','Suwama Chiaki','It spins thread from both its rear and its mouth. Then it wraps its prey up in thread and sips their bodily fluids at its leisure.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/10.png","large":"https://images.pokemontcg.io/sm8/10_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Grass"]','Spinarak',NULL,NULL,'[{"name":"Trapping Thread","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Whenever your opponent plays an Item or Supporter card from their hand during their next turn, prevent all effects of that card done to the Defending Pokémon."},{"name":"Poison Jab","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[168]',NULL,NULL,'sm8');
