INSERT INTO "Card" VALUES('sm8-35','Skiddo','Pokémon','35','Common','Ken Sugimori','If it has sunshine and water, it doesn''t need to eat, because it can generate energy from the leaves on its back.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/35.png","large":"https://images.pokemontcg.io/sm8/35_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,'["Gogoat"]',NULL,'[{"name":"Collect","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw a card."},{"name":"Vine Whip","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[672]',NULL,NULL,'sm8');
INSERT INTO "Card" VALUES('sm8-36','Gogoat','Pokémon','36','Uncommon','sowsow','They inhabit mountainous regions. The leader of the herd is decided by a battle of clashing horns.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/36.png","large":"https://images.pokemontcg.io/sm8/36_hires.png"}',NULL,'130',NULL,'["Stage 1"]','["Grass"]','Skiddo',NULL,NULL,'[{"name":"Leaf Wallop","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"During your next turn, this Pokémon''s Leaf Wallop attack does 50 more damage (before applying Weakness and Resistance)."},{"name":"Solar Beam","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[673]',NULL,NULL,'sm8');
