INSERT INTO "Card" VALUES('sm8-74','Lanturn','Pokémon','74','Rare','Ken Sugimori','This Pokémon flashes a bright light that blinds its prey. This creates an opening for it to deliver an electrical attack.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/74.png","large":"https://images.pokemontcg.io/sm8/74_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Lightning"]','Chinchou',NULL,NULL,'[{"name":"Salvage","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Shuffle 4 Item cards from your discard pile into your deck."},{"name":"Signal Beam","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"Your opponent''s Active Pokémon is now Confused."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[171]',NULL,NULL,'sm8');
