INSERT INTO "Card" VALUES('sm8-120','Umbreon','Pokémon','120','Rare','Ryota Murayama','With its black fur, it blends into the darkness. It bides its time, and when prey appears, this Pokémon goes for its threat, and then eats it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/120.png","large":"https://images.pokemontcg.io/sm8/120_hires.png"}',NULL,'110',NULL,'["Stage 1"]','["Darkness"]','Eevee',NULL,NULL,'[{"name":"Retaliate","cost":["Darkness"],"convertedEnergyCost":1,"damage":"30+","text":"If any of your Pokémon were Knocked Out by damage from an opponent''s attack during their last turn, this attack does 90 more damage."},{"name":"Dark Cutter","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"60","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[197]',NULL,NULL,'sm8');
