INSERT INTO "Card" VALUES('sm8-131','Magearna','Pokémon','131','Uncommon','Masakazu Fukuda','Its mechanized body is merely a vessel. Its true self is its Soul-Heart, an artificial soul.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/131.png","large":"https://images.pokemontcg.io/sm8/131_hires.png"}',NULL,'90',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Minor Errand-Running","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck."},{"name":"Energy Press","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"This attack does 20 more damage times the amount of Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[801]',NULL,NULL,'sm8');
