INSERT INTO "Card" VALUES('sm8-169','Choice Helmet','Trainer','169','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/169.png","large":"https://images.pokemontcg.io/sm8/169_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Pokémon this card is attached to takes 30 less damage from the attacks of your opponent''s Pokémon-GX and Pokémon-EX (after applying Weakness and Resistance).","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-170','Counter Gain','Trainer','170','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/170.png","large":"https://images.pokemontcg.io/sm8/170_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","If you have more Prize cards remaining than your opponent, the attacks of the Pokémon this card is attached to cost Colorless less.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-171','Custom Catcher','Trainer','171','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/171.png","large":"https://images.pokemontcg.io/sm8/171_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play 2 Custom Catcher cards at once.\n• If you played 1 card, draw cards until you have 3 cards in your hand.\n• If you played 2 cards, switch 1 of your opponent''s Benched Pokémon with their Active Pokémon. (This effects works one time for 2 cards.)","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-172','Electropower','Trainer','172','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/172.png","large":"https://images.pokemontcg.io/sm8/172_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During this turn, your Lightning Pokémon''s attacks do 30 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
