INSERT INTO "Card" VALUES('sm8-173','Faba','Trainer','173','Uncommon','take',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/173.png","large":"https://images.pokemontcg.io/sm8/173_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a Pokémon Tool or Special Energy card attached to 1 of your opponent''s Pokémon, or any Stadium card in play, and put it in the Lost Zone.","You may play only 1 Supporter card during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-174','Fairy Charm Grass','Trainer','174','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/174.png","large":"https://images.pokemontcg.io/sm8/174_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Prevent all damage done to the Fairy Pokémon this card is attached to by attacks from your opponent''s Grass Pokémon-GX and Grass Pokémon-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-175','Fairy Charm Psychic','Trainer','175','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/175.png","large":"https://images.pokemontcg.io/sm8/175_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Prevent all damage done to the Fairy Pokémon this card is attached to by attacks from your opponent''s Psychic Pokémon-GX and Psychic Pokémon-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
