INSERT INTO "Card" VALUES('sm8-177','Fairy Charm Dragon','Trainer','177','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/177.png","large":"https://images.pokemontcg.io/sm8/177_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Prevent all damage done to the Fairy Pokémon this card is attached to by attacks from your opponent''s Dragon Pokémon-GX and Dragon Pokémon-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-178','Heat Factory ◇','Trainer','178','Rare Prism Star','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/178.png","large":"https://images.pokemontcg.io/sm8/178_hires.png"}',NULL,NULL,NULL,'["Stadium","Prism Star"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard a Fire Energy card from their hand. If they do, they draw 3 cards.","Whenever any player plays an Item or Supporter card from their hand, prevent all effects of that card done to this Stadium card.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm8');
INSERT INTO "Card" VALUES('sm8-179','Kahili','Trainer','179','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/179.png","large":"https://images.pokemontcg.io/sm8/179_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 2 cards. Then, flip a coin. If heads, if you played this Kahili from your hand, put this card into your hand instead of the discard pile. If you have no cards in your deck, you can''t play this card.","You may play only 1 Supporter card during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-180','Life Forest ◇','Trainer','180','Rare Prism Star','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/180.png","large":"https://images.pokemontcg.io/sm8/180_hires.png"}',NULL,NULL,NULL,'["Stadium","Prism Star"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may heal 60 damage and remove all Special Conditions from 1 of their Grass Pokémon.","Whenever any player plays an Item or Supporter card from their hand, prevent all effects of that card done to this Stadium card.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card.","◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm8');
INSERT INTO "Card" VALUES('sm8-181','Lost Blender','Trainer','181','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/181.png","large":"https://images.pokemontcg.io/sm8/181_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 2 cards from your hand in the Lost Zone. If you do, draw a card.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-182','Lusamine ◇','Trainer','182','Rare Prism Star','nagimiso',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/182.png","large":"https://images.pokemontcg.io/sm8/182_hires.png"}',NULL,NULL,NULL,'["Supporter","Prism Star"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if your opponent has exactly 3 Prize cards remaining.","Prevent all damage done to your Ultra Beasts by attacks during your opponent''s next turn.","You may play only 1 Supporter card during your turn (before your attack).","◇ (Prism Star) Rule: You can''t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead."]','sm8');
INSERT INTO "Card" VALUES('sm8-183','Mina','Trainer','183','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/183.png","large":"https://images.pokemontcg.io/sm8/183_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Fairy Energy card and attach it to 1 of your Pokémon. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-184','Mixed Herbs','Trainer','184','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/184.png","large":"https://images.pokemontcg.io/sm8/184_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You may play 2 Mixed Herbs cards at once.\n• If you played 1 card, remove a Special Condition from your Active Pokémon.\n• If you played 2 cards, heal 90 damage and remove all Special Conditions from your Active Pokémon. (This effects works one time for 2 cards.)","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-185','Moomoo Milk','Trainer','185','Uncommon','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/185.png","large":"https://images.pokemontcg.io/sm8/185_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon, and then flip 2 coins. For each heads, heal 30 damage from that Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-186','Morty','Trainer','186','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/186.png","large":"https://images.pokemontcg.io/sm8/186_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if 1 of your Psychic Pokémon was Knocked Out during your opponent''s last turn.","Your opponent reveals their hand. Choose 2 cards you find there. Your opponent shuffles those cards into their deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm8');
