INSERT INTO "Card" VALUES('sm8-233','Lost Blender','Trainer','233','Rare Secret','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/233.png","large":"https://images.pokemontcg.io/sm8/233_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 2 cards from your hand in the Lost Zone. If you do, draw a card.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-234','Net Ball','Trainer','234','Rare Secret','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/234.png","large":"https://images.pokemontcg.io/sm8/234_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Basic Grass Pokémon or a Grass Energy card, reveal it, and put it into your hand. Then, shuffle your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-235','Spell Tag','Trainer','235','Rare Secret','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/235.png","large":"https://images.pokemontcg.io/sm8/235_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","When the Psychic Pokémon this card is attached to is Knocked Out by damage from an opponent''s attack, put 4 damage counters on your opponent''s Pokémon in any way you like.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
INSERT INTO "Card" VALUES('sm8-236','Wait and See Hammer','Trainer','236','Rare Secret','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm8/236.png","large":"https://images.pokemontcg.io/sm8/236_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you go second, and only on your first turn.","Discard an Energy from 1 of your opponent''s Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm8');
