INSERT INTO "Card" VALUES('sm9-19','Moltres','Pokémon','19','Rare Holo','Shin Nagasawa','It is said to be the legendary bird Pokémon of fire. Every flap of its wings creates a dazzling flare of flames.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/19.png","large":"https://images.pokemontcg.io/sm9/19_hires.png"}',NULL,'120',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Top Burner","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Discard all Fire Energy from this Pokémon. Then, discard a card from the top of your opponent''s deck for each Energy you discarded in this way."},{"name":"Fire Spin","cost":["Fire","Fire","Fire","Colorless"],"convertedEnergyCost":4,"damage":"180","text":"Discard 3 Energy from this Pokémon."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[146]',NULL,NULL,'sm9');
