INSERT INTO "Card" VALUES('sm9-34','Alolan Geodude','Pokémon','34','Common','Yukiko Baba','If you mistake it for a rock and step on it, it will headbutt you in anger. In addition to the pain, it will also zap you with a shock.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/34.png","large":"https://images.pokemontcg.io/sm9/34_hires.png"}',NULL,'60',NULL,'["Basic"]','["Lightning"]',NULL,'["Graveler"]',NULL,'[{"name":"Self-Destruct","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"This Pokémon does 60 damage to itself."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless"]',2,'[74]',NULL,NULL,'sm9');
