INSERT INTO "Card" VALUES('sm9-44','Blitzle','Pokémon','44','Common','Akira Komayama','Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/44.png","large":"https://images.pokemontcg.io/sm9/44_hires.png"}',NULL,'60',NULL,'["Basic"]','["Lightning"]',NULL,'["Zebstrika"]',NULL,'[{"name":"Delivery Dash","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Electropower cards, reveal them, and put them into your hand. Then, shuffle your deck."},{"name":"Zap Kick","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[522]',NULL,NULL,'sm9');
