INSERT INTO "Card" VALUES('sm9-126','Persian','Pokémon','126','Uncommon','Yukiko Baba','Although the jewel on its forehead appears to be a different color than those of Alolan Persian, it''s mostly made of the same material.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/126.png","large":"https://images.pokemontcg.io/sm9/126_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Colorless"]','Meowth',NULL,NULL,'[{"name":"Make ''Em Pay","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"If your opponent has 4 or more cards in their hand, they reveal their hand. Discard cards you find there until your opponent has exactly 4 cards in their hand."},{"name":"Sharp Claws","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 60 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[53]',NULL,NULL,'sm9');
