INSERT INTO "Card" VALUES('sm9-129','Tauros','Pokémon','129','Uncommon','kodama','They live in groups. The one with the longest, thickest, and most-scarred horns is the boss of the herd.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/129.png","large":"https://images.pokemontcg.io/sm9/129_hires.png"}',NULL,'130',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Raging Herd","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"This attack does 10 more damage for each damage counter on all of your Tauros and Tauros-GX."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[128]',NULL,NULL,'sm9');
