INSERT INTO "Card" VALUES('sm9-132','Zangoose','Pokémon','132','Rare Holo','Misa Tsutsui','Its fur would all stand on end if it smelled a Seviper nearby. Its sharp claws tear up its foes.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/132.png","large":"https://images.pokemontcg.io/sm9/132_hires.png"}',NULL,'100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Head Hunt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 6 cards of your deck, reveal any number of Pokémon you find there, and put them into your hand. Discard the other cards."},{"name":"Slash","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[335]',NULL,NULL,'sm9');
