INSERT INTO "Card" VALUES('sm9-137','Dana','Trainer','137','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/137.png","large":"https://images.pokemontcg.io/sm9/137_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if your opponent''s Active Pokémon is a Stage 2 Pokémon.","Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-138','Dangerous Drill','Trainer','138','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/138.png","large":"https://images.pokemontcg.io/sm9/138_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you discard a Darkness Pokémon from your hand.","Discard a Pokémon Tool or Special Energy card from 1 of your opponent''s Pokémon, or discard any Stadium card in play.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-139','Electrocharger','Trainer','139','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/139.png","large":"https://images.pokemontcg.io/sm9/139_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. For each heads, shuffle an Electropower card from your discard pile into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-140','Erika''s Hospitality','Trainer','140','Rare Holo','Sanosuke Sakuma',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/140.png","large":"https://images.pokemontcg.io/sm9/140_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you have 4 or fewer other cards in your hand.","Draw a card for each of your opponent''s Pokémon in play.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
