INSERT INTO "Card" VALUES('sm9-142','Fairy Charm UB','Trainer','142','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/142.png","large":"https://images.pokemontcg.io/sm9/142_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Prevent all damage done to the Fairy Pokémon this card is attached to by attacks from your opponent''s Ultra Beast Pokémon-GX and Ultra Beast Pokémon-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-143','Grass Memory','Trainer','143','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/143.png","large":"https://images.pokemontcg.io/sm9/143_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Silvally-GX this card is attached to is a Grass Pokémon.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-144','Ingo & Emmet','Trainer','144','Uncommon','Yusuke Ohmura',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/144.png","large":"https://images.pokemontcg.io/sm9/144_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top card of your deck, and then choose 1:\n• Discard your hand and draw 5 cards.\n• Discard your hand and draw 5 cards from the bottom of your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-145','Jasmine','Trainer','145','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/145.png","large":"https://images.pokemontcg.io/sm9/145_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Metal Pokémon, reveal it, and put it into your hand. If you go second and it''s your first turn, search for 5 Metal Pokémon instead of 1. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
