INSERT INTO "Card" VALUES('sm9-147','Lavender Town','Trainer','147','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/147.png","large":"https://images.pokemontcg.io/sm9/147_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may have their opponent reveal their hand.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','sm9');
INSERT INTO "Card" VALUES('sm9-148','Metal Goggles','Trainer','148','Uncommon','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/148.png","large":"https://images.pokemontcg.io/sm9/148_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Metal Pokémon this card is attached to takes 30 less damage from your opponent''s attacks (after applying Weakness and Resistance), and your opponent''s attacks and Abilities can''t put damage counters on it.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-149','Morgan','Trainer','149','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/149.png","large":"https://images.pokemontcg.io/sm9/149_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you discard Dana, Evelyn, and Nita from your hand.","Look at the top 12 cards of your deck and attach any number of Energy cards you find there to your Pokémon in any way you like. Shuffle the other cards back into your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-150','Nanu','Trainer','150','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/150.png","large":"https://images.pokemontcg.io/sm9/150_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a Basic Darkness Pokémon in your discard pile. Switch it with 1 of your Pokémon in play. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
