INSERT INTO "Card" VALUES('sm9-173','Dana','Trainer','173','Rare Ultra','Kagemaru Himeno',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/173.png","large":"https://images.pokemontcg.io/sm9/173_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if your opponent''s Active Pokémon is a Stage 2 Pokémon.","Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-174','Erika''s Hospitality','Trainer','174','Rare Ultra','Sanosuke Sakuma',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/174.png","large":"https://images.pokemontcg.io/sm9/174_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you have 4 or fewer other cards in your hand.","Draw a card for each of your opponent''s Pokémon in play.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-175','Evelyn','Trainer','175','Rare Ultra','Kagemaru Himeno',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/175.png","large":"https://images.pokemontcg.io/sm9/175_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if your opponent''s Active Pokémon is a Stage 1 Pokémon.","Draw 4 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
