INSERT INTO "Card" VALUES('sm9-177','Jasmine','Trainer','177','Rare Ultra','Hideki Ishikawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/177.png","large":"https://images.pokemontcg.io/sm9/177_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Metal Pokémon, reveal it, and put it into your hand. If you go second and it''s your first turn, search for 5 Metal Pokémon instead of 1. Then, shuffle your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-178','Morgan','Trainer','178','Rare Ultra','Kagemaru Himeno',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/178.png","large":"https://images.pokemontcg.io/sm9/178_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you discard Dana, Evelyn, and Nita from your hand.","Look at the top 12 cards of your deck and attach any number of Energy cards you find there to your Pokémon in any way you like. Shuffle the other cards back into your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-179','Nanu','Trainer','179','Rare Ultra','Hitoshi Ariga',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/179.png","large":"https://images.pokemontcg.io/sm9/179_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a Basic Darkness Pokémon in your discard pile. Switch it with 1 of your Pokémon in play. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.","You may play only 1 Supporter card during your turn (before your attack)."]','sm9');
