INSERT INTO "Card" VALUES('sm9-193','Electrocharger','Trainer','193','Rare Secret','Eske Yoshinob',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/193.png","large":"https://images.pokemontcg.io/sm9/193_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. For each heads, shuffle an Electropower card from your discard pile into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-194','Judge Whistle','Trainer','194','Rare Secret','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/194.png","large":"https://images.pokemontcg.io/sm9/194_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1:\n• Draw a card\n• Put a Judge card from your discard pile into your hand.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-195','Metal Goggles','Trainer','195','Rare Secret','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/195.png","large":"https://images.pokemontcg.io/sm9/195_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Metal Pokémon this card is attached to takes 30 less damage from your opponent''s attacks (after applying Weakness and Resistance), and your opponent''s attacks and Abilities can''t put damage counters on it.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sm9-196','Pokémon Communication','Trainer','196','Rare Secret','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sm9/196.png","large":"https://images.pokemontcg.io/sm9/196_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal a Pokémon from your hand and put it into your deck. If you do, search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','sm9');
INSERT INTO "Card" VALUES('sma-SV1','Scyther','Pokémon','SV1','Rare Shiny','Shigenori Negishi','While young, they live together deep in the mountains, training themselves in how to fight with their scythes and move at high speeds.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV1.png","large":"https://images.pokemontcg.io/sma/SV1_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,'["Scizor"]',NULL,'[{"name":"Twin Play","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Scyther and put them onto your Bench. Then, shuffle your deck."},{"name":"Agility","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent''s next turn."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[123]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV2','Rowlet','Pokémon','SV2','Rare Shiny','sui','This wary Pokémon uses photosynthesis to store up energy during the day, while becoming active at night.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV2.png","large":"https://images.pokemontcg.io/sma/SV2_hires.png"}',NULL,'60',NULL,'["Basic"]','["Grass"]',NULL,'["Dartrix"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Leafage","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[722]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV3','Dartrix','Pokémon','SV3','Rare Shiny','Shigenori Negishi','A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV3.png","large":"https://images.pokemontcg.io/sma/SV3_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Grass"]','Rowlet','["Decidueye"]',NULL,'[{"name":"Sharp Blade Quill","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Leaf Blade","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"Flip a coin. If heads, this attack does 20 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[723]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV4','Wimpod','Pokémon','SV4','Rare Shiny','SATOSHI NAKAI','This Pokémon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV4.png","large":"https://images.pokemontcg.io/sma/SV4_hires.png"}',NULL,'70',NULL,'["Basic"]','["Grass"]',NULL,'["Golisopod"]','[{"name":"Wimp Out","text":"During your first turn, this Pokémon has no Retreat Cost.","type":"Ability"}]','[{"name":"Gnaw","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[767]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV5','Pheromosa','Pokémon','SV5','Rare Shiny','Mizue','One of the Ultra Beasts. It refuses to touch anything, perhaps because it senses some uncleanness in this world.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV5.png","large":"https://images.pokemontcg.io/sma/SV5_hires.png"}',NULL,'110',NULL,'["Basic","Ultra Beast"]','["Grass"]',NULL,NULL,NULL,'[{"name":"High Jump Kick","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"White Ray","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"90+","text":"If you have only 1 Prize card remaining, this attack does 90 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[795]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV6','Charmander','Pokémon','SV6','Rare Shiny','kirisAki','From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV6.png","large":"https://images.pokemontcg.io/sma/SV6_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fire"]',NULL,'["Charmeleon"]',NULL,'[{"name":"Fire Fang","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Your opponent''s Active Pokémon is now Burned."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[4]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV7','Charmeleon','Pokémon','SV7','Rare Shiny','nagimiso','When it swings its burning tail, it elevates the air temperature to unbearably high levels.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV7.png","large":"https://images.pokemontcg.io/sma/SV7_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fire"]','Charmander','["Charizard"]','[{"name":"Burning Fighter","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may discard the top 5 cards of your deck. If any of those cards are Fire Energy cards, attach them to this Pokémon.","type":"Ability"}]','[{"name":"Flamethrower","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Discard an Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[5]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV8','Alolan Vulpix','Pokémon','SV8','Rare Shiny','Kouki Saitou','It exhales air colder than -58 degrees Fahrenheit. Elderly people in Alola call this Pokémon by an older name—Keokeo.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV8.png","large":"https://images.pokemontcg.io/sma/SV8_hires.png"}',NULL,'60',NULL,'["Basic"]','["Water"]',NULL,'["Ninetales"]',NULL,'[{"name":"Beacon","cost":[],"convertedEnergyCost":0,"damage":"","text":"Search your deck for up to 2 Pokémon, reveal them, and put them into your hand. Then, shuffle your deck."},{"name":"Icy Snow","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[37]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV9','Wooper','Pokémon','SV9','Rare Shiny','Misa Tsutsui','When the temperature cools in the evening, they emerge from water to seek food along the shore.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV9.png","large":"https://images.pokemontcg.io/sma/SV9_hires.png"}',NULL,'70',NULL,'["Basic"]','["Water"]',NULL,'["Quagsire"]',NULL,'[{"name":"Ram","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Rain Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[194]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV10','Quagsire','Pokémon','SV10','Rare Shiny','Saya Tsuruta','This carefree Pokémon has an easygoing nature. While swimming, it always bumps into boat hulls.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV10.png","large":"https://images.pokemontcg.io/sma/SV10_hires.png"}',NULL,'120',NULL,'["Stage 1"]','["Water"]','Wooper',NULL,'[{"name":"Wash Out","text":"As often as you like during your turn (before your attack), you may move a Water Energy from 1 of your Benched Pokémon to your Active Pokémon.","type":"Ability"}]','[{"name":"Hydro Pump","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"This attack does 20 more damage times the amount of Water Energy attached to this Pokémon."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[195]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV11','Froakie','Pokémon','SV11','Rare Shiny','sui','It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV11.png","large":"https://images.pokemontcg.io/sma/SV11_hires.png"}',NULL,'50',NULL,'["Basic"]','["Water"]',NULL,'["Frogadier"]','[{"name":"Frubbles","text":"If this Pokémon has any Water Energy attached to it, it has no Retreat Cost.","type":"Ability"}]','[{"name":"Flop","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[656]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV12','Frogadier','Pokémon','SV12','Rare Shiny','Anesaki Dynamic','Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute''s time.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV12.png","large":"https://images.pokemontcg.io/sma/SV12_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Water"]','Froakie','["Greninja"]','[{"name":"Gale Shuriken","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may put 2 damage counters on 1 of your opponent''s Pokémon.","type":"Ability"}]','[{"name":"Water Drip","cost":["Water"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[657]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV13','Voltorb','Pokémon','SV13','Rare Shiny','Shin Nagasawa','Usually found in power plants. Easily mistaken for a Poké Ball, it has zapped many people.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV13.png","large":"https://images.pokemontcg.io/sma/SV13_hires.png"}',NULL,'50',NULL,'["Basic"]','["Lightning"]',NULL,'["Electrode"]','[{"name":"Floating Electrons","text":"If this Pokémon has any Energy attached to it, it has no Retreat Cost.","type":"Ability"}]','[{"name":"Thunder Shock","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[100]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV14','Xurkitree','Pokémon','SV14','Rare Shiny','Naoki Saito','It appeared from the Ultra Wormhole. It raided a power plant, so people think it energizes itself with electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV14.png","large":"https://images.pokemontcg.io/sma/SV14_hires.png"}',NULL,'120',NULL,'["Basic","Ultra Beast"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Dazzle Blast","cost":["Lightning"],"convertedEnergyCost":1,"damage":"20","text":"Your opponent''s Active Pokémon is now Confused."},{"name":"Cablegram","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"If you have exactly 3 Prize cards remaining, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[796]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV15','Seviper','Pokémon','SV15','Rare Shiny','SATOSHI NAKAI','In battle, it uses its bladed tail to counter any Zangoose. It secretes a deadly venom in its tail.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV15.png","large":"https://images.pokemontcg.io/sma/SV15_hires.png"}',NULL,'100',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"More Poison","text":"Put 1 more damage counter on your opponent''s Poisoned Pokémon between turns.","type":"Ability"}]','[{"name":"Venomous Fang","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[336]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV16','Shuppet','Pokémon','SV16','Rare Shiny','sui','It loves vengeful emotions and hangs in rows under the eaves of houses where vengeful people live.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV16.png","large":"https://images.pokemontcg.io/sma/SV16_hires.png"}',NULL,'60',NULL,'["Basic"]','["Psychic"]',NULL,'["Banette"]',NULL,'[{"name":"Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Will-O-Wisp","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[353]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV17','Inkay','Pokémon','SV17','Rare Shiny','Shigenori Negishi','It flashes the light-emitting spots on its body, which drains its opponent''s will to fight. It takes the opportunity to scuttle away and hide.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV17.png","large":"https://images.pokemontcg.io/sma/SV17_hires.png"}',NULL,'60',NULL,'["Basic"]','["Psychic"]',NULL,'["Malamar"]',NULL,'[{"name":"Hypnosis","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Asleep."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[686]',NULL,NULL,'sma');
INSERT INTO "Card" VALUES('sma-SV18','Malamar','Pokémon','SV18','Rare Shiny','Hideki Ishikawa','It lures prey close with hypnotic motions, then wraps its tentacles around it before finishing it off with digestive fluids.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV18.png","large":"https://images.pokemontcg.io/sma/SV18_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Psychic"]','Inkay',NULL,'[{"name":"Psychic Recharge","text":"Once during your turn (before your attack), you may attach a Psychic Energy card from your discard pile to 1 of your Benched Pokémon.","type":"Ability"}]','[{"name":"Psychic Sphere","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[687]',NULL,NULL,'sma');
