INSERT INTO "Card" VALUES('sma-SV20','Sudowoodo','Pokémon','SV20','Rare Shiny','Kyoko Umemoto','To avoid attack, it mimics a tree. It will run off if splashed with water, which it hates.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sma/SV20.png","large":"https://images.pokemontcg.io/sma/SV20_hires.png"}',NULL,'100',NULL,'["Basic"]','["Fighting"]',NULL,NULL,'[{"name":"Roadblock","text":"Your opponent can''t have more than 4 Benched Pokémon. If they have 5 or more Benched Pokémon, they discard Benched Pokémon until they have 4 Pokémon on the Bench. If more than one effect changes the number of Benched Pokémon allowed, use the smaller number.","type":"Ability"}]','[{"name":"Rock Throw","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[185]',NULL,NULL,'sma');
