INSERT INTO "Card" VALUES('smp-SM209','Stakataka','Pokémon','SM209','Promo','Shin Nagasawa','It appeared from an Ultra Wormhole. Each one appears to be made up of many life-forms stacked one on top of each other.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/smp/SM209.png","large":"https://images.pokemontcg.io/smp/SM209_hires.png"}',NULL,'120',NULL,'["Basic","Ultra Beast"]','["Fighting"]',NULL,NULL,'[{"name":"Wall of Stone","text":"If your opponent has 3 or fewer Prize cards remaining, this Pokémon''s maximum HP is 200.","type":"Ability"}]','[{"name":"Top Down","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"110","text":"Flip a coin until you get tails. For each heads, discard the top card of your opponent''s deck."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[805]',NULL,NULL,'smp');
