INSERT INTO "Card" VALUES('sv1-125','Koraidon ex','Pokémon','125','Double Rare','aky CG Works','This seems to be the Winged King mentioned in an old expedition journal. It was said to have split the land with its bare fists.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/125.png","large":"https://images.pokemontcg.io/sv1/125_hires.png"}','G','230',NULL,'["Basic","ex"]','["Fighting"]',NULL,NULL,'[{"type":"Ability","name":"Dino Cry","text":"Once during your turn, you may attach up to 2 Basic Fighting Energy cards from your discard pile to your Basic Fighting Pokémon in any way you like. If you use this Ability, your turn ends."}]','[{"cost":["Fighting","Fighting","Colorless"],"name":"Wild Impact","damage":"220","text":"During your next turn, this Pokémon can''t attack.","convertedEnergyCost":3}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[1007]',NULL,'["Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards."]','sv1');
