INSERT INTO "Card" VALUES('sv1-128','Seviper','Pokémon','128','Common','sui','It sharpens its swordlike tail on hard rocks. It hides in tall grass and strikes unwary prey with venomous fangs.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/128.png","large":"https://images.pokemontcg.io/sv1/128_hires.png"}','G','120',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"cost":["Darkness"],"name":"Spit Poison","damage":"","text":"Your opponent''s Active Pokémon is now Poisoned.","convertedEnergyCost":1},{"cost":["Darkness","Colorless","Colorless"],"name":"Venoshock","damage":"60+","text":"If your opponent''s Active Pokémon is Poisoned, this attack does 120 more damage.","convertedEnergyCost":3}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[336]',NULL,NULL,'sv1');
