INSERT INTO "Card" VALUES('sv1-138','Bombirdier','Pokémon','138','Uncommon','nagimiso','Bombirdier uses the apron on its chest to bundle up food, which it carries back to its nest. It enjoys dropping things that make loud noises.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/138.png","large":"https://images.pokemontcg.io/sv1/138_hires.png"}','G','110',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"cost":["Colorless"],"name":"Knickknack Carrying","damage":"","text":"Search your deck for up to 3 Pokémon Tool cards, reveal them, and put them into your hand. Then, shuffle your deck.","convertedEnergyCost":1},{"cost":["Darkness","Colorless"],"name":"Clutch","damage":"60","text":"During your opponent''s next turn, the Defending Pokémon can''t retreat.","convertedEnergyCost":2}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[962]',NULL,NULL,'sv1');
