INSERT INTO "Card" VALUES('sv1-164','Cyclizar','Pokémon','164','Rare','Ryota Murayama','It can sprint at over 70 mph while carrying a human. The rider''s body heat warms Cyclizar''s back and lifts the Pokémon''s spirit.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/164.png","large":"https://images.pokemontcg.io/sv1/164_hires.png"}','G','110',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"cost":["Colorless"],"name":"Touring","damage":"","text":"Draw 2 cards.","convertedEnergyCost":1},{"cost":["Colorless","Colorless","Colorless"],"name":"Speed Attack","damage":"100","text":"","convertedEnergyCost":3}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[967]',NULL,NULL,'sv1');
INSERT INTO "Card" VALUES('sv1-165','Flamigo','Pokémon','165','Uncommon','kantaro','Thanks to a behavior of theirs known as "synchronizing," an entire flock of these Pokémon can attack simultaneously in perfect harmony.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/165.png","large":"https://images.pokemontcg.io/sv1/165_hires.png"}','G','110',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"cost":["Colorless"],"name":"Flap","damage":"30","text":"","convertedEnergyCost":1},{"cost":["Colorless","Colorless","Colorless"],"name":"Nosedive","damage":"110","text":"This Pokémon also does 20 damage to itself.","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[973]',NULL,NULL,'sv1');
INSERT INTO "Card" VALUES('sv1-166','Arven','Trainer','166','Uncommon','GIDORA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/166.png","large":"https://images.pokemontcg.io/sv1/166_hires.png"}','G',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for an Item card and a Pokémon Tool card, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','sv1');
INSERT INTO "Card" VALUES('sv1-167','Beach Court','Trainer','167','Uncommon','Oswaldo KATO',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/167.png","large":"https://images.pokemontcg.io/sv1/167_hires.png"}','G',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The Retreat Cost of each Basic Pokémon in play (both yours and your opponent''s) is Colorless less.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv1');
