INSERT INTO "Card" VALUES('sv1-170','Electric Generator','Trainer','170','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/170.png","large":"https://images.pokemontcg.io/sv1/170_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 5 cards of your deck and attach up to 2 Basic Lightning Energy cards you find there to your Benched Lightning Pokémon in any way you like. Shuffle the other cards back into your deck.","You may play any number of Item cards during your turn."]','sv1');
INSERT INTO "Card" VALUES('sv1-171','Energy Retrieval','Trainer','171','Common','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv1/171.png","large":"https://images.pokemontcg.io/sv1/171_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put up to 2 Basic Energy cards from your discard pile into your hand.","You may play any number of Item cards during your turn."]','sv1');
