INSERT INTO "Card" VALUES('sv2-2','Skiploom','Pokémon','2','Uncommon','Yoriyuki Ikegami','Skiploom enthusiasts can apparently tell where a Skiploom was born by the scent drifting from the flower on the Pokémon''s head.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/2.png","large":"https://images.pokemontcg.io/sv2/2_hires.png"}','G','70',NULL,'["Stage 1"]','["Grass"]','Hoppip',NULL,'[{"type":"Ability","name":"Drifting Dodge","text":"If any damage is done to this Pokémon by attacks, flip a coin. If heads, prevent that damage."}]','[{"cost":["Grass"],"name":"Flowery Zephyr","damage":"30","text":"This attack also does 30 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)","convertedEnergyCost":1}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[188]',NULL,NULL,'sv2');
