INSERT INTO "Card" VALUES('sv2-6','Heracross','Pokémon','6','Uncommon','GOSSAN','It loves sweet nectar. To keep all the nectar to itself, it hurls rivals away with its prized horn.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/6.png","large":"https://images.pokemontcg.io/sv2/6_hires.png"}','G','130',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"cost":["Grass","Grass"],"name":"Tackle","damage":"50","text":"","convertedEnergyCost":2},{"cost":["Grass","Grass","Grass"],"name":"Smashing Horn","damage":"110","text":"This attack''s damage isn''t affected by Resistance.","convertedEnergyCost":3}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[214]',NULL,NULL,'sv2');
