INSERT INTO "Card" VALUES('sv2-146','Grafaiai','Pokémon','146','Uncommon','Souichirou Gunjima','The color of the poisonous saliva depends on what the Pokémon eats. Grafaiai covers its fingers in its saliva and draws patterns on trees in forests.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/146.png","large":"https://images.pokemontcg.io/sv2/146_hires.png"}','G','90',NULL,'["Stage 1"]','["Darkness"]','Shroodle',NULL,NULL,'[{"cost":["Darkness"],"name":"Spit Poison","damage":"","text":"Your opponent''s Active Pokémon is now Poisoned.","convertedEnergyCost":1},{"cost":["Darkness"],"name":"Colorful Graffiti","damage":"40×","text":"You may discard as many Basic Energy cards as you like from your hand. This attack does 40 damage for each type of Basic Energy you discarded in this way.","convertedEnergyCost":1}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[945]',NULL,NULL,'sv2');
INSERT INTO "Card" VALUES('sv2-147','Bombirdier','Pokémon','147','Uncommon','Sekio','It gathers things up in an apron made from shed feathers added to the Pokémon''s chest feathers, then drops those things from high places for fun.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/147.png","large":"https://images.pokemontcg.io/sv2/147_hires.png"}','G','120',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"cost":["Colorless"],"name":"Delivery Pocket","damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck.","convertedEnergyCost":1},{"cost":["Darkness","Darkness","Colorless"],"name":"Dark Edge","damage":"120","text":"Discard an Energy from this Pokémon.","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[962]',NULL,NULL,'sv2');
INSERT INTO "Card" VALUES('sv2-148','Corviknight','Pokémon','148','Uncommon','Scav','Corviknight can''t serve as a taxi service in Paldea because the Pokémon''s natural predators will attack it while it flies, endangering the customer.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/148.png","large":"https://images.pokemontcg.io/sv2/148_hires.png"}','G','170',NULL,'["Stage 2"]','["Metal"]','Corvisquire',NULL,NULL,'[{"cost":["Metal"],"name":"Accelerate","damage":"50","text":"If your opponent''s Pokémon is Knocked Out by damage from this attack, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon.","convertedEnergyCost":1},{"cost":["Metal","Colorless","Colorless"],"name":"Spinning Bird","damage":"200","text":"Discard 2 Energy from this Pokémon.","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[823]',NULL,NULL,'sv2');
