INSERT INTO "Card" VALUES('sv2-156','Dunsparce','Pokémon','156','Common','Nagomi Nijo','It creates mazes in dark locations. When spotted, it flees into the ground by digging with its tail.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/156.png","large":"https://images.pokemontcg.io/sv2/156_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"cost":["Colorless"],"name":"Find a Friend","damage":"","text":"Search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","convertedEnergyCost":1},{"cost":["Colorless","Colorless","Colorless"],"name":"Bite","damage":"50","text":"","convertedEnergyCost":3}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[206]',NULL,NULL,'sv2');
