INSERT INTO "Card" VALUES('sv2-159','Pelipper','Pokémon','159','Uncommon','Shinya Komatsu','It is a flying transporter that carries small Pokémon in its beak. It bobs on the waves to rest its wings.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/159.png","large":"https://images.pokemontcg.io/sv2/159_hires.png"}','G','120',NULL,'["Stage 1"]','["Colorless"]','Wingull',NULL,'[{"type":"Ability","name":"Hearsay","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may choose 1: put a Supporter card from your discard pile into your hand; or search your deck for a Supporter card, reveal it, put it into your hand, and then shuffle your deck."}]','[{"cost":["Colorless","Colorless","Colorless"],"name":"Wing Attack","damage":"90","text":"","convertedEnergyCost":3}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[279]',NULL,NULL,'sv2');
