INSERT INTO "Card" VALUES('sv2-162','Slaking','Pokémon','162','Rare','Yuya Oka','It is the world''s most slothful Pokémon. However, it can exert horrifying power by releasing pent-up energy all at once.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/162.png","large":"https://images.pokemontcg.io/sv2/162_hires.png"}','G','180',NULL,'["Stage 2"]','["Colorless"]','Vigoroth',NULL,'[{"type":"Ability","name":"Stir and Snooze","text":"If this Pokémon is Asleep, flip 2 coins instead of 1 during Pokémon Checkup. If either of them is tails, this Pokémon is still Asleep."}]','[{"cost":["Colorless","Colorless","Colorless"],"name":"Slacker''s Headstrike","damage":"240","text":"This Pokémon is now Asleep.","convertedEnergyCost":3}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[289]',NULL,NULL,'sv2');
