INSERT INTO "Card" VALUES('sv2-174','Calamitous Snowy Mountain','Trainer','174','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/174.png","large":"https://images.pokemontcg.io/sv2/174_hires.png"}','G',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Whenever any player attaches an Energy card from their hand to 1 of their Basic non-Water Pokémon, put 2 damage counters on that Pokémon.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv2');
INSERT INTO "Card" VALUES('sv2-175','Calamitous Wasteland','Trainer','175','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/175.png","large":"https://images.pokemontcg.io/sv2/175_hires.png"}','G',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The Retreat Cost of each Basic non-Fighting Pokémon in play (both yours and your opponent''s) is Colorless more.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv2');
