INSERT INTO "Card" VALUES('sv2-177','Clavell','Trainer','177','Common','Hitoshi Ariga',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/177.png","large":"https://images.pokemontcg.io/sv2/177_hires.png"}','G',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for up to 3 Basic Pokémon with 120 HP or less, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','sv2');
INSERT INTO "Card" VALUES('sv2-178','Delivery Drone','Trainer','178','Uncommon','inose yukie',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/178.png","large":"https://images.pokemontcg.io/sv2/178_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. If both of them are heads, search your deck for a card and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','sv2');
