INSERT INTO "Card" VALUES('sv2-181','Fighting Au Lait','Trainer','181','Uncommon','Ayaka Yoshida',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/181.png","large":"https://images.pokemontcg.io/sv2/181_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you have more Prize cards remaining than your opponent.Heal 60 damage from 1 of your Pokémon.","You may play any number of Item cards during your turn."]','sv2');
