INSERT INTO "Card" VALUES('sv2-185','Iono','Trainer','185','Uncommon','Sanosuke Sakuma',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/185.png","large":"https://images.pokemontcg.io/sv2/185_hires.png"}','G',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, each player draws a card for each of their remaining Prize cards.","You may play only 1 Supporter card during your turn."]','sv2');
