INSERT INTO "Card" VALUES('sv2-190','Jet Energy','Energy','190','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/190.png","large":"https://images.pokemontcg.io/sv2/190_hires.png"}','G',NULL,NULL,'["Special"]','["Colorless"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides Colorless Energy. When you attach this card from your hand to 1 of your Benched Pokémon, switch that Pokémon with your Active Pokémon."]','sv2');
INSERT INTO "Card" VALUES('sv2-191','Luminous Energy','Energy','191','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/191.png","large":"https://images.pokemontcg.io/sv2/191_hires.png"}','G',NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides every type of Energy but provides only 1 Energy at a time.If the Pokémon this card is attached to has any other Special Energy attached, this card provides Colorless Energy instead."]','sv2');
INSERT INTO "Card" VALUES('sv2-192','Reversal Energy','Energy','192','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/192.png","large":"https://images.pokemontcg.io/sv2/192_hires.png"}','G',NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides Colorless Energy.If you have more Prize cards remaining than your opponent, and if this card is attached to an Evolution Pokémon that doesn''t have a Rule Box (Pokémon ex, Pokémon V, etc. have Rule Boxes), this card provides every type of Energy but provides only 3 Energy at a time."]','sv2');
INSERT INTO "Card" VALUES('sv2-193','Therapeutic Energy','Energy','193','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/193.png","large":"https://images.pokemontcg.io/sv2/193_hires.png"}','G',NULL,NULL,'["Special"]','["Colorless"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides Colorless Energy.The Pokémon this card is attached to recovers from being Asleep, Confused, or Paralyzed and can''t be affected by those Special Conditions."]','sv2');
