INSERT INTO "Card" VALUES('sv2-198','Bramblin','Pokémon','198','Illustration Rare','sowsow','A soul unable to move on to the afterlife was blown around by the wind until it got tangled up with dried grass and became a Pokémon.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/198.png","large":"https://images.pokemontcg.io/sv2/198_hires.png"}','G','50',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"cost":["Grass"],"name":"Blot","damage":"10","text":"Heal 10 damage from this Pokémon.","convertedEnergyCost":1}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[946]',NULL,NULL,'sv2');
INSERT INTO "Card" VALUES('sv2-199','Fletchinder','Pokémon','199','Illustration Rare','Atsushi Furusawa','Fletchinder scatters embers in tall grass where bug Pokémon might be hiding and then catches them as they come leaping out.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv2/199.png","large":"https://images.pokemontcg.io/sv2/199_hires.png"}','G','80',NULL,'["Stage 1"]','["Fire"]','Fletchling',NULL,NULL,'[{"cost":["Fire"],"name":"Heat Dive","damage":"50","text":"This Pokémon also does 10 damage to itself.","convertedEnergyCost":1}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[662]',NULL,NULL,'sv2');
