INSERT INTO "Card" VALUES('sv3-12','Trevenant','Pokémon','12','Uncommon','Anesaki Dynamic','Small roots that extend from the tips of this Pokémon''s feet can tie into the trees of the forest and give Trevenant control over them.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/12.png","large":"https://images.pokemontcg.io/sv3/12_hires.png"}','G','140',NULL,'["Stage 1"]','["Grass"]','Phantump',NULL,'[{"name":"Forest Miasma","text":"During Pokémon Checkup, if this Pokémon is in the Active Spot, put 1 damage counter on your opponent''s Active Pokémon.","type":"Ability"}]','[{"name":"Lock Up","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"During your opponent''s next turn, the Defending Pokémon can''t retreat."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[709]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-13','Rowlet','Pokémon','13','Common','Tomokazu Komiya','It feels relaxed in tight, dark places and has been known to use its Trainer''s pocket or bag as a nest.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/13.png","large":"https://images.pokemontcg.io/sv3/13_hires.png"}','G','70',NULL,'["Basic"]','["Grass"]',NULL,'["Dartrix"]',NULL,'[{"name":"Razor Wing","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[722]',NULL,NULL,'sv3');
