INSERT INTO "Card" VALUES('sv3-65','Magnezone','Pokémon','65','Uncommon','Anesaki Dynamic','As it zooms through the sky, this Pokémon seems to be receiving signals of unknown origin while transmitting signals of unknown purpose.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/65.png","large":"https://images.pokemontcg.io/sv3/65_hires.png"}','G','170',NULL,'["Stage 2"]','["Lightning"]','Magneton',NULL,NULL,'[{"name":"Magnetic Repulsion","cost":["Lightning"],"convertedEnergyCost":1,"damage":"50","text":"You may switch out your opponent''s Active Pokémon to the Bench. (Your opponent chooses the new Active Pokémon.)"},{"name":"Thunder","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"180","text":"This Pokémon also does 30 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[462]',NULL,NULL,'sv3');
