INSERT INTO "Card" VALUES('sv3-145','Bronzong','Pokémon','145','Uncommon','Nobuhiro Imagawa','In ages past, this Pokémon was revered as a bringer of rain. It was found buried in the ground.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/145.png","large":"https://images.pokemontcg.io/sv3/145_hires.png"}','G','140',NULL,'["Stage 1"]','["Metal"]','Bronzor',NULL,NULL,'[{"name":"Oracle Press","cost":["Metal"],"convertedEnergyCost":1,"damage":"20","text":"During your opponent''s next turn, prevent all effects of attacks used by your opponent''s Pokémon done to this Pokémon. (Damage is not an effect.)"},{"name":"Extrasensory","cost":["Metal","Metal"],"convertedEnergyCost":2,"damage":"70+","text":"If you have the same number of cards in your hand as your opponent, this attack does 90 more damage."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[437]',NULL,NULL,'sv3');
