INSERT INTO "Card" VALUES('sv3-165','Kangaskhan','Pokémon','165','Uncommon','Yuya Oka','There are records of a lost human child being raised by a childless Kangaskhan.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/165.png","large":"https://images.pokemontcg.io/sv3/165_hires.png"}','G','130',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":""},{"name":"Spike Draw","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"Draw 2 cards."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[115]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-166','Eevee','Pokémon','166','Common','ryoma uratsuka','Its ability to evolve into many forms allows it to adapt smoothly and perfectly to any environment.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/166.png","large":"https://images.pokemontcg.io/sv3/166_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Vaporeon","Jolteon","Flareon","Espeon","Umbreon","Leafeon","Glaceon","Sylveon"]',NULL,'[{"name":"Cheer Up","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Attach an Energy card from your hand to 1 of your Pokémon."},{"name":"Kick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[133]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-167','Zigzagoon','Pokémon','167','Common','Kagemaru Himeno','A Pokémon with abundant curiosity. It shows an interest in everything, so it always zigzags.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/167.png","large":"https://images.pokemontcg.io/sv3/167_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Linoone"]',NULL,'[{"name":"Headbutt Bounce","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Claw Slash","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[263]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-168','Linoone','Pokémon','168','Uncommon','Nagomi Nijo','It uses its explosive speed and razor-sharp claws to bring down prey. Running along winding paths is not its strong suit.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/168.png","large":"https://images.pokemontcg.io/sv3/168_hires.png"}','G','110',NULL,'["Stage 1"]','["Colorless"]','Zigzagoon','["Obstagoon"]',NULL,'[{"name":"Jet Headbutt","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":""},{"name":"Reckless Charge","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"150","text":"This Pokémon also does 30 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[264]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-169','Swablu','Pokémon','169','Common','Oswaldo KATO','It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/169.png","large":"https://images.pokemontcg.io/sv3/169_hires.png"}','G','50',NULL,'["Basic"]','["Colorless"]',NULL,'["Altaria"]',NULL,'[{"name":"Fluffy Guard","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, this Pokémon takes 20 less damage from attacks (after applying Weakness and Resistance)."},{"name":"Flap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[333]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-170','Lillipup','Pokémon','170','Common','Yuka Morii','This Pokémon is far brighter than the average child, and Lillipup won''t forget the love it receives or any abuse it suffers.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/170.png","large":"https://images.pokemontcg.io/sv3/170_hires.png"}','G','50',NULL,'["Basic"]','["Colorless"]',NULL,'["Herdier"]',NULL,'[{"name":"Rear Kick","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[506]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-171','Herdier','Pokémon','171','Common','Kariya','The black fur that covers this Pokémon''s body is dense and springy. Even sharp fangs bounce right off.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/171.png","large":"https://images.pokemontcg.io/sv3/171_hires.png"}','G','90',NULL,'["Stage 1"]','["Colorless"]','Lillipup','["Stoutland"]',NULL,'[{"name":"Rear Kick","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":""},{"name":"Hammer In","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[507]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-172','Stoutland','Pokémon','172','Uncommon','Keisin','Stoutland is immensely proud of its impressive moustache. It''s said that moustache length is what determines social standing among this species.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/172.png","large":"https://images.pokemontcg.io/sv3/172_hires.png"}','G','160',NULL,'["Stage 2"]','["Colorless"]','Herdier',NULL,NULL,'[{"name":"Chomp Chomp Panic","cost":["Colorless"],"convertedEnergyCost":1,"damage":"50×","text":"This attack does 50 damage for each Colorless in your opponent''s Active Pokémon''s Retreat Cost."},{"name":"Sharp Fang","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"140","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[508]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-173','Audino','Pokémon','173','Common','Tika Matsuno','This Pokémon has a kind heart. By touching with its feelers, Audino can gauge other creatures'' feelings and physical conditions.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/173.png","large":"https://images.pokemontcg.io/sv3/173_hires.png"}','G','100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Find a Friend","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Slap","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[531]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-174','Bouffalant','Pokémon','174','Uncommon','Yuya Oka','These Pokémon live in herds of about 20 individuals. Bouffalant that betray the herd will lose the hair on their heads for some reason.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/174.png","large":"https://images.pokemontcg.io/sv3/174_hires.png"}','G','120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Bouffer","text":"This Pokémon takes 20 less damage from attacks (after applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Damage Rush","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50+","text":"Flip a coin until you get tails. This attack does 30 more damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[626]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-175','Bunnelby','Pokémon','175','Common','Lee HyunJung','It''s very sensitive to danger. The sound of Corviknight''s flapping will have Bunnelby digging a hole to hide underground in moments.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/175.png","large":"https://images.pokemontcg.io/sv3/175_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Diggersby"]',NULL,'[{"name":"Stompy Stomp","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[659]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-176','Yungoos','Pokémon','176','Common','saino misaki','Its stomach fills most of its torso. It wanders the same path every day, searching for fresh food.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/176.png","large":"https://images.pokemontcg.io/sv3/176_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Gumshoos"]',NULL,'[{"name":"Knock Away","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[734]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-177','Gumshoos','Pokémon','177','Uncommon','Eri Yamaki','Once it finds signs of prey, it will patiently stake out the location, waiting until the sun goes down.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/177.png","large":"https://images.pokemontcg.io/sv3/177_hires.png"}','G','120',NULL,'["Stage 1"]','["Colorless"]','Yungoos',NULL,NULL,'[{"name":"Headbang","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":""},{"name":"Crunch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"Discard an Energy from your opponent''s Active Pokémon."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[735]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-178','Skwovet','Pokémon','178','Common','Taiga Kayama','It stores berries in its cheeks. When there are no berries to be found, Skwovet will stuff pebbles into its cheeks to stave off its cravings.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/178.png","large":"https://images.pokemontcg.io/sv3/178_hires.png"}','G','60',NULL,'["Basic"]','["Colorless"]',NULL,'["Greedent"]',NULL,'[{"name":"Nicked Nibble","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Discard the top card of your opponent''s deck."},{"name":"Gentle Slap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[819]',NULL,NULL,'sv3');
INSERT INTO "Card" VALUES('sv3-179','Greedent ex','Pokémon','179','Double Rare','5ban Graphics',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/179.png","large":"https://images.pokemontcg.io/sv3/179_hires.png"}','G','260',NULL,'["Stage 1","ex","Tera"]','["Colorless"]','Skwovet',NULL,NULL,'[{"name":"Never Ever Enough","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 3 cards of your deck. You may put those cards into your hand. If you don''t, discard those cards and draw 3 cards."},{"name":"Slip ''n'' Roll","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"210","text":"During your next turn, this Pokémon can''t use Slip ''n'' Roll."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[820]',NULL,'["Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.","Tera: As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent''s)."]','sv3');
INSERT INTO "Card" VALUES('sv3-180','Lechonk','Pokémon','180','Common','HYOGONOSUKE','It searches for food all day. It possesses a keen sense of smell but doesn''t use it for anything other than foraging.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/180.png","large":"https://images.pokemontcg.io/sv3/180_hires.png"}','G','60',NULL,'["Basic"]','["Colorless"]',NULL,'["Oinkologne"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[915]',NULL,NULL,'sv3');
