INSERT INTO "Card" VALUES('sv3-204','Houndour','Pokémon','204','Illustration Rare','KYUPIYAMA','It is smart enough to hunt in packs. It uses a variety of cries for communicating with others.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3/204.png","large":"https://images.pokemontcg.io/sv3/204_hires.png"}','G','50',NULL,'["Basic"]','["Darkness"]',NULL,'["Houndoom"]',NULL,'[{"name":"Coordinated Pack","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"For each of your Benched Houndour, search your deck for a Basic Darkness Energy card and attach it to that Houndour. Then, shuffle your deck."},{"name":"Focus Fangs","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[228]',NULL,NULL,'sv3');
