INSERT INTO "Card" VALUES('sv3pt5-39','Jigglypuff','Pokémon','39','Common','saino misaki','When its huge eyes waver, it sings a mysteriously soothing melody that lulls its enemies to sleep.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3pt5/39.png","large":"https://images.pokemontcg.io/sv3pt5/39_hires.png"}','G','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Wigglytuff"]',NULL,'[{"name":"Lead","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Stompy Stomp","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 2 coins. This attack does 20 damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[39]',NULL,NULL,'sv3pt5');
