INSERT INTO "Card" VALUES('sv3pt5-94','Gengar','Pokémon','94','Rare','Tomokazu Komiya','To steal the life of its target, it slips into the prey''s shadow and silently waits for an opportunity.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3pt5/94.png","large":"https://images.pokemontcg.io/sv3pt5/94_hires.png"}','G','130',NULL,'["Stage 2"]','["Psychic"]','Haunter',NULL,NULL,'[{"name":"Poltergeist","cost":["Psychic"],"convertedEnergyCost":1,"damage":"50×","text":"Your opponent reveals their hand. This attack does 50 damage for each Trainer card you find there."},{"name":"Hollow Dive","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"110","text":"Put 3 damage counters on your opponent''s Benched Pokémon in any way you like."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[94]',NULL,NULL,'sv3pt5');
