INSERT INTO "Card" VALUES('sv3pt5-104','Cubone','Pokémon','104','Common','Shinya Komatsu','This Pokémon wears the skull of its deceased mother. Sometimes Cubone''s dreams make it cry, but each tear Cubone sheds makes it stronger.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3pt5/104.png","large":"https://images.pokemontcg.io/sv3pt5/104_hires.png"}','G','70',NULL,'["Basic"]','["Fighting"]',NULL,'["Marowak"]','[{"name":"Cheering Bone","text":"As long as this Pokémon is on your Bench, attacks used by your Marowak do 30 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Hit Twice","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 2 coins. This attack does 10 damage for each heads."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[104]',NULL,NULL,'sv3pt5');
