INSERT INTO "Card" VALUES('sv3pt5-147','Dratini','Pokémon','147','Common','Sanosuke Sakuma','It sheds many layers of skin as it grows larger. During this process, it is protected by a rapid waterfall.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv3pt5/147.png","large":"https://images.pokemontcg.io/sv3pt5/147_hires.png"}','G','60',NULL,'["Basic"]','["Dragon"]',NULL,'["Dragonair"]',NULL,'[{"name":"Beat","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Draconic Whip","cost":["Water","Lightning"],"convertedEnergyCost":2,"damage":"40","text":""}]',NULL,NULL,'["Colorless"]',1,'[147]',NULL,NULL,'sv3pt5');
