INSERT INTO "Card" VALUES('sv4-1','Surskit','Pokémon','1','Common','Yoriyuki Ikegami','It secretes a thick, sweet-scented syrup from the tip of its head. It lives on weed-choked ponds.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/1.png","large":"https://images.pokemontcg.io/sv4/1_hires.png"}','G','50',NULL,'["Basic"]','["Grass"]',NULL,'["Masquerain"]',NULL,'[{"name":"Triple Spin","cost":["Grass"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 3 coins. This attack does 10 damage for each heads."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[283]',NULL,NULL,'sv4');
INSERT INTO "Card" VALUES('sv4-2','Masquerain','Pokémon','2','Uncommon','kantaro','The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/2.png","large":"https://images.pokemontcg.io/sv4/2_hires.png"}','G','100',NULL,'["Stage 1"]','["Grass"]','Surskit',NULL,NULL,'[{"name":"Daunting Eyes","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin until you get tails. For each heads, shuffle an Energy attached to your opponent''s Active Pokémon into their deck."},{"name":"Cutting Wind","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"70","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[284]',NULL,NULL,'sv4');
