INSERT INTO "Card" VALUES('sv4-8','Bounsweet','Pokémon','8','Common','Kouki Saitou','Its sweat is sweet, like syrup made from boiled- down fruit. Because of this, Bounsweet was highly valued in the past, when sweeteners were scarce.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/8.png","large":"https://images.pokemontcg.io/sv4/8_hires.png"}','G','60',NULL,'["Basic"]','["Grass"]',NULL,'["Steenee"]',NULL,'[{"name":"Quick Blow","cost":["Grass"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 20 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[761]',NULL,NULL,'sv4');
