INSERT INTO "Card" VALUES('sv4-20','Pansear','Pokémon','20','Common','LINNE','This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/20.png","large":"https://images.pokemontcg.io/sv4/20_hires.png"}','G','70',NULL,'["Basic"]','["Fire"]',NULL,'["Simisear"]',NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck."},{"name":"Searing Flame","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20","text":"Your opponent''s Active Pokémon is now Burned."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[513]',NULL,NULL,'sv4');
