INSERT INTO "Card" VALUES('sv4-24','Crocalor','Pokémon','24','Uncommon','Pani Kobayashi','The combination of Crocalor''s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon''s head.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/24.png","large":"https://images.pokemontcg.io/sv4/24_hires.png"}','G','100',NULL,'["Stage 1"]','["Fire"]','Fuecoco',NULL,NULL,'[{"name":"Rolling Fireball","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"90","text":"Put an Energy attached to this Pokémon into your hand."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[910]',NULL,NULL,'sv4');
INSERT INTO "Card" VALUES('sv4-25','Charcadet','Pokémon','25','Common','kantaro','Burnt charcoal came to life and became a Pokémon. Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/25.png","large":"https://images.pokemontcg.io/sv4/25_hires.png"}','G','60',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Protect","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."},{"name":"Magma Punch","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[935]',NULL,NULL,'sv4');
