INSERT INTO "Card" VALUES('sv4-41','Panpour','Pokémon','41','Common','Natsumi Yoshida','The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/41.png","large":"https://images.pokemontcg.io/sv4/41_hires.png"}','G','70',NULL,'["Basic"]','["Water"]',NULL,'["Simipour"]',NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck."},{"name":"Water Pulse","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":"Your opponent''s Active Pokémon is now Asleep."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[515]',NULL,NULL,'sv4');
