INSERT INTO "Card" VALUES('sv4-43','Vanillite','Pokémon','43','Common','miki kudo','Supposedly, this Pokémon was born from an icicle. It spews out freezing air at −58 degrees Fahrenheit to make itself more comfortable.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/43.png","large":"https://images.pokemontcg.io/sv4/43_hires.png"}','G','60',NULL,'["Basic"]','["Water"]',NULL,'["Vanillish"]',NULL,'[{"name":"Chilly","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"40","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[582]',NULL,NULL,'sv4');
INSERT INTO "Card" VALUES('sv4-44','Vanillish','Pokémon','44','Common','Lee HyunJung','It blasts enemies with cold air reaching −148 degrees Fahrenheit, freezing them solid. But it spares their lives afterward—it''s a kind Pokémon.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/44.png","large":"https://images.pokemontcg.io/sv4/44_hires.png"}','G','90',NULL,'["Stage 1"]','["Water"]','Vanillite','["Vanilluxe"]',NULL,'[{"name":"Frost Smash","cost":["Water","Water"],"convertedEnergyCost":2,"damage":"60","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[583]',NULL,NULL,'sv4');
