INSERT INTO "Card" VALUES('sv4-49','Golisopod','Pokémon','49','Rare','nagimiso','They live in sunken ships or in holes in the seabed. When Golisopod and Grapploct battle, the loser becomes the winner''s meal.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/49.png","large":"https://images.pokemontcg.io/sv4/49_hires.png"}','G','140',NULL,'["Stage 1"]','["Water"]','Wimpod',NULL,NULL,'[{"name":"Powerful Cross","cost":["Water"],"convertedEnergyCost":1,"damage":"20×","text":"This attack does 20 damage for each card in your opponent''s hand."},{"name":"Waterfall","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"130","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[768]',NULL,NULL,'sv4');
