INSERT INTO "Card" VALUES('sv4-62','Blitzle','Pokémon','62','Common','Shinji Kanda','Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/62.png","large":"https://images.pokemontcg.io/sv4/62_hires.png"}','G','60',NULL,'["Basic"]','["Lightning"]',NULL,'["Zebstrika"]',NULL,'[{"name":"Rear Kick","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Wild Charge","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"This Pokémon also does 20 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[522]',NULL,NULL,'sv4');
