INSERT INTO "Card" VALUES('sv4-67','Oricorio','Pokémon','67','Common','Saya Tsuruta','The energetic, cheerful dance of these Oricorio is popular with children, but the Oricorio themselves are hard to find in Paldea.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/67.png","large":"https://images.pokemontcg.io/sv4/67_hires.png"}','G','90',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Pep Up","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Shuffle your hand into your deck. Then, draw a card for each Benched Pokémon (both yours and your opponent''s)."},{"name":"Volt Wave","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[741]',NULL,NULL,'sv4');
