INSERT INTO "Card" VALUES('sv4-78','Gourgeist','Pokémon','78','Uncommon','nisimono','In the darkness of a new-moon night, Gourgeist will come knocking. Whoever answers the door will be swept off to the afterlife.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/78.png","large":"https://images.pokemontcg.io/sv4/78_hires.png"}','G','110',NULL,'["Stage 1"]','["Psychic"]','Pumpkaboo',NULL,'[{"name":"Startling Pumpkin","text":"If this Pokémon is Knocked Out by damage from an attack from your opponent''s Pokémon, discard 2 random cards from your opponent''s hand.","type":"Ability"}]','[{"name":"Shadow Bind","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"During your opponent''s next turn, the Defending Pokémon can''t retreat."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[711]',NULL,NULL,'sv4');
