INSERT INTO "Card" VALUES('sv4-206','Morpeko','Pokémon','206','Illustration Rare','Yuu Nishida','Hunger hormones affect its temperament. Until its hunger is appeased, it gets up to all manner of evil deeds.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/206.png","large":"https://images.pokemontcg.io/sv4/206_hires.png"}','G','70',NULL,'["Basic"]','["Darkness"]',NULL,NULL,'[{"name":"In a Hungry Hurry","text":"If this Pokémon has no Energy attached, it has no Retreat Cost.","type":"Ability"}]','[{"name":"Energizer Wheel","cost":["Darkness","Darkness"],"convertedEnergyCost":2,"damage":"70","text":"Move 2 Darkness Energy from this Pokémon to 1 of your Benched Pokémon."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[877]',NULL,NULL,'sv4');
