INSERT INTO "Card" VALUES('sv4-266','Reversal Energy','Energy','266','Hyper Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4/266.png","large":"https://images.pokemontcg.io/sv4/266_hires.png"}','G',NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides Colorless Energy.    If you have more Prize cards remaining than your opponent, and if this card is attached to an Evolution Pokémon that doesn''t have a Rule Box (Pokémon ex, Pokémon V, etc. have Rule Boxes), this card provides every type of Energy but provides only 3 Energy at a time."]','sv4');
INSERT INTO "Card" VALUES('sv4pt5-1','Pineco','Pokémon','1','Common','Kouki Saitou','It likes to make its shell thicker by adding layers of tree bark. The additional weight doesn''t bother it.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/1.png","large":"https://images.pokemontcg.io/sv4pt5/1_hires.png"}','G','70',NULL,'["Basic"]','["Grass"]',NULL,'["Forretress"]',NULL,'[{"name":"Rollout","cost":["Grass","Grass"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[204]',NULL,NULL,'sv4pt5');
