INSERT INTO "Card" VALUES('sv4pt5-7','Charmander','Pokémon','7','Common','GIDORA','From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/7.png","large":"https://images.pokemontcg.io/sv4pt5/7_hires.png"}','G','70',NULL,'["Basic"]','["Fire"]',NULL,'["Charmeleon"]',NULL,'[{"name":"Blazing Destruction","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Discard a Stadium in play."},{"name":"Steady Firebreathing","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[4]',NULL,NULL,'sv4pt5');
