INSERT INTO "Card" VALUES('sv4pt5-41','Flittle','Pokémon','41','Common','kawayoo','Flittle''s toes levitate about half an inch above the ground because of the psychic power emitted from the frills on the Pokémon''s belly.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/41.png","large":"https://images.pokemontcg.io/sv4pt5/41_hires.png"}','G','30',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Psy Bolt","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[955]',NULL,NULL,'sv4pt5');
INSERT INTO "Card" VALUES('sv4pt5-42','Greavard','Pokémon','42','Common','yuu','This friendly Pokémon doesn''t like being alone. Pay it even the slightest bit of attention, and it will follow you forever.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/42.png","large":"https://images.pokemontcg.io/sv4pt5/42_hires.png"}','G','70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Graveyard Gamboling","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10×","text":"This attack does 10 damage for each Psychic Pokémon in your discard pile."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[971]',NULL,NULL,'sv4pt5');
