INSERT INTO "Card" VALUES('sv4pt5-79','Electric Generator','Trainer','79','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/79.png","large":"https://images.pokemontcg.io/sv4pt5/79_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 5 cards of your deck and attach up to 2 Basic Lightning Energy cards you find there to your Benched Lightning Pokémon in any way you like. Shuffle the other cards back into your deck.","You may play any number of Item cards during your turn."]','sv4pt5');
