INSERT INTO "Card" VALUES('sv4pt5-81','Moonlit Hill','Trainer','81','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/81.png","large":"https://images.pokemontcg.io/sv4pt5/81_hires.png"}','G',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard a Basic Psychic Energy card from their hand in order to heal 30 damage from each of their Pokémon.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv4pt5');
