INSERT INTO "Card" VALUES('sv4pt5-89','Rare Candy','Trainer','89','Common','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/89.png","large":"https://images.pokemontcg.io/sv4pt5/89_hires.png"}','G',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card onto the Basic Pokémon to evolve it, skipping the Stage 1. You can''t use this card during your first turn or on a Basic Pokémon that was put into play this turn.","You may play any number of Item cards during your turn."]','sv4pt5');
INSERT INTO "Card" VALUES('sv4pt5-90','Technical Machine: Crisis Punch','Trainer','90','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/90.png","large":"https://images.pokemontcg.io/sv4pt5/90_hires.png"}','G',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,'[{"name":"Crisis Punch","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"280","text":"You can use this attack only when your opponent has exactly 1 Prize card remaining."}]',NULL,NULL,NULL,NULL,NULL,NULL,'["The Pokémon this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.) If this card is attached to 1 of your Pokémon, discard it at the end of your turn.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','sv4pt5');
