INSERT INTO "Card" VALUES('sv4pt5-111','Paldean Tauros','Pokémon','111','Shiny Rare','Hitoshi Ariga','People call this kind of Tauros the Blaze Breed due to the hot air it snorts from its nostrils. Its three tails are intertwined.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/111.png","large":"https://images.pokemontcg.io/sv4pt5/111_hires.png"}','G','130',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Raging Horns","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"This attack does 10 more damage for each damage counter on this Pokémon."},{"name":"Blaze Dash","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"120","text":"Discard an Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[128]',NULL,NULL,'sv4pt5');
