INSERT INTO "Card" VALUES('sv4pt5-138','Pachirisu','Pokémon','138','Shiny Rare','saino misaki','A pair may be seen rubbing their cheek pouches together in an effort to share stored electricity.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/138.png","large":"https://images.pokemontcg.io/sv4pt5/138_hires.png"}','G','70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,'[{"name":"Electricity Pouches","text":"This Pokémon can''t be Paralyzed.","type":"Ability"}]','[{"name":"Everyone Discharge","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"This attack does 20 more damage for each of your Benched Lightning Pokémon. This attack''s damage isn''t affected by Weakness."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[417]',NULL,NULL,'sv4pt5');
