INSERT INTO "Card" VALUES('sv4pt5-140','Toxel','Pokémon','140','Shiny Rare','Lee HyunJung','It has no problem drinking dirty water. An organ inside Toxel''s body filters such water into a poisonous liquid that is harmless to Toxel.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/140.png","large":"https://images.pokemontcg.io/sv4pt5/140_hires.png"}','G','70',NULL,'["Basic"]','["Lightning"]',NULL,'["Toxtricity"]',NULL,'[{"name":"Slight Intrusion","cost":["Lightning"],"convertedEnergyCost":1,"damage":"30","text":"This Pokémon also does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[848]',NULL,NULL,'sv4pt5');
