INSERT INTO "Card" VALUES('sv4pt5-142','Pawmi','Pokémon','142','Shiny Rare','kurumitsu','The pads of its paws are electricity-discharging organs. Pawmi fires electricity from its forepaws while standing unsteadily on its hind legs.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/142.png","large":"https://images.pokemontcg.io/sv4pt5/142_hires.png"}','G','60',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Light Punch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Zap Kick","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[921]',NULL,NULL,'sv4pt5');
