INSERT INTO "Card" VALUES('sv4pt5-157','Mime Jr.','Pokémon','157','Shiny Rare','Saya Tsuruta','In an attempt to confuse its enemy, it mimics the enemy''s movements. Then it wastes no time in making itself scarce!','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv4pt5/157.png","large":"https://images.pokemontcg.io/sv4pt5/157_hires.png"}','G','30',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Mimed Games","cost":[],"convertedEnergyCost":0,"damage":"","text":"Your opponent chooses an attack from 1 of their Pokémon in play. Use the chosen attack as this attack."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]',NULL,NULL,'[439]',NULL,NULL,'sv4pt5');
