INSERT INTO "Card" VALUES('sv5-121','Miraidon','Pokémon','121','Rare','GOSSAN','This seems to be the Iron Serpent mentioned in an old book. The Iron Serpent is said to have turned the land to ash with its lightning.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv5/121.png","large":"https://images.pokemontcg.io/sv5/121_hires.png"}','H','110',NULL,'["Basic","Future"]','["Dragon"]',NULL,NULL,NULL,'[{"name":"Peak Acceleration","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":"Search your deck for up to 2 Basic Energy cards and attach them to your Future Pokémon in any way you like. Then, shuffle your deck."},{"name":"Sparking Strike","cost":["Lightning","Lightning","Psychic"],"convertedEnergyCost":3,"damage":"160","text":""}]',NULL,NULL,'["Colorless","Colorless"]',2,'[1008]',NULL,NULL,'sv5');
