INSERT INTO "Card" VALUES('sv6-2','Tangrowth','Pokémon','2','Common','LINNE','Tangrowth has two arms that it can extend as it pleases. Recent research has shown that these arms are, in fact, bundles of vines.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/2.png","large":"https://images.pokemontcg.io/sv6/2_hires.png"}','H','150',NULL,'["Stage 1"]','["Grass"]','Tangela',NULL,'[{"name":"Thicket Body","text":"This Pokémon takes 30 less damage from attacks (after applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Loom Over","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"150-","text":"This attack does 10 less damage for each damage counter on this Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[465]',NULL,NULL,'sv6');
