INSERT INTO "Card" VALUES('sv6-6','Sunkern','Pokémon','6','Common','Naoyo Kimura','It is very weak. Its only means of defense is to shake its leaves desperately at its attacker.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/6.png","large":"https://images.pokemontcg.io/sv6/6_hires.png"}','H','40',NULL,'["Basic"]','["Grass"]',NULL,'["Sunflora"]',NULL,'[{"name":"Bullet Seed","cost":["Grass"],"convertedEnergyCost":1,"damage":"10×","text":"Flip 4 coins. This attack does 10 damage for each heads."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[191]',NULL,NULL,'sv6');
