INSERT INTO "Card" VALUES('sv6-9','Volbeat','Pokémon','9','Common','Orca','It flashes the light on its rear to communicate with other Volbeat. It loves the sweet aroma given off by Illumise.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/9.png","large":"https://images.pokemontcg.io/sv6/9_hires.png"}','H','70',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Quick Sign","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If you go first, you can use this attack during your first turn. Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck."},{"name":"Coordinated Strike","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"If Illumise is on your Bench, this attack does 60 more damage."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[313]',NULL,NULL,'sv6');
