INSERT INTO "Card" VALUES('sv6-95','Munkidori','Pokémon','95','Rare','kodama','Munkidori keeps itself somewhere safe while it toys with its foes, using psychokinesis to induce intense dizziness.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/95.png","large":"https://images.pokemontcg.io/sv6/95_hires.png"}','H','110',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Adrena-Brain","text":"Once during your turn, if this Pokémon has any Darkness Energy attached, you may move up to 3 damage counters from 1 of your Pokémon to 1 of your opponent''s Pokémon.","type":"Ability"}]','[{"name":"Mind Bend","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"Your opponent''s Active Pokémon is now Confused."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[1015]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-96','Fezandipiti','Pokémon','96','Rare','Kouki Saitou','Fezandipiti beats its glossy wings to scatter pheromones that captivate people and Pokémon.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/96.png","large":"https://images.pokemontcg.io/sv6/96_hires.png"}','H','120',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Adrena-Pheromone","text":"If this Pokémon has any Darkness Energy attached and is damaged by an attack, flip a coin. If heads, prevent that damage.","type":"Ability"}]','[{"name":"Energy Feather","cost":["Psychic"],"convertedEnergyCost":1,"damage":"30×","text":"This attack does 30 damage for each Energy attached to this Pokémon."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[1016]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-97','Sandshrew','Pokémon','97','Common','Tetsu Kayama','No matter how high a place it falls from, this Pokémon can save itself by rolling into a ball and bouncing.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/97.png","large":"https://images.pokemontcg.io/sv6/97_hires.png"}','H','60',NULL,'["Basic"]','["Fighting"]',NULL,'["Sandslash"]',NULL,'[{"name":"Rollout","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Double Scratch","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 2 coins. This attack does 20 damage for each heads."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[27]',NULL,NULL,'sv6');
