INSERT INTO "Card" VALUES('sv6-113','Poochyena','Pokémon','113','Common','Shibuzoh.','Poochyena pursue their prey in packs. Once the prey is exhausted, the pack finishes it off. But sometimes the prey retaliates, and the pack flees.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/113.png","large":"https://images.pokemontcg.io/sv6/113_hires.png"}','H','70',NULL,'["Basic"]','["Darkness"]',NULL,'["Mightyena"]',NULL,'[{"name":"Continuous Steps","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10×","text":"Flip a coin until you get tails. This attack does 10 damage for each heads."},{"name":"Darkness Fang","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[261]',NULL,NULL,'sv6');
