INSERT INTO "Card" VALUES('sv6-135','Eevee','Pokémon','135','Common','satoma','Its genetic code is irregular. It may mutate if it is exposed to radiation from element stones.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/135.png","large":"https://images.pokemontcg.io/sv6/135_hires.png"}','H','50',NULL,'["Basic"]','["Colorless"]',NULL,'["Vaporeon","Jolteon","Flareon","Sylveon","Espeon","Umbreon","Leafeon","Glaceon"]',NULL,'[{"name":"Ascension","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a card that evolves from this Pokémon and put it onto this Pokémon to evolve it. Then, shuffle your deck."},{"name":"Quick Attack","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[133]',NULL,NULL,'sv6');
