INSERT INTO "Card" VALUES('sv6-138','Ambipom','Pokémon','138','Uncommon','KEIICHIRO ITO','Split into two, the tails are so adept at handling and doing things that Ambipom rarely uses its hands.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/138.png","large":"https://images.pokemontcg.io/sv6/138_hires.png"}','H','110',NULL,'["Stage 1"]','["Colorless"]','Aipom',NULL,'[{"name":"Wicked Tail","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may flip 2 coins. For each heads, choose a random card from your opponent''s hand. Your opponent reveals those cards and shuffles them into their deck.","type":"Ability"}]','[{"name":"Gentle Slap","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[424]',NULL,NULL,'sv6');
