INSERT INTO "Card" VALUES('sv6-153','Jamming Tower','Trainer','153','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/153.png","large":"https://images.pokemontcg.io/sv6/153_hires.png"}','H',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Pokémon Tools attached to each Pokémon (both yours and your opponent''s) have no effect.","You may play only 1 Stadium card during your turn. Put it into the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv6');
INSERT INTO "Card" VALUES('sv6-154','Kieran','Trainer','154','Uncommon','GIDORA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/154.png","large":"https://images.pokemontcg.io/sv6/154_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1:    • Switch your Active Pokémon with 1 of your Benched Pokémon.  • During this turn, attacks used by your Pokémon do 30 more damage to your opponent''s Active Pokémon ex and Active Pokémon V (before applying Weakness and Resistance).","You may play only 1 Supporter card during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-155','Lana''s Aid','Trainer','155','Uncommon','Atsushi Furusawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/155.png","large":"https://images.pokemontcg.io/sv6/155_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put up to 3 in any combination of Pokémon that don''t have a Rule Box and Basic Energy cards from your discard pile into your hand. (Pokémon ex, Pokémon V, etc. have Rule Boxes.)","You may play only 1 Supporter card during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-156','Love Ball','Trainer','156','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/156.png","large":"https://images.pokemontcg.io/sv6/156_hires.png"}','H',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon with the same name as 1 of your opponent''s Pokémon in play, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-157','Lucian','Trainer','157','Uncommon','hncl',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/157.png","large":"https://images.pokemontcg.io/sv6/157_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, each player flips a coin. If heads, that player draws 6 cards. If tails, they draw 3 cards.","You may play only 1 Supporter card during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-158','Lucky Helmet','Trainer','158','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/158.png","large":"https://images.pokemontcg.io/sv6/158_hires.png"}','H',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["If the Pokémon this card is attached to is in the Active Spot and is damaged by an attack from your opponent''s Pokémon (even if this Pokémon is Knocked Out), draw 2 cards.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached.","Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached."]','sv6');
INSERT INTO "Card" VALUES('sv6-159','Ogre''s Mask','Trainer','159','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/159.png","large":"https://images.pokemontcg.io/sv6/159_hires.png"}','H',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a Pokémon ex in your discard pile that has \"Ogerpon\" in its name, and switch it with 1 of your Pokémon ex in play that has \"Ogerpon\" in its name. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.","You may play any number of Item cards during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-160','Perrin','Trainer','160','Uncommon','Naoki Saito',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/160.png","large":"https://images.pokemontcg.io/sv6/160_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal up to 2 Pokémon in your hand and put them into your deck. If you do, search your deck for up to that many Pokémon, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-161','Raifort','Trainer','161','Uncommon','hncl',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/161.png","large":"https://images.pokemontcg.io/sv6/161_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 5 cards of your deck and discard any number of them. Put the other cards back in any order.","You may play only 1 Supporter card during your turn."]','sv6');
INSERT INTO "Card" VALUES('sv6-162','Scoop Up Cyclone','Trainer','162','ACE SPEC Rare','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/162.png","large":"https://images.pokemontcg.io/sv6/162_hires.png"}','H',NULL,NULL,'["Item","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","Put 1 of your Pokémon and all attached cards into your hand.","You may play any number of Item cards during your turn.","ACE SPEC: You can''t have more than 1 ACE SPEC card in your deck."]','sv6');
INSERT INTO "Card" VALUES('sv6-163','Secret Box','Trainer','163','ACE SPEC Rare','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/163.png","large":"https://images.pokemontcg.io/sv6/163_hires.png"}','H',NULL,NULL,'["Item","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","You can use this card only if you discard 3 other cards from your hand.    Search your deck for an Item card, a Pokémon Tool card, a Supporter card, and a Stadium card, reveal them, and put them into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn.","ACE SPEC: You can''t have more than 1 ACE SPEC card in your deck."]','sv6');
INSERT INTO "Card" VALUES('sv6-164','Survival Brace','Trainer','164','ACE SPEC Rare','inose yukie',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/164.png","large":"https://images.pokemontcg.io/sv6/164_hires.png"}','H',NULL,NULL,'["Pokémon Tool","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","If the Pokémon this card is attached to has full HP and would be Knocked Out by damage from an attack from your opponent''s Pokémon, it is not Knocked Out, and its remaining HP becomes 10. Then, discard this card.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached.","Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached.","ACE SPEC: You can''t have more than 1 ACE SPEC card in your deck."]','sv6');
INSERT INTO "Card" VALUES('sv6-165','Unfair Stamp','Trainer','165','ACE SPEC Rare','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/165.png","large":"https://images.pokemontcg.io/sv6/165_hires.png"}','H',NULL,NULL,'["Item","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","You can use this card only if any of your Pokémon were Knocked Out during your opponent''s last turn.    Each player shuffles their hand into their deck. Then, you draw 5 cards, and your opponent draws 2 cards.","You may play any number of Item cards during your turn.","ACE SPEC: You can''t have more than 1 ACE SPEC card in your deck."]','sv6');
INSERT INTO "Card" VALUES('sv6-166','Boomerang Energy','Energy','166','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/166.png","large":"https://images.pokemontcg.io/sv6/166_hires.png"}','H',NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon, it provides Colorless Energy.    If this card is discarded by an effect of an attack used by the Pokémon this card is attached to, attach this card from your discard pile to that Pokémon after attacking."]','sv6');
INSERT INTO "Card" VALUES('sv6-167','Legacy Energy','Energy','167','ACE SPEC Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/167.png","large":"https://images.pokemontcg.io/sv6/167_hires.png"}','H',NULL,NULL,'["Special","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","As long as this card is attached to a Pokémon, it provides every type of Energy but provides only 1 Energy at a time.    If the Pokémon this card is attached to is Knocked Out by damage from an attack from your opponent''s Pokémon, that player takes 1 fewer Prize card. This effect of your Legacy Energy can''t be applied more than once per game.","ACE SPEC: You can''t have more than 1 ACE SPEC card in your deck."]','sv6');
INSERT INTO "Card" VALUES('sv6-168','Pinsir','Pokémon','168','Illustration Rare','Yukihiro Tada','These Pokémon judge one another based on pincers. Thicker, more impressive pincers make for more popularity with the opposite gender.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/168.png","large":"https://images.pokemontcg.io/sv6/168_hires.png"}','H','110',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Slow Crunch","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Discard all Energy from this Pokémon. At the end of your opponent''s next turn, the Defending Pokémon will be Knocked Out."},{"name":"Superpowered Horns","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[127]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-169','Sunflora','Pokémon','169','Illustration Rare','Shinya Komatsu','Since it converts sunlight into energy, it is always looking in the direction of the sun.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/169.png","large":"https://images.pokemontcg.io/sv6/169_hires.png"}','H','100',NULL,'["Stage 1"]','["Grass"]','Sunkern',NULL,NULL,'[{"name":"Redirected Sunlight","cost":["Grass"],"convertedEnergyCost":1,"damage":"60×","text":"This attack does 60 damage for each Fire Energy attached to all of your opponent''s Pokémon."},{"name":"Mega Drain","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"Heal 30 damage from this Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[192]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-170','Dipplin','Pokémon','170','Illustration Rare','Akira Komayama','The head sticking out belongs to the fore-wyrm, while the tail belongs to the core-wyrm. The two share one apple and help each other out.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/170.png","large":"https://images.pokemontcg.io/sv6/170_hires.png"}','H','80',NULL,'["Stage 1"]','["Grass"]','Applin',NULL,'[{"name":"Festival Lead","text":"If Festival Grounds is in play, this Pokémon may use an attack it has twice. If the first attack Knocks Out your opponent''s Active Pokémon, you may attack again after your opponent chooses a new Active Pokémon.","type":"Ability"}]','[{"name":"Do the Wave","cost":["Grass"],"convertedEnergyCost":1,"damage":"20×","text":"This attack does 20 damage for each of your Benched Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[1011]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-171','Poltchageist','Pokémon','171','Illustration Rare','Saboteri','Poltchageist looks like a regional form of Sinistea, but it was recently discovered that the two Pokémon are entirely unrelated.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/171.png","large":"https://images.pokemontcg.io/sv6/171_hires.png"}','H','30',NULL,'["Basic"]','["Grass"]',NULL,NULL,'[{"name":"Storehouse Hideaway","text":"As long as this Pokémon is on your Bench, prevent all damage from and effects of attacks from your opponent''s Pokémon done to this Pokémon.","type":"Ability"}]','[{"name":"Hook","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[1012]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-172','Torkoal','Pokémon','172','Illustration Rare','Masa','Coal is the source of Torkoal''s energy. Large amounts of coal can be found in the mountains where they live.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/172.png","large":"https://images.pokemontcg.io/sv6/172_hires.png"}','H','130',NULL,'["Basic"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Ramming Shell","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"During your opponent''s next turn, this Pokémon takes 30 less damage from attacks (after applying Weakness and Resistance)."},{"name":"Fire Spin","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"110","text":"Discard 2 Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[324]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-173','Infernape','Pokémon','173','Illustration Rare','Krgc','Its crown of fire is indicative of its fiery nature. It is beaten by none in terms of quickness.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/173.png","large":"https://images.pokemontcg.io/sv6/173_hires.png"}','H','140',NULL,'["Stage 2"]','["Fire"]','Monferno',NULL,'[{"name":"Pyro Dance","text":"Once during your turn, you may attach a Basic Fire Energy card, a Basic Fighting Energy card, or 1 of each from your hand to your Pokémon in any way you like.","type":"Ability"}]','[{"name":"Scorching Fire","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"200","text":"Discard an Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[392]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-174','Froslass','Pokémon','174','Illustration Rare','matazo','It freezes prey by blowing its −58 degree Fahrenheit breath. It is said to then secretly display its prey.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/174.png","large":"https://images.pokemontcg.io/sv6/174_hires.png"}','H','90',NULL,'["Stage 1"]','["Water"]','Snorunt',NULL,'[{"name":"Freezing Shroud","text":"During Pokémon Checkup, put 1 damage counter on each Pokémon that has an Ability (both yours and your opponent''s), except any Froslass.","type":"Ability"}]','[{"name":"Frost Smash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"60","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[478]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-175','Phione','Pokémon','175','Illustration Rare','takashi shiraishi','When the water warms, they inflate the flotation sac on their heads and drift languidly on the sea in packs.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/175.png","large":"https://images.pokemontcg.io/sv6/175_hires.png"}','H','70',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Beckon","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Put a Supporter card from your discard pile into your hand."},{"name":"Energy Press","cost":["Water"],"convertedEnergyCost":1,"damage":"20×","text":"This attack does 20 damage for each Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[489]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-176','Cramorant','Pokémon','176','Illustration Rare','Fujimoto Gold','It''s an incredibly poor learner because it uses the bare minimum amount of energy for its brain. It focuses on battling instead.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/176.png","large":"https://images.pokemontcg.io/sv6/176_hires.png"}','H','110',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Water Gun","cost":["Water"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Spit Shot","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard all Energy from this Pokémon. This attack does 120 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[845]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-177','Heliolisk','Pokémon','177','Illustration Rare','Tonji Matsuno','A now-vanished desert culture treasured these Pokémon. Appropriately, when Heliolisk came to the Galar region, treasure came with them.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/177.png","large":"https://images.pokemontcg.io/sv6/177_hires.png"}','H','100',NULL,'["Stage 1"]','["Lightning"]','Helioptile',NULL,NULL,'[{"name":"Wild Charge","cost":["Lightning"],"convertedEnergyCost":1,"damage":"70","text":"This Pokémon also does 20 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[695]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-178','Wattrel','Pokémon','178','Illustration Rare','Mitsuhiro Arita','These Pokémon make their nests on coastal cliffs. The nests have a strange, crackling texture, and they''re a popular delicacy.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/178.png","large":"https://images.pokemontcg.io/sv6/178_hires.png"}','H','60',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Thunder Shock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[940]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-179','Chimecho','Pokémon','179','Illustration Rare','REND','Its cries echo inside its hollow body to emerge as beautiful notes for startling and repelling foes.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/179.png","large":"https://images.pokemontcg.io/sv6/179_hires.png"}','H','70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Hyper Voice","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Homeward Chime","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Shuffle 1 of your Benched Pokémon and all attached cards into your deck."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[358]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-180','Enamorus','Pokémon','180','Illustration Rare','GOTO minori','When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/180.png","large":"https://images.pokemontcg.io/sv6/180_hires.png"}','H','120',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Heart Sign","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":""},{"name":"Love Resonance","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80+","text":"If any of your Pokémon in play are the same type as any of your opponent''s Pokémon in play, this attack does 120 more damage."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[905]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-181','Hisuian Growlithe','Pokémon','181','Illustration Rare','GIDORA','They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/181.png","large":"https://images.pokemontcg.io/sv6/181_hires.png"}','H','80',NULL,'["Basic"]','["Fighting"]',NULL,'["Arcanine"]',NULL,'[{"name":"Blazing Destruction","cost":[],"convertedEnergyCost":0,"damage":"","text":"Discard a Stadium in play."},{"name":"Take Down","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40","text":"This Pokémon also does 10 damage to itself."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[58]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-182','Probopass','Pokémon','182','Illustration Rare','Kariya','Probopass radiates such a powerful magnetic field that nearby electrical appliances are rendered useless while it''s around.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/182.png","large":"https://images.pokemontcg.io/sv6/182_hires.png"}','H','140',NULL,'["Stage 1"]','["Fighting"]','Nosepass',NULL,NULL,'[{"name":"Assault Laser","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80+","text":"If your opponent''s Active Pokémon has a Pokémon Tool attached, this attack does 80 more damage."},{"name":"Land Crush","cost":["Fighting","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"120","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[476]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-183','Timburr','Pokémon','183','Illustration Rare','Yuriko Akase','It fights by swinging a piece of lumber around. It is close to evolving when it can handle heavy lumber without difficulty.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/183.png","large":"https://images.pokemontcg.io/sv6/183_hires.png"}','H','80',NULL,'["Basic"]','["Fighting"]',NULL,'["Gurdurr"]',NULL,'[{"name":"Best Punch","cost":["Fighting"],"convertedEnergyCost":1,"damage":"40","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[532]',NULL,NULL,'sv6');
INSERT INTO "Card" VALUES('sv6-184','Lairon','Pokémon','184','Illustration Rare','Dsuke','Lairon live in mountains brimming with spring water and iron ore, so these Pokémon often came into conflict with humans in the past.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv6/184.png","large":"https://images.pokemontcg.io/sv6/184_hires.png"}','H','110',NULL,'["Stage 1"]','["Metal"]','Aron','["Aggron"]',NULL,'[{"name":"Steel Tackle","cost":["Metal"],"convertedEnergyCost":1,"damage":"40","text":"This Pokémon also does 20 damage to itself."},{"name":"Metal Claw","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[305]',NULL,NULL,'sv6');
