INSERT INTO "Card" VALUES('sv7-128','Terapagos ex','Pokémon','128','Double Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/128.png","large":"https://images.pokemontcg.io/sv7/128_hires.png"}','H','230',NULL,'["Basic","Tera","ex"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Unified Beatdown","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30×","text":"If you go second, you can''t use this attack during your first turn. This attack does 30 damage for each of your Benched Pokémon."},{"name":"Crown Opal","cost":["Grass","Water","Lightning"],"convertedEnergyCost":3,"damage":"180","text":"During your opponent''s next turn, prevent all damage done to this Pokémon by attacks from Basic non-Colorless Pokémon."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[1024]',NULL,'["As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent''s).","Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards."]','sv7');
INSERT INTO "Card" VALUES('sv7-129','Antique Cover Fossil','Trainer','129','Common',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/129.png","large":"https://images.pokemontcg.io/sv7/129_hires.png"}','H','60',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Protective Cover","text":"Prevent all effects of attacks used by your opponent''s Pokémon done to this Pokémon. (Damage is not an effect.)","type":"Ability"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play this card as if it were a 60-HP Basic Colorless Pokémon. This card can''t be affected by any Special Conditions and can''t retreat.    At any time during your turn, you may discard this card from play.","You may play any number of Item cards during your turn."]','sv7');
INSERT INTO "Card" VALUES('sv7-130','Antique Root Fossil','Trainer','130','Common',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/130.png","large":"https://images.pokemontcg.io/sv7/130_hires.png"}','H','60',NULL,'["Item"]',NULL,NULL,NULL,'[{"name":"Primal Root","text":"As long as this Pokémon is in the Active Spot, attacks used by your opponent''s Basic Pokémon cost Colorless more.","type":"Ability"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Play this card as if it were a 60-HP Basic Colorless Pokémon. This card can''t be affected by any Special Conditions and can''t retreat.  At any time during your turn, you may discard this card from play.","You may play any number of Item cards during your turn."]','sv7');
INSERT INTO "Card" VALUES('sv7-131','Area Zero Underdepths','Trainer','131','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/131.png","large":"https://images.pokemontcg.io/sv7/131_hires.png"}','H',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player who has any Tera Pokémon in play can have up to 8 Pokémon on their Bench.    If a player no longer has any Tera Pokémon in play, that player discards Pokémon from their Bench until they have 5. When this card leaves play, both players discard Pokémon from their Bench until they have 5, and the player who played this card discards first.","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv7');
INSERT INTO "Card" VALUES('sv7-132','Briar','Trainer','132','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/132.png","large":"https://images.pokemontcg.io/sv7/132_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if your opponent has exactly 2 Prize cards remaining.    During this turn, if your opponent''s Active Pokémon is Knocked Out by damage from an attack used by your Tera Pokémon, take 1 more Prize card.","You may play only 1 Supporter card during your turn."]','sv7');
INSERT INTO "Card" VALUES('sv7-133','Crispin','Trainer','133','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/133.png","large":"https://images.pokemontcg.io/sv7/133_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for up to 2 Basic Energy cards of different types, reveal them, and put 1 of them into your hand. Attach the other to 1 of your Pokémon. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','sv7');
INSERT INTO "Card" VALUES('sv7-134','Deluxe Bomb','Trainer','134','ACE SPEC Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/134.png","large":"https://images.pokemontcg.io/sv7/134_hires.png"}','H',NULL,NULL,'["Pokémon Tool","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","If the Pokémon this card is attached to is in the Active Spot and is damaged by an attack from your opponent''s Pokémon (even if this Pokémon is Knocked Out), put 12 damage counters on the Attacking Pokémon. If you placed any damage counters in this way, discard this card.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','sv7');
INSERT INTO "Card" VALUES('sv7-135','Glass Trumpet','Trainer','135','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/135.png","large":"https://images.pokemontcg.io/sv7/135_hires.png"}','H',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you have any Tera Pokémon in play.    Choose up to 2 of your Benched Colorless Pokémon and attach a Basic Energy card from your discard pile to each of them.","You may play any number of Item cards during your turn."]','sv7');
INSERT INTO "Card" VALUES('sv7-136','Grand Tree','Trainer','136','ACE SPEC Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/136.png","large":"https://images.pokemontcg.io/sv7/136_hires.png"}','H',NULL,NULL,'["Stadium","ACE SPEC"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can''t have more than 1 ACE SPEC card in your deck.","Once during each player''s turn, that player may search their deck for a Stage 1 Pokémon that evolves from 1 of their Basic Pokémon and put it onto that Pokémon to evolve it. If that Pokémon was evolved in this way, that player may search their deck for a Stage 2 Pokémon that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, that player shuffles their deck. (Players can''t evolve a Basic Pokémon during their first turn or a Basic Pokémon that was put into play this turn.)","You may play only 1 Stadium card during your turn. Put it next to the Active Spot, and discard it if another Stadium comes into play. A Stadium with the same name can''t be played."]','sv7');
INSERT INTO "Card" VALUES('sv7-137','Gravity Gemstone','Trainer','137','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/137.png","large":"https://images.pokemontcg.io/sv7/137_hires.png"}','H',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as the Pokémon this card is attached to is in the Active Spot, the Retreat Cost of both Active Pokémon is Colorless more.","You may attach any number of Pokémon Tools to your Pokémon during your turn. You may attach only 1 Pokémon Tool to each Pokémon, and it stays attached."]','sv7');
INSERT INTO "Card" VALUES('sv7-138','Kofu','Trainer','138','Uncommon',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/138.png","large":"https://images.pokemontcg.io/sv7/138_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 2 cards from your hand on the bottom of your deck in any order. If you put 2 cards on the bottom of your deck in this way, draw 4 cards. (If you can''t put 2 cards from your hand on the bottom of your deck, you can''t use this card.)","You may play only 1 Supporter card during your turn."]','sv7');
