INSERT INTO "Card" VALUES('sv7-171','Briar','Trainer','171','Special Illustration Rare',NULL,NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/sv7/171.png","large":"https://images.pokemontcg.io/sv7/171_hires.png"}','H',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if your opponent has exactly 2 Prize cards remaining.    During this turn, if your opponent''s Active Pokémon is Knocked Out by damage from an attack used by your Tera Pokémon, take 1 more Prize card.","You may play only 1 Supporter card during your turn."]','sv7');
