INSERT INTO "Card" VALUES('svp-7','Hawlucha','Pokémon','7','Promo','Yuya Oka','Its elegant finishing moves—performed by nimbly leaping around using its wings—are polished in the forest where it was born and raised.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/svp/7.png","large":"https://images.pokemontcg.io/svp/7_hires.png"}','G','70',NULL,'["Basic"]','["Fighting"]',NULL,NULL,'[{"name":"Flying Entry","text":"When you play this Pokémon from your hand onto your Bench during your turn, you may choose 2 of your opponent''s Benched Pokémon and put 1 damage counter on each of them.","type":"Ability"}]','[{"name":"Wing Attack","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[701]',NULL,NULL,'svp');
