INSERT INTO "Card" VALUES('svp-99','Shroodle','Pokémon','99','Promo','Hitoshi Ariga','Though usually a mellow Pokémon, it will sink its sharp, poison-soaked front teeth into any that anger it, causing paralysis in the object of its ire.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/svp/99.png","large":"https://images.pokemontcg.io/svp/99_hires.png"}','G','50',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Toxic Teeth","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[944]',NULL,NULL,'svp');
