INSERT INTO "Card" VALUES('swsh1-22','Vulpix','Pokémon','22','Common','Taira Akitsu','While young, it has six gorgeous tails. When it grows, several new tails are sprouted.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/22.png","large":"https://images.pokemontcg.io/swsh1/22_hires.png"}','D','70',NULL,'["Basic"]','["Fire"]',NULL,'["Ninetales"]',NULL,'[{"name":"Flare","cost":["Fire"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[37]',NULL,NULL,'swsh1');
INSERT INTO "Card" VALUES('swsh1-23','Ninetales','Pokémon','23','Rare','Megumi Higuchi','It is said to live 1,000 years, and each of its tails is loaded with supernatural powers.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/23.png","large":"https://images.pokemontcg.io/swsh1/23_hires.png"}','D','120',NULL,'["Stage 1"]','["Fire"]','Vulpix',NULL,NULL,'[{"name":"Flame Cloak","cost":["Fire"],"convertedEnergyCost":1,"damage":"30","text":"Attach a Fire Energy card from your discard pile to this Pokémon."},{"name":"Fire Mane","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"70","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[38]',NULL,NULL,'swsh1');
