INSERT INTO "Card" VALUES('swsh1-34','Cinderace','Pokémon','34','Rare Holo','Kouki Saitou','It''s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/34.png","large":"https://images.pokemontcg.io/swsh1/34_hires.png"}','D','170',NULL,'["Stage 2"]','["Fire"]','Raboot',NULL,'[{"name":"Libero","text":"Once during your turn, when this Pokémon moves from your Bench to the Active Spot, you may attach up to 2 Fire Energy cards from your discard pile to it.","type":"Ability"}]','[{"name":"Flare Striker","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"190","text":"Discard 2 Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[815]',NULL,NULL,'swsh1');
INSERT INTO "Card" VALUES('swsh1-35','Cinderace','Pokémon','35','Rare Holo','Naoki Saito','It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/35.png","large":"https://images.pokemontcg.io/swsh1/35_hires.png"}','D','170',NULL,'["Stage 2"]','["Fire"]','Raboot',NULL,NULL,'[{"name":"Pyro Ball","cost":["Fire"],"convertedEnergyCost":1,"damage":"50","text":"Your opponent''s Active Pokémon is now Burned."},{"name":"Burning Kick","cost":["Fire","Fire"],"convertedEnergyCost":2,"damage":"160","text":"Discard all Energy from this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[815]',NULL,NULL,'swsh1');
