INSERT INTO "Card" VALUES('swsh1-38','Sizzlipede','Pokémon','38','Common','Kouki Saitou','It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/38.png","large":"https://images.pokemontcg.io/swsh1/38_hires.png"}','D','70',NULL,'["Basic"]','["Fire"]',NULL,'["Centiskorch"]',NULL,'[{"name":"Relentless Flames","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"40×","text":"Flip a coin until you get tails. This attack does 40 damage for each heads."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[850]',NULL,NULL,'swsh1');
