INSERT INTO "Card" VALUES('swsh1-107','Silicobra','Pokémon','107','Common','Misa Tsutsui','It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/107.png","large":"https://images.pokemontcg.io/swsh1/107_hires.png"}','D','80',NULL,'["Basic"]','["Fighting"]',NULL,'["Sandaconda"]',NULL,'[{"name":"Sand Attack","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, if the Defending Pokémon tries to attack, your opponent flips a coin. If tails, that attack doesn''t happen."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[843]',NULL,NULL,'swsh1');
