INSERT INTO "Card" VALUES('swsh1-140','Snorlax','Pokémon','140','Rare','chibi','It is not satisfied unless it eats over 880 pounds of food every day. When it is done eating, it goes promptly to sleep.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/140.png","large":"https://images.pokemontcg.io/swsh1/140_hires.png"}','D','150',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Rolling Tackle","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":""},{"name":"Heavy Impact","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"130","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[143]',NULL,NULL,'swsh1');
