INSERT INTO "Card" VALUES('swsh1-147','Cinccino','Pokémon','147','Rare','sui','Its body secretes oil that this Pokémon spreads over its nest as a coating to protect it from dust. Cinccino won''t tolerate even a speck of the stuff.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/147.png","large":"https://images.pokemontcg.io/swsh1/147_hires.png"}','D','90',NULL,'["Stage 1"]','["Colorless"]','Minccino',NULL,'[{"name":"Make Do","text":"You must discard a card from your hand in order to use this Ability. Once during your turn, you may draw 2 cards.","type":"Ability"}]','[{"name":"Energy Assist","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":"Attach a basic Energy card from your discard pile to 1 of your Benched Pokémon."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[573]',NULL,NULL,'swsh1');
INSERT INTO "Card" VALUES('swsh1-148','Oranguru','Pokémon','148','Rare Holo','Shigenori Negishi','It knows the forest inside and out. If it comes across a wounded Pokémon, Oranguru will gather medicinal herbs to treat it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/148.png","large":"https://images.pokemontcg.io/swsh1/148_hires.png"}','D','120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Primate Wisdom","text":"Once during your turn, you may switch a card from your hand with the top card of your deck.","type":"Ability"}]','[{"name":"Whap Down","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[765]',NULL,NULL,'swsh1');
