INSERT INTO "Card" VALUES('swsh1-151','Corvisquire','Pokémon','151','Uncommon','Anesaki Dynamic','Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/151.png","large":"https://images.pokemontcg.io/swsh1/151_hires.png"}','D','80',NULL,'["Stage 1"]','["Colorless"]','Rookidee','["Corviknight"]',NULL,'[{"name":"Pluck","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Before doing damage, discard all Pokémon Tools from your opponent''s Active Pokémon."},{"name":"Drill Peck","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[822]',NULL,NULL,'swsh1');
