INSERT INTO "Card" VALUES('swsh1-153','Wooloo','Pokémon','153','Common','Mizue','Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh1/153.png","large":"https://images.pokemontcg.io/swsh1/153_hires.png"}','D','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Dubwool"]',NULL,'[{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Headbutt","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[831]',NULL,NULL,'swsh1');
