INSERT INTO "Card" VALUES('swsh10-92','Hisuian Sneasel','Pokémon','92','Common','Mizue','Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/92.png","large":"https://images.pokemontcg.io/swsh10/92_hires.png"}','F','70',NULL,'["Basic"]','["Darkness"]',NULL,'["Weavile"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Claw Slash","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[215]',NULL,NULL,'swsh10');
