INSERT INTO "Card" VALUES('swsh10-96','Mightyena','Pokémon','96','Rare','otumami','It chases down prey in a pack of around ten. They defeat foes with perfectly coordinated teamwork.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/96.png","large":"https://images.pokemontcg.io/swsh10/96_hires.png"}','F','110',NULL,'["Stage 1"]','["Darkness"]','Poochyena',NULL,'[{"name":"Hustle Bark","text":"If your opponent has any Pokémon VMAX in play, this Pokémon''s attacks cost ColorlessColorlessColorless less.","type":"Ability"}]','[{"name":"Wild Tackle","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"160","text":"This Pokémon also does 50 damage to itself."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[262]',NULL,NULL,'swsh10');
