INSERT INTO "Card" VALUES('swsh10-111','Bronzor','Pokémon','111','Common','Kouki Saitou','Floats using a mysterious energy. The pattern engraved upon its back is held as sacred and can sometimes be found in imagery from ancient cemeteries and other such timeworn places.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/111.png","large":"https://images.pokemontcg.io/swsh10/111_hires.png"}','F','60',NULL,'["Basic"]','["Metal"]',NULL,'["Bronzong"]',NULL,'[{"name":"Metal Press","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[436]',NULL,NULL,'swsh10');
