INSERT INTO "Card" VALUES('swsh10-115','Pawniard','Pokémon','115','Common','Tomokazu Komiya','It uses river stones to maintain the cutting edges of the blades covering its body. These sharpened blades allow it to bring down opponents.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/115.png","large":"https://images.pokemontcg.io/swsh10/115_hires.png"}','F','60',NULL,'["Basic"]','["Metal"]',NULL,'["Bisharp"]',NULL,'[{"name":"Reckless Charge","cost":["Metal"],"convertedEnergyCost":1,"damage":"30","text":"This Pokémon also does 10 damage to itself."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[624]',NULL,NULL,'swsh10');
