INSERT INTO "Card" VALUES('swsh10-136','Canceling Cologne','Trainer','136','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/136.png","large":"https://images.pokemontcg.io/swsh10/136_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Until the end of your turn, your opponent''s Active Pokémon has no Abilities. (This includes Pokémon that come into play during that turn.)","You may play any number of Item cards during your turn."]','swsh10');
