INSERT INTO "Card" VALUES('swsh10-138','Cyllene','Trainer','138','Uncommon','nagimiso',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/138.png","large":"https://images.pokemontcg.io/swsh10/138_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip 2 coins. Put a number of cards up to the number of heads from your discard pile on top of your deck in any order.","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-139','Dark Patch','Trainer','139','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/139.png","large":"https://images.pokemontcg.io/swsh10/139_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a basic Darkness Energy card from your discard pile to 1 of your Benched Darkness Pokémon.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-140','Energy Loto','Trainer','140','Uncommon','ORBITALLINK Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/140.png","large":"https://images.pokemontcg.io/swsh10/140_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 7 cards of your deck. You may reveal an Energy card you find there and put it into your hand. Shuffle the other cards back into your deck.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-141','Feather Ball','Trainer','141','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/141.png","large":"https://images.pokemontcg.io/swsh10/141_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon that has no Retreat Cost, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-142','Gapejaw Bog','Trainer','142','Uncommon','Oswaldo KATO',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/142.png","large":"https://images.pokemontcg.io/swsh10/142_hires.png"}','F',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Whenever either player puts a Basic Pokémon from their hand onto their Bench, put 2 damage counters on that Pokémon."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-143','Gardenia''s Vigor','Trainer','143','Uncommon','Yuu Nishida',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/143.png","large":"https://images.pokemontcg.io/swsh10/143_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw 2 cards. If you drew any cards in this way, attach up to 2 Grass Energy cards from your hand to 1 of your Benched Pokémon.","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-144','Grant','Trainer','144','Uncommon','Hideki Ishikawa',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/144.png","large":"https://images.pokemontcg.io/swsh10/144_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["During this turn, your Fighting Pokémon''s attacks do 30 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance). During your turn, if this Grant is in your discard pile, you may discard 2 cards, except any Grant, from your hand. If you do, put this Grant into your hand. (This effect doesn''t use up your Supporter card for the turn.)","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-145','Gutsy Pickaxe','Trainer','145','Uncommon','Eske Yoshinob',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/145.png","large":"https://images.pokemontcg.io/swsh10/145_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal the top card of your deck. If that card is a Fighting Energy card, attach it to 1 of your Benched Pokémon. If it is not a Fighting Energy card, put it into your hand.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-146','Hisuian Heavy Ball','Trainer','146','Uncommon','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/146.png","large":"https://images.pokemontcg.io/swsh10/146_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at your face-down Prize cards. You may reveal a Basic Pokémon you find there, put it into your hand, and put this Hisuian Heavy Ball in its place as a face-down Prize card. (If you don''t reveal a Basic Pokémon, put this card in the discard pile.) Then, shuffle your face-down Prize cards.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-147','Irida','Trainer','147','Rare Holo','kirisAki',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/147.png","large":"https://images.pokemontcg.io/swsh10/147_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Water Pokémon and an Item card, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-148','Jubilife Village','Trainer','148','Uncommon','Oswaldo KATO',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/148.png","large":"https://images.pokemontcg.io/swsh10/148_hires.png"}','F',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may shuffle their hand into their deck and draw 5 cards. If they do, their turn ends."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-149','Kamado','Trainer','149','Uncommon','Hitoshi Ariga',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/149.png","large":"https://images.pokemontcg.io/swsh10/149_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose a card in your hand, and discard the other cards. If you do, draw 4 cards. (If you have no other cards in your hand, you can''t use this card.)","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-150','Roxanne','Trainer','150','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/150.png","large":"https://images.pokemontcg.io/swsh10/150_hires.png"}','F',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if your opponent has 3 or fewer Prize cards remaining. Each player shuffles their hand into their deck. Then, you draw 6 cards, and your opponent draws 2 cards.","You may play only 1 Supporter card during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-151','Spicy Seasoned Curry','Trainer','151','Uncommon','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/151.png","large":"https://images.pokemontcg.io/swsh10/151_hires.png"}','E',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Your Active Pokémon is now Burned. Heal 40 damage from it.","You may play any number of Item cards during your turn."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-152','Supereffective Glasses','Trainer','152','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/152.png","large":"https://images.pokemontcg.io/swsh10/152_hires.png"}','F',NULL,NULL,'["Item","Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["When applying Weakness to damage from the attacks of the Pokémon this card is attached to done to your opponent''s Active Pokémon, apply it as ×3.","You may play any number of Item cards during your turn.","Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached."]','swsh10');
INSERT INTO "Card" VALUES('swsh10-153','Sweet Honey','Trainer','153','Uncommon','ORBITALLINK Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh10/153.png","large":"https://images.pokemontcg.io/swsh10/153_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Pokémon, and then flip a coin until you get tails. For each heads, heal 40 damage from that Pokémon.","You may play any number of Item cards during your turn."]','swsh10');
