INSERT INTO "Card" VALUES('swsh11-27','Delphox V','Pokémon','27','Rare Holo V','5ban Graphics',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/27.png","large":"https://images.pokemontcg.io/swsh11/27_hires.png"}','F','210',NULL,'["Basic","V"]','["Fire"]',NULL,NULL,NULL,'[{"name":"Eerie Glow","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Burned and Confused."},{"name":"Magical Fire","cost":["Fire","Fire","Colorless"],"convertedEnergyCost":3,"damage":"120","text":"Put 2 Energy attached to this Pokémon in the Lost Zone. This attack also does 120 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[655]',NULL,'["V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards."]','swsh11');
INSERT INTO "Card" VALUES('swsh11-28','Litleo','Pokémon','28','Common','Sekio','This hot-blooded Pokémon is filled with curiosity. When it gets angry or starts fighting, its short mane gets hot.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/28.png","large":"https://images.pokemontcg.io/swsh11/28_hires.png"}','F','70',NULL,'["Basic"]','["Fire"]',NULL,'["Pyroar"]',NULL,'[{"name":"Singe","cost":["Fire"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Burned."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[667]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-29','Pyroar','Pokémon','29','Rare Holo','Misa Tsutsui','The temperature of its breath is over 10,000 degrees Fahrenheit, but Pyroar doesn''t use it on its prey. This Pokémon prefers to eat raw meat.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/29.png","large":"https://images.pokemontcg.io/swsh11/29_hires.png"}','F','120',NULL,'["Stage 1"]','["Fire"]','Litleo',NULL,'[{"name":"Scorching Aura","text":"During Pokémon Checkup, put 4 damage counters on your opponent''s Burned Pokémon instead of 2.","type":"Ability"}]','[{"name":"Fire Fang","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Burned."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[668]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-30','Poliwag','Pokémon','30','Common','Miki Tanaka','For Poliwag, swimming is easier than walking. The swirl pattern on its belly is actually part of the Pokémon''s innards showing through the skin.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/30.png","large":"https://images.pokemontcg.io/swsh11/30_hires.png"}','F','60',NULL,'["Basic"]','["Water"]',NULL,'["Poliwhirl"]',NULL,'[{"name":"Splashing Dodge","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[60]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-31','Poliwhirl','Pokémon','31','Uncommon','Scav','Staring at the swirl on its belly causes drowsiness. This trait of Poliwhirl''s has been used in place of lullabies to get children to go to sleep.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/31.png","large":"https://images.pokemontcg.io/swsh11/31_hires.png"}','F','90',NULL,'["Stage 1"]','["Water"]','Poliwag','["Poliwrath","Politoed"]',NULL,'[{"name":"Light Punch","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Double Smash","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50×","text":"Flip 2 coins. This attack does 50 damage for each heads."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[61]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-32','Politoed','Pokémon','32','Rare','ryoma uratsuka','At nightfall, these Pokémon appear on the shores of lakes. They announce their territorial claims by letting out cries that sound like shouting.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/32.png","large":"https://images.pokemontcg.io/swsh11/32_hires.png"}','F','140',NULL,'["Stage 2"]','["Water"]','Poliwhirl',NULL,NULL,'[{"name":"Lordly Songleader","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"If Poliwag is on your Bench, this attack does 60 more damage. If Poliwhirl is on your Bench, this attack does 90 more damage. If Poliwrath is on your Bench, this attack does 120 more damage."},{"name":"Hydro Splash","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[186]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-33','Seel','Pokémon','33','Common','GIDORA','Thanks to its thick fat, cold seas don''t bother it at all, but it gets tired pretty easily in warm waters.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/33.png","large":"https://images.pokemontcg.io/swsh11/33_hires.png"}','F','70',NULL,'["Basic"]','["Water"]',NULL,'["Dewgong"]',NULL,'[{"name":"Headbutt","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Rain Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[86]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-34','Dewgong','Pokémon','34','Rare','chibi','It sunbathes on the beach after meals. The rise in its body temperature helps its digestion.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/34.png","large":"https://images.pokemontcg.io/swsh11/34_hires.png"}','F','120',NULL,'["Stage 1"]','["Water"]','Seel',NULL,NULL,'[{"name":"Swim Freely","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."},{"name":"Floe Return","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40×","text":"Shuffle any amount of Water Energy from your Pokémon into your deck. This attack does 40 damage for each card you shuffled into your deck in this way."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[87]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-35','Horsea','Pokémon','35','Common','Tika Matsuno','Horsea makes its home in oceans with gentle currents. If this Pokémon is under attack, it spits out pitch-black ink and escapes.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/35.png","large":"https://images.pokemontcg.io/swsh11/35_hires.png"}','F','50',NULL,'["Basic"]','["Water"]',NULL,'["Seadra"]',NULL,'[{"name":"Reverse Thrust","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Switch this Pokémon with 1 of your Benched Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[116]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-36','Seadra','Pokémon','36','Uncommon','sui','It''s the males that raise the offspring. While Seadra are raising young, the spines on their backs secrete thicker and stronger poison.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/36.png","large":"https://images.pokemontcg.io/swsh11/36_hires.png"}','F','80',NULL,'["Stage 1"]','["Water"]','Horsea','["Kingdra"]',NULL,'[{"name":"Swim Freely","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."},{"name":"Hydro Jet","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Pokémon for each Water Energy attached to this Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[117]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-37','Kingdra','Pokémon','37','Rare Holo','AKIRA EGAWA','With the arrival of a storm at sea, this Pokémon will show itself on the surface. When a Kingdra and a Dragonite meet, a fierce battle ensues.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/37.png","large":"https://images.pokemontcg.io/swsh11/37_hires.png"}','F','150',NULL,'["Stage 2"]','["Water"]','Seadra',NULL,'[{"name":"Seething Currents","text":"Once during your turn, you may have either player shuffle their hand and put it on the bottom of their deck. If that player put any cards on the bottom of their deck in this way, they draw 4 cards.","type":"Ability"}]','[{"name":"Hydro Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"130","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[230]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-38','Luvdisc','Pokémon','38','Common','Sekio','Luvdisc makes its home in coral reefs in warm seas. It especially likes sleeping in the space between Corsola''s branches.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/38.png","large":"https://images.pokemontcg.io/swsh11/38_hires.png"}','F','70',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Matching Look","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Each player reveals the top 2 cards of their deck, then draws those cards."},{"name":"Tackle","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[370]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-39','Shellos','Pokémon','39','Common','Saya Tsuruta','There''s speculation that its appearance is determined by what it eats, but the truth remains elusive.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/39.png","large":"https://images.pokemontcg.io/swsh11/39_hires.png"}','F','70',NULL,'["Basic"]','["Water"]',NULL,'["Gastrodon"]',NULL,'[{"name":"Rain Splash","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Surf","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[422]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-40','Finneon','Pokémon','40','Common','Taira Akitsu','It lures in prey with its shining tail fins. It stays near the surface during the day and moves to the depths when night falls.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/40.png","large":"https://images.pokemontcg.io/swsh11/40_hires.png"}','F','50',NULL,'["Basic"]','["Water"]',NULL,'["Lumineon"]','[{"name":"Oceanic Accompaniment","text":"As often as you like during your turn, you may attach a Water Energy card from your hand to 1 of your Pokémon that has the Swim Freely attack.","type":"Ability"}]','[{"name":"Water Gun","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[456]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-41','Lumineon','Pokémon','41','Uncommon','zig','They traverse the deep waters as if crawling over the seafloor. The fantastic lights of its fins shine like stars in the night sky.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/41.png","large":"https://images.pokemontcg.io/swsh11/41_hires.png"}','F','90',NULL,'["Stage 1"]','["Water"]','Finneon',NULL,NULL,'[{"name":"Swim Freely","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."},{"name":"Waterfall","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"120","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[457]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-42','Snover','Pokémon','42','Common','Mitsuhiro Arita','One is likely to encounter this Pokémon while out in the snow. There are stories of Snover appearing in human settlements but doing no harm—rather, they bond with the children.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/42.png","large":"https://images.pokemontcg.io/swsh11/42_hires.png"}','F','80',NULL,'["Basic"]','["Water"]',NULL,'["Abomasnow"]',NULL,'[{"name":"Corkscrew Punch","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Icicle Missile","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[459]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-43','Abomasnow','Pokémon','43','Uncommon','kodama','If it sees any packs of Darumaka going after Snover, it chases them off, swinging its sizable arms like hammers.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/43.png","large":"https://images.pokemontcg.io/swsh11/43_hires.png"}','F','140',NULL,'["Stage 1"]','["Water"]','Snover',NULL,NULL,'[{"name":"Icicle Punch","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""},{"name":"Double-Edge","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"160","text":"This Pokémon also does 30 damage to itself."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[460]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-44','Hisuian Basculin','Pokémon','44','Common','Oswaldo KATO','Though it differs from other Basculin in several respects, including demeanor—this one is gentle—I have categorized it as a regional form given the vast array of shared qualities.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/44.png","large":"https://images.pokemontcg.io/swsh11/44_hires.png"}','F','50',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Surprise Attack","cost":[],"convertedEnergyCost":0,"damage":"40","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[550]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-45','Hisuian Basculegion','Pokémon','45','Rare Holo','AKIRA EGAWA','Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/45.png","large":"https://images.pokemontcg.io/swsh11/45_hires.png"}','F','110',NULL,'["Stage 1"]','["Water"]','Hisuian Basculin',NULL,NULL,'[{"name":"Upstream Spirits","cost":[],"convertedEnergyCost":0,"damage":"20×","text":"This attack does 20 damage for each basic Energy card in your discard pile. Then, shuffle those cards into your deck."},{"name":"Water Shot","cost":["Water"],"convertedEnergyCost":1,"damage":"70","text":"Discard an Energy from this Pokémon."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[902]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-46','Ducklett','Pokémon','46','Common','Yuka Morii','They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/46.png","large":"https://images.pokemontcg.io/swsh11/46_hires.png"}','F','60',NULL,'["Basic"]','["Water"]',NULL,'["Swanna"]',NULL,'[{"name":"Rain Splash","cost":["Water"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[580]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-47','Swanna','Pokémon','47','Uncommon','Sekio','Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/47.png","large":"https://images.pokemontcg.io/swsh11/47_hires.png"}','F','120',NULL,'["Stage 1"]','["Water"]','Ducklett',NULL,NULL,'[{"name":"Water Pulse","cost":["Water"],"convertedEnergyCost":1,"damage":"20","text":"Your opponent''s Active Pokémon is now Asleep."},{"name":"Air Slash","cost":["Water","Water","Colorless"],"convertedEnergyCost":3,"damage":"130","text":"Discard an Energy from this Pokémon."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[581]',NULL,NULL,'swsh11');
