INSERT INTO "Card" VALUES('swsh11-148','Bouffalant','Pokémon','148','Rare','Nisota Niso','These Pokémon can crush a car with no more than a headbutt. Bouffalant with more hair on their heads hold higher positions within the herd.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/148.png","large":"https://images.pokemontcg.io/swsh11/148_hires.png"}','F','130',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Lost Headbutt","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":"Put an Energy attached to your opponent''s Active Pokémon in the Lost Zone."},{"name":"Superpowered Horns","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"120","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[626]',NULL,NULL,'swsh11');
INSERT INTO "Card" VALUES('swsh11-149','Komala','Pokémon','149','Uncommon','HYOGONOSUKE','It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/149.png","large":"https://images.pokemontcg.io/swsh11/149_hires.png"}','F','100',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"All Just a Dream","text":"If this Pokémon is Asleep and is Knocked Out by damage from an attack from your opponent''s Pokémon, your opponent can''t take any Prize cards for it.","type":"Ability"}]','[{"name":"Collapse","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"This Pokémon is now Asleep."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[775]',NULL,NULL,'swsh11');
