INSERT INTO "Card" VALUES('swsh11-151','Greedent','Pokémon','151','Rare','sui','It stashes berries in its tail—so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn''t notice the loss.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh11/151.png","large":"https://images.pokemontcg.io/swsh11/151_hires.png"}','F','130',NULL,'["Stage 1"]','["Colorless"]','Skwovet',NULL,NULL,'[{"name":"Collect","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw 2 cards."},{"name":"Spill Out","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60+","text":"Discard your hand. If you discarded 5 or more cards in this way, this attack does 150 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[820]',NULL,NULL,'swsh11');
