INSERT INTO "Card" VALUES('swsh12-63','Misdreavus','Pokémon','63','Common','HYOGONOSUKE','What makes it happy is imitating the voices of weeping people and scaring everyone. It doesn''t deal well with folks who aren''t easily frightened.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12/63.png","large":"https://images.pokemontcg.io/swsh12/63_hires.png"}','F','60',NULL,'["Basic"]','["Psychic"]',NULL,'["Mismagius"]',NULL,'[{"name":"Confuse Ray","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Confused."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[200]',NULL,NULL,'swsh12');
INSERT INTO "Card" VALUES('swsh12-64','Mismagius','Pokémon','64','Rare','kawayoo','Its muttered curses can cause awful headaches or terrifying visions that torment others.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12/64.png","large":"https://images.pokemontcg.io/swsh12/64_hires.png"}','F','90',NULL,'["Stage 1"]','["Psychic"]','Misdreavus',NULL,'[{"name":"Spiteful Magic","text":"If this Pokémon has full HP and is Knocked Out by damage from an attack from your opponent''s Pokémon, put 8 damage counters on the Attacking Pokémon.","type":"Ability"}]','[{"name":"Eerie Voice","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Put 2 damage counters on each of your opponent''s Pokémon."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[429]',NULL,NULL,'swsh12');
