INSERT INTO "Card" VALUES('swsh12-137','Smeargle','Pokémon','137','Common','Mizue','It draws symbols with the fluid that oozes from the tip of its tail. Depending on the symbol, Smeargle fanatics will pay big money for them.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12/137.png","large":"https://images.pokemontcg.io/swsh12/137_hires.png"}','F','70',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Colorful Palette","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Look at the top 5 cards of your deck. You may attach any number of basic Energy cards you find there to 1 of your Pokémon. Shuffle the other cards back into your deck."},{"name":"Ram","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[235]',NULL,NULL,'swsh12');
