INSERT INTO "Card" VALUES('swsh12pt5-2','Gloom','Pokémon','2','Uncommon','Kyoko Umemoto','Its pistils exude an incredibly foul odor. The horrid stench can cause fainting at a distance of 1.25 miles.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/2.png","large":"https://images.pokemontcg.io/swsh12pt5/2_hires.png"}','F','70',NULL,'["Stage 1"]','["Grass"]','Oddish','["Vileplume","Bellossom"]',NULL,'[{"name":"Offensive Scent","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Your opponent''s Active Pokémon is now Confused and Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[44]',NULL,NULL,'swsh12pt5');
