INSERT INTO "Card" VALUES('swsh12pt5-5','Tangrowth','Pokémon','5','Rare','zig','Tangrowth has two arms that it can extend as it pleases. Recent research has shown that these arms are, in fact, bundles of vines.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/5.png","large":"https://images.pokemontcg.io/swsh12pt5/5_hires.png"}','F','150',NULL,'["Stage 1"]','["Grass"]','Tangela',NULL,NULL,'[{"name":"Suctioning Vines","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"Heal 30 damage from this Pokémon."},{"name":"Hammer In","cost":["Grass","Grass","Colorless"],"convertedEnergyCost":3,"damage":"130","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[465]',NULL,NULL,'swsh12pt5');
