INSERT INTO "Card" VALUES('swsh12pt5-11','Cherubi','Pokémon','11','Common','Lee HyunJung','The deeper a Cherubi''s red, the more nutrients it has stockpiled in its body. And the sweeter and tastier its small ball!','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/11.png","large":"https://images.pokemontcg.io/swsh12pt5/11_hires.png"}','E','50',NULL,'["Basic"]','["Grass"]',NULL,'["Cherrim"]',NULL,'[{"name":"Leafage","cost":["Grass"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[420]',NULL,NULL,'swsh12pt5');
