INSERT INTO "Card" VALUES('swsh12pt5-31','Wailmer','Pokémon','31','Common','kodama','It shows off by spraying jets of seawater from the nostrils above its eyes. It eats a solid ton of Wishiwashi every day.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/31.png","large":"https://images.pokemontcg.io/swsh12pt5/31_hires.png"}','F','120',NULL,'["Basic"]','["Water"]',NULL,'["Wailord"]',NULL,'[{"name":"Nap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Heal 30 damage from this Pokémon."},{"name":"Water Gun","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[320]',NULL,NULL,'swsh12pt5');
