INSERT INTO "Card" VALUES('swsh12pt5-35','Luvdisc','Pokémon','35','Common','Miki Tanaka','Luvdisc makes its home in coral reefs in warm seas. It especially likes sleeping in the space between Corsola''s branches.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/35.png","large":"https://images.pokemontcg.io/swsh12pt5/35_hires.png"}','F','70',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Emotional Draw","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Shuffle your hand into your deck. Then, draw 5 cards."},{"name":"Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[370]',NULL,NULL,'swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-36','Kyogre','Pokémon','36','Rare Holo','Kouki Saitou','It is said to have widened the seas by causing downpours. It had been asleep in a marine trench.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/36.png","large":"https://images.pokemontcg.io/swsh12pt5/36_hires.png"}','F','140',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Wave Summoning","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Water Energy card and attach it to this Pokémon. Then, shuffle your deck."},{"name":"Dynamic Wave","cost":["Water","Water","Water","Colorless"],"convertedEnergyCost":4,"damage":"","text":"Put 3 Energy attached to this Pokémon into your hand. This attack does 180 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[382]',NULL,NULL,'swsh12pt5');
