INSERT INTO "Card" VALUES('swsh12pt5-40','Shinx','Pokémon','40','Common','0313','This Pokémon generates electricity by contracting its muscles. Excited trembling is a sign that Shinx is generating a tremendous amount of electricity.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/40.png","large":"https://images.pokemontcg.io/swsh12pt5/40_hires.png"}','F','60',NULL,'["Basic"]','["Lightning"]',NULL,'["Luxio"]',NULL,'[{"name":"Thunder Jolt","cost":["Lightning"],"convertedEnergyCost":1,"damage":"30","text":"This Pokémon also does 10 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[403]',NULL,NULL,'swsh12pt5');
