INSERT INTO "Card" VALUES('swsh12pt5-47','Emolga','Pokémon','47','Common','Saya Tsuruta','As it flies, it scatters electricity around, so bird Pokémon keep their distance. That''s why Emolga can keep all its food to itself.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/47.png","large":"https://images.pokemontcg.io/swsh12pt5/47_hires.png"}','E','70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Thunder Shock","cost":["Lightning"],"convertedEnergyCost":1,"damage":"30","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fighting","value":"×2"}]',NULL,NULL,NULL,'[587]',NULL,NULL,'swsh12pt5');
