INSERT INTO "Card" VALUES('swsh12pt5-89','Aggron','Pokémon','89','Rare Holo','GOSSAN','Aggron has a horn sharp enough to perforate thick iron sheets. It brings down its opponents by ramming into them horn first.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/89.png","large":"https://images.pokemontcg.io/swsh12pt5/89_hires.png"}','F','180',NULL,'["Stage 2"]','["Metal"]','Lairon',NULL,NULL,'[{"name":"Counter Press","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"During your opponent''s next turn, if this Pokémon is damaged by an attack (even if this Pokémon is Knocked Out), put damage counters on the Attacking Pokémon equal to the damage done to this Pokémon."},{"name":"Heavy Impact","cost":["Metal","Metal","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"180","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless","Colorless"]',4,'[306]',NULL,NULL,'swsh12pt5');
