INSERT INTO "Card" VALUES('swsh12pt5-93','Bisharp','Pokémon','93','Uncommon','DOM','It''s accompanied by a large retinue of Pawniard. Bisharp keeps a keen eye on its minions, ensuring none of them even think of double-crossing it.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/93.png","large":"https://images.pokemontcg.io/swsh12pt5/93_hires.png"}','F','110',NULL,'["Stage 1"]','["Metal"]','Pawniard',NULL,NULL,'[{"name":"Spike Draw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Draw 2 cards."},{"name":"Power Edge","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"70","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[625]',NULL,NULL,'swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-94','Zacian','Pokémon','94','Rare Holo','nagimiso','Now armed with a weapon it used in ancient times, this Pokémon needs only a single strike to fell even Gigantamax Pokémon.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/94.png","large":"https://images.pokemontcg.io/swsh12pt5/94_hires.png"}','F','130',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Battle Legion","cost":["Metal"],"convertedEnergyCost":1,"damage":"20+","text":"This attack does 10 more damage for each of your Benched Pokémon. This attack''s damage isn''t affected by Weakness or by any effects on your opponent''s Active Pokémon."},{"name":"Slicing Blade","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless"]',2,'[888]',NULL,NULL,'swsh12pt5');
