INSERT INTO "Card" VALUES('swsh12pt5-106','Tauros','Pokémon','106','Rare','Kouki Saitou','When Tauros begins whipping itself with its tails, it''s a warning that the Pokémon is about to charge with astounding speed.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/106.png","large":"https://images.pokemontcg.io/swsh12pt5/106_hires.png"}','F','110',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Smash Kick","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Adrena-Tackle","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"If this Pokémon has no damage counters on it, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[128]',NULL,NULL,'swsh12pt5');
