INSERT INTO "Card" VALUES('swsh12pt5-111','Bidoof','Pokémon','111','Common','Naoyo Kimura','It constantly gnaws on logs and rocks to whittle down its front teeth. It nests alongside water.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/111.png","large":"https://images.pokemontcg.io/swsh12pt5/111_hires.png"}','F','60',NULL,'["Basic"]','["Colorless"]',NULL,'["Bibarel"]','[{"name":"Carefree Countenance","text":"As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent''s).","type":"Ability"}]','[{"name":"Hyper Fang","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[399]',NULL,NULL,'swsh12pt5');
