INSERT INTO "Card" VALUES('swsh12pt5-118','Gumshoos','Pokémon','118','Rare','Mizue','Patient by nature, this Pokémon loses control of itself and pounces when it spots its favorite meal—Rattata!','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/118.png","large":"https://images.pokemontcg.io/swsh12pt5/118_hires.png"}','F','120',NULL,'["Stage 1"]','["Colorless"]','Yungoos',NULL,NULL,'[{"name":"Stakeout Headbutt","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"If your opponent''s Active Pokémon moved from the Bench to the Active Spot during your opponent''s last turn, this attack does 120 more damage."},{"name":"Lunge Out","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[735]',NULL,NULL,'swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-119','Oranguru','Pokémon','119','Rare','Sekio','With waves of its fan—made from leaves and its own fur—Oranguru skillfully gives instructions to other Pokémon.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/119.png","large":"https://images.pokemontcg.io/swsh12pt5/119_hires.png"}','F','110',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Primate Acting","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Choose a Supporter card from your opponent''s discard pile and use the effect of that card as the effect of this attack."},{"name":"Hammer In","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[765]',NULL,NULL,'swsh12pt5');
