INSERT INTO "Card" VALUES('swsh12pt5-121','Wooloo','Pokémon','121','Common','OKACHEKE','Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/121.png","large":"https://images.pokemontcg.io/swsh12pt5/121_hires.png"}','F','70',NULL,'["Basic"]','["Colorless"]',NULL,'["Dubwool"]',NULL,'[{"name":"Rolling Rollout","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30×","text":"Flip a coin until you get tails. This attack does 30 damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[831]',NULL,NULL,'swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-122','Dubwool','Pokémon','122','Rare','Sanosuke Sakuma','Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You''ll start to bounce the moment you set foot on it.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/122.png","large":"https://images.pokemontcg.io/swsh12pt5/122_hires.png"}','F','120',NULL,'["Stage 1"]','["Colorless"]','Wooloo',NULL,NULL,'[{"name":"Overhead Throw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":"This attack also does 10 damage to 1 of your Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Rolling Dash","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60+","text":"Flip a coin until you get tails. This attack does 30 more damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[832]',NULL,NULL,'swsh12pt5');
