INSERT INTO "Card" VALUES('swsh12pt5-140','Raihan','Trainer','140','Rare Holo','Hideki Ishikawa',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/140.png","large":"https://images.pokemontcg.io/swsh12pt5/140_hires.png"}','E',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if any of your Pokémon were Knocked Out during your opponent''s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-141','Rare Candy','Trainer','141','Uncommon','Yoshinobu Saito',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/141.png","large":"https://images.pokemontcg.io/swsh12pt5/141_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card onto the Basic Pokémon to evolve it, skipping the Stage 1. You can''t use this card during your first turn or on a Basic Pokémon that was put into play this turn.","You may play any number of Item cards during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-142','Rescue Carrier','Trainer','142','Uncommon','Amelicart',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/142.png","large":"https://images.pokemontcg.io/swsh12pt5/142_hires.png"}','E',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put up to 2 Pokémon, each with 90 HP or less, from your discard pile into your hand.","You may play any number of Item cards during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-143','Sky Seal Stone','Trainer','143','Rare Holo','AYUMI ODASHIMA',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/143.png","large":"https://images.pokemontcg.io/swsh12pt5/143_hires.png"}','F',NULL,NULL,'["Item","Pokémon Tool"]',NULL,NULL,NULL,'[{"name":"Star Order","text":"During your turn, you may use this Ability. During this turn, if your opponent''s Active Pokémon VSTAR or Active Pokémon VMAX is Knocked Out by damage from an attack from your Basic Pokémon V, take 1 more Prize card. (You can''t use more than 1 VSTAR Power in a game.)","type":"Ability"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The Pokémon V this card is attached to can use the VSTAR Power on this card.","You may play any number of Item cards during your turn.","Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-144','Switch','Trainer','144','Common','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/144.png","large":"https://images.pokemontcg.io/swsh12pt5/144_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Switch your Active Pokémon with 1 of your Benched Pokémon.","You may play any number of Item cards during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-145','Trekking Shoes','Trainer','145','Uncommon','Amelicart',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/145.png","large":"https://images.pokemontcg.io/swsh12pt5/145_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top card of your deck. You may put that card into your hand. If you don''t, discard that card and draw a card.","You may play any number of Item cards during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-146','Ultra Ball','Trainer','146','Uncommon','Amelicart',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/146.png","large":"https://images.pokemontcg.io/swsh12pt5/146_hires.png"}','F',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can use this card only if you discard 2 other cards from your hand. Search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','swsh12pt5');
INSERT INTO "Card" VALUES('swsh12pt5-147','Elesa''s Sparkle','Trainer','147','Rare Ultra','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5/147.png","large":"https://images.pokemontcg.io/swsh12pt5/147_hires.png"}','E',NULL,NULL,'["Fusion Strike","Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose up to 2 of your Fusion Strike Pokémon. For each of those Pokémon, search your deck for a Fusion Strike Energy card and attach it to that Pokémon. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','swsh12pt5');
