INSERT INTO "Card" VALUES('swsh12pt5gg-GG25','Bibarel','Pokémon','GG25','Trainer Gallery Rare Holo','Amelicart','It makes its nest by damming streams with bark and mud. It is known as an industrious worker.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh12pt5gg/GG25.png","large":"https://images.pokemontcg.io/swsh12pt5gg/GG25_hires.png"}','F','120',NULL,'["Stage 1"]','["Colorless"]','Bidoof',NULL,'[{"name":"Industrious Incisors","text":"Once during your turn, you may draw cards until you have 5 cards in your hand.","type":"Ability"}]','[{"name":"Tail Smash","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[400]',NULL,NULL,'swsh12pt5gg');
