INSERT INTO "Card" VALUES('swsh2-20','Applin','Pokémon','20','Common','Mizue','It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it''s just an apple and nothing more.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/20.png","large":"https://images.pokemontcg.io/swsh2/20_hires.png"}','D','40',NULL,'["Basic"]','["Grass"]',NULL,'["Flapple"]',NULL,'[{"name":"Continuous Tumble","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin until you get tails. This attack does 30 more damage for each heads."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[840]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-21','Applin','Pokémon','21','Common','Kagemaru Himeno','It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it''s just an apple and nothing more.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/21.png","large":"https://images.pokemontcg.io/swsh2/21_hires.png"}','D','40',NULL,'["Basic"]','["Grass"]',NULL,'["Flapple"]',NULL,'[{"name":"Withdraw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage done to this Pokémon by attacks."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[840]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-22','Flapple','Pokémon','22','Rare Holo','Shin Nagasawa','It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/22.png","large":"https://images.pokemontcg.io/swsh2/22_hires.png"}','D','80',NULL,'["Stage 1"]','["Grass"]','Applin',NULL,'[{"name":"Apple Drop","text":"Once during your turn, you may put 2 damage counters on 1 of your opponent''s Pokémon. If you placed any damage counters in this way, shuffle this Pokémon and all attached cards into your deck.","type":"Ability"}]','[{"name":"Acid Spray","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"Flip a coin. If heads, discard an Energy from your opponent''s Active Pokémon."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[841]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-23','Appletun','Pokémon','23','Rare Holo','Akira Komayama','Eating a sweet apple caused its evolution. A nectarous scent wafts from its body, luring in the bug Pokémon it preys on.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/23.png","large":"https://images.pokemontcg.io/swsh2/23_hires.png"}','D','90',NULL,'["Stage 1"]','["Grass"]','Applin',NULL,'[{"name":"Delicious Aroma","text":"Once during your turn, you may flip a coin. If heads, switch 1 of your opponent''s Benched Basic Pokémon with their Active Pokémon.","type":"Ability"}]','[{"name":"Solar Beam","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"70","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[842]',NULL,NULL,'swsh2');
