INSERT INTO "Card" VALUES('swsh2-73','Morpeko','Pokémon','73','Uncommon','Kouki Saitou','As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. It''s also generating electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/73.png","large":"https://images.pokemontcg.io/swsh2/73_hires.png"}','D','80',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Torment","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Choose 1 of your opponent''s Active Pokémon''s attacks. During your opponent''s next turn, that Pokémon can''t use that attack."},{"name":"Spark","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"This attack also does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[877]',NULL,NULL,'swsh2');
