INSERT INTO "Card" VALUES('swsh2-89','Dreepy','Pokémon','89','Common','Akira Komayama','After being reborn as a ghost Pokémon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/89.png","large":"https://images.pokemontcg.io/swsh2/89_hires.png"}','D','60',NULL,'["Basic"]','["Psychic"]',NULL,'["Drakloak"]',NULL,'[{"name":"Quick Attack","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10+","text":"Flip a coin. If heads, this attack does 10 more damage."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[885]',NULL,NULL,'swsh2');
