INSERT INTO "Card" VALUES('swsh2-100','Whiscash','Pokémon','100','Rare','kawayoo','It makes its nest at the bottom of swamps. It will eat anything—if it is alive, Whiscash will eat it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/100.png","large":"https://images.pokemontcg.io/swsh2/100_hires.png"}','D','140',NULL,'["Stage 1"]','["Fighting"]','Barboach',NULL,'[{"name":"Submerge","text":"As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent''s).","type":"Ability"}]','[{"name":"Earthquake","cost":["Fighting","Fighting"],"convertedEnergyCost":2,"damage":"140","text":"This attack also does 20 damage to each of your Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[340]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-101','Galarian Yamask','Pokémon','101','Common','Akira Komayama','A clay slab with cursed engravings took possession of a Yamask. The slab is said to be absorbing the Yamask''s dark power.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/101.png","large":"https://images.pokemontcg.io/swsh2/101_hires.png"}','D','70',NULL,'["Basic"]','["Fighting"]',NULL,'["Runerigus"]',NULL,'[{"name":"Reckless Charge","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"50","text":"This Pokémon also does 30 damage to itself."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[562]',NULL,NULL,'swsh2');
