INSERT INTO "Card" VALUES('swsh2-103','Binacle','Pokémon','103','Common','Saya Tsuruta','After two Binacle find a suitably sized rock, they adhere themselves to it and live together. They cooperate to gather food during high tide.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/103.png","large":"https://images.pokemontcg.io/swsh2/103_hires.png"}','D','80',NULL,'["Basic"]','["Fighting"]',NULL,'["Barbaracle"]',NULL,'[{"name":"Dual Chop","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50×","text":"Flip 2 coins. This attack does 50 damage for each heads."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[688]',NULL,NULL,'swsh2');
