INSERT INTO "Card" VALUES('swsh2-109','Falinks','Pokémon','109','Uncommon','Misa Tsutsui','Five of them are troopers, and one is the brass. The brass''s orders are absolute.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/109.png","large":"https://images.pokemontcg.io/swsh2/109_hires.png"}','D','90',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck."},{"name":"Team Attack","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30×","text":"This attack does 30 damage for each of your Benched Pokémon that has \"Falinks\" in its name."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[870]',NULL,NULL,'swsh2');
