INSERT INTO "Card" VALUES('swsh2-203','Sonia','Trainer','203','Rare Rainbow','Naoki Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/203.png","large":"https://images.pokemontcg.io/swsh2/203_hires.png"}','D',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for up to 2 Basic Pokémon or up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.","You may play only 1 Supporter card during your turn."]','swsh2');
INSERT INTO "Card" VALUES('swsh2-204','Frosmoth','Pokémon','204','Rare Secret','PLANETA Tsuji','It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/204.png","large":"https://images.pokemontcg.io/swsh2/204_hires.png"}','D','90',NULL,'["Stage 1"]','["Water"]','Snom',NULL,'[{"name":"Ice Dance","text":"As often as you like during your turn, you may attach a Water Energy card from your hand to 1 of your Benched Water Pokémon.","type":"Ability"}]','[{"name":"Aurora Beam","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[873]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-205','Galarian Perrserker','Pokémon','205','Rare Secret','PLANETA Tsuji','What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/205.png","large":"https://images.pokemontcg.io/swsh2/205_hires.png"}','D','120',NULL,'["Stage 1"]','["Metal"]','Galarian Meowth',NULL,'[{"name":"Steely Spirit","text":"Your Metal Pokémon''s attacks do 20 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Metal Claw","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless"]',2,'[863]',NULL,NULL,'swsh2');
INSERT INTO "Card" VALUES('swsh2-206','Big Charm','Trainer','206','Rare Secret','inose yukie',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/206.png","large":"https://images.pokemontcg.io/swsh2/206_hires.png"}','D',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached.","The Pokémon this card is attached to gets +30 HP.","You may play any number of Item cards during your turn."]','swsh2');
INSERT INTO "Card" VALUES('swsh2-207','Scoop Up Net','Trainer','207','Rare Secret','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Banned"}','{"small":"https://images.pokemontcg.io/swsh2/207.png","large":"https://images.pokemontcg.io/swsh2/207_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put 1 of your Pokémon that isn''t a Pokémon V or a Pokémon-GX into your hand. (Discard all attached cards.)","You may play any number of Item cards during your turn."]','swsh2');
INSERT INTO "Card" VALUES('swsh2-208','Tool Scrapper','Trainer','208','Rare Secret','Studio Bora Inc.',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/208.png","large":"https://images.pokemontcg.io/swsh2/208_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose up to 2 Pokémon Tools attached to Pokémon (yours or your opponent''s) and discard them.","You may play any number of Item cards during your turn."]','swsh2');
INSERT INTO "Card" VALUES('swsh2-209','Twin Energy','Energy','209','Rare Secret',NULL,NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh2/209.png","large":"https://images.pokemontcg.io/swsh2/209_hires.png"}','D',NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["As long as this card is attached to a Pokémon that isn''t a Pokémon V or a Pokémon-GX, it provides ColorlessColorless Energy.","If this card is attached to a Pokémon V or a Pokémon-GX, it provides Colorless Energy instead."]','swsh2');
