INSERT INTO "Card" VALUES('swsh3-96','Diggersby','Pokémon','96','Rare','0313','With power equal to an excavator, it can dig through dense bedrock. It''s a huge help during tunnel construction.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh3/96.png","large":"https://images.pokemontcg.io/swsh3/96_hires.png"}','D','130',NULL,'["Stage 1"]','["Fighting"]','Bunnelby',NULL,NULL,'[{"name":"Hammer In","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":""},{"name":"Land Crush","cost":["Fighting","Fighting","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"140","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[660]',NULL,NULL,'swsh3');
INSERT INTO "Card" VALUES('swsh3-97','Passimian','Pokémon','97','Common','SATOSHI NAKAI','Displaying amazing teamwork, they follow the orders of their boss as they all help out in the search for their favorite berries.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh3/97.png","large":"https://images.pokemontcg.io/swsh3/97_hires.png"}','D','110',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck."},{"name":"Rock Hurl","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"This attack''s damage isn''t affected by Resistance."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[766]',NULL,NULL,'swsh3');
