INSERT INTO "Card" VALUES('swsh3-102','Spinarak','Pokémon','102','Common','Kyoko Umemoto','Although the poison from its fangs isn''t that strong, it''s potent enough to weaken prey that gets caught in its web.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh3/102.png","large":"https://images.pokemontcg.io/swsh3/102_hires.png"}','D','60',NULL,'["Basic"]','["Darkness"]',NULL,'["Ariados"]',NULL,'[{"name":"Hang Down","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Sting","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[167]',NULL,NULL,'swsh3');
INSERT INTO "Card" VALUES('swsh3-103','Ariados','Pokémon','103','Uncommon','Shin Nagasawa','It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh3/103.png","large":"https://images.pokemontcg.io/swsh3/103_hires.png"}','D','110',NULL,'["Stage 1"]','["Darkness"]','Spinarak',NULL,'[{"name":"Spider Net","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may switch 1 of your opponent''s Benched Evolution Pokémon with their Active Pokémon.","type":"Ability"}]','[{"name":"Poison Sting","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent''s Active Pokémon is now Poisoned."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[168]',NULL,NULL,'swsh3');
