INSERT INTO "Card" VALUES('swsh3-112','Nickit','Pokémon','112','Common','Misa Tsutsui','Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh3/112.png","large":"https://images.pokemontcg.io/swsh3/112_hires.png"}','D','70',NULL,'["Basic"]','["Darkness"]',NULL,'["Thievul"]',NULL,'[{"name":"Tail Whip","cost":["Darkness"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, during your opponent''s next turn, the Defending Pokémon can''t attack."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[827]',NULL,NULL,'swsh3');
