INSERT INTO "Card" VALUES('swsh35-48','Swablu','Pokémon','48','Common','0313','It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/48.png","large":"https://images.pokemontcg.io/swsh35/48_hires.png"}','D','50',NULL,'["Basic"]','["Colorless"]',NULL,'["Altaria"]',NULL,'[{"name":"Peck","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[333]',NULL,NULL,'swsh35');
INSERT INTO "Card" VALUES('swsh35-49','Altaria','Pokémon','49','Rare Holo','Taira Akitsu','On sunny days, it flies freely through the sky and blends into the clouds. It sings in a beautiful soprano.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/49.png","large":"https://images.pokemontcg.io/swsh35/49_hires.png"}','D','110',NULL,'["Stage 1"]','["Colorless"]','Swablu',NULL,'[{"name":"Miraculous Charm","text":"Prevent all damage done to this Pokémon by attacks from your opponent''s Pokémon V and Pokémon-GX.","type":"Ability"}]','[{"name":"Speed Dive","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"60","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[334]',NULL,NULL,'swsh35');
