INSERT INTO "Card" VALUES('swsh35-51','Full Heal','Trainer','51','Uncommon','Yoshinobu Saito',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/51.png","large":"https://images.pokemontcg.io/swsh35/51_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Remove all Special Conditions from your Active Pokémon.","You may play any number of Item cards during your turn."]','swsh35');
