INSERT INTO "Card" VALUES('swsh35-55','Kabu','Trainer','55','Uncommon','take',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/55.png","large":"https://images.pokemontcg.io/swsh35/55_hires.png"}','D',NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Shuffle your hand into your deck. Then, draw 4 cards. If your Active Pokémon is your only Pokémon in play, draw 8 cards instead.","You may play only 1 Supporter card during your turn."]','swsh35');
