INSERT INTO "Card" VALUES('swsh35-59','Poké Ball','Trainer','59','Common','Studio Bora Inc.',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/59.png","large":"https://images.pokemontcg.io/swsh35/59_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","You may play any number of Item cards during your turn."]','swsh35');
