INSERT INTO "Card" VALUES('swsh35-63','Rotom Bike','Trainer','63','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/63.png","large":"https://images.pokemontcg.io/swsh35/63_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Draw cards until you have 6 cards in your hand. Your turn ends.","You may play any number of Item cards during your turn."]','swsh35');
INSERT INTO "Card" VALUES('swsh35-64','Rotom Phone','Trainer','64','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh35/64.png","large":"https://images.pokemontcg.io/swsh35/64_hires.png"}','D',NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the top 5 cards of your deck, choose 1 of them, and shuffle the other cards back into your deck. Then, put the card you chose on top of your deck.","You may play any number of Item cards during your turn."]','swsh35');
