INSERT INTO "Card" VALUES('swsh4-9','Celebi','Pokémon','9','Amazing Rare','5ban Graphics','This Pokémon has the ability to move through time. Records describing it as a forest deity can be found from many different eras.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/9.png","large":"https://images.pokemontcg.io/swsh4/9_hires.png"}','D','60',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Energy Press","cost":["Grass"],"convertedEnergyCost":1,"damage":"30×","text":"This attack does 30 damage for each Energy attached to your opponent''s Active Pokémon."},{"name":"Amazing Bloom","cost":["Lightning","Psychic"],"convertedEnergyCost":2,"damage":"","text":"For each of your Benched Pokémon, search your deck for a card that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[251]',NULL,NULL,'swsh4');
