INSERT INTO "Card" VALUES('swsh4-77','Dedenne','Pokémon','77','Common','Yuka Morii','Its upper whiskers are sensors that survey its surroundings. Its lower whiskers are organs that shoot electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/77.png","large":"https://images.pokemontcg.io/swsh4/77_hires.png"}','D','70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Tail Trickery","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":"Your opponent''s Active Pokémon is now Confused."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[702]',NULL,NULL,'swsh4');
