INSERT INTO "Card" VALUES('swsh4-84','Quagsire','Pokémon','84','Rare','otumami','It has an easygoing nature. It doesn''t care if it bumps its head on boats and boulders while swimming.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/84.png","large":"https://images.pokemontcg.io/swsh4/84_hires.png"}','D','120',NULL,'["Stage 1"]','["Fighting"]','Wooper',NULL,NULL,'[{"name":"Beat","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Fickle Impact","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"180","text":"If you have exactly 2, 4, or 6 Prize cards remaining, this attack does nothing."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[195]',NULL,NULL,'swsh4');
INSERT INTO "Card" VALUES('swsh4-85','Shuckle','Pokémon','85','Uncommon','Mizue','It stores berries inside its shell. To avoid attacks, it hides beneath rocks and remains completely still.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/85.png","large":"https://images.pokemontcg.io/swsh4/85_hires.png"}','D','70',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Deck Distiller","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin until you get tails. For each heads, discard the top card of your opponent''s deck."},{"name":"Rock Throw","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"50","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[213]',NULL,NULL,'swsh4');
