INSERT INTO "Card" VALUES('swsh4-105','Sableye','Pokémon','105','Uncommon','KEIICHIRO ITO','This Pokémon is feared. When its gemstone eyes begin to glow with a sinister shine, it''s believed that Sableye will steal people''s spirits away.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/105.png","large":"https://images.pokemontcg.io/swsh4/105_hires.png"}','D','70',NULL,'["Basic"]','["Darkness"]',NULL,NULL,NULL,'[{"name":"Filch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw a card."},{"name":"Torment","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Choose 1 of your opponent''s Active Pokémon''s attacks. During your opponent''s next turn, that Pokémon can''t use that attack."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[302]',NULL,NULL,'swsh4');
