INSERT INTO "Card" VALUES('swsh4-108','Krokorok','Pokémon','108','Uncommon','sowsow','It buries some of its prey in the sand to use as emergency meals when its hunts are unsuccessful.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/108.png","large":"https://images.pokemontcg.io/swsh4/108_hires.png"}','D','90',NULL,'["Stage 1"]','["Darkness"]','Sandile','["Krookodile"]',NULL,'[{"name":"Bite","cost":["Darkness"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Dredge Up","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard the top 3 cards of your opponent''s deck."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[552]',NULL,NULL,'swsh4');
