INSERT INTO "Card" VALUES('swsh4-110','Trubbish','Pokémon','110','Common','Kyoko Umemoto','Its favorite places are unsanitary ones. If you leave trash lying around, you could even find one of these Pokémon living in your room.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/110.png","large":"https://images.pokemontcg.io/swsh4/110_hires.png"}','D','70',NULL,'["Basic"]','["Darkness"]',NULL,'["Garbodor"]',NULL,'[{"name":"Lucky Find","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Search your deck for an Item card, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Sludge Toss","cost":["Darkness","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[568]',NULL,NULL,'swsh4');
