INSERT INTO "Card" VALUES('swsh4-119','Jirachi','Pokémon','119','Amazing Rare','Sanosuke Sakuma','Once every 1,000 years, the singing of a pure voice will rouse this Pokémon from its near-perpetual slumber. It wakes for only seven days.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/119.png","large":"https://images.pokemontcg.io/swsh4/119_hires.png"}','D','70',NULL,'["Basic"]','["Metal"]',NULL,NULL,'[{"name":"Dreamy Revelation","text":"Once during your turn, if this Pokémon is in the Active Spot, you may look at the top 2 cards of your deck and put 1 of them into your hand. Put the other card back on top of your deck.","type":"Ability"}]','[{"name":"Amazing Star","cost":["Psychic","Fighting","Metal"],"convertedEnergyCost":3,"damage":"","text":"Search your deck for up to 7 basic Energy cards and attach them to your Pokémon in any way you like. Then, shuffle your deck."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[385]',NULL,NULL,'swsh4');
