INSERT INTO "Card" VALUES('swsh4-135','Whismur','Pokémon','135','Common','Tika Matsuno','If it senses danger, it scares the foe by crying out with the volume of a jet-plane engine.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/135.png","large":"https://images.pokemontcg.io/swsh4/135_hires.png"}','D','60',NULL,'["Basic"]','["Colorless"]',NULL,'["Loudred"]',NULL,'[{"name":"Continuous Tumble","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"40×","text":"Flip a coin until you get tails. This attack does 40 damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[293]',NULL,NULL,'swsh4');
