INSERT INTO "Card" VALUES('swsh4-199','Oranguru','Pokémon','199','Rare Secret','PLANETA Mochizuki','It knows the forest inside and out. If it comes across a wounded Pokémon, Oranguru will gather medicinal herbs to treat it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/199.png","large":"https://images.pokemontcg.io/swsh4/199_hires.png"}','D','120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Primate Wisdom","text":"Once during your turn, you may switch a card from your hand with the top card of your deck.","type":"Ability"}]','[{"name":"Whap Down","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[765]',NULL,NULL,'swsh4');
INSERT INTO "Card" VALUES('swsh4-200','Cape of Toughness','Trainer','200','Rare Secret','inose yukie',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/200.png","large":"https://images.pokemontcg.io/swsh4/200_hires.png"}','D',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached.","The Basic Pokémon this card is attached to gets +50 HP, except Pokémon-GX.","You may play any number of Item cards during your turn."]','swsh4');
INSERT INTO "Card" VALUES('swsh4-201','Hero''s Medal','Trainer','201','Rare Secret','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/201.png","large":"https://images.pokemontcg.io/swsh4/201_hires.png"}','D',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached.","The Pokémon VMAX this card is attached to gets -100 HP, and if it is Knocked Out by damage from an attack from your opponent''s Pokémon, that player takes 1 fewer Prize card. You can''t attach this card to a Pokémon VMAX that has 100 HP or less remaining.","You may play any number of Item cards during your turn."]','swsh4');
INSERT INTO "Card" VALUES('swsh4-202','Memory Capsule','Trainer','202','Rare Secret','sadaji',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh4/202.png","large":"https://images.pokemontcg.io/swsh4/202_hires.png"}','D',NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached.","The Pokémon this card is attached to can use any attack from its previous Evolutions. (You still need the necessary Energy to use each attack.)","You may play any number of Item cards during your turn."]','swsh4');
