INSERT INTO "Card" VALUES('swsh45-30','Frosmoth','Pokémon','30','Rare Holo','Kagemaru Himeno','It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh45/30.png","large":"https://images.pokemontcg.io/swsh45/30_hires.png"}','D','90',NULL,'["Stage 1"]','["Water"]','Snom',NULL,'[{"name":"Ice Dance","text":"As often as you like during your turn, you may attach a Water Energy card from your hand to 1 of your Benched Water Pokémon.","type":"Ability"}]','[{"name":"Aurora Beam","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[873]',NULL,NULL,'swsh45');
