INSERT INTO "Card" VALUES('swsh45sv-SV100','Greedent','Pokémon','SV100','Rare Shiny','Hideki Ishikawa','It stashes berries in its tail—so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn''t notice the loss.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh45sv/SV100.png","large":"https://images.pokemontcg.io/swsh45sv/SV100_hires.png"}','D','120',NULL,'["Stage 1"]','["Colorless"]','Skwovet',NULL,'[{"name":"Greedy Tail","text":"Once during your turn, you may search your deck for a Pokémon Tool card, reveal it, and put it into your hand. Then, shuffle your deck.","type":"Ability"}]','[{"name":"Tail Smack","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[820]',NULL,NULL,'swsh45sv');
