INSERT INTO "Card" VALUES('swsh5-49','Pachirisu','Pokémon','49','Common','Naoyo Kimura','A pair may be seen rubbing their cheek pouches together in an effort to share stored electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh5/49.png","large":"https://images.pokemontcg.io/swsh5/49_hires.png"}','E','70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Find a Friend","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Gnaw","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[417]',NULL,NULL,'swsh5');
