INSERT INTO "Card" VALUES('swsh5-107','Aegislash','Pokémon','107','Rare Holo','miki kudo','Once upon a time, a king with an Aegislash reigned over the land. His Pokémon eventually drained him of life, and his kingdom fell with him.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh5/107.png","large":"https://images.pokemontcg.io/swsh5/107_hires.png"}','E','150',NULL,'["Stage 2"]','["Metal"]','Doublade',NULL,'[{"name":"Stance Change","text":"Once during your turn, you may switch this Pokémon with an Aegislash in your hand. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.","type":"Ability"}]','[{"name":"Full Metal Blade","cost":["Metal","Metal","Colorless"],"convertedEnergyCost":3,"damage":"210","text":"Discard 2 Metal Energy from this Pokémon."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[681]',NULL,NULL,'swsh5');
