INSERT INTO "Card" VALUES('swsh5-116','Purugly','Pokémon','116','Uncommon','Akira Komayama','To make itself appear intimidatingly beefy, it tightly cinches its waist with its twin tails.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh5/116.png","large":"https://images.pokemontcg.io/swsh5/116_hires.png"}','E','120',NULL,'["Stage 1"]','["Colorless"]','Glameow',NULL,NULL,'[{"name":"Caturday","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw 3 cards. If you do, this Pokémon is now Asleep."},{"name":"Claw Slash","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"120","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[432]',NULL,NULL,'swsh5');
