INSERT INTO "Card" VALUES('swsh5-119','Drampa','Pokémon','119','Rare','Eri Yamaki','Drampa is a kind and friendly Pokémon—up until it''s angered. When that happens, it stirs up a gale and flattens everything around.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh5/119.png","large":"https://images.pokemontcg.io/swsh5/119_hires.png"}','E','120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Call for Family","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck."},{"name":"Spiral Rush","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin until you get tails. This attack does 30 more damage for each heads."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[780]',NULL,NULL,'swsh5');
