INSERT INTO "Card" VALUES('swsh6-60','Kirlia','Pokémon','60','Uncommon','0313','It has a psychic power that enables it to distort the space around it and see into the future.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/60.png","large":"https://images.pokemontcg.io/swsh6/60_hires.png"}','E','80',NULL,'["Stage 1"]','["Psychic"]','Ralts','["Gardevoir","Gallade"]',NULL,'[{"name":"Mirage Step","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 3 Kirlia and put them onto your Bench. Then, shuffle your deck."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[281]',NULL,NULL,'swsh6');
INSERT INTO "Card" VALUES('swsh6-61','Gardevoir','Pokémon','61','Rare Holo','kodama','To protect its Trainer, it will expend all its psychic power to create a small black hole.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/61.png","large":"https://images.pokemontcg.io/swsh6/61_hires.png"}','E','140',NULL,'["Stage 2"]','["Psychic"]','Kirlia',NULL,'[{"name":"Shining Arcana","text":"Once during your turn, you may look at the top 2 cards of your deck and attach any number of basic Energy cards you find there to your Pokémon in any way you like. Put the other cards into your hand.","type":"Ability"}]','[{"name":"Brainwave","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"This attack does 30 more damage for each Psychic Energy attached to this Pokémon."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[282]',NULL,NULL,'swsh6');
