INSERT INTO "Card" VALUES('swsh6-69','Inkay','Pokémon','69','Common','Sanosuke Sakuma','By exposing foes to the blinking of its luminescent spots, Inkay demoralizes them, and then it seizes the chance to flee.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/69.png","large":"https://images.pokemontcg.io/swsh6/69_hires.png"}','E','50',NULL,'["Basic","Rapid Strike"]','["Psychic"]',NULL,'["Malamar"]',NULL,'[{"name":"Spinning Attack","cost":["Psychic"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[686]',NULL,NULL,'swsh6');
