INSERT INTO "Card" VALUES('swsh6-72','Hattrem','Pokémon','72','Uncommon','miki kudo','Using the braids on its head, it pummels foes to get them to quiet down. One blow from those braids would knock out a professional boxer.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/72.png","large":"https://images.pokemontcg.io/swsh6/72_hires.png"}','E','80',NULL,'["Stage 1"]','["Psychic"]','Hatenna','["Hatterene"]',NULL,'[{"name":"Spiral Drain","cost":["Psychic"],"convertedEnergyCost":1,"damage":"30","text":"Heal 30 damage from this Pokémon."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[857]',NULL,NULL,'swsh6');
INSERT INTO "Card" VALUES('swsh6-73','Hatterene','Pokémon','73','Rare Holo','chibi','If you''re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/73.png","large":"https://images.pokemontcg.io/swsh6/73_hires.png"}','E','130',NULL,'["Stage 2"]','["Psychic"]','Hattrem',NULL,'[{"name":"Witch Rondo","text":"Once during your turn, you may switch your Active Pokémon with 1 of your Benched Pokémon. If you do, your opponent switches their Active Pokémon with 1 of their Benched Pokémon.","type":"Ability"}]','[{"name":"Psychic","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"This attack does 50 more damage for each Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[858]',NULL,NULL,'swsh6');
