INSERT INTO "Card" VALUES('swsh6-76','Diglett','Pokémon','76','Common','Souichirou Gunjima','It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/76.png","large":"https://images.pokemontcg.io/swsh6/76_hires.png"}','E','50',NULL,'["Basic","Rapid Strike"]','["Fighting"]',NULL,'["Dugtrio"]',NULL,'[{"name":"Dig","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, during your opponent''s next turn, prevent all damage from and effects of attacks done to this Pokémon."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[50]',NULL,NULL,'swsh6');
