INSERT INTO "Card" VALUES('swsh6-84','Crabrawler','Pokémon','84','Common','Mitsuhiro Arita','Crabrawler has been known to mistake Exeggutor for a coconut tree and climb it. The enraged Exeggutor shakes it off and stomps it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh6/84.png","large":"https://images.pokemontcg.io/swsh6/84_hires.png"}','E','80',NULL,'["Basic"]','["Fighting"]',NULL,'["Crabominable"]',NULL,'[{"name":"Light Punch","cost":["Fighting"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Double Lariat","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"40×","text":"Flip 2 coins. This attack does 40 damage for each heads."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[739]',NULL,NULL,'swsh6');
