INSERT INTO "Card" VALUES('swsh7-78','Cutiefly','Pokémon','78','Common','Yukiko Baba','An opponent''s aura can tell Cutiefly what that opponent''s next move will be. Then Cutiefly can glide around the attack and strike back.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh7/78.png","large":"https://images.pokemontcg.io/swsh7/78_hires.png"}','E','30',NULL,'["Basic"]','["Psychic"]',NULL,'["Ribombee"]',NULL,'[{"name":"Flap","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,NULL,NULL,'[742]',NULL,NULL,'swsh7');
