INSERT INTO "Card" VALUES('swsh8-50','Shellder','Pokémon','50','Common','kawayoo','Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/50.png","large":"https://images.pokemontcg.io/swsh8/50_hires.png"}','E','70',NULL,'["Basic","Rapid Strike"]','["Water"]',NULL,'["Cloyster"]',NULL,'[{"name":"Tongue Slap","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Wave Splash","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[90]',NULL,NULL,'swsh8');
