INSERT INTO "Card" VALUES('swsh8-58','Marill','Pokémon','58','Common','sowsow','Even after Marill swims in a cold sea, its water- repellent fur dries almost as soon as Marill leaves the water. That''s why this Pokémon is never cold.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/58.png","large":"https://images.pokemontcg.io/swsh8/58_hires.png"}','E','50',NULL,'["Basic"]','["Water"]',NULL,'["Azumarill"]',NULL,'[{"name":"Aqua Liner","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"This attack does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Let''s All Rollout","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"This attack does 20 damage for each of your Benched Pokémon that has the Let''s All Rollout attack."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[183]',NULL,NULL,'swsh8');
