INSERT INTO "Card" VALUES('swsh8-68','Panpour','Pokémon','68','Common','Sekio','The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/68.png","large":"https://images.pokemontcg.io/swsh8/68_hires.png"}','E','60',NULL,'["Basic"]','["Water"]',NULL,'["Simipour"]',NULL,'[{"name":"Pry","cost":["Water"],"convertedEnergyCost":1,"damage":"10","text":"Your opponent reveals their hand."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless"]',1,'[515]',NULL,NULL,'swsh8');
