INSERT INTO "Card" VALUES('swsh8-99','Heliolisk','Pokémon','99','Uncommon','Kagemaru Himeno','One Heliolisk basking in the sun with its frill outspread is all it would take to produce enough electricity to power a city.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/99.png","large":"https://images.pokemontcg.io/swsh8/99_hires.png"}','E','110',NULL,'["Stage 1"]','["Lightning"]','Helioptile',NULL,NULL,'[{"name":"Gnaw","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Electrobullet","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"60","text":"This attack also does 20 damage to 1 of your opponent''s Benched Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[695]',NULL,NULL,'swsh8');
INSERT INTO "Card" VALUES('swsh8-100','Charjabug','Pokémon','100','Uncommon','sowsow','Its digestive processes convert the leaves it eats into electricity. An electric sac in its belly stores the electricity for later use.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/100.png","large":"https://images.pokemontcg.io/swsh8/100_hires.png"}','E','100',NULL,'["Stage 1"]','["Lightning"]','Grubbin','["Vikavolt"]',NULL,'[{"name":"Vise Grip","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""},{"name":"Head Bolt","cost":["Lightning","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[737]',NULL,NULL,'swsh8');
