INSERT INTO "Card" VALUES('swsh8-119','Mawile','Pokémon','119','Common','Kouki Saitou','It chomps with its gaping mouth. Its huge jaws are actually steel horns that have been transformed.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/119.png","large":"https://images.pokemontcg.io/swsh8/119_hires.png"}','E','90',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Chomp Chomp Hold","cost":["Psychic"],"convertedEnergyCost":1,"damage":"30","text":"During your opponent''s next turn, the Defending Pokémon''s attacks cost Colorless more, and its Retreat Cost is Colorless more."}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[303]',NULL,NULL,'swsh8');
