INSERT INTO "Card" VALUES('swsh8-174','Pangoro','Pokémon','174','Uncommon','HYOGONOSUKE','Using its leaf, Pangoro can predict the moves of its opponents. It strikes with punches that can turn a dump truck into scrap with just one hit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/174.png","large":"https://images.pokemontcg.io/swsh8/174_hires.png"}','E','140',NULL,'["Stage 1"]','["Darkness"]','Pancham',NULL,NULL,'[{"name":"Knocking Hammer","cost":["Darkness","Darkness","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"Discard the top card of your opponent''s deck."},{"name":"Shakedown","cost":["Darkness","Darkness","Darkness","Colorless"],"convertedEnergyCost":4,"damage":"150","text":"Discard a random card from your opponent''s hand."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[675]',NULL,NULL,'swsh8');
