INSERT INTO "Card" VALUES('swsh8-184','Durant','Pokémon','184','Common','Shin Nagasawa','With their large mandibles, these Pokémon can crunch their way through rock. They work together to protect their eggs from Sandaconda.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/184.png","large":"https://images.pokemontcg.io/swsh8/184_hires.png"}','E','70',NULL,'["Basic"]','["Metal"]',NULL,NULL,NULL,'[{"name":"Adversity Jaws","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"70","text":"If your opponent''s Active Pokémon is a Fire Pokémon, it is now Paralyzed."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Grass","value":"-30"}]','["Colorless"]',1,'[632]',NULL,NULL,'swsh8');
