INSERT INTO "Card" VALUES('swsh8-203','Blissey','Pokémon','203','Rare','Mizue','This Pokémon is overflowing with love. Only Chansey that share a strong bond with their Trainer can evolve, so people say.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/203.png","large":"https://images.pokemontcg.io/swsh8/203_hires.png"}','E','130',NULL,'["Stage 1"]','["Colorless"]','Chansey',NULL,'[{"name":"Expert in Roundness","text":"Prevent all damage done to each of your Pokémon that has the Let''s All Rollout attack by attacks from your opponent''s Pokémon VMAX.","type":"Ability"}]','[{"name":"Let''s All Rollout","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"20×","text":"This attack does 20 damage for each of your Benched Pokémon that has the Let''s All Rollout attack."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[242]',NULL,NULL,'swsh8');
INSERT INTO "Card" VALUES('swsh8-204','Kangaskhan','Pokémon','204','Rare','Souichirou Gunjima','You shouldn''t get close to the child when it''s playing outside its mother''s pouch. Its mother is always nearby watching over it.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/204.png","large":"https://images.pokemontcg.io/swsh8/204_hires.png"}','E','120',NULL,'["Basic","Rapid Strike"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Pound","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":""},{"name":"Coordinated One-Two Punch","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"Flip a coin. If heads, this attack does 100 more damage."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[115]',NULL,NULL,'swsh8');
