INSERT INTO "Card" VALUES('swsh8-210','Skitty','Pokémon','210','Common','Yukiko Baba','It shows its cute side by chasing its own tail until it gets dizzy.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh8/210.png","large":"https://images.pokemontcg.io/swsh8/210_hires.png"}','E','60',NULL,'["Basic"]','["Colorless"]',NULL,'["Delcatty"]',NULL,'[{"name":"Whimsy Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[300]',NULL,NULL,'swsh8');
