INSERT INTO "Card" VALUES('swsh9-4','Breloom','Pokémon','4','Rare','Sekio','It scatters poisonous spores and throws powerful punches while its foe is hampered by inhaled spores.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/4.png","large":"https://images.pokemontcg.io/swsh9/4_hires.png"}','F','110',NULL,'["Stage 1"]','["Grass"]','Shroomish',NULL,NULL,'[{"name":"Spore Ball","cost":["Grass"],"convertedEnergyCost":1,"damage":"30","text":"Your opponent''s Active Pokémon is now Asleep."},{"name":"Powdery Uppercut","cost":["Grass"],"convertedEnergyCost":1,"damage":"130","text":"You can use this attack only if this Pokémon used Spore Ball during your last turn."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[286]',NULL,NULL,'swsh9');
