INSERT INTO "Card" VALUES('swsh9-7','Grotle','Pokémon','7','Uncommon','Nisota Niso','It knows where pure water wells up. It carries fellow Pokémon there on its back.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/7.png","large":"https://images.pokemontcg.io/swsh9/7_hires.png"}','F','100',NULL,'["Stage 1"]','["Grass"]','Turtwig','["Torterra"]','[{"name":"Sun-Drenched Shell","text":"Once during your turn, you may search your deck for a Grass Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.","type":"Ability"}]','[{"name":"Razor Leaf","cost":["Grass","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[388]',NULL,NULL,'swsh9');
