INSERT INTO "Card" VALUES('swsh9-54','Clefable','Pokémon','54','Rare','Mizue','A timid fairy Pokémon that is rarely seen, it will run and hide the moment it senses people.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/54.png","large":"https://images.pokemontcg.io/swsh9/54_hires.png"}','F','100',NULL,'["Stage 1"]','["Psychic"]','Clefairy',NULL,NULL,'[{"name":"Moonlit Miracle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip 3 coins. Choose a number of your Pokémon in play up to the number of heads. For each of those Pokémon, search your deck for a card that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck."},{"name":"Magical Shot","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[36]',NULL,NULL,'swsh9');
