INSERT INTO "Card" VALUES('swsh9-62','Dusknoir','Pokémon','62','Rare Holo','otumami','At the bidding of transmissions from the spirit world, it steals people and Pokémon away. No one knows whether it has a will of its own.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/62.png","large":"https://images.pokemontcg.io/swsh9/62_hires.png"}','F','160',NULL,'["Stage 2"]','["Psychic"]','Dusclops',NULL,'[{"name":"Special Transfer","text":"As often as you like during your turn, you may move a Special Energy from 1 of your Pokémon to another of your Pokémon.","type":"Ability"}]','[{"name":"Devour Soul","cost":["Psychic","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"120","text":""}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless","Colorless"]',3,'[477]',NULL,NULL,'swsh9');
INSERT INTO "Card" VALUES('swsh9-63','Chimecho','Pokémon','63','Common','MAHOU','Emitting ultrasonic cries, it floats on winds to travel great distances.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/63.png","large":"https://images.pokemontcg.io/swsh9/63_hires.png"}','F','70',NULL,'["Basic"]','["Psychic"]',NULL,NULL,NULL,'[{"name":"Clear Tone","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Special Energy cards, reveal them, and put them into your hand. Then, shuffle your deck."},{"name":"Hang Down","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless"]',1,'[358]',NULL,NULL,'swsh9');
