INSERT INTO "Card" VALUES('swsh9-70','Milcery','Pokémon','70','Common','Misa Tsutsui','They say that any patisserie visited by Milcery is guaranteed success and good fortune.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/70.png","large":"https://images.pokemontcg.io/swsh9/70_hires.png"}','E','50',NULL,'["Basic"]','["Psychic"]',NULL,'["Alcremie"]',NULL,'[{"name":"Lead","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Supporter card, reveal it, and put it into your hand. Then, shuffle your deck."},{"name":"Ram","cost":["Psychic"],"convertedEnergyCost":1,"damage":"10","text":""}]','[{"type":"Metal","value":"×2"}]',NULL,'["Colorless"]',1,'[868]',NULL,NULL,'swsh9');
