INSERT INTO "Card" VALUES('swsh9-137','Collapsed Stadium','Trainer','137','Uncommon','Oswaldo KATO',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swsh9/137.png","large":"https://images.pokemontcg.io/swsh9/137_hires.png"}','F',NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player can''t have more than 4 Benched Pokémon. If a player has 5 or more Benched Pokémon, they discard Benched Pokémon until they have 4 Pokémon on the Bench. The player who played this card discards first. If more than one effect changes the number of Benched Pokémon allowed, use the smaller number."]','swsh9');
