INSERT INTO "Card" VALUES('swshp-SWSH123','Galarian Articuno','Pokémon','SWSH123','Promo','Shin Nagasawa','Known as Articuno, this Pokémon fires beams that can immobilize opponents as if they had been frozen solid.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swshp/SWSH123.png","large":"https://images.pokemontcg.io/swshp/SWSH123_hires.png"}','E','120',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Cruel Charge","text":"When you play this Pokémon from your hand onto your Bench during your turn, you may attach up to 2 Psychic Energy cards from your hand to this Pokémon.","type":"Ability"}]','[{"name":"Psylaser","cost":["Psychic","Psychic","Colorless"],"convertedEnergyCost":3,"damage":"","text":"Discard all Psychic Energy from this Pokémon. This attack does 120 damage to 1 of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-30"}]','["Colorless","Colorless"]',2,'[144]',NULL,NULL,'swshp');
