INSERT INTO "Card" VALUES('swshp-SWSH278','Cinderace','Pokémon','SWSH278','Promo','Yuya Oka','It''s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/swshp/SWSH278.png","large":"https://images.pokemontcg.io/swshp/SWSH278_hires.png"}','E','170',NULL,'["Stage 2","Single Strike"]','["Fire"]','Raboot',NULL,'[{"name":"Crisis Power","text":"This Pokémon''s attacks do 30 more damage to your opponent''s Active Pokémon for each Prize card your opponent has taken (before applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Fireball Shot","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"150","text":"During your next turn, this Pokémon can''t attack."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[815]',NULL,NULL,'swshp');
