INSERT INTO "Card" VALUES('xy0-7','Pansear','Pokémon','7',NULL,'Naoyo Kimura','Very intelligent, it roasts berries before eating them. It likes to help people.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy0/7.png","large":"https://images.pokemontcg.io/xy0/7_hires.png"}',NULL,'70',NULL,'["Basic"]','["Fire"]',NULL,'["Simisear"]',NULL,'[{"name":"Collect","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw a card."},{"name":"Fury Swipes","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"10×","text":"Flip 3 coins. This attack does 10 damage times the number of heads."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[513]',NULL,NULL,'xy0');
INSERT INTO "Card" VALUES('xy0-8','Fennekin','Pokémon','8',NULL,'5ban Graphics','Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy0/8.png","large":"https://images.pokemontcg.io/xy0/8_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Braixen"]',NULL,'[{"name":"Scratch","cost":["Fire"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Live Coal","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[653]',NULL,NULL,'xy0');
