INSERT INTO "Card" VALUES('xy1-23','Simisear','Pokémon','23','Rare','sui','A flame burns inside its body. It scatters embers from its head and tail to sear its opponents.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/23.png","large":"https://images.pokemontcg.io/xy1/23_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fire"]','Pansear',NULL,NULL,'[{"name":"Yawn","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Your opponent''s Active Pokémon is now Asleep."},{"name":"Flamethrower","cost":["Fire","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"90","text":"Discard a Fire Energy attached to this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[514]',NULL,NULL,'xy1');
INSERT INTO "Card" VALUES('xy1-24','Fennekin','Pokémon','24','Common','5ban Graphics','Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/24.png","large":"https://images.pokemontcg.io/xy1/24_hires.png"}',NULL,'50',NULL,'["Basic"]','["Fire"]',NULL,'["Braixen"]',NULL,'[{"name":"Will-O-Wisp","cost":["Fire"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[653]',NULL,NULL,'xy1');
