INSERT INTO "Card" VALUES('xy1-27','Fletchinder','Pokémon','27','Uncommon','5ban Graphics','From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/27.png","large":"https://images.pokemontcg.io/xy1/27_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Fire"]','Fletchling','["Talonflame"]',NULL,'[{"name":"Flame Charge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a Fire Energy card and attach it to this Pokémon. Shuffle your deck afterward."},{"name":"Fire Wing","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[662]',NULL,NULL,'xy1');
