INSERT INTO "Card" VALUES('xy1-41','Greninja','Pokémon','41','Rare Holo','5ban Graphics','It creates throwing stars out of compressed water. When it spins them and throws them at high speed, these stars can split metal in two.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/41.png","large":"https://images.pokemontcg.io/xy1/41_hires.png"}',NULL,'130',NULL,'["Stage 2"]','["Water"]','Frogadier',NULL,'[{"name":"Water Shuriken","text":"Once during your turn (before your attack), you may discard a Water Energy card from your hand. If you do, put 3 damage counters on 1 of your opponent''s Pokémon.","type":"Ability"}]','[{"name":"Mist Slash","cost":["Water"],"convertedEnergyCost":1,"damage":"50","text":"This attack''s damage isn''t affected by Weakness, Resistance, or any other effects on your opponent''s Active Pokémon."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[658]',NULL,NULL,'xy1');
