INSERT INTO "Card" VALUES('xy1-60','Rhyhorn','Pokémon','60','Common','MAHOU','Strong, but not too bright, this Pokémon can shatter even a skyscraper with its charging Tackles.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/60.png","large":"https://images.pokemontcg.io/xy1/60_hires.png"}',NULL,'80',NULL,'["Basic"]','["Fighting"]',NULL,'["Rhydon"]',NULL,'[{"name":"Dig Out","cost":["Fighting"],"convertedEnergyCost":1,"damage":"10","text":"Discard the top card of your deck. If that card is a Fighting Energy, attach it to this Pokémon."},{"name":"Horn Drill","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"40","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[111]',NULL,NULL,'xy1');
