INSERT INTO "Card" VALUES('xy1-66','Gurdurr','Pokémon','66','Uncommon','Kouki Saitou','With strengthened bodies, they skillfully wield steel beams to take down buildings.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/66.png","large":"https://images.pokemontcg.io/xy1/66_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Fighting"]','Timburr','["Conkeldurr"]',NULL,'[{"name":"Pummel","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"Flip a coin. If heads, this attack does 20 more damage."},{"name":"Hammer Arm","cost":["Fighting","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"60","text":"Discard the top card of your opponent''s deck."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[533]',NULL,NULL,'xy1');
