INSERT INTO "Card" VALUES('xy1-120','Max Revive','Trainer','120','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/120.png","large":"https://images.pokemontcg.io/xy1/120_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Put a Pokémon from your discard pile on top of your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','xy1');
INSERT INTO "Card" VALUES('xy1-121','Muscle Band','Trainer','121','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/121.png","large":"https://images.pokemontcg.io/xy1/121_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The attacks of the Pokémon this card is attached to do 20 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","You may play as many Item cards as you like during your turn (before your attack)."]','xy1');
INSERT INTO "Card" VALUES('xy1-122','Professor Sycamore','Trainer','122','Uncommon','Yusuke Ohmura',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy1/122.png","large":"https://images.pokemontcg.io/xy1/122_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Discard your hand and draw 7 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','xy1');
