INSERT INTO "Card" VALUES('xy10-1','Shuckle','Pokémon','1','Uncommon','sui','It stores Berries inside its shell. To avoid attacks, it hides beneath rocks and remains completely still.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/1.png","large":"https://images.pokemontcg.io/xy10/1_hires.png"}',NULL,'80',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Hide a Berry","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Draw 2 cards. Then, put a card from your hand on the bottom of your deck."},{"name":"Wrap","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[213]',NULL,NULL,'xy10');
