INSERT INTO "Card" VALUES('xy10-6','Servine','Pokémon','6','Uncommon','Sumiyoshi Kizuki','When it gets dirty, its leaves can''t be used in photosynthesis, so it always keeps itself clean.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/6.png","large":"https://images.pokemontcg.io/xy10/6_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Snivy','["Serperior"]','[{"name":"Serpentine Strangle","text":"When you play this Pokémon from your hand to evolve 1 of your Pokémon, you may flip a coin. If heads, your opponent''s Active Pokémon is now Paralyzed.","type":"Ability"}]','[{"name":"Vine Whip","cost":["Grass"],"convertedEnergyCost":1,"damage":"20","text":""}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[496]',NULL,NULL,'xy10');
