INSERT INTO "Card" VALUES('xy10-12','Braixen','Pokémon','12','Uncommon','kirisAki','When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/12.png","large":"https://images.pokemontcg.io/xy10/12_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fire"]','Fennekin','["Delphox"]',NULL,'[{"name":"Destructive Flame","cost":["Fire"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If heads, discard an Energy attached to your opponent''s Active Pokémon."},{"name":"Crackling Ribbon","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[654]',NULL,NULL,'xy10');
