INSERT INTO "Card" VALUES('xy10-22','Binacle','Pokémon','22','Common','Tomokazu Komiya','They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/22.png","large":"https://images.pokemontcg.io/xy10/22_hires.png"}',NULL,'60',NULL,'["Basic"]','["Water"]',NULL,'["Barbaracle"]',NULL,'[{"name":"Swing Around","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip 2 coins. This attack does 20 more damage for each heads."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[688]',NULL,NULL,'xy10');
