INSERT INTO "Card" VALUES('xy10-24','Rotom','Pokémon','24','Rare','Tomokazu Komiya','Its body is composed of plasma. It is known to infiltrate electronic devices and wreak havoc.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/24.png","large":"https://images.pokemontcg.io/xy10/24_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Energy Extract","cost":["Lightning"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for a basic Energy card and attach it to this Pokémon. Shuffle your deck afterward."},{"name":"Plasmagic","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Move 2 damage counters from each of your Pokémon to your opponent''s Active Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[479]',NULL,NULL,'xy10');
