INSERT INTO "Card" VALUES('xy10-76','Aerodactyl','Pokémon','76','Rare','kawayoo','This vicious Pokémon is said to have flown in ancient skies while shrieking high-pitched cries.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/76.png","large":"https://images.pokemontcg.io/xy10/76_hires.png"}',NULL,'120',NULL,'["Restored"]','["Colorless"]','Old Amber Aerodactyl',NULL,NULL,'[{"name":"Bite","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Jet Draft","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"120","text":"Discard a Special Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]',NULL,NULL,'[142]',NULL,'["Put this card onto your Bench only with the effect of Old Amber Aerodactyl"]','xy10');
