INSERT INTO "Card" VALUES('xy10-78','Lugia','Pokémon','78','Rare','TOKIYA','It is said to be the guardian of the seas. It is rumored to have been seen on the night of a storm.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/78.png","large":"https://images.pokemontcg.io/xy10/78_hires.png"}',NULL,'120',NULL,'["Basic"]','["Colorless"]',NULL,NULL,'[{"name":"Pressure","text":"As long as this Pokémon is your Active Pokémon, any damage done by attacks from your opponent''s Active Pokémon is reduced by 20 (before applying Weakness and Resistance).","type":"Ability"}]','[{"name":"Intensifying Burn","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60+","text":"If your opponent''s Active Pokémon is a Pokémon-EX, this attack does 60 more damage."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless","Colorless"]',2,'[249]',NULL,NULL,'xy10');
