INSERT INTO "Card" VALUES('xy10-109','Random Receiver','Trainer','109','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/109.png","large":"https://images.pokemontcg.io/xy10/109_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Reveal cards from the top of your deck until you reveal a Supporter card. Put it into your hand. Shuffle the other cards back into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','xy10');
INSERT INTO "Card" VALUES('xy10-110','Scorched Earth','Trainer','110','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy10/110.png","large":"https://images.pokemontcg.io/xy10/110_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard a Fire or Fighting Energy card from his or her hand. If that player does so, he or she draws 2 cards.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy10');
