INSERT INTO "Card" VALUES('xy11-18','Chimchar','Pokémon','18','Common','Shibuzoh.','The gas made in its belly burns from its rear end. The fire burns weakly when it feels sick.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/18.png","large":"https://images.pokemontcg.io/xy11/18_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Monferno"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Ember","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, discard a Fire Energy attached to this Pokémon."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[390]',NULL,NULL,'xy11');
INSERT INTO "Card" VALUES('xy11-19','Monferno','Pokémon','19','Uncommon','Mizue','It uses ceilings and walls to launch aerial attacks. Its fiery tail is but one weapon.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/19.png","large":"https://images.pokemontcg.io/xy11/19_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Fire"]','Chimchar','["Infernape"]',NULL,'[{"name":"Scratch","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":""},{"name":"Flare","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":""}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[391]',NULL,NULL,'xy11');
