INSERT INTO "Card" VALUES('xy11-22','Litleo','Pokémon','22','Common','Kyoko Umemoto','They set off on their own from their pride and live by themselves to become stronger. These hot-blooded Pokémon are quick to fight.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/22.png","large":"https://images.pokemontcg.io/xy11/22_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Pyroar"]',NULL,'[{"name":"Lunge","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[667]',NULL,NULL,'xy11');
