INSERT INTO "Card" VALUES('xy11-57','Armaldo','Pokémon','57','Rare','Satoshi Shirai','Protected by a hard shell, its body is very sturdy. It skewers prey with its claws to feed.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/57.png","large":"https://images.pokemontcg.io/xy11/57_hires.png"}',NULL,'150',NULL,'["Stage 1"]','["Fighting"]','Anorith',NULL,NULL,'[{"name":"Rushing Water","cost":["Colorless"],"convertedEnergyCost":1,"damage":"40","text":"Move an Energy from your opponent''s Active Pokémon to 1 of his or her Benched Pokémon."},{"name":"Guard Claw","cost":["Fighting","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"100","text":"During your opponent''s next turn, any damage done to this Pokémon by attacks is reduced by 30 (after applying Weakness and Resistance)."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[348]',NULL,NULL,'xy11');
INSERT INTO "Card" VALUES('xy11-58','Croagunk','Pokémon','58','Common','Masakazu Fukuda','Inflating its poison sacs, it fills the area with an odd sound and hits flinching opponents with a poison jab.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/58.png","large":"https://images.pokemontcg.io/xy11/58_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Toxicroak"]',NULL,'[{"name":"Poison Up","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"If the Defending Pokémon is Poisoned, put 3 more damage counters on that Pokémon between turns. This effect can be applied more than once."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless"]',1,'[453]',NULL,NULL,'xy11');
