INSERT INTO "Card" VALUES('xy11-60','Sneasel','Pokémon','60','Common','Hajime Kusajima','Its paws conceal sharp claws. If attacked, it suddenly extends the claws and startles its enemy.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/60.png","large":"https://images.pokemontcg.io/xy11/60_hires.png"}',NULL,'60',NULL,'["Basic"]','["Darkness"]',NULL,'["Weavile"]',NULL,'[{"name":"Nyan Roll","cost":["Darkness"],"convertedEnergyCost":1,"damage":"10","text":"Flip a coin. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent''s next turn."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[215]',NULL,NULL,'xy11');
INSERT INTO "Card" VALUES('xy11-61','Weavile','Pokémon','61','Rare','kawayoo','They live in cold regions, forming groups of four or five that hunt prey with impressive coordination.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/61.png","large":"https://images.pokemontcg.io/xy11/61_hires.png"}',NULL,'90',NULL,'["Stage 1"]','["Darkness"]','Sneasel',NULL,'[{"name":"Tear Away","text":"As often as you like during your turn (before your attack), you may put a Pokémon Tool card attached to 1 of your Pokémon into your hand.","type":"Ability"}]','[{"name":"Slash","cost":["Darkness","Colorless"],"convertedEnergyCost":2,"damage":"40","text":""}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless"]',1,'[461]',NULL,NULL,'xy11');
