INSERT INTO "Card" VALUES('xy11-69','Shieldon','Pokémon','69','Uncommon','Mizue','It was generated from a fossil dug out of a layer of clay that was older than anyone knows. It has a sturdy face.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/69.png","large":"https://images.pokemontcg.io/xy11/69_hires.png"}',NULL,'90',NULL,'["Restored"]','["Metal"]','Armor Fossil Shieldon','["Bastiodon"]',NULL,'[{"name":"Rock Head","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"During your opponent''s next turn, any damage done to this Pokémon by attacks is reduced by 20 (after applying Weakness and Resistance)."},{"name":"Hammer In","cost":["Metal","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"60","text":""}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[410]',NULL,'["Put this card onto your Bench only with the effect of Armor Fossil Shieldon"]','xy11');
