INSERT INTO "Card" VALUES('xy11-76','Marill','Pokémon','76','Common','Shibuzoh.','The tip of its tail is filled with oil that is lighter than water, so it acts as a float.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/76.png","large":"https://images.pokemontcg.io/xy11/76_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fairy"]',NULL,'["Azumarill"]',NULL,'[{"name":"Bubble Drain","cost":["Fairy"],"convertedEnergyCost":1,"damage":"10","text":"Heal 10 damage from this Pokémon."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[183]',NULL,NULL,'xy11');
INSERT INTO "Card" VALUES('xy11-77','Azumarill','Pokémon','77','Uncommon','Sanosuke Sakuma','The bubble-like pattern on its stomach helps it camouflage itself when it''s in the water.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/77.png","large":"https://images.pokemontcg.io/xy11/77_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Fairy","Water"]','Marill',NULL,NULL,'[{"name":"Play Rough","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30+","text":"Flip a coin. If heads, this attack does 30 more damage."},{"name":"Bubble Drain","cost":["Fairy","Fairy","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Heal 30 damage from this Pokémon."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless","Colorless"]',2,'[184]',NULL,NULL,'xy11');
