INSERT INTO "Card" VALUES('xy11-102','Greedy Dice','Trainer','102','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/102.png","large":"https://images.pokemontcg.io/xy11/102_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if you took it as a face-down Prize card, before you put it into your hand.","Flip a coin. If heads, take 1 more Prize card.","You may play as many Item cards as you like during your turn (before your attack)."]','xy11');
INSERT INTO "Card" VALUES('xy11-103','Ninja Boy','Trainer','103','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy11/103.png","large":"https://images.pokemontcg.io/xy11/103_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. Search your deck for a Basic Pokémon and switch it with that Pokémon. (Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.) Shuffle the first Pokémon into your deck.","You may play only 1 Supporter card during your turn (before your attack)."]','xy11');
