INSERT INTO "Card" VALUES('xy12-47','Gastly','Pokémon','47','Common','Keiji Kinebuchi','A being that exists as a thin gas. It can topple an Indian elephant by enveloping the prey in two seconds.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy12/47.png","large":"https://images.pokemontcg.io/xy12/47_hires.png"}',NULL,'40','8','["Basic"]','["Psychic"]',NULL,'["Haunter"]',NULL,'[{"name":"Little Grudge","cost":["Psychic"],"convertedEnergyCost":1,"damage":"","text":"During your opponent''s next turn, if this Pokémon is Knocked Out by damage from an attack, discard an Energy attached to the Attacking Pokémon."},{"name":"Nightmare","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"20","text":"Flip a coin. If heads, your opponent''s Active Pokémon is now Asleep."}]','[{"type":"Darkness","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[92]',NULL,NULL,'xy12');
