INSERT INTO "Card" VALUES('xy2-10','Maractus','Pokémon','10','Uncommon','match','It uses an up-tempo song and dance to drive away the bird Pokémon that prey on its flower seeds.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy2/10.png","large":"https://images.pokemontcg.io/xy2/10_hires.png"}',NULL,'90',NULL,'["Basic"]','["Grass"]',NULL,NULL,NULL,'[{"name":"Exciting Shake","cost":["Grass"],"convertedEnergyCost":1,"damage":"","text":"During your next turn, flip 6 coins instead of 2 for this Pokémon''s Prickly Needles attack."},{"name":"Prickly Needles","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"20×","text":"Flip 2 coins. This attack does 20 damage times the number of heads."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[556]',NULL,NULL,'xy2');
