INSERT INTO "Card" VALUES('xy2-36','Helioptile','Pokémon','36','Common','5ban Graphics','They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy2/36.png","large":"https://images.pokemontcg.io/xy2/36_hires.png"}',NULL,'60',NULL,'["Basic"]','["Lightning"]',NULL,'["Heliolisk"]',NULL,'[{"name":"Pound","cost":["Lightning"],"convertedEnergyCost":1,"damage":"10","text":""},{"name":"Destructive Beam","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"","text":"Flip a coin. If heads, discard an Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[694]',NULL,NULL,'xy2');
