INSERT INTO "Card" VALUES('xy3-12','Torchic','Pokémon','12','Common','Sanosuke Sakuma','It has a flame sac inside its belly that perpetually burns. It feels warm if it is hugged.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/12.png","large":"https://images.pokemontcg.io/xy3/12_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fire"]',NULL,'["Combusken"]',NULL,'[{"name":"Quick Attack","cost":["Fire","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"Flip a coin. If heads, this attack does 30 more damage."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless"]',1,'[255]',NULL,NULL,'xy3');
