INSERT INTO "Card" VALUES('xy3-34','Dedenne','Pokémon','34','Uncommon','5ban Graphics','Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/34.png","large":"https://images.pokemontcg.io/xy3/34_hires.png"}',NULL,'70',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Entrainment","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Shuffle your deck afterward."},{"name":"Energy Short","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20×","text":"This attack does 20 damage times the amount of Energy attached to your opponent''s Active Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless"]',1,'[702]',NULL,NULL,'xy3');
