INSERT INTO "Card" VALUES('xy3-90','Fighting Stadium','Trainer','90','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/90.png","large":"https://images.pokemontcg.io/xy3/90_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["The attacks of each Fighting Pokémon in play (both yours and your opponent''s) do 20 more damage to the Defending Pokémon-EX (before applying Weakness and Resistance).","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy3');
