INSERT INTO "Card" VALUES('xy3-97','Mountain Ring','Trainer','97','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/97.png","large":"https://images.pokemontcg.io/xy3/97_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Prevent all damage done to Benched Pokémon by attacks (both yours and your opponent''s).","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy3');
INSERT INTO "Card" VALUES('xy3-98','Sail Fossil','Trainer','98','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/98.png","large":"https://images.pokemontcg.io/xy3/98_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Look at the bottom 7 cards of your deck. You may reveal an Amaura you find there and put it onto your Bench. Shuffle the other cards back into your deck.","You may play as many Item cards as you like during your turn (before your attack)."]','xy3');
INSERT INTO "Card" VALUES('xy3-99','Sparkling Robe','Trainer','99','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/99.png","large":"https://images.pokemontcg.io/xy3/99_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Pokémon this card is attached to can''t be affected by any Special Conditions. (Remove any Special Conditions affecting that Pokémon.)","You may play as many Item cards as you like during your turn (before your attack)."]','xy3');
INSERT INTO "Card" VALUES('xy3-100','Super Scoop Up','Trainer','100','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/100.png","large":"https://images.pokemontcg.io/xy3/100_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Flip a coin. If heads, put 1 of your Pokémon and all cards attached to it into your hand.","You may play as many Item cards as you like during your turn (before your attack)."]','xy3');
