INSERT INTO "Card" VALUES('xy3-102','Training Center','Trainer','102','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/102.png","large":"https://images.pokemontcg.io/xy3/102_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each Stage 1 and Stage 2 Pokémon in play (both yours and your opponent''s) gets +30 HP.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy3');
INSERT INTO "Card" VALUES('xy3-103','Herbal Energy','Energy','103','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/103.png","large":"https://images.pokemontcg.io/xy3/103_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card can only be attached to Grass Pokémon. This card provides Grass Energy only while this card is attached to a Grass Pokémon.","When you attach this card from your hand to 1 of your Grass Pokémon, heal 30 damage from that Pokémon.","(If this card is attached to anything other than a Grass Pokémon, discard this card.)"]','xy3');
INSERT INTO "Card" VALUES('xy3-104','Strong Energy','Energy','104','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy3/104.png","large":"https://images.pokemontcg.io/xy3/104_hires.png"}',NULL,NULL,NULL,'["Special"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["This card can only be attached to Fighting Pokémon. This card provides Fighting Energy only while this card is attached to a Fighting Pokémon.","The attacks of the Fighting Pokémon this card is attached to do 20 more damage to your opponent''s Active Pokémon (before applying Weakness and Resistance).","(If this card is attached to anything other than a Fighting Pokémon, discard this card.)"]','xy3');
