INSERT INTO "Card" VALUES('xy4-19','Lumineon','Pokémon','19','Uncommon','sui','It lives on the deep-sea floor. It attracts prey by flashing the patterns on its four tail fins.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/19.png","large":"https://images.pokemontcg.io/xy4/19_hires.png"}',NULL,'80',NULL,'["Stage 1"]','["Water"]','Finneon',NULL,NULL,'[{"name":"Neon Sign","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Search your deck for up to 2 Pokémon, reveal them, and put them into your hand. Shuffle your deck afterward."},{"name":"Water Pulse","cost":["Water","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent''s Active Pokémon is now Asleep."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[457]',NULL,NULL,'xy4');
