INSERT INTO "Card" VALUES('xy4-22','Alomomola','Pokémon','22','Common','Kouki Saitou','Floating in the open sea is how they live. When they find a wounded Pokémon, they embrace it and bring it to shore.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/22.png","large":"https://images.pokemontcg.io/xy4/22_hires.png"}',NULL,'100',NULL,'["Basic"]','["Water"]',NULL,NULL,NULL,'[{"name":"Super Deep Dive","cost":["Water"],"convertedEnergyCost":1,"damage":"","text":"Heal 30 damage from this Pokémon. Switch this Pokémon with 1 of your Benched Pokémon."},{"name":"Surf","cost":["Water","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":""}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[594]',NULL,NULL,'xy4');
