INSERT INTO "Card" VALUES('xy4-36','Wobbuffet','Pokémon','36','Uncommon','sui','It hates light and shock. If attacked, it inflates its body to build up its counterstrike.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/36.png","large":"https://images.pokemontcg.io/xy4/36_hires.png"}',NULL,'110',NULL,'["Basic"]','["Psychic"]',NULL,NULL,'[{"name":"Bide Barricade","text":"If this Pokémon is your Active Pokémon, each Pokémon in play, in each player''s hand, and in each player''s discard pile has no Abilities (except for Psychic Pokémon).","type":"Ability"}]','[{"name":"Psychic Assault","cost":["Psychic","Colorless"],"convertedEnergyCost":2,"damage":"10+","text":"This attack does 10 more damage for each damage counter on your opponent''s Active Pokémon."}]','[{"type":"Psychic","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[202]',NULL,NULL,'xy4');
