INSERT INTO "Card" VALUES('xy4-74','Hydreigon','Pokémon','74','Rare Holo','5ban Graphics','Their heads on their arms do not have brains. They use all three heads to consume and destroy everything.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/74.png","large":"https://images.pokemontcg.io/xy4/74_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Dragon"]','Zweilous',NULL,'[{"name":"Dark Impulse","text":"Once during your turn (before your attack), you may attach a Darkness Energy card from your discard pile to your Active Pokémon.","type":"Ability"}]','[{"name":"Crazy Headbutt","cost":["Psychic","Darkness","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"130","text":"Discard an Energy attached to this Pokémon."}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[635]',NULL,NULL,'xy4');
