INSERT INTO "Card" VALUES('xy4-85','Exploud','Pokémon','85','Rare','Kouki Saitou','Its howls can be heard over six miles away. It emits all sorts of noises from the ports on its body.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/85.png","large":"https://images.pokemontcg.io/xy4/85_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Colorless"]','Loudred',NULL,NULL,'[{"name":"Boomburst","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"","text":"This attack does 20 damage to each of your opponent''s Pokémon. (Don''t apply Weakness and Resistance for Benched Pokémon.)"},{"name":"Hyper Voice","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"90","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[295]',NULL,NULL,'xy4');
INSERT INTO "Card" VALUES('xy4-86','Regigigas','Pokémon','86','Rare Holo','kawayoo','It is said to have made Pokémon that look like itself from a special ice mountain, rocks, and magma.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy4/86.png","large":"https://images.pokemontcg.io/xy4/86_hires.png"}',NULL,'130',NULL,'["Basic"]','["Colorless"]',NULL,NULL,NULL,'[{"name":"Daunt","cost":["Colorless","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"During your opponent''s next turn, any damage done by attacks from the Defending Pokémon is reduced by 40 (before applying Weakness and Resistance)."},{"name":"Heavy Impact","cost":["Colorless","Colorless","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"100","text":""}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless","Colorless"]',4,'[486]',NULL,NULL,'xy4');
