INSERT INTO "Card" VALUES('xy5-110','Flygon','Pokémon','110','Rare Holo','kirisAki','Known as "The Desert Spirit," this Pokémon hides in the sandstorms it causes by beating its wings.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/110.png","large":"https://images.pokemontcg.io/xy5/110_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Dragon"]','Vibrava',NULL,'[{"name":"Sand Flap","text":"Once during your turn (before your attack), you may choose either player. That player shuffles his or her hand into his or her deck and draws 4 cards.","type":"Ability"}]','[{"name":"Sand Tomb","cost":["Grass","Fighting","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"The Defending Pokémon can''t retreat during your opponent''s next turn."}]','[{"type":"Fairy","value":"×2"}]',NULL,'["Colorless"]',1,'[330]',NULL,NULL,'xy5');
