INSERT INTO "Card" VALUES('xy5-131','Groudon Spirit Link','Trainer','131','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/131.png","large":"https://images.pokemontcg.io/xy5/131_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Your turn does not end if the Pokémon this card is attached to becomes Primal Groudon-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-132','Kyogre Spirit Link','Trainer','132','Uncommon','5ban Graphics',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/132.png","large":"https://images.pokemontcg.io/xy5/132_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","Your turn does not end if the Pokémon this card is attached to becomes Primal Kyogre-EX.","You may play as many Item cards as you like during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-133','Maxie''s Hidden Ball Trick','Trainer','133','Uncommon','Ken Sugimori',NULL,'{"unlimited":"Legal","expanded":"Banned"}','{"small":"https://images.pokemontcg.io/xy5/133.png","large":"https://images.pokemontcg.io/xy5/133_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only when it is the last card in your hand.","Put a Fighting Pokémon from your discard pile onto your Bench. Then, draw 5 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-134','Professor Birch''s Observations','Trainer','134','Uncommon','Yusuke Ohmura',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/134.png","large":"https://images.pokemontcg.io/xy5/134_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Shuffle your hand into your deck and flip a coin. If heads, draw 7 cards. If tails, draw 4 cards.","You may play only 1 Supporter card during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-135','Rare Candy','Trainer','135','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/135.png","large":"https://images.pokemontcg.io/xy5/135_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.) You can''t use this card during your first turn or on a Basic Pokémon that was put into play this turn.","You may play as many Item cards as you like during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-136','Repeat Ball','Trainer','136','Uncommon','Toyste Beach',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/136.png","large":"https://images.pokemontcg.io/xy5/136_hires.png"}',NULL,NULL,NULL,'["Item"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Search your deck for a Pokémon with the same name as 1 of your Pokémon in play, reveal it, and put it into your hand. Shuffle your deck afterward.","You may play as many Item cards as you like during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-137','Rough Seas','Trainer','137','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/137.png","large":"https://images.pokemontcg.io/xy5/137_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may heal 30 damage from each of his or her Water Pokémon and Lightning Pokémon.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy5');
INSERT INTO "Card" VALUES('xy5-138','Scorched Earth','Trainer','138','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/138.png","large":"https://images.pokemontcg.io/xy5/138_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Once during each player''s turn, that player may discard a Fire or Fighting Energy card from his or her hand. If that player does so, he or she draws 2 cards.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy5');
INSERT INTO "Card" VALUES('xy5-139','Shrine of Memories','Trainer','139','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/139.png","large":"https://images.pokemontcg.io/xy5/139_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each player''s evolved Pokémon can use any attack from its previous Evolutions. (That player still needs the necessary Energy to use each attack.)","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy5');
INSERT INTO "Card" VALUES('xy5-140','Silent Lab','Trainer','140','Uncommon','Ryo Ueda',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/140.png","large":"https://images.pokemontcg.io/xy5/140_hires.png"}',NULL,NULL,NULL,'["Stadium"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Each Basic Pokémon in play, in each player''s hand, and in each player''s discard pile has no Abilities.","This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can''t play this card."]','xy5');
INSERT INTO "Card" VALUES('xy5-141','Teammates','Trainer','141','Uncommon','Megumi Mizutani',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/141.png","large":"https://images.pokemontcg.io/xy5/141_hires.png"}',NULL,NULL,NULL,'["Supporter"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["You can play this card only if 1 of your Pokémon was Knocked Out during your opponent''s last turn.","Search your deck for up to 2 cards and put them into your hand. Shuffle your deck afterward.","You may play only 1 Supporter card during your turn (before your attack)."]','xy5');
INSERT INTO "Card" VALUES('xy5-142','Weakness Policy','Trainer','142','Uncommon','Ayaka Yoshida',NULL,'{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy5/142.png","large":"https://images.pokemontcg.io/xy5/142_hires.png"}',NULL,NULL,NULL,'["Pokémon Tool"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["Attach a Pokémon Tool to 1 of your Pokémon that doesn''t already have a Pokémon Tool attached to it.","The Pokémon this card is attached to has no Weakness.","You may play as many Item cards as you like during your turn (before your attack)."]','xy5');
