INSERT INTO "Card" VALUES('xy6-7','Dustox','Pokémon','7','Uncommon','Akira Komayama','It violently flutters its wings to scatter toxic dust when attacked. It becomes active after sunset.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy6/7.png","large":"https://images.pokemontcg.io/xy6/7_hires.png"}',NULL,'140',NULL,'["Stage 2"]','["Grass"]','Cascoon',NULL,NULL,'[{"name":"Psybeam","cost":["Colorless","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Your opponent''s Active Pokémon is now Confused."},{"name":"Twilight Poison","cost":["Grass","Grass","Colorless","Colorless"],"convertedEnergyCost":4,"damage":"80","text":"Your opponent''s Active Pokémon is now Asleep and Poisoned."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[269]',NULL,NULL,'xy6');
