INSERT INTO "Card" VALUES('xy6-9','Nincada','Pokémon','9','Common','Kyoko Umemoto','It can sometimes live underground for more than 10 years. It absorbs nutrients from the roots of trees.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy6/9.png","large":"https://images.pokemontcg.io/xy6/9_hires.png"}',NULL,'40',NULL,'["Basic"]','["Grass"]',NULL,'["Ninjask"]',NULL,'[{"name":"Slight Intrusion","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"This Pokémon does 10 damage to itself."}]','[{"type":"Fire","value":"×2"}]',NULL,'["Colorless"]',1,'[290]',NULL,NULL,'xy6');
INSERT INTO "Card" VALUES('xy6-10','Ninjask','Pokémon','10','Uncommon','Sumiyoshi Kizuki','Because it moves so quickly, it sometimes becomes unseeable. It congregates around tree sap.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy6/10.png","large":"https://images.pokemontcg.io/xy6/10_hires.png"}',NULL,'70',NULL,'["Stage 1"]','["Grass"]','Nincada','["Shedinja"]','[{"name":"Wing Buzz","text":"Once during your turn (before your attack), if this Pokémon is your Active Pokémon, you may discard a card from your hand. If you do, discard the top card of your opponent''s deck.","type":"Ability"}]','[{"name":"Afterimage Assault","cost":["Grass","Colorless"],"convertedEnergyCost":2,"damage":"30","text":"Search your deck for up to 2 Ninjask and put them onto your Bench. Shuffle your deck afterward."}]','[{"type":"Fire","value":"×2"}]',NULL,NULL,NULL,'[291]',NULL,NULL,'xy6');
