INSERT INTO "Card" VALUES('xy8-56','Stunfisk','Pokémon','56','Uncommon','Naoki Saito','It conceals itself in the mud of the seashore. Then it waits. When prey touch it, it delivers a jolt of electricity.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy8/56.png","large":"https://images.pokemontcg.io/xy8/56_hires.png"}',NULL,'110',NULL,'["Basic"]','["Lightning"]',NULL,NULL,NULL,'[{"name":"Revenge","cost":["Lightning","Colorless"],"convertedEnergyCost":2,"damage":"20+","text":"If any of your Pokémon were Knocked Out by damage from an opponent''s attack during his or her last turn, this attack does 80 more damage."},{"name":"Thunder Blast","cost":["Lightning","Lightning","Colorless"],"convertedEnergyCost":3,"damage":"80","text":"Discard an Energy attached to this Pokémon."}]','[{"type":"Fighting","value":"×2"}]','[{"type":"Metal","value":"-20"}]','["Colorless","Colorless","Colorless"]',3,'[618]',NULL,NULL,'xy8');
