INSERT INTO "Card" VALUES('xy8-114','Meowth','Pokémon','114','Common','kirisAki','Adores round objects. It wanders the streets on a nightly basis to look for dropped loose change.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy8/114.png","large":"https://images.pokemontcg.io/xy8/114_hires.png"}',NULL,'60',NULL,'["Basic"]','["Colorless"]',NULL,'["Persian"]',NULL,'[{"name":"Exhausted Tackle","cost":["Colorless"],"convertedEnergyCost":1,"damage":"","text":"Flip a coin. If heads, this attack does 30 damage to your opponent''s Active Pokémon. If tails, this Pokémon does 30 damage to itself."}]','[{"type":"Fighting","value":"×2"}]',NULL,'["Colorless"]',1,'[52]',NULL,NULL,'xy8');
