INSERT INTO "Card" VALUES('xy9-36','Ducklett','Pokémon','36','Common','Atsuko Nishida','They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy9/36.png","large":"https://images.pokemontcg.io/xy9/36_hires.png"}',NULL,'60',NULL,'["Basic"]','["Water"]',NULL,'["Swanna"]',NULL,'[{"name":"Lunge","cost":["Colorless"],"convertedEnergyCost":1,"damage":"20","text":"Flip a coin. If tails, this attack does nothing."}]','[{"type":"Lightning","value":"×2"}]','[{"type":"Fighting","value":"-20"}]','["Colorless"]',1,'[580]',NULL,NULL,'xy9');
