INSERT INTO "Card" VALUES('xy9-67','Sudowoodo','Pokémon','67','Uncommon','Hitoshi Ariga','It disguises itself as a tree to avoid attack. It hates water, so it will disappear if it starts raining.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy9/67.png","large":"https://images.pokemontcg.io/xy9/67_hires.png"}',NULL,'90',NULL,'["Basic"]','["Fighting"]',NULL,NULL,NULL,'[{"name":"Watch and Learn","cost":["Fighting","Colorless"],"convertedEnergyCost":2,"damage":"","text":"If your opponent''s Pokémon used an attack during his or her last turn, use it as this attack."}]','[{"type":"Water","value":"×2"}]',NULL,'["Colorless","Colorless"]',2,'[185]',NULL,NULL,'xy9');
INSERT INTO "Card" VALUES('xy9-68','Gible','Pokémon','68','Common','Naoyo Kimura','It nests in small, horizontal holes in cave walls. It pounces to catch prey that stray too close.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy9/68.png","large":"https://images.pokemontcg.io/xy9/68_hires.png"}',NULL,'60',NULL,'["Basic"]','["Fighting"]',NULL,'["Gabite"]',NULL,'[{"name":"Never Enough","cost":["Fighting"],"convertedEnergyCost":1,"damage":"","text":"Discard a card from your hand. If you do, draw 2 cards."}]','[{"type":"Grass","value":"×2"}]',NULL,'["Colorless"]',1,'[443]',NULL,NULL,'xy9');
