INSERT INTO "Card" VALUES('xy9-79','Ferroseed','Pokémon','79','Common','Satoshi Shirai','It absorbs the iron it finds in the rock while clinging to the ceiling. It shoots spikes when in danger.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy9/79.png","large":"https://images.pokemontcg.io/xy9/79_hires.png"}',NULL,'60',NULL,'["Basic"]','["Metal"]',NULL,'["Ferrothorn"]',NULL,'[{"name":"Harden","cost":["Metal","Colorless"],"convertedEnergyCost":2,"damage":"","text":"During your opponent''s next turn, if this Pokémon would be damaged by an attack, prevent that attack''s damage done to this Pokémon if that damage is 60 or less."}]','[{"type":"Fire","value":"×2"}]','[{"type":"Psychic","value":"-20"}]','["Colorless","Colorless"]',2,'[597]',NULL,NULL,'xy9');
