INSERT INTO "Card" VALUES('xy9-82','Clefable','Pokémon','82','Rare','Sanosuke Sakuma','A timid fairy Pokémon that is rarely seen, it will run and hide the moment it senses people.','{"unlimited":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/xy9/82.png","large":"https://images.pokemontcg.io/xy9/82_hires.png"}',NULL,'100',NULL,'["Stage 1"]','["Fairy"]','Clefairy',NULL,NULL,'[{"name":"Moon Barrier","cost":["Fairy"],"convertedEnergyCost":1,"damage":"30","text":"During your opponent''s next turn, prevent all effects of attacks, including damage, done to this Pokémon by Dragon Pokémon."},{"name":"Tumbling Attack","cost":["Fairy","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"50+","text":"Flip a coin. If heads, this attack does 30 more damage."}]','[{"type":"Metal","value":"×2"}]','[{"type":"Darkness","value":"-20"}]','["Colorless"]',1,'[36]',NULL,NULL,'xy9');
