INSERT INTO "Card" VALUES('zsv10pt5-23','Carracosta','Pokémon','23','Rare','Gemi','They can live both in the ocean and on land. A slap from one of them is enough to open a hole in the bottom of a tanker.','{"unlimited":"Legal","standard":"Legal","expanded":"Legal"}','{"small":"https://images.pokemontcg.io/zsv10pt5/23.png","large":"https://images.pokemontcg.io/zsv10pt5/23_hires.png"}','I','180',NULL,'["Stage 2"]','["Water"]','Tirtouga',NULL,'[{"name":"Mighty Shell","text":"Prevent all damage from and effects of attacks done to this Pokémon by your opponent''s Pokémon that have any Special Energy attached.","type":"Ability"}]','[{"name":"Big Bite","cost":["Water","Colorless","Colorless"],"convertedEnergyCost":3,"damage":"150","text":"During your opponent''s next turn, the Defending Pokémon can''t retreat."}]','[{"type":"Lightning","value":"×2"}]',NULL,'["Colorless","Colorless","Colorless"]',3,'[565]',NULL,NULL,'zsv10pt5');
